  str_skill_href_desc_name_30040 = "이성 시스템",
  str_skill_href_desc_desc_30040 = "이성 수치의 한도는 100으로, 이성 수치가 부족할 시 1포인트마다 파티의 HP 1%를 대신 차감한다.\n100~80: 침착한 상태로, 모든 것이 정상이다.\n79~50: 적과 아군의 방어력이 10% 감소한다.\n49~20: 턴이 시작될 때마다 레프타가 랜덤 위치에 등장한다.\n19~1: 아군의 치료 효과가 기존의 70%로 감소한다.\n0: 광기 상태에 진입해 모든 오로리안의 방어력이 30%만 남는다.",
  str_skill_href_desc_name_30041 = "무한의 인장",
  str_skill_href_desc_desc_30041 = "조준 대상에게 피해를 입힐 때마다 1단계를 부여한다(최대 99단계). 조준 대상을 변경하면 단계는 초기화된다.",
  str_skill_href_desc_name_30042 = "무한의 인장",
