  str_skill_href_desc_name_30044 = "종결 수치",
  str_skill_href_desc_desc_30044 = "턴 종료 시 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>20</color>포인트). 종결 상태에서는 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트를 추가로 획득하며, 종결 상태 종료 시 추가 포인트는 사라진다.",
  str_skill_href_desc_name_300441 = "종결 수치",
  str_skill_href_desc_desc_300441 = "턴 종료 시 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>20</color>포인트). 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_href_desc_name_300442 = "종결 수치",
  str_skill_href_desc_desc_300442 = "턴 종료 시 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>20</color>포인트). 종결 상태에서는 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트를 추가로 획득하며, 종결 상태 종료 시 추가 포인트는 사라진다. 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_href_desc_name_300443 = "종결 수치",
  str_skill_href_desc_desc_300443 = "턴 종료 시 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>20</color>포인트). 종결 상태에서는 한도를 초과할 수 있는 <color=#00F6FF>6</color>포인트를 추가로 획득하며, 종결 상태 종료 시 추가 포인트는 사라진다. 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_href_desc_name_30045 = "고독 수치",
  str_skill_href_desc_desc_30045 = "바튼 더 데프트 블레이드가 일반공격을 할 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30046 = "고독 수치",
  str_skill_href_desc_desc_30046 = "전투 진입 시 <color=#00F6FF>20</color>포인트를 획득하며, 바튼 더 데프트 블레이드가 일반공격을 할 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30047 = "고독 수치",
  str_skill_href_desc_desc_30047 = "전투 진입 시 <color=#00F6FF>20</color>포인트를 획득하며, 바튼 더 데프트 블레이드가 일반공격을 할 때마다 <color=#00F6FF>1</color>포인트를 획득한다. 액티브 스킬을 시전해 고독한 용맹 상태에 진입할 경우 즉시 <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_href_desc_name_30048 = "피브릴 수치",
  str_skill_href_desc_desc_30048 = "전투 시작 시 <color=#00F6FF>2</color>포인트를 보유하며, 턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30049 = "피브릴 수치",
  str_skill_href_desc_desc_30049 = "전투 시작 시 <color=#00F6FF>4</color>포인트를 보유하며, 턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30050 = "피브릴 수치",
  str_skill_href_desc_desc_30050 = "턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30051 = "특수기",
  str_skill_href_desc_desc_30051 = "출전한 P5R 콜라보 캐릭터 수에 따라 적 전체에게 피해를 입힌다. <color=#00F6FF>WEAK 상태</color>의 적에게 더 높은 피해를 입히며, <color=#00F6FF>WEAK 상태</color>를 초기화한다. 모든 적이 <color=#00F6FF>WEAK 상태</color>일 시 <color=#00F6FF>특수기 연출</color>이 발동한다.",
  str_skill_href_desc_name_30052 = "약점 노출",
  str_skill_href_desc_desc_30052 = "약점 노출 단계가 <color=#00F6FF>100</color> 도달 시 <color=#00F6FF>WEAK 상태</color>에 진입한다.",
  str_skill_href_desc_name_30053 = "빛의 혼 수치",
  str_skill_href_desc_desc_30053 = "턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>6</color>포인트).",
  str_skill_href_desc_name_30054 = "빛의 혼 수치",
  str_skill_href_desc_desc_30054 = "전투 시작 시 <color=#00F6FF>2</color>포인트를 보유하며, 턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>6</color>포인트).",
  str_skill_href_desc_name_30055 = "미끼 수치",
  str_skill_href_desc_desc_30055 = "턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>9</color>포인트).",
  str_skill_href_desc_name_30056 = "미끼 수치",
  str_skill_href_desc_desc_30056 = "턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득하며, 웨이브가 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>9</color>포인트).",
  str_skill_href_desc_name_30057 = "선회",
  str_skill_href_desc_desc_30057 = "측면 또는 후면 대각선 방향",
  str_skill_href_desc_name_30058 = "기원의 카드",
  str_skill_href_desc_desc_30058 = "기원의 카드는 태양, 달, 별 3종으로 구성되며, 선택된 3장의 카드 유형에 따라 해당하는 효과가 활성화된다.\n모두 동일한 카드 - 「모여드는 빛」: <color=#00F6FF>현재 리더</color>가 제노의 기본 공격력의 <color=#00F6FF>8%</color>에 해당하는 추가 공격력을 획득한다.\n모두 다른 카드 - 「달과 별의 기세」: <color=#00F6FF>현재 편대의 후미</color> 오로리안이 제노의 기본 공격력의 <color=#00F6FF>7%</color>에 해당하는 추가 공격력을 획득한다.\n기타 상황 - 「이색의 광채」: 이번 전투의 리더 변경 횟수가 1회 증가하며, 감소한 이성 수치의 <color=#00F6FF>18%</color>를 추가로 회복한다.\n공격력 증가 효과는 전투가 끝날 때까지 지속되며, 동일 효과는 중첩되지 않는다.",
  str_skill_href_desc_name_30059 = "기원의 카드",
  str_skill_href_desc_desc_30059 = "기원의 카드는 태양, 달, 별 3종으로 구성되며, 선택된 3장의 카드 유형에 따라 해당하는 효과가 활성화된다.\n모두 동일한 카드 - 「모여드는 빛」: <color=#00F6FF>현재 리더</color>가 제노의 기본 공격력의 <color=#00F6FF>8%</color>에 해당하는 추가 공격력을 획득한다.\n모두 다른 카드 - 「달과 별의 기세」: <color=#00F6FF>현재 편대의 후미</color> 오로리안이 제노의 기본 공격력의 <color=#00F6FF>7%</color>에 해당하는 추가 공격력을 획득한다.\n기타 상황 - 「이색의 광채」: 이번 전투의 리더 변경 횟수가 1회 증가하며, 감소한 이성 수치의 <color=#00F6FF>18%</color>를 추가로 회복한다.\n공격력 증가 효과는 전투가 끝날 때까지 지속되며, 동일 효과는 중첩되지 않는다.",
  str_skill_href_desc_name_30060 = "기원의 카드",
  str_skill_href_desc_desc_30060 = "기원의 카드는 태양, 달, 별 3종으로 구성되며, 선택된 3장의 카드 유형에 따라 해당하는 효과가 활성화된다.\n모두 동일한 카드 - 「모여드는 빛」: <color=#00F6FF>현재 리더</color>가 제노의 기본 공격력의 <color=#00F6FF>8%</color>에 해당하는 추가 공격력을 획득한다.\n모두 다른 카드 - 「달과 별의 기세」: <color=#00F6FF>현재 편대의 후미</color> 오로리안이 제노의 기본 공격력의 <color=#00F6FF>7%</color>에 해당하는 추가 공격력을 획득한다.\n기타 상황 - 「이색의 광채」: 이번 전투의 리더 변경 횟수가 1회 증가하며, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 추가로 회복한다.\n공격력 증가 효과는 전투가 끝날 때까지 지속되며, 동일 효과는 중첩되지 않는다.",
  str_skill_href_desc_name_30061 = "샤워헤드 인장",
  str_skill_href_desc_desc_30061 = "샤워헤드 인장은 필드에 <color=#00F6FF>3</color>턴간 존재 후 사라진다.",
  str_skill_href_desc_name_30062 = "율법의 상",
  str_skill_href_desc_desc_30062 = "율법의 상은 최대 5레벨로, 다른 오로리안의 소환물을 대체할 수 없으며, 적이 지나간 후 사라진다.",
  str_skill_href_desc_name_30063 = "카타 에너지",
  str_skill_href_desc_desc_30063 = "턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30064 = "카타 에너지",
  str_skill_href_desc_desc_30064 = "전투 시작 시 <color=#00F6FF>2</color>포인트를 보유하며, 턴이 시작될 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30065 = "흡수",
  str_skill_href_desc_desc_30065 = "연결 이동과 동일한 효과로 간주하며, 피해 보너스를 제공한다. 관련 오로리안의 대응 효과를 발동할 수 있다.",
  str_skill_href_desc_name_30066 = "플래시 필드",
  str_skill_href_desc_desc_30066 = "연쇄 스킬 시전 후 <color=#00F6FF>플래시 필드</color> 외부에 있을 경우 현재 연쇄 스킬 범위 내에 새로운 플래시 필드가 생성된다. 동시에 최대 <color=#00F6FF>2</color>개의 플래시 필드를 유지할 수 있으며, 수량을 초과할 시 가장 먼저 생성된 플래시 필드가 사라진다.",
  str_skill_href_desc_name_30067 = "플래시 필드",
  str_skill_href_desc_desc_30067 = "연쇄 스킬 시전 후 <color=#00F6FF>플래시 필드</color> 외부에 있을 경우 현재 연쇄 스킬 범위 내에 새로운 플래시 필드가 생성된다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있으며, 수량을 초과할 시 가장 먼저 생성된 플래시 필드가 사라진다.",
  str_skill_href_desc_name_30068 = "플래시 필드",
  str_skill_href_desc_desc_30068 = "연쇄 스킬 시전 후 <color=#00F6FF>플래시 필드</color> 외부에 있을 경우 현재 연쇄 스킬 범위 내에 새로운 플래시 필드가 생성된다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있으며, 수량을 초과할 시 가장 먼저 생성된 플래시 필드가 사라진다. 전투 시작 후 초기 위치에 <color=#00F6FF>마름모 12칸</color> 범위의 플래시 필드가 생성된다.",
  str_skill_href_desc_name_30069 = "큐빅 에너지",
  str_skill_href_desc_desc_30069 = "턴마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>9</color>포인트).",
  str_skill_href_desc_name_30070 = "큐빅 에너지",
  str_skill_href_desc_desc_30070 = "전투 시작 시 <color=#00F6FF>2</color>포인트를 보유하며, 턴마다 <color=#00F6FF>1</color>포인트를 획득한다(최대 <color=#00F6FF>9</color>포인트).",
  str_skill_href_desc_name_30071 = "제어 모듈",
  str_skill_href_desc_desc_30071 = "제어 모듈 내에서 액티브 스킬 효과를 전환할 수 있으며, 제어 모듈 내에는 이번 전투에 등장했던 <color=#00F6FF>일부 번개 속성 오로리안의 소환물</color>이 기록된다.\n선택 가능한 <color=#00F6FF>특수 칸</color>: 짙은 칸, 프리즘 칸, 십자형 프리즘 칸\n다음 <color=#00F6FF>아군 오로리안</color>의 소환물 선택 가능: 아메모리, 라인하르트, 보프, 로이, 시엘, 나딘, 에이미",
  str_skill_href_desc_name_30072 = "큐어 볼",
  str_skill_href_desc_desc_30072 = "<color=#00F6FF>0/1/2</color>턴간 존재한 상태에서 오로리안이 지나거나 액티브 스킬로 흡수 시 악셀리아의 공격력의 <color=#00F6FF>40%/100%/200%</color>에 해당하는 HP를 회복한다.",
  str_skill_href_desc_name_30073 = "큐어 볼",
  str_skill_href_desc_desc_30073 = "<color=#00F6FF>0/1/2</color>턴간 존재한 상태에서 오로리안이 지날 시 악셀리아의 공격력의 <color=#00F6FF>40%/100%/250%</color>에 해당하는 HP를 회복하고, 액티브 스킬로 흡수 시 효과가 <color=#00F6FF>80%/180%/400%</color>로 증가한다.",
  str_skill_href_desc_name_30074 = "정룡의 광휘",
  str_skill_href_desc_desc_30074 = "<color=#00F6FF>2/3/4</color>단계의 연쇄 스킬을 발동해 각 단계에 해당하는 「정룡의 광휘」를 점등할 수 있으며, 「정룡의 광휘」가 <color=#00F6FF>3</color>개 점등되면 액티브 스킬이 준비된다. 액티브 스킬 시전 후 모든 「정룡의 광휘」가 꺼진다.",
  str_skill_href_desc_name_30075 = "통찰력",
  str_skill_href_desc_desc_30075 = "불 속성 칸을 1개 지날 때마다 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_href_desc_name_30076 = "통찰력",
  str_skill_href_desc_desc_30076 = "불 속성 칸을 1개 지날 때마다 <color=#00F6FF>1</color>포인트를 획득하며, 전투 진입 시 <color=#00F6FF>5</color>포인트, 웨이브가 시작될 때마다 <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_href_desc_name_30077 = "통찰력",
  str_skill_href_desc_desc_30077 = "칸을 1개 지날 때마다 <color=#00F6FF>1</color>포인트를 획득하며, 전투 진입 시 <color=#00F6FF>5</color>포인트, 웨이브가 시작될 때마다 <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_href_desc_name_30078 = "열에너지",
  str_skill_href_desc_desc_30078 = "일반공격마다 <color=#00F6FF>5</color>포인트를 획득한다(최대 <color=#00F6FF>100</color>포인트).",
  str_skill_href_desc_name_30079 = "예비 탄약",
  str_skill_href_desc_desc_30079 = "턴이 시작될 때마다 1개를 비축하며, 자신이 액티브 스킬 시전 시 5개를 비축할 수 있다. 다른 오로리안이 액티브 스킬 시전 시 1개를 비축할 수 있다.",
  str_skill_href_desc_name_30080 = "십자 프리즘 칸",
  str_skill_href_desc_desc_30080 = "연결 시 십자 프리즘 칸 주변 십자형 4칸을 십자 프리즘 칸과 동일한 속성으로 바꾼다.",
  str_skill_href_desc_name_30081 = "끌어당기기",
  str_skill_href_desc_desc_30081 = "끌어당길 수 있는 대상에게만 유효하며, 먼저 선택한 대상이 구역 중앙에 더 가까이 당겨진다.",
  str_skill_href_desc_name_30082 = "밀집",
  str_skill_href_desc_desc_30082 = "공격 대상 주변 1서클 범위 내에 다른 대상이 존재하는 경우를 가리킨다.",
  str_skill_href_desc_name_30083 = "심판",
  str_skill_href_desc_desc_30083 = "HP 한도가 없는 대상은 심판 수치를 추가할 수 없습니다.",
  str_skill_href_desc_name_30084 = "취합",
  str_skill_href_desc_desc_30084 = "칸의 속성만 새로 배열해 해당 행/열의 물 속성 칸이 현재 선택한 칸의 주변으로 모이도록 하며, 칸 위의 적, 소환물, 특수 칸의 위치는 바뀌지 않는다.",
  str_skill_href_desc_name_30085 = "잔물결",
  str_skill_href_desc_desc_30085 = "최대 99단계, 매회 최소 7단계를 소모하며, HP가 최대일 시 더는 단계를 소모하지 않는다.",
  str_skill_href_desc_name_30086 = "잔물결",
  str_skill_href_desc_desc_30086 = "최대 99단계, 매회 최소 5단계를 소모하며, HP가 최대일 시 더는 단계를 소모하지 않는다.",
  str_skill_href_desc_name_30087 = "사족 강철 도마뱀",
  str_skill_href_desc_desc_30087 = "사족 강철 도마뱀은 최대 2턴간 존재하며, 필드에 최대 1마리만 존재할 수 있다.",
  str_skill_href_desc_name_30088 = "사족 강철 도마뱀",
  str_skill_href_desc_desc_30088 = "턴마다 사족 강철 도마뱀을 터치해 스킬을 시전할 수 있다. 사족 강철 도마뱀은 최대 2턴간 존재하며, 필드에 최대 1마리만 존재할 수 있다.",
  str_skill_href_desc_name_30089 = "「끌림의 울음소리」",
  str_skill_href_desc_desc_30089 = "시전 시 주변 2서클 내의 적을 1칸 끌어당긴 후 사라진다.",
  str_skill_href_desc_name_30090 = "「거대한 힘」",
  str_skill_href_desc_desc_30090 = "시전 시 보프의 이번 턴 연쇄 스킬 범위가 사족 강철 도마뱀 자신을 향하도록 바꾸며, 범위가 필드 가장자리까지 확장된다.",
  str_skill_href_desc_name_30091 = "접촉",
  str_skill_href_desc_desc_30091 = "적의 발밑에 수정이 생성되거나 적이 수정 위치로 이동 시 피해를 입히며, 적의 발밑에 여러 개의 수정 생성 시 중복으로 피해를 입힐 수 있다.",
  str_skill_href_desc_name_30092 = "위치이동",
  str_skill_href_desc_desc_30092 = "아군 오로리안의 액티브 스킬 순간이동, 적 스킬로 인한 넉백/끌어당김, 전송 회오리 사용 등을 포함한다.",
  str_skill_href_desc_name_30093 = "짙은 칸",
  str_skill_href_desc_desc_30093 = "해당 위치에 갱신되는 다음 칸은 반드시 현재와 동일한 속성이 된다.",
  str_skill_href_desc_name_30094 = "신체 침식",
  str_skill_href_desc_desc_30094 = "최대 40단계, 단계마다 3턴간 지속.",
  str_skill_href_desc_name_30095 = "공구",
  str_skill_href_desc_desc_30095 = "전투 시작 시 3개를 획득하며, 턴이 시작될 때마다 1개를 획득한다.",
  str_skill_href_desc_name_30096 = "그림자의 선물",
  str_skill_href_desc_desc_30096 = "턴이 시작될 때마다 1포인트를 획득하며, 짙은 칸을 지날 시 1포인트를 획득한다.",
  str_skill_href_desc_name_30097 = "그림자의 선물",
  str_skill_href_desc_desc_30097 = "전투 진입 시 5포인트, 턴이 시작될 때마다 1포인트, 짙은 칸을 지날 시 1포인트를 획득한다.",
  str_skill_href_desc_name_30098 = "그림자의 선물",
  str_skill_href_desc_desc_30098 = "전투 진입 시 5포인트, 턴이 시작될 때마다 1포인트, 웨이브가 시작될 때마다 2포인트, 짙은 칸을 지날 시 1포인트를 획득한다.",
  str_skill_href_desc_name_30099 = "그림자의 선물",
  str_skill_href_desc_desc_30099 = "턴이 시작될 때마다 1포인트, 웨이브가 시작될 때마다 2포인트, 짙은 칸을 지날 시 1포인트를 획득한다.",
  str_skill_href_desc_name_510218 = "투자 전략",
  str_skill_href_desc_desc_510218 = "물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다.\n캐피탈 크레딧이2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 종류마다 2개 중 1개를 선택해 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_513218 = "투자 전략",
  str_skill_href_desc_desc_513218 = "물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(각성3 개방).\n캐피탈 크레딧이 2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 2개 중 1개를 선택해 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_516218 = "투자 전략",
  str_skill_href_desc_desc_516218 = "전투 시작 시 캐피탈 크레딧을 5포인트 획득하며, 물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(각성3 개방).\n캐피탈 크레딧이 2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 2개 중 1개를 선택해 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_530218 = "투자 전략",
  str_skill_href_desc_desc_530218 = "물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다.\n캐피탈 크레딧이 2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 종류마다 2개 중 1개를 선택해 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_533218 = "투자 전략",
  str_skill_href_desc_desc_533218 = "물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다.\n캐피탈 크레딧이 2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 종류마다 2개 중 1개를 선택해 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_536218 = "투자 전략",
  str_skill_href_desc_desc_536218 = "전투 시작 시 캐피탈 크레딧을 5포인트 획득하며, 물 속성 칸 5개/짙은 칸 1개를 통과할 때마다 캐피탈 크레딧 1포인트를 획득한다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다.\n캐피탈 크레딧이 2/5/8포인트 도달 시 투자 전략에 액티브 스킬/연쇄 스킬/일반공격 3종의 전투 능력이 각 2개씩 순차 개방되며, 종류마다 2개 중 1개를 선택해 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다.\n[선택 가능한 전투 능력]\n◇휘감는 뱀: 액티브 스킬 범위가 마름모 13칸으로 확장됨\n◇안개 조종: 액티브 스킬 피해 50% 증가\n◇상냥한 자본가: 연쇄 스킬이 가장 먼 대상을 추가로 1회 공격하며, 횟수에 따라 피해가 감소하지 않음\n◇일확억금: 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 피해 횟수 1회 증가\n◇자본 확장: 일반공격이 사선 방향을 공격할 수 있게 됨\n◇자본 타격: 이번 연결이 짙은 칸을 1개 지날 때마다 일반공격 피해가 20% 증가하며, 최대 2배까지 증가",
  str_skill_href_desc_name_30100 = "컬러보드",
  str_skill_href_desc_desc_30100 = "제타는 다음 방법으로 컬러보드를 채울 수 있으며, 색을 다 채우면 액티브 스킬 [컬러풀 미스틱]을 시전할 수 있다.\n1. 액티브 스킬 [혼합 폭격]이 선택한 칸을 초기화하기 전 해당 칸의 색상을 컬러보드에 기록한다.\n2. 액티브 스킬 [컬러풀 미스틱]으로 소환한 「코난」이 공격 중 지나는 칸의 색상을 컬러보드에 기록한다.",
  str_skill_href_desc_name_30110 = "넥스트 블록",
  str_skill_href_desc_desc_30110 = "[넥스트 블록]은 총 7종이 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위이다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 모양이 랜덤으로 변경된다.",
  str_skill_href_desc_name_30111 = "넥스트 블록",
  str_skill_href_desc_desc_30111 = "[넥스트 블록]은 총 7종이 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위이다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신하며, 불 속성 칸을 지날 시 에너지 1포인트를 충전한다. 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 5포인트씩 증가한다.",
  str_skill_href_desc_name_30112 = "넥스트 블록",
  str_skill_href_desc_desc_30112 = "[넥스트 블록]은 총 7종이 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위이다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신하며, 초기 에너지를 10포인트 보유한다. 불 속성 칸을 지날 시 에너지 1포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 5포인트씩 증가한다.",
  str_skill_href_desc_name_30113 = "넥스트 블록",
  str_skill_href_desc_desc_30113 = "[넥스트 블록]은 총 7종이 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위이다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신하며, 초기 에너지를 10포인트 보유한다. 불 속성 칸을 지날 시 에너지 1포인트를 충전한다.",
  str_skill_href_desc_name_30114 = "넥스트 블록",
  str_skill_href_desc_desc_30114 = "[넥스트 블록]에는 총 7종의 형태가 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위가 된다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신한다. 불 속성 칸을 지날 시 에너지 1포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 5포인트씩 증가한다.\n[넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_href_desc_name_30115 = "넥스트 블록",
  str_skill_href_desc_desc_30115 = "[넥스트 블록]에는 총 7종의 형태가 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위가 된다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신하며, 초기 에너지를 10포인트 보유한다. 불 속성 칸을 지날 시 에너지 1포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 5포인트씩 증가한다.\n[넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_href_desc_name_30116 = "넥스트 블록",
  str_skill_href_desc_desc_30116 = "[넥스트 블록]에는 총 7종의 형태가 존재하며, 현재 표시되는 블록의 형태가 바티아의 액티브 스킬의 색 변경 범위가 된다.\n바티아가 액티브 스킬을 시전할 때마다 블록의 형태가 랜덤으로 변경된다.\n에너지 5포인트를 소모해 [넥스트 블록]의 형태를 랜덤으로 갱신할 수 있다. 초기 에너지를 10포인트 보유하며, 갱신 시 에너지 5포인트를 소모한다. 불 속성 칸을 지날 시 에너지 1포인트를 충전한다.\n[넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_href_desc_name_30117 = "진혼의 인장",
  str_skill_href_desc_desc_30117 = "일반공격 또는 연쇄 스킬이 뇌격을 발동해 적을 공격할 때마다 1단계를 획득한다.",
  str_skill_href_desc_name_30118 = "진리의 계약",
  str_skill_href_desc_desc_30118 = "필드 내 최대 1명까지만 진리의 계약을 지닐 수 있다.",
  str_skill_href_desc_name_30119 = "AP",
  str_skill_href_desc_desc_30119 = "《라이자의 아틀리에2》 콜라보 오로리안은 AP(액션 포인트)를 공유하며, 각 오로리안은 액티브 스킬을 턴마다 최대 1회 시전할 수 있다. 캐릭터가 이번 턴에 액티브 스킬을 시전하지 않을 경우 턴 종료 시 AP 10포인트를 획득한다.",
  str_skill_href_desc_name_30120 = "AP",
  str_skill_href_desc_desc_30120 = "《라이자의 아틀리에2》 콜라보 오로리안은 AP(액션 포인트)를 공유하며, 각 오로리안은 액티브 스킬을 턴마다 최대 1회 시전할 수 있다. 전투 진입 시 AP 20포인트를 획득하며, 캐릭터가 이번 턴에 액티브 스킬을 시전하지 않을 경우 턴 종료 시 AP 10포인트를 획득한다.",
  str_skill_href_desc_name_30121 = "AP",
  str_skill_href_desc_desc_30121 = "《라이자의 아틀리에2》 콜라보 오로리안은 AP(액션 포인트)를 공유하며, 각 오로리안은 액티브 스킬을 턴마다 최대 1회 시전할 수 있다. 전투 진입 시 AP 20포인트를 획득하며, 턴이 끝날 때마다 AP 10포인트를 획득한다.",
  str_skill_href_desc_name_30122 = "택틱스 시스템",
  str_skill_href_desc_desc_30122 = "전투 중 다양한 행동을 통해 택틱스 포인트를 획득하며, 택틱스 포인트가 지정 수치에 도달하면 대응하는 효과를 획득한다.\n택틱스 포인트 10 - Lv.1: 《라이자의 아틀리에2》 콜라보 오로리안의 연쇄 스킬 최종 피해가 15% 증가한다.\n택틱스 포인트 40 - Lv.2: 턴이 시작될 때마다 랜덤 위치에 짙은 칸을 1개 생성한다.\n택틱스 포인트 70 - Lv.3: 라이자, 파트리샤의 연쇄 스킬이 적에게 명중 시 작열 효과를 1회 추가한다. 클라우디아의 연쇄 스킬이 적에게 명중 시 중독 효과를 1회 추가한다.\n택틱스 포인트 100 - Lv.4: 《라이자의 아틀리에2》 콜라보 오로리안의 액티브 스킬 최종 피해가 50% 증가한다.\n택틱스 포인트 130 - Lv.5: 턴이 시작될 때마다 랜덤 위치에 짙은 칸을 1개 생성한다.",
  str_skill_href_desc_name_30123 = "택틱스 시스템",
  str_skill_href_desc_desc_30123 = "전투 중 다양한 행동을 통해 택틱스 포인트를 획득하며, 택틱스 포인트가 지정 수치에 도달하면 대응하는 효과를 획득한다. 초기 레벨 한도는 Lv.5이며, 전투 진입 후 택틱스 시스템 레벨 한도가 +1 증가한다.\n택틱스 포인트 10 - Lv.1: 《라이자의 아틀리에2》 콜라보 오로리안의 연쇄 스킬 최종 피해가 15% 증가한다.\n택틱스 포인트 40 - Lv.2: 턴이 시작될 때마다 랜덤 위치에 짙은 칸을 1개 생성한다.\n택틱스 포인트 70 - Lv.3: 라이자, 파트리샤의 연쇄 스킬이 적에게 명중 시 작열 효과를 1회 추가한다. 클라우디아의 연쇄 스킬이 적에게 명중 시 중독 효과를 1회 추가한다.\n택틱스 포인트 100 - Lv.4: 《라이자의 아틀리에2》 콜라보 오로리안의 액티브 스킬 최종 피해가 50% 증가한다.\n택틱스 포인트 130 - Lv.5: 턴이 시작될 때마다 랜덤 위치에 짙은 칸을 1개 생성한다.\n택틱스 포인트 160 - Lv.6: 《라이자의 아틀리에2》 콜라보 오로리안의 기본 공격력이 10% 증가한다.\n택틱스 포인트 200 - Lv.7: 턴이 시작될 때마다 랜덤 위치에 짙은 칸을 1개 생성한다.",
  str_skill_href_desc_name_30124 = "흡수",
  str_skill_href_desc_desc_30124 = "연결 이동과 동일한 효과로 간주하며, 관련 오로리안의 대응 효과를 발동할 수 있다.",
  str_skill_href_desc_name_30125 = "ESP",
  str_skill_href_desc_desc_30125 = "파티가 2칸을 지나갈 때마다 ESP 1포인트를 획득한다.",
  str_skill_href_desc_name_30126 = "ESP",
  str_skill_href_desc_desc_30126 = "파티가 2칸을 지나갈 때마다 ESP 1포인트를 획득하며, 턴이 시작될 때마다 ESP 5포인트를 획득한다.",
  str_skill_href_desc_name_30127 = "연결 조종",
  str_skill_href_desc_desc_30127 = "연결 시 칸의 색상을 무시하며, 1칸마다 ESP 1포인트를 소모한다.",
  str_skill_href_desc_name_30128 = "이탈 상태",
  str_skill_href_desc_desc_30128 = "이탈 상태의 그라디우스는 리더가 될 수 없으며, 파티의 연결을 따라 출전하지 않는다.",
  str_skill_href_desc_name_30129 = "잔영",
  str_skill_href_desc_desc_30129 = "파티/적이 지나가면 잔영은 사라지며, 그라디우스가 파티로 돌아온다.",
