  str_skill_name_1100201 = "체이스비 소환",
  str_skill_desc_1100201 = "체이스비 룬 4개를 소환하며, 체이스비 룬은 1턴 후 체이스비로 변한다.",
  str_skill_desc_1200201 = "체이스비 룬 2개를 소환하며, 체이스비 룬은 1턴 후 체이스비로 변한다.",
  str_skill_name_80001 = "주머니·전기 충격",
  str_skill_name_80002 = "주머니·스톤 히트",
  str_skill_name_80003 = "주머니·응급 조치",
  str_skill_name_590028103 = "크로스 다크매터",
  str_skill_desc_590028103 = "다크 서머너가 십자형 최대 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_590028104 = "비컨 소환",
  str_skill_desc_590028104 = "다크 서머너가 주변에 비컨 2개를 소환한 후 모든 비컨의 HP를 회복시킨다.",
  str_skill_name_590028105 = "비컨 소환",
  str_skill_desc_590028105 = "다크 서머너가 주변에 비컨 3개를 소환한 후 모든 비컨의 HP를 회복시킨다.",
  str_skill_name_590028106 = "에너지 축적I",
  str_skill_desc_590028106 = "다크 서머너가 제자리에서 에너지를 축적해 대규모 범위 공격을 준비한다. 비컨의 수가 많을수록 공격 범위가 커진다.",
  str_skill_name_590028107 = "에너지 축적II",
  str_skill_desc_590028107 = "다크 서머너가 목표 근처로 순간이동해 에너지를 축적하여 대규모 범위 공격을 준비한다. 비컨의 수가 많을수록 공격 범위가 커진다.",
  str_skill_name_590028108 = "침묵",
  str_skill_desc_590028108 = "다크 서머너가 축적한 에너지 서클을 터트려 좁은 범위에 피해를 입힌다.",
  str_skill_name_590028109 = "적막",
  str_skill_desc_590028109 = "다크 서머너가 축적한 에너지 서클을 터트려 넓은 범위에 피해를 입힌다.",
  str_skill_name_590028110 = "공허",
  str_skill_desc_590028110 = "다크 서머너가 축적한 에너지 서클을 터트려 전체 범위에 피해를 입힌다.",
  str_skill_desc_510001 = "발톱을 휘둘러 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510002 = "단단한 머리로 공격 범위 내 대상에게 충돌한다.",
  str_skill_desc_510003 = "두 주먹을 휘둘러 공격 범위 내 대상을 공격한다.",
  str_skill_desc_511003 = "두 주먹을 휘둘러 공격 범위 내 대상을 공격하며, 다음 턴에 주변 적에게 피해를 입히고 스턴시킨다.",
  str_skill_desc_510004 = "공격 범위 내의 동일한 행 또는 열에 있는 대상에게 원거리 공격을 가한다.",
  str_skill_desc_510005 = "이빨로 공격 범위 내 대상을 물어뜯는다.",
  str_skill_desc_510006 = "턴마다 프로버를 전장에 소환한다.",
  str_skill_desc_510007 = "턴마다 그레이웜을 전장에 소환한다. 전장 내 그레이웜이 5마리가 되면 더는 소환할 수 없다.",
  str_skill_desc_5100061 = "턴마다 체이스비를 전장에 소환한다.",
  str_skill_desc_5100062 = "턴마다 드레드블레이드를 전장에 소환한다.",
  str_skill_desc_5100063 = "턴마다 다크 하운드를 전장에 소환한다.",
  str_skill_desc_5100064 = "턴마다 데드아이를 전장에 소환한다.",
  str_skill_desc_5100071 = "턴마다 암귀를 전장에 소환한다.",
  str_skill_desc_1000071 = "턴마다 버스터웜을 전장에 소환한다.",
  str_skill_desc_510008 = "턴마다 백야성 장창병 1명을 전장에 소환한다.",
  str_skill_desc_510009 = "체이스비가 꼬리의 가시로 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510010 = "드레드블레이드가 칼날을 사용해 공격 범위 내 대상을 2회 공격한다.",
  str_skill_desc_29203121 = "프라이드 스피어가 칼날을 휘둘러 공격 범위 내 대상을 2회 공격하고, 출혈 상태를 추가한다.",
  str_skill_desc_29203123 = "프라이드 스피어가 칼날을 휘둘러 공격 범위 내 대상을 2회 공격하고, 출혈 및 극한의 피로 상태를 추가한다.",
  str_skill_desc_510011 = "블랙박서가 특제 무기로 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510012 = "배리어를 펼쳐 공격을 3회 막을 수 있다.",
  str_skill_desc_510013 = "레이저로 자신과 1칸 떨어진 대상을 공격한다.",
  str_skill_desc_510014 = "공격 범위 내 대상을 공격하며, 공격 후 필드 내 원하는 위치로 순간이동한다.",
  str_skill_desc_510015 = "장창으로 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510016 = "큰 방패로 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510017 = "총기를 사용해 공격 범위 내 동일한 1행 또는 1열의 대상에게 원거리 공격을 가한다.",
  str_skill_desc_510018 = "주변 사방의 전방 1칸에 피해를 1회 입히고, 명중한 대상을 1칸 넉백시킨다.",
  str_skill_desc_510019 = "자신의 전방 넓은 범위에 피해를 입힌다.",
  str_skill_desc_510020 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_510021 = "전방 3줄에 피해를 입히며, 적중한 대상을 넉백시킨다.",
  str_skill_desc_510022 = "다크매터를 소환해 자신을 보호하며, 다크매터 단계마다 피해에 1회 면역된다.",
  str_skill_desc_510023 = "범위 내 대상에게 화염 피해를 입힌다.",
  str_skill_desc_510024 = "포탄을 발사해 직선상의 대상을 넉백시킨다.",
  str_skill_desc_510025 = "컨트롤러를 건드리면 석궁탑 방향으로 1발의 화살을 발사해 명중한 대상에게 피해를 입힌다.",
  str_skill_desc_510026 = "피니가 에너지를 구동해 공격 범위 내 대상에게 원거리 공격을 가한다.",
  str_skill_desc_510027 = "피니가 에너지를 구동해 필릭스의 생명력을 회복시킨다.",
  str_skill_desc_510028 = "필릭스가 무기를 휘둘러 방어하고, 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510029 = "필릭스가 무기 방어에 에너지를 주입한 후 땅을 내리치며, 범위 내 대상에게 피해를 입히고 스턴시킨다.",
  str_skill_desc_510030 = "버서커가 두 주먹으로 땅을 강하게 내리쳐 범위 내 대상에게 피해를 입히고 스턴시킨다.",
  str_skill_desc_510031 = "2턴마다 자신의 주변 1서클 내 대상에게 피해를 1회 입힌다.",
  str_skill_desc_510032 = "통과한 칸에 스파이크를 설치한다. 스파이크는 통과하는 대상에게 피해를 입힌다.",
  str_skill_desc_510033 = "범위 내 대상에게 피해를 입히며, 명중한 대상은 넉백된다.",
  str_skill_desc_510034 = "범위 내 대상을 1회 공격한다.",
  str_skill_desc_510035 = "보레돔이 힘을 응축해 대규모 십자 범위에 불 속성 공격을 준비하며, 명중한 대상에게 피해를 입히고 작열을 부여한다. 힘을 응축할 때는 차단할 수 없다.",
  str_skill_desc_510036 = "보레돔이 주변 1서클에서 자신의 속성과 동일한 칸의 에너지를 흡수하고 범위 내 대상을 공격한다(흡수한 칸이 많을수록 피해 증가). 적중 시 작열 상태가 부여된다.",
  str_skill_desc_510037 = "보레돔이 힘을 응축해 대규모 십자 범위에 번개 속성 공격을 준비한다. 명중한 대상에게 피해를 입히고 마비 효과를 부여한다. 힘을 응축할 때는 차단할 수 없다.",
  str_skill_desc_510038 = "보레돔이 주변 1서클에서 자신의 속성과 동일한 칸의 에너지를 흡수하고 범위 내 대상을 공격한다(흡수한 칸이 많을수록 피해 증가). 적중 시 마비 상태가 부여된다.",
  str_skill_desc_500039 = "스예트가 굵은 꼬리를 사용해 자신의 공격 범위 내 대상을 공격하며, 2회의 피해 효과를 입힌다.",
  str_skill_desc_500040 = "샤를이 꼬리에 응축된 에너지 스파이크를 사용해 공격 범위 내 대상에게 원거리 공격을 가하며, 2회의 피해 효과를 입힌다.",
  str_skill_desc_510039 = "스예트가 굵은 꼬리를 사용해 자신의 공격 범위 내 대상을 공격한다.",
  str_skill_desc_510040 = "샤를이 꼬리에 응축된 에너지 스파이크를 사용해 공격 범위 내 대상에게 원거리 공격을 가한다.",
  str_skill_desc_510041 = "컨트롤러를 건드리면 화살탑이 위치한 방향으로 1발의 독화살을 발사하며, 명중한 대상에게 피해를 입히고 중독 상태를 부여한다.",
  str_skill_desc_510042 = "컨트롤러를 건드리면 화살탑이 위치한 방향으로 1발의 마비 화살을 발사한다. 명중당한 오로리안은 이동할 수 없으며, 다음 턴에도 1칸만 이동할 수 있다.",
  str_skill_desc_510043 = "스타 봄버를 보유한 장치. 항상 미사일 사일로 1개를 적재하고 있다.",
  str_skill_desc_510044 = "타바드가 발톱을 휘둘러 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_510045 = "모든 대상에게 피해를 1회 입힌다.",
  str_skill_desc_510046 = "유니메트가 제작한 신비한 도구. 해당 칸을 지나면 효과가 발동된다. 전체 오로리안의 공격력이 유니메트의 공격력의 10%만큼 증가한다.",
  str_skill_desc_510047 = "유니메트가 제작한 신비한 도구. 해당 칸을 지나면 효과가 발동된다. 파티의 방어력이 유니메트 방어력의 10%만큼 증가한다.",
  str_skill_desc_80001 = "유니메트가 낙뢰 결정을 모방해 제작한 모방품. 해당 칸을 지나면 효과가 발동된다. 발동 시 번개를 소환해 모든 적 대상에게 유니메트 50%의 피해를 입힌다.",
  str_skill_desc_80002 = "유니메트가 운석 결정을 모방해 제작한 모방품. 해당 칸을 지나면 효과가 발동된다. 발동 시 운석을 소환해 HP가 가장 높은 적 대상에게 유니메트 100%의 피해를 입힌다.",
  str_skill_desc_80003 = "유니메트가 제작한 신비한 도구. 해당 칸을 지나면 효과가 발동된다. 전체 오로리안 HP가 유니메트의 공격력의 100%만큼 회복된다.",
  str_skill_desc_510048 = "최대 HP의 20%를 회복한다.",
  str_skill_desc_5100482 = "최대 HP의 10%를 회복한다.",
  str_skill_desc_510049 = "출전한 모든 오로리안의 스킬 턴 수가 1 감소한다.",
  str_skill_desc_510050 = "넉백될 수 있으며, 넉백 과정에서 대상에 부딪히거나 가로막히면 큰 폭발을 일으키고 폭발 지점 및 주변 1서클에 범위 피해를 입힌다.",
  str_skill_desc_510051 = "전투 구역에 놓인 단단한 돌이다. 부서지지 않으며, 원거리 탄도 공격을 막을 수 있다.",
  str_skill_desc_510052 = "평범한 암석이다. 범위 피해 스킬로 파괴할 수 있다.",
  str_skill_desc_510053 = "보물상자를 여는 스위치다. 트랩을 3개 밟으면 가운데의 보물상자를 열 수 있다.",
  str_skill_desc_510054 = "옛 수도에서 대량의 물자를 보관한 보물상자다. 보물상자 주변의 제어 스위치 3개를 밟으면 보물상자를 열어 대량의 물자를 획득할 수 있다.",
  str_skill_desc_500216 = "보링거가 다음 턴에 에너지 충전 상태에 진입한다. 에너지 충전 상태에서 스타 봄버가 중간의 암귀 위치에 명중할 경우 보링거는 1턴간 마비 상태가 된다.",
  str_skill_desc_510216 = "보링거가 스타 봄버를 시전한 후 에너지 충전 상태에 진입한다. 에너지 충전 상태에서 스타 봄버가 중간의 암귀 위치에 명중할 경우 보링거가 마비 상태에 진입한다. 1턴간 지속.",
  str_skill_desc_500217 = "보링거가 보드 내 2*2구역 6개에 폭열 폭탄 공격을 시전해 구역 내 대상을 공격한다(스타 봄버 중앙 명중 시 보링거는 마비 상태가 됨).",
  str_skill_desc_500218 = "보링거가 축적한 에너지를 방출해 모든 적에게 피해를 입히고 넉백시킨다.",
  str_skill_name_510219 = "착란",
  str_skill_desc_510219 = "범위 내의 대상을 1회 공격하며, 모든 오로리안의 액티브 스킬 쿨다운 턴이 1 증가한다.",
  str_skill_name_510220 = "리프 어택",
  str_skill_desc_510220 = "도약해 범위 내의 대상을 1회 공격한다.",
  str_skill_name_510221 = "루미나 체인",
  str_skill_desc_510221 = "루미나를 봉인한다. 자신의 주변 1서클의 칸을 잠그며, 잠긴 칸은 색을 변경할 수 없다.",
  str_skill_name_510222 = "스나이퍼",
  str_skill_desc_510222 = "범위 내 대상에게 원거리 공격을 1회 가하며, 데드아이의 거리가 대상과 멀수록 입히는 피해가 증가한다.",
  str_skill_name_510223 = "샤프 클로",
  str_skill_desc_510223 = "범위 내 대상을 1회 공격한다.",
  str_skill_name_510224 = "힘의 발산",
  str_skill_desc_510224 = "범위 내 대상에게 피해를 입히며, 동시에 범위 내 모든 칸을 부순다.",
  str_skill_name_510225 = "증오",
  str_skill_desc_510225 = "범위 내 대상에게 피해를 입히며, 대상 명중 후 자신의 속성과 동일한 리더가 아닌 오로리안에게 증오를 시전한다. 증오에 당한 오로리안은 출전할 수 없으며, 액티브 스킬을 사용할 수 없다. 커스 사망 시 해당 속성과 동일한 오로리안이 지닌 증오 효과가 제거된다.",
  str_skill_name_510226 = "혼의 불꽃",
  str_skill_desc_510226 = "범위 내 대상에게 원거리 공격을 1회 가한다.",
  str_skill_name_510227 = "속박의 촉수",
  str_skill_desc_510227 = "대상에게 돌격, 자신의 주변으로 충돌시키며, 자신의 위치 및 주변 2서클 칸의 속성을 변경한다.",
  str_skill_name_510228 = "파동의 빛",
  str_skill_desc_510228 = "범위 내 대상에게 대량의 피해를 입힌다.",
  str_skill_name_510229 = "평온한 햇살",
  str_skill_desc_510229 = "범위 내의 대상에게 비교적 높은 피해를 입히며, 대상 명중 시 주변 1서클 칸의 속성을 변경한다.",
  str_skill_name_1001811 = "월륜",
  str_skill_desc_1001811 = "레체가 월륜으로 변해 범위 내 대상에게 피해를 입히며, 공격 범위 중간 구역의 칸을 잠근다.",
  str_skill_name_1001821 = "달의 능멸",
  str_skill_desc_1001821 = "레체가 에너지를 발산해 가로+세로 4열 범위에 피해를 입히며, 랜덤으로 공격 범위 내 8개의 칸을 잠근다.",
  str_skill_name_1001831 = "달의 기세",
  str_skill_desc_1001831 = "레체가 월륜으로 변해 범위 내의 대상에게 피해를 입히며, 동시에 필드의 반대편으로 이동한다. 이동 후 자신의 주변 2서클 내의 칸을 잠그며, 잠긴 칸은 색 변경을 진행할 수 없다.",
  str_skill_name_1002111 = "분쇄",
  str_skill_desc_1002111 = "범위 내의 대상에게 피해를 입힌다. 대상에게 명중 시 대상을 외곽까지 넉백시킨다.",
  str_skill_name_1002121 = "바람의 기세",
  str_skill_desc_1002121 = "자신의 주변 2서클 내의 대상에게 대량의 피해를 입히고 넉백시키며, 공격 범위 내의 모든 칸을 분쇄한다.",
  str_skill_name_1002131 = "솟구치는 힘",
  str_skill_desc_1002131 = "가로+세로 4열 범위에 피해를 입힌다. 대상에게 명중 시 대상을 외곽까지 넉백시킨다.",
  str_skill_name_1002211 = "강화 낙뢰 부적",
  str_skill_desc_1002211 = "대량의 낙뢰를 소환해 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1002221 = "날카로운 칼날",
  str_skill_desc_1002221 = "이동 후 자신의 주변 십자형 최대 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1002231 = "콜로서스-거친 음파",
  str_skill_desc_1002231 = "슈모르가 콜로서스를 제어해 음파 공격으로 필드의 모든 대상을 공격한다.",
  str_skill_name_1002251 = "악령 소환",
  str_skill_desc_1002251 = "슈모르가 이동 후 대상을 외곽까지 넉백시키며, 근처에 악령을 소환한다. 소환된 악령은 자신의 주변 2서클 내 대상에게 피해를 입힌다.",
  str_skill_name_1002261 = "에너지 광폭",
  str_skill_desc_1002261 = "슈모르가 광폭의 에너지를 발산해 모든 적을 공격한다. 공격당하는 대상이 슈모르와 멀수록 받는 피해가 증가한다.",
  str_skill_name_1002271 = "질풍",
  str_skill_desc_1002271 = "슈모르가 대상과 멀리 떨어진 후, 공격 범위에 질풍을 일으켜 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_29002421 = "연소",
  str_skill_desc_29002421 = "자신의 전방 5열 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_29002422 = "불타는 대지",
  str_skill_desc_29002422 = "화염을 분사해 전체화면에 피해를 입히고, 추가로 외곽 4개 열 범위 내의 대상에게 높은 피해를 1회 입힌다.",
  str_skill_name_29002423 = "데드아이 소환",
  str_skill_desc_29002423 = "데드아이 2마리를 전장에 소환한다.",
  str_skill_name_1002603 = "에너지 차지",
  str_skill_desc_1002603 = "에너지를 모아 전방의 대상을 공격하고 명중한 대상을 넉백시킨다.",
  str_skill_name_1002604 = "반사 배리어",
  str_skill_desc_1002604 = "배리어를 펼쳐 자신이 받는 피해를 감소시킨다. 배리어가 존재할 때 공격을 당하면 받는 일부 피해를 대상에게 반사한다.",
  str_skill_name_1002605 = "정지 상태 수리",
  str_skill_desc_1002605 = "T1024가 제자리에 멈춰 손상 부위를 수리하며, 자신의 HP를 일정량 회복한다.",
  str_skill_name_1004501 = "속박",
  str_skill_desc_1004501 = "범위 내의 대상에게 피해를 입히며, 대상에게 명중 시 대상의 주변 1서클의 칸을 잠근다. 잠긴 칸은 색 변경을 진행할 수 없다.",
  str_skill_name_1002702 = "동적 상태 수리",
  str_skill_desc_1002702 = "공격 범위 내의 동일한 행 또는 열에 있는 대상에게 원거리 공격을 가한다.",
  str_skill_name_1000901 = "기회 포착",
  str_skill_desc_1000901 = "대상과의 거리에 따라 행동 방식이 결정된다. 거리가 가까울 경우 대상에게 대량의 피해를 입히며, 멀 경우 대상을 자신의 주위로 끌어당긴다.",
  str_skill_name_1000911 = "기회 포착",
  str_skill_desc_1000911 = "대상과의 거리에 따라 행동 방식을 결정한다. 대상과의 거리가 가까울 시 대상에게 대량의 피해를 입히고, 멀 시에는 대상을 자신의 근처로 끌어당기며, 이후 자신의 주변 1서클에 스파이크를 소환한다.",
  str_skill_name_1000921 = "임기응변",
  str_skill_desc_1000921 = "대상과의 거리에 따라 행동 방식을 결정하며, 자신의 뒤에 스파이크를 생성한다. 대상과의 거리가 가까울 시 대상에게 대량의 피해를 입히며, 멀 시에는 대상을 자신의 근처로 끌어당긴다.",
  str_skill_name_1000931 = "임기응변",
  str_skill_desc_1000931 = "대상과의 거리에 따라 행동 방식을 결정하며, 자신의 뒤에 스파이크를 생성한다. 대상과의 거리가 가까울 시 대상에게 대량의 피해를 입히며, 멀 시에는 대상을 자신의 근처로 끌어당긴다.",
  str_skill_name_1001001 = "에너지 탈취",
  str_skill_desc_1001001 = "액티브 스킬의 쿨다운 턴 수가 가장 적은 오로리안의 에너지를 빼앗으며, 대상의 액티브 스킬 쿨다운 턴 수가 3 증가한다.",
  str_skill_name_1001611 = "난-고도",
  str_skill_desc_1001611 = "범위 내의 대상을 자신의 주변으로 충돌시키며, 자신의 위치 및 주변 2서클 칸의 속성을 변경한다.",
  str_skill_name_1001621 = "난-폭발",
  str_skill_desc_1001621 = "범위 내의 대상에게 비교적 높은 피해를 입히며, 대상 명중 시 위치 주변 1서클 칸의 속성을 변경한다.",
  str_skill_name_1001631 = "난-잿더미",
  str_skill_desc_1001631 = "필드 내 랜덤으로 2*2 범위 7곳에 피해를 입히며, 대상 명중 시 위치 주변 1서클 칸의 속성을 변경한다.",
  str_skill_name_1001711 = "스펙터-버스터",
  str_skill_desc_1001711 = "주변 2서클 범위 내의 대상에게 피해를 입히며, 대상 명중 시 파티 내 모든 오로리안의 액티브 스킬 쿨다운 턴 수가 2 증가한다.",
  str_skill_name_1001721 = "스펙터-여진",
  str_skill_desc_1001721 = "십자형 최대 범위에 피해를 입히며, 대상 명중 시 파티 내 모든 오로리안의 액티브 스킬 쿨다운 턴 수가 2 증가한다.",
  str_skill_name_1001741 = "멸-꼬리 공격",
