  str_skill_name_1001751 = "멸-여운",
  str_skill_desc_1001751 = "십자형 최대 범위에 피해를 입히며, 대상 명중 시 파티 내 모든 오로리안의 액티브 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_name_1001771 = "꼬리 공격",
  str_skill_desc_1001771 = "십자형 최대 범위에 피해를 입히며, 대상 명중 시 액티브 스킬의 쿨다운 턴 수가 가장 적은 오로리안의 쿨다운 턴 수가 3 증가한다.",
  str_skill_name_1001781 = "에너지 탈취",
  str_skill_desc_1001781 = "범위 내의 대상에게 피해를 입히며, 대상 명중 시 액티브 스킬의 쿨다운 턴 수가 가장 적은 오로리안의 쿨다운 턴 수가 3 증가한다.",
  str_skill_name_500411 = "에너지 공급",
  str_skill_desc_500411 = "비컨은 제자리에 머물며 에너지 체인을 통해 다크 서머너의 피해를 감소시킨다.",
  str_skill_name_500244 = "낙뢰 결정",
  str_skill_desc_500244 = "신비한 빛의 수정. 해당 칸을 지나갈 때 효과를 발동시킬 수 있다. 발동 시 번개를 소환해 모든 적 대상을 공격한다.",
  str_skill_name_500245 = "운석 결정",
  str_skill_desc_500245 = "신비한 빛의 수정. 해당 칸을 지나갈 때 효과를 발동시킬 수 있다. 발동 시 운석을 소환해 적 중 HP가 가장 높은 대상을 공격한다.",
  str_skill_name_500170 = "낫",
  str_skill_desc_500170 = "고스트가 속성 공격을 1회 입힌다.",
  str_skill_name_500171 = "낫+",
  str_skill_desc_500171 = "광폭한 고스트가 속성 공격을 2회 입히며, 피해가 대폭 증가한다.",
  str_skill_name_500172 = "머피의 법칙",
  str_skill_desc_500172 = "고스트가 십자형 범위에 속성 피해를 입힌다.",
  str_skill_name_500173 = "머피의 법칙+",
  str_skill_desc_500173 = "광폭한 고스트가 모든 칸에 속성 피해를 입힌다.",
  str_skill_name_500174 = "환영의 지원",
  str_skill_desc_500174 = "환영을 1개 소환해 고스트 본체와 함께 싸운다. 필드에 이미 환영이 있을 경우 기존 환영을 회수한 후 새로운 환영을 다시 소환한다.",
  str_skill_name_500227 = "탐색",
  str_skill_desc_500227 = "실러가 자신의 속성과 동일한 칸 근처로 이동해 칸의 속성 에너지를 흡수할 준비를 한다.",
  str_skill_name_500228 = "에너지 축적",
  str_skill_desc_500228 = "실러가 자신 및 주변 1서클 내 동일 속성 칸 에너지를 흡수한 후, 모든 적에게 에너지볼 공격을 시전한다. 흡수한 칸수가 많을수록 피해가 증가한다.",
  str_skill_desc_520228 = "실러가 자신 및 주변 1서클 내 동일 속성 칸 에너지를 흡수한 후, 범위 내 불 속성 칸을 파괴한다. 모든 적에게 에너지볼 공격을 시전한다. 흡수한 칸수가 많을수록 피해가 증가한다.",
  str_skill_name_501001 = "환상 번개",
  str_skill_desc_501001 = "블레이저가 보드의 랜덤 구역에 번개를 소환해 속성 피해를 입히고 대상을 마비 상태에 빠트린다.",
  str_skill_name_501003 = "불의 비",
  str_skill_desc_501003 = "블레이저가 보드의 랜덤 위치에 불의 비를 소환해 속성 피해를 입히며, 대상을 작열 상태에 빠트린다.",
  str_skill_name_501011 = "원거리 공격",
  str_skill_desc_501011 = "다크 워커가 자신의 주변 2칸 십자형 최대 범위에 충격파를 방출해 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501015 = "격려",
  str_skill_desc_501015 = "다크 워커가 아군 대상이 가장 많은 구역으로 이동해 자신의 주변 12칸의 아군 대상에게 강세의 인장을 부여한다. 인장을 지닌 대상은 공격력이 증가한다.",
  str_skill_name_501021 = "헤딩슛",
  str_skill_desc_501021 = "버스터웜이 단단한 머리로 범위 내 대상에게 피해를 입힌다. HP가 낮을 시 불안정 상태에 진입하며, 대상을 향해 이동한 후 자폭한다.",
  str_skill_name_501025 = "잿더미",
  str_skill_desc_501025 = "버스터웜이 마지막 생명을 불태워 이동 후 자폭해 주변 1서클 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501031 = "오염",
  str_skill_desc_501031 = "레지스터가 범위 내의 목표를 공격한다. 레지스터는 강한 속성 저항력을 지니고 있으므로, 유리한 속성으로 공격해야만 더 많은 피해를 줄 수 있다.",
  str_skill_name_501032 = "오염",
  str_skill_desc_501032 = "레지스터가 범위 내 대상을 공격하고, 이동 경로상의 칸 속성을 자신과 동일한 속성으로 변환시킨다.",
  str_skill_name_501042 = "비명",
  str_skill_desc_501042 = "거츠더의 부하가 자신의 주변 2서클 범위 내 대상에게 파열의 인장을 추가한다. 인장 개수마다 대상의 방어력을 일정량 감소시키며, 인장 개수가 많을수록 방어력이 감소한다.",
  str_skill_name_501052 = "콜로서스의 칼날",
  str_skill_desc_501052 = "슈모르가 자신의 십자형 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501053 = "번개의 힘",
  str_skill_desc_501053 = "슈모르가 번개의 힘을 소환해 필드의 여러 랜덤 구역에 피해를 입힌다.",
  str_skill_name_501054 = "콜로서스-거친 음파",
  str_skill_desc_501054 = "슈모르가 콜로서스를 제어해 음파 공격으로 필드의 모든 대상을 공격한다.",
  str_skill_name_501056 = "콜로서스-촉수",
  str_skill_desc_501056 = "슈모르가 콜로서스를 제어해 전방의 큰 면적에 범위 피해를 입힌다.",
  str_skill_name_501057 = "콜로서스-거친 음파",
  str_skill_desc_501057 = "슈모르가 콜로서스를 제어해 필드 전체를 공격하고 랜덤 위치에 낙뢰 결정을 소환한다. 오로리안이 낙뢰 결정을 통과하면 결정은 사라진다.",
  str_skill_name_501058 = "낙뢰 부적 소환",
  str_skill_desc_501058 = "슈모르가 필드의 랜덤 위치에 낙뢰 결정을 소환한다. 낙뢰 결정을 밟지 않으면 슈모르가 다음 턴에 해당 위치에 낙뢰를 소환해 피해를 입힌다.",
  str_skill_name_501059 = "번개의 소리",
  str_skill_desc_501059 = "슈모르가 낙뢰 결정 위치에 낙뢰를 소환해 대량의 피해를 입히며, 명중한 대상을 마비 상태에 빠트린다. 오로리안이 낙뢰 결정을 지나가면 결정이 사라진다.",
  str_skill_name_501061 = "영역",
  str_skill_desc_501061 = "슈모르가 자신의 공격 범위 내 대상을 향해 원거리 공격을 시전한다.",
  str_skill_name_501062 = "진동 폭발",
  str_skill_desc_501062 = "슈모르가 자신의 범위 내 대상에게 진동 공격으로 비교적 높은 피해를 입힌다.",
  str_skill_name_501063 = "동기화의 경지",
  str_skill_desc_501063 = "슈모르가 HP를 동기화한다. 남은 HP가 가장 높은 슈모르를 기준으로 모든 슈모르의 HP를 동기화하며, 자신의 HP를 최대 30% 회복한다.",
  str_skill_desc_511063 = "슈모르가 HP를 동기화한다. 남은 HP가 가장 높은 슈모르를 기준으로 모든 슈모르의 HP를 동기화하며, 다른 슈모르가 없을 경우 자신의 최대 HP의 20%를 즉시 회복한다.",
  str_skill_name_501082 = "시종 소환",
  str_skill_desc_501082 = "거츠더가 필드의 랜덤 위치에 이동할 수 없는 부하 2명을 소환한다.",
  str_skill_name_501083 = "대지 균열",
  str_skill_desc_501083 = "거츠더가 범위 내 대상을 공격하고, 대상에게 파열의 인장을 1회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_name_501084 = "비명",
  str_skill_desc_501084 = "거츠더가 포효해 범위 내 적 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_name_501085 = "폭파",
  str_skill_desc_501085 = "거츠더가 대상이 지닌 파열의 인장을 폭발시켜 대상에게 대량의 피해를 입힌다. 인장 개수가 많을수록 피해가 증가한다.",
  str_skill_name_501087 = "시종 소환 강화",
  str_skill_desc_501087 = "거츠더가 필드의 랜덤 위치에 이동할 수 없는 부하 3명을 소환한다.",
  str_skill_name_501088 = "강화 대지 균열",
  str_skill_desc_501088 = "거츠더가 미친 듯이 범위 내 대상을 2회 공격하고, 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_name_501089 = "비명 강화",
  str_skill_desc_501089 = "거츠더가 최후의 포효로 범위 내 대상에게 파열의 인장을 3회 부여한다. 인장 개수가 많을수록 대상의 방어력이 낮아진다.",
  str_skill_name_501092 = "어둠의 상처",
  str_skill_desc_501092 = "맥거핀이 눈앞의 공간을 왜곡하고 갈라 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501093 = "윤회의 사자",
  str_skill_desc_501093 = "맥거핀이 곧 닥칠 백야의 파도를 위해 힘을 축적한다.",
  str_skill_name_501095 = "백야의 파도",
  str_skill_desc_501095 = "맥거핀이 필드의 고정 구역을 돌아가며 폭격한다.",
  str_skill_name_501192 = "어둠의 상처",
  str_skill_desc_501192 = "맥거핀·스모가 눈앞의 공간을 왜곡하고 갈라 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501193 = "윤회의 사자",
  str_skill_desc_501193 = "맥거핀·스모가 곧 닥칠 백야의 파도를 위해 힘을 축적한다.",
  str_skill_name_501195 = "백야의 파도",
  str_skill_desc_501195 = "맥거핀·스모가 필드의 고정 구역을 돌아가며 폭격한다.",
  str_skill_name_501102 = "땅 뚫기",
  str_skill_desc_501102 = "마레이셀",
  str_skill_name_501103 = "그리트 플레임",
  str_skill_desc_501103 = "화염을 분사해 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_501104 = "소환",
  str_skill_desc_501104 = "마레이셀이 버스터웜 3마리를 전장에 소환한다.",
  str_skill_desc_580043104 = "마레이셀이 블라스터 3마리를 전장에 소환한다.",
  str_skill_name_501113 = "암석 분열",
  str_skill_desc_501113 = "블랙혼이 범위 내 대상을 공격하고 넉백시킨다.",
  str_skill_name_501114 = "수정 소환",
  str_skill_desc_501114 = "블랙혼이 필드의 랜덤 위치에 증식의 수정을 2개 소환한다.",
  str_skill_name_501115 = "지진 베기",
  str_skill_desc_501115 = "블랙혼이 범위 내 대상을 공격하고 넉백시킨다. 대상이 넉백되면 해당 대상의 앞에 원소 암석 1개를 추가로 생성한다.",
  str_skill_name_501116 = "암석 추락",
  str_skill_desc_501116 = "블랙혼이 모든 원소 암석을 응축해 대상에게 피해를 입힌다. 원소 암석 수가 많을수록 블랙혼이 입히는 피해가 증가한다.",
  str_skill_name_501141 = "암석 소환",
  str_skill_desc_501141 = "수정 증식",
  str_skill_name_515002 = "만연",
  str_skill_desc_515002 = "솔모프가 대상이 있는 방향을 향해 두 행 넓이의 충격파 1개를 발사해 명중한 대상에게 피해를 입힌다.",
  str_skill_name_515003 = "솔모프 함정",
  str_skill_desc_515003 = "솔모프가 범위 내 대상에게 피해를 입히고 자신의 곁으로 끌어당긴다. 대상 공격 성공 여부와 관계없이 자신의 주변 2서클의 칸을 초기화한다.",
  str_skill_name_534001 = "탈출 계획",
  str_skill_name_510244 = "심판의 돌진",
  str_skill_desc_510244 = "타바드가 가장자리로 순간이동해 대상이 위치한 곳을 향해 돌진할 준비를 한다.",
  str_skill_desc_534001 = "도주 실력 하나는 끝내주는 도굴꾼들은 어떻게든 추격자를 피해 달아납니다!",
  str_skill_name_500638 = "땅의 불",
  str_skill_desc_500638 = "맥거핀이 땅을 갈라 땅의 불을 방출해 범위 내 대상에게 피해를 입히고, 다크 하운드 2마리를 소환한다.",
  str_skill_desc_5006381 = "맥거핀이 땅을 갈라 땅의 불을 방출해 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_500639 = "멸화",
  str_skill_desc_500639 = "맥거핀이 응축한 힘을 터트려 전방 3열 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_500640 = "화염의 기운",
  str_skill_desc_500640 = "맥거핀이 날개를 흔들어 푸른 화염을 방출, 모든 적에게 피해를 입힌다.",
  str_skill_desc_5006401 = "맥거핀이 날개를 흔들어 푸른 화염을 방출, 모든 적에게 피해를 입히고 자신을 위해 피해면역 배리어를 펼친다.",
  str_skill_desc_49005111 = "맥거핀이 날개를 흔들어 푸른 화염을 방출, 모든 적에게 피해를 입히고 3칸 넉백시킨다. 이후 고정 위치에 섀도프리크를 소환한다.",
  str_skill_name_505106 = "배후의 습격",
  str_skill_desc_505106 = "스페큘러가 빛의 벽에서 돌진해 대상에게 피해를 입히고 대상이 위치한 행 또는 열의 칸 속성을 초기화한다.",
  str_skill_name_505109 = "다크 타이드",
  str_skill_desc_505109 = "스페큘러가 이동 후 범위 내 대상에게 원거리 공격을 가하며, 턴마다 가장자리에서 환영을 1개 소환해 전장에 진입시킨다.",
  str_skill_name_504901 = "섀도우 어택",
  str_skill_desc_504901 = "환영이 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_505121 = "빛의 벽",
  str_skill_desc_505121 = "스페큘러가 변신한 물체다. 스페큘러는 적과 가장 가까운 빛의 벽에 숨는다(해당 빛의 벽은 공격당할 수 있음). 빛의 벽이 파괴되면 환영을 소환해 적을 공격하며, 빛의 벽 2개가 파괴되면 모든 빛의 벽이 사라져 스페큘러의 본체가 나타난다.",
  str_skill_name_500251 = "허리케인 스트림",
  str_skill_desc_500251 = "웬디의 깃털을 사용해 아군 캐릭터를 깃털이 있는 곳으로 전송한다.",
  str_skill_name_500252 = "스피어 스탭",
  str_skill_desc_500252 = "범위 내 대상을 1회 공격한다.",
  str_skill_name_1002811 = "장갑 암귀",
  str_skill_desc_1002811 = "운송 임무를 담당하는 암귀, 처치 시 운송 중인 나이티움을 획득할 수 있다.",
  str_skill_name_515121 = "빛의 벽",
  str_skill_desc_515121 = "스페큘러가 변신한 물체다. 스페큘러는 적과 가장 가까운 빛의 벽에 숨는다(해당 빛의 벽은 공격당할 수 있음). 빛의 벽이 파괴되면 환영을 소환해 적을 공격하며, 빛의 벽 3개가 파괴되면 모든 빛의 벽이 사라져 스페큘러의 본체가 나타난다.",
  str_skill_name_1003401 = "전투력 증가",
  str_skill_desc_1003401 = "허거가 주변 1서클 내의 암귀에게 빙의해 실드를 추가하고 공격력을 강화한다.",
  str_skill_name_1003421 = "이성 상실",
  str_skill_desc_1003421 = "이성을 잃은 허거가 주변 1서클 내의 오로리안에게 빙의해 지속적으로 오로리안의 이성 수치를 감소시킨다.",
  str_skill_name_1003501 = "회복",
  str_skill_desc_1003501 = "도엔의 주변 1서클 접근 시 체내에 녹아들어 도엔의 HP를 회복시킨다.",
  str_skill_name_1003502 = "강화 회복",
  str_skill_desc_1003502 = "도엔의 주변 1서클에 다가갈 시 체내에 녹아들어 도엔의 HP를 회복하며, 실드를 추가한다.",
  str_skill_name_1003601 = "피어나는 여명",
  str_skill_desc_1003601 = "자신의 주변 2서클 내 대상에게 대량의 피해를 입힌다.",
  str_skill_name_1003611 = "숲의 허리케인",
  str_skill_desc_1003611 = "허리케인을 일으켜 적 전체에 높은 피해를 입힌다. 필드 내 새벽의 정령의 수가 많을수록 입히는 피해가 증가한다.",
  str_skill_name_1003621 = "새벽의 정령 소환",
  str_skill_desc_1003621 = "도엔이 회복 능력을 지닌 새벽의 정령을 소환한다. 새벽의 정령이 도엔 주변 1서클 내로 이동하면 도엔의 HP를 회복시킨다.",
  str_skill_name_1003622 = "강화 새벽의 정령 소환",
  str_skill_desc_1003622 = "도엔이 회복 능력을 지닌 새벽의 정령을 소환한다. 새벽의 정령이 도엔 주변 1서클 내로 이동하면 도엔의 HP를 회복하고 실드를 추가한다.",
  str_skill_name_1003800 = "고립된 폰",
  str_skill_desc_1003800 = "이동 후 자신의 주변 십자형 4칸에 피해를 입힌다.",
  str_skill_name_1003901 = "다이렉트 히트",
  str_skill_desc_1003901 = "현재 위치의 십자형 방향으로 이동할 수 있으며, 이동 후 자신의 주변 1서클 내의 대상에게 피해를 입힌다. 이동 중 대상과 충돌할 경우 대상에게 비교적 높은 피해를 입히고 필드의 외곽까지 넉백시킨다.",
  str_skill_name_1003902 = "크리스크로스",
  str_skill_desc_1003902 = "현재 위치의 십자형 방향으로 이동할 수 있으며, 이동 후 자신의 주변 2서클 내의 대상에게 피해를 입힌다. 이동 중 대상과 충돌할 경우 대상에게 비교적 높은 피해를 입히고 필드의 외곽까지 넉백시킨다.",
  str_skill_name_1003912 = "응고화",
  str_skill_desc_1003912 = "공간과 함께 고정된 것처럼 이동 및 공격이 불가능해지며, 피해도 입지 않는다. 다음 웨이브 활성화 후 행동을 시작할 수 있다.",
  str_skill_name_1004001 = "리프 어택",
  str_skill_desc_1004001 = "이동 후 현재 위치의 십자형 4칸에 피해를 입힌다. 이동 위치에 대상이 있을 경우 대상에게 대량의 피해를 입히며, 해당 대상을 스턴 및 넉백시킨다.",
  str_skill_name_1004002 = "리프",
  str_skill_desc_1004002 = "이동 후 현재 위치의 주변 1서클에 피해를 입힌다. 이동 위치에 대상이 있을 경우 대상에게 대량의 피해를 입히며, 해당 대상을 스턴 및 넉백시킨다.",
  str_skill_desc_1104002 = "이동 후 현재 위치의 주변 1서클에 피해를 입히고 범위 내에 스파이크를 생성한다. 이동 위치에 대상이 있을 경우 대상에게 대량의 피해를 입히며, 해당 대상을 스턴 및 넉백시킨다.",
  str_skill_name_1004101 = "사선 공격",
  str_skill_desc_1004101 = "사선 방향으로 이동할 수 있으며, 이동 후 자신의 주변 십자형 최대 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1004102 = "사선 격파",
  str_skill_desc_1004102 = "사선 방향으로 이동할 수 있으며, 이동 후 자신의 주변 십자형 최대 범위 내 대상에게 피해를 입히고 대상의 방어를 감소시킨다.",
  str_skill_desc_1104102 = "사선 방향으로 이동할 수 있으며, 이동 후 자신의 주변 십자형 최대 범위 내 대상에게 피해를 입히고 대상의 방어를 대폭 감소시킨다.",
  str_skill_name_1004201 = "퀸사이드",
  str_skill_desc_1004201 = "자신의 주변 쌍십자형 최대 범위의 대상에게 대상의 최대 HP 퍼센트에 비례하는 피해를 입힌다.",
  str_skill_name_1004202 = "거점 수호",
  str_skill_desc_1004202 = "자신의 주변 쌍십자형 최대 범위의 대상에게 대상의 최대 HP 퍼센트를 기준으로 피해를 입힌다. 자신의 주변 8방향에 대상이 없을 경우 자신에게 방어 배리어를 추가하며, 추가로 아군 대상의 HP를 회복시킨다.",
  str_skill_desc_1104202 = "자신의 주변 쌍십자형 최대 범위의 대상에게 대상의 최대 HP 퍼센트를 기준으로 피해를 입힌다. 자신의 주변 8방향에 대상이 없을 경우 자신에게 방어 배리어를 추가하고, 플레이어의 이성 수치를 감소시키며, 추가로 아군 대상의 HP를 회복시킨다.",
  str_skill_name_1004301 = "호령",
  str_skill_desc_1004301 = "폰을 지휘해 폰의 주변 1서클 내 대상에게 피해를 입힌다.",
  str_skill_name_1004302 = "대항",
  str_skill_desc_1004302 = "범위 내 대상을 스킬 공격 범위까지 넉백시킨다.",
  str_skill_name_1004303 = "킹스 필드",
  str_skill_desc_1004303 = "필드 내 모든 적에게 피해를 입힌다.",
  str_skill_name_1006511 = "충돌",
  str_skill_desc_1006511 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1006521 = "블라스터",
  str_skill_desc_1006521 = "체내의 에너지를 폭발시켜 범위 내 대상에게 피해를 입히고, 현재 위치의 칸을 파괴한다.",
  str_skill_name_1007001 = "지둔",
  str_skill_desc_1007001 = "대상 범위에 부서진 칸이 있을 시 땅을 뚫고 대상 근처의 부서진 칸에서 나와 피해를 입히고, 주변의 칸을 부순다. 오로리안이 부서진 칸을 이동할 시 연쇄 수가 증가하지 않는다.",
  str_skill_name_1007011 = "대지 분쇄",
  str_skill_desc_1007011 = "대상의 주변에 부서진 칸이 없을 시 자신의 2칸 거리의 위치로 이동, 주변 1서클의 8개 칸을 분쇄한다. 오로리안이 부서진 칸을 이동할 시 연쇄 수가 증가하지 않는다.",
  str_skill_name_29010011 = "비명",
  str_skill_desc_29010011 = "대상 주변에 부서진 칸이 있을 시 대상 근처의 부서진 칸 위로 이동해 대상에게 피해를 입히고 대상을 넉백시킨다.",
  str_skill_name_29010012 = "경악",
  str_skill_desc_29010012 = "대상이 자신을 기준으로 쌍십자형 범위 내에 있을 시 대상의 근처로 이동, 대상에게 피해를 입히고 넉백시킨다. 동시에 대상과 자신 사이의 일직선 범위 내의 칸을 부순다.",
  str_skill_name_1007102 = "타격",
  str_skill_desc_1007102 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_10071021 = "범위 내 대상을 즉시 처치한다.",
  str_skill_desc_220091202 = "범위 내 모든 칸을 부수며, 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1007103 = "죽음의 타격",
  str_skill_desc_1007103 = "대상의 이전 턴 위치 및 주변 1서클에 공격을 시전하며, 대상이 범위 내에 있을 경우 대량의 피해를 입힌다.",
  str_skill_desc_1107103 = "대상의 이전 턴 위치 및 주변 1서클에 공격을 시전하며, 범위 내의 적을 즉시 처치한다.",
  str_skill_desc_220091201 = "대상의 이전 턴 위치 및 주변 1서클에 공격을 시전하며, 범위 내의 칸을 부수고, 범위 내의 적을 즉시 처치한다.",
  str_skill_name_1007104 = "음파 공격",
  str_skill_desc_1007104 = "범위 내 대상에게 피해를 입히고 대상을 넉백시킨다.",
  str_skill_desc_10071041 = "범위 내 대상에게 피해를 입히고 대상을 넉백시키며, 오로리안의 이성 수치를 감소시키는 텐타클로를 여러 개 소환한다.",
  str_skill_name_1007112 = "광선 타격",
  str_skill_desc_1007112 = "대상의 이전 턴 위치에 광선 타격을 시전하며, 경로 위치 및 목표 위치의 대상에게 피해를 입힌다. (몬스터 사망 시 2턴 후 제자리에서 부활)",
  str_skill_desc_10071121 = "대상의 이전 턴 위치에 광선 타격을 시전하며, 경로 위치 및 목표 위치의 대상에게 피해를 입힌다.",
  str_skill_name_1007113 = "강풍",
  str_skill_desc_1007113 = "범위 내 대상을 필드 중간 위치로 넉백시킨다. (몬스터 사망 시 2턴 후 제자리에서 부활)",
  str_skill_name_39004511 = "다크 타이드",
  str_skill_desc_39004511 = "스페큘러가 이동 후 범위 내 대상에게 원거리 공격을 가하며, 가장자리에서 환영을 2개 소환해 전장에 진입시킨다.",
  str_skill_name_39004512 = "배후의 습격",
  str_skill_desc_39004512 = "스페큘러가 대상 근처로 이동해 피해를 입히고, 대상 주변에 환영을 1개 소환한다.",
  str_skill_name_20005011 = "임기응변",
  str_skill_desc_20005011 = "대상과의 거리에 따라 행동 방식을 결정하며, 자신의 뒤에 스파이크를 생성한다. 대상과의 거리가 가까울 시 대상에게 대량의 피해를 입히며, 멀 시에는 대상을 자신의 근처로 끌어당긴다.",
  str_skill_name_20002441 = "암귀 소환",
  str_skill_desc_20002441 = "라치온이 턴마다 더 강력한 암귀를 전장에 소환한다.",
  str_skill_desc_20002411 = "턴마다 강력한 암귀를 전장에 소환한다.",
  str_skill_name_200024211 = "소환-드레드블레이드",
  str_skill_desc_200024211 = "턴마다 드레드블레이드를 전장에 소환한다.",
  str_skill_name_200024221 = "소환-드레드블레이드·스펠하운드",
  str_skill_name_200024231 = "소환-드레드블레이드&데드아이",
  str_skill_desc_200024221 = "턴마다 드레드블레이드와 스펠하운드를 전장에 소환한다.",
  str_skill_desc_200024231 = "턴마다 드레드블레이드와 데드아이를 전장에 소환한다.",
  str_skill_name_10000021 = "소환-스펠하운드",
  str_skill_desc_10000021 = "턴마다 스펠하운드를 전장에 소환한다.",
  str_skill_name_28002411 = "제압",
  str_skill_desc_28002411 = "노라가 턴마다 대상을 넉백시킴",
  str_skill_name_390041101 = "루인-대지 균열",
  str_skill_desc_390041101 = "거츠더가 범위 내 대상을 미친 듯이 2회 공격하고, 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 공격력이 낮아진다. 이후 거츠더가 지정 위치에 거츠더의 부하 4명을 소환한다.",
  str_skill_name_390041102 = "루인-대지 균열",
  str_skill_desc_390041102 = "거츠더가 범위 내 대상을 미친 듯이 2회 공격하고, 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 공격력이 낮아진다. 이후 거츠더가 지정 위치에 거츠더의 부하 4명을 소환한다.",
  str_skill_name_390041103 = "루인-비명 강화",
  str_skill_desc_390041103 = "거츠더가 최후의 포효로 범위 내 대상에게 파열의 인장을 3회 부여하며, 인장 개수가 많을수록 대상의 방어력이 낮아진다.",
  str_skill_name_390041104 = "루인-폭파",
  str_skill_desc_390041104 = "거츠더가 대상이 지닌 파열의 인장을 폭발시켜 대상에게 대량의 피해를 입힌다. 인장 개수가 많을수록 피해가 증가한다. 파열의 인장이 폭발한 후에도 초기화되지 않는다.",
  str_skill_name_300045101 = "루인-비명",
  str_skill_desc_300045101 = "거츠더의 부하가 자신의 주변 2서클 범위 내 대상에게 파열의 인장을 추가한다. 인장 개수마다 대상의 방어력을 일정량 감소시키며, 인장 개수가 많을수록 방어력이 감소한다.",
  str_skill_name_391028101 = "크로스 다크매터",
  str_skill_desc_391028101 = "다크 서머너가 십자형 최대 범위 내 대상에게 피해를 입히고, 지정 위치에 비컨 2개를 소환한다.",
  str_skill_name_391028102 = "에너지 축적",
  str_skill_desc_391028102 = "다크 서머너가 제자리에서 에너지를 모으며, 지정 위치에 비컨 4개를 소환한 후 모든 비컨의 HP를 회복시킨다.",
  str_skill_name_391028103 = "공허",
  str_skill_desc_391028103 = "다크 서머너가 축적한 에너지를 폭발시켜 전체 범위에 피해를 입힌다.",
  str_skill_name_391028104 = "크로스 다크매터",
  str_skill_desc_391028104 = "다크 서머너가 십자형 최대 범위 내 대상에게 피해를 입히고, 지정 위치에 비컨 2개를 소환한다.",
  str_skill_name_300040101 = "강화 에너지 공급",
  str_skill_desc_300040101 = "비컨은 에너지 체인을 통해 다크 서머너에게 에너지를 제공하며, 비컨의 개수마다 다크 서머너의 공격력이 5% 증가한다.",
  str_skill_name_390026401 = "루인-피어나는 여명",
  str_skill_desc_390026401 = "이동 후 자신의 주변 2서클 내 대상에게 대량의 피해를 입히고, 지정 위치에 새벽의 정령 2마리를 소환한다.",
  str_skill_name_390026402 = "루인-피어나는 여명",
  str_skill_desc_390026402 = "이동 후 자신의 주변 2서클 내 대상에게 대량의 피해를 입히고, 지정 위치에 새벽의 정령 2마리를 소환한다.",
  str_skill_name_390026403 = "루인-숲의 허리케인",
  str_skill_desc_390026403 = "허리케인을 일으켜 적 전체에 높은 피해를 입힌다. 필드 내 새벽의 정령의 수가 많을수록 입히는 피해가 증가한다.",
  str_skill_name_300060201 = "루인-기생",
  str_skill_desc_300060201 = "적을 향해 이동하며, 적의 주변 1서클까지 도달하면 적에게 피해를 입힌다.",
  str_skill_name_390064101 = "루인-월광",
  str_skill_desc_390064101 = "레체가 이동 후 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_390064102 = "루인-달의 능멸",
  str_skill_desc_390064102 = "레체가 에너지를 발산해 가로+세로 2열 범위 내의 대상에게 피해를 입히고, 밟고 있는 칸을 잠근다.",
  str_skill_name_390064103 = "루인-달의 기세",
  str_skill_desc_390064103 = "레체가 월륜으로 변해 대상과 충돌하여 대상에게 피해를 입힌다.",
  str_skill_name_390066101 = "루인-분쇄",
  str_skill_desc_390066101 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_name_390066102 = "루인-솟구치는 힘",
  str_skill_desc_390066102 = "가로+세로 2열 범위 내의 대상에게 피해를 입히고, 밟고 있는 칸을 부순다.",
  str_skill_name_390066103 = "루인-바람의 기세",
  str_skill_desc_390066103 = "전체 범위에 대량의 피해를 입힌다.",
  str_skill_name_390021101 = "루인-진동",
  str_skill_desc_390021101 = "주변 사방의 전방 1칸에 피해를 1회 입히고, 동시에 지정 위치에 암석 4개를 소환한다.",
  str_skill_name_390021102 = "루인-진동",
  str_skill_desc_390021102 = "주변 사방의 전방 1칸에 피해를 1회 입히고, 동시에 지정 위치에 암석 4개를 소환한다.",
  str_skill_name_390021103 = "루인-거석 충돌",
  str_skill_desc_390021103 = "아비시어의 주변 네 방향에 적이 있을 경우 적을 가장 먼 곳으로 넉백시키며, 적 앞에 암석 1개를 생성한다.",
  str_skill_name_390021104 = "루인-암석 낙하",
  str_skill_desc_390021104 = "아비시어가 전장의 암석을 흡수하며, 흡수한 암석 수에 따라 적에게 피해를 입힌다.",
  str_skill_name_390025101 = "루인-낫",
  str_skill_desc_390025101 = "고스트가 속성 공격을 1회 입힌다.",
  str_skill_name_390025102 = "루인-머피의 법칙",
  str_skill_desc_390025102 = "고스트가 십자형 범위에 속성 피해를 입힌다.",
  str_skill_name_390025103 = "환영 소환",
  str_skill_desc_390025103 = "광폭한 고스트의 환영 1마리를 소환하고, 환영을 조종해 전체화면 범위 내의 적에게 피해를 입힌다. 대상의 HP가 낮을수록 입히는 피해가 증가한다.",
  str_skill_name_1007211 = "소로스의 암류",
  str_skill_desc_1007211 = "마우트가 자신의 전방 2칸 사각형 최대 범위에 충격파를 방출해 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_1007221 = "소로스의 인형",
  str_skill_desc_1007221 = "마우트가 특정 암귀를 소환해 오로리안의 행동을 방해한다.",
  str_skill_name_290120101 = "빛과 어둠",
  str_skill_desc_290120101 = "그라디우스가 대상의 근처로 칸을 따라 이동할 경로가 없을 경우, 암귀의 방식으로 행동한다. 이동 후 범위 내 대상에게 참격을 가해 피해를 입히고 1회의 공격을 막아내는 배리어를 전개한다.",
  str_skill_name_290120102 = "죽음의 빛",
  str_skill_desc_290120102 = "그라디우스가 대상의 근처로 칸을 따라 이동할 경로가 있을 경우, 오로리안의 방식으로 행동한다. 칸을 연결해 이동한 후 대상에게 대량의 피해를 입힌다.",
  str_skill_name_290120103 = "그림자 사냥",
  str_skill_desc_290120103 = "그라디우스가 필드 중앙으로 순간이동 후 강력한 힘으로 필드 중심에서 십자 범위의 칸을 무너트리고, 다크매터의 장막을 펼쳐 필드 내 3개의 구역 내 루미나가 일시적으로 흩어지게 만든다.",
  str_skill_name_290130101 = "추방",
  str_skill_desc_290130101 = "마음의 악마가 스킬 범위 내 대상을 공격해 피해를 입히고 대상을 넉백시킨다.",
  str_skill_name_290130102 = "악몽",
  str_skill_desc_290130102 = "마음의 악마가 전체 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_290130103 = "부패",
  str_skill_desc_290130103 = "마음의 악마가 2서클 범위 내에 피해를 입히고, 스킬 범위 내의 칸 색상을 변경하며, 추가로 스킬 범위 내 일부 칸을 잠근다. 이후 필드에 시종을 3명 소환한다.",
  str_skill_desc_290130113 = "마음의 악마가 2서클 범위 내에 피해를 입히고, 스킬 범위 내의 칸 색상을 변경하며, 추가로 스킬 범위 내 일부 칸을 잠근다. 이후 필드에 시종을 2명 소환한다.",
  str_skill_desc_290130123 = "마음의 악마가 2서클 범위 내에 피해를 입히고, 스킬 범위 내의 칸 색상을 변경하며, 추가로 스킬 범위 내 일부 칸을 잠근다. 이후 필드에 시종을 4명 소환한다.",
  str_skill_name_290134101 = "추방",
  str_skill_desc_290134101 = "마음의 악마가 스킬 범위 내 대상을 공격해 피해를 입히고 대상을 넉백시키며, 이후 필드에 악마의 시종을 소환한다.",
  str_skill_name_290134102 = "악몽",
  str_skill_desc_290134102 = "마음의 악마가 전체 범위 내 대상에게 피해를 입히고, 필드에 약화 칸을 생성한다.",
  str_skill_name_290134103 = "부패",
  str_skill_desc_290134103 = "마음의 악마가 2서클 범위 내의 칸 색상을 변경하며, 추가로 스킬 범위 내 일부 칸을 잠근다.",
  str_skill_desc_290130104 = "???가 스킬 범위 내 적 대상을 공격해 피해를 입히고 대상을 넉백시킨다.",
  str_skill_desc_290130105 = "???가 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_290130106 = "???가 2서클 범위 내의 적에게 피해를 입히고, 스킬 범위 내의 칸 색상을 변경하며, 추가로 스킬 범위 내 일부 칸을 잠근다.",
  str_skill_name_200130101 = "기습",
  str_skill_desc_200130101 = "범위 내 적 대상에게 대량의 피해를 입힌다.",
  str_skill_name_200134101 = "기습",
  str_skill_desc_200134101 = "범위 내 적 대상에게 대량의 피해를 1회 입힌다.",
  str_skill_name_200134105 = "기습",
  str_skill_desc_200134105 = "범위 내 적 대상에게 대량의 피해를 입힌다.",
  str_skill_desc_200130102 = "범위 내 적 대상에게 대량의 피해를 입히고, 대상에게 악마의 인장을 추가한다. 인장 개수마다 대상의 방어력을 일정량 감소시키며, 인장 개수가 많을수록 방어력이 감소한다. 오로라 타임 진입 시 모든 악마의 인장을 제거할 수 있다.",
  str_skill_name_290180101 = "지령-추방",
  str_skill_desc_290180101 = "범위 내 대상에게 원거리 공격을 1회 가한다.",
  str_skill_name_290180201 = "지령-호위",
  str_skill_desc_290180201 = "범위 내 대상에게 원거리 공격을 1회 가하며, 필드에 재머를 소환한다. 재머는 일정 한도만큼만 소환할 수 있다.",
  str_skill_name_290180301 = "지령-소멸",
  str_skill_desc_290180301 = "범위 내 대상에게 원거리 공격을 1회 가하며, 필드에 프리즘 타워를 소환한다.",
  str_skill_name_290180401 = "지령-숙청",
  str_skill_desc_290180401 = "범위 내 대상에게 원거리 공격을 1회 가하며, 필드에 프리즘 타워와 재머를 소환한다. 재머는 일정 한도만큼만 소환할 수 있다.",
  str_skill_name_51104811 = "환영 소환",
  str_skill_desc_51104811 = "정면 칸에 플레이어의 환상 소환",
  str_skill_desc_39104512 = "스페큘러가 대상의 근처로 이동해 피해를 입히고, 대상의 주변에 환영을 1개 소환해 전장에 진입시킨다. 남은 벽 수가 적을수록 환영이 더 강해진다.",
  str_skill_desc_39204512 = "스페큘러가 대상의 근처로 이동해 피해를 입히고, 대상의 주변에 환영을 1개 소환해 전장에 진입시키며, 주변 1서클의 칸을 잠근다. 남은 벽 수가 적을수록 환영이 더 강해진다.",
  str_skill_desc_39104522 = "스페큘러가 대상의 근처로 이동해 피해를 입히고, 남은 벽 수량에 따라 환영을 1~2개 소환해 전장에 진입시킨다. 남은 벽 수가 적을수록 환영이 더 강해진다.",
  str_skill_desc_39204522 = "스페큘러가 대상의 근처로 이동해 피해를 입히고, 남은 벽 수량에 따라 환영을 1~2개 소환해 전장에 진입시키며, 주변 1서클의 칸을 잠근다. 남은 벽 수가 적을수록 환영이 더 강해진다.",
  str_skill_desc_39104511 = "스페큘러가 이동 후 범위 내 대상에게 원거리 공격을 가한다.",
  str_skill_desc_290039101 = "보링거가 전장에 6발의 스타 봄버를 발사한다.",
  str_skill_desc_290039102 = "보링거가 전장 내 2*2 범위 7곳을 폭격하며, 범위 내의 스타 봄버를 폭파한다.",
  str_skill_desc_290139102 = "보링거가 전장 내 2*2 범위 7곳을 폭격하며, 범위 내의 칸을 초기화하고 스타 봄버를 폭파한다.",
  str_skill_desc_291139102 = "보링거가 전장 내 2*2 범위 7곳을 폭격하며, 범위 내의 칸을 초기화하고 스타 봄버를 폭파한다.",
  str_skill_name_13005802 = "깃발의 여명",
  str_skill_desc_13005802 = "1칸을 선택해 에이미의 깃발을 배치하고, 오로리안과 깃발의 거리가 가까울수록 방어력이 증가하며, 방어력은 최대 <color=#00F6FF>30%</color>까지 증가한다. 깃발은 적에게 닿으면 사라진다.",
  str_skill_name_13008001 = "만능 지원상자",
  str_skill_desc_13008001 = "<color=#00F6FF>턴마다 1회만 시전할 수 있다</color>. 원하는 1칸에 깡통을 던져 해당 칸에 방어 아이템을 생성한다.",
  str_skill_name_14006701 = "기사와 왕비",
  str_skill_desc_14006701 = "즉시 파티의 최대 HP를 10% 회복하며, 이번 턴에서 다음에 입는 피해가 <color=#00F6FF>30%</color> 감소한다.",
  str_skill_desc_100001 = "흰색 수선화_일반공격",
  str_skill_desc_100002 = "히이로_일반공격",
