  str_skill_desc_500016 = "이클립스 공병 AOC 스킬: 피해+스턴",
  str_skill_desc_500017 = "섀도고스트 룬 1개를 소환하며, 2턴 후 치료 능력을 지닌 섀도고스트로 바뀐다.",
