  str_skill_desc_500023 = "맥거핀이 한 번 더 고정 구역을 돌아가며 폭격한다.",
  str_skill_desc_500028 = "턴마다 그레이웜을 전장에 소환한다.",
  str_skill_desc_500029 = "지형을 무시하고 지면 위의 어떤 대상이든 공격할 수 있다.",
  str_skill_desc_500032 = "주변 1서클 내의 대상에게 피해를 입히고 1턴간 스턴시킨다.",
  str_skill_desc_5000322 = "주변 1서클 내의 대상에게 피해를 입힌다.",
  str_skill_desc_500033 = "주변 24칸 내의 대상에게 피해를 입히고 1턴간 스턴시킨다.",
  str_skill_desc_5000331 = "주변 2서클 내의 대상에게 피해를 입히고 1턴간 스턴시킨다.",
