  str_skill_upgrade_desc_16010513 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16010516 = "액티브 스킬 강화: 자신의 위치 <color=#00F6FF>주변 2서클</color> 내에 번개 속성 칸이 1개 있을 때마다 액티브 스킬이 추가로 피해를 1회 입힌다.",
  str_skill_upgrade_desc_17010913 = "장비 스킬 강화: 턴마다 첫 일반공격 시 ESP <color=#FFFF00>1</color>포인트를 획득하며, 해당 일반공격의 피해가 <color=#FFFF00>100%</color> 증가한다.",
  str_skill_upgrade_desc_17010916 = "연쇄 스킬 강화: 30% 확률로 연쇄 스킬 피해가 <color=#FFFF00>50%</color> 증가하고, ESP 1포인트마다 발동 확률이 1% 증가한다.",
  str_skill_upgrade_desc_17011013 = "장비 스킬 강화: 액티브 스킬로 적 <color=#FFFF00>1</color>명을 처치하면 ESP <color=#FFFF00>2</color>포인트를 획득한다.",
  str_skill_upgrade_desc_17011016 = "액티브 스킬 강화: ESP 1포인트를 제거할 때마다 이번 피해가 대상의 방어를 <color=#FFFF00>1%</color> 무시한다.",
  str_skill_upgrade_desc_17010713 = "액티브 스킬 강화: 증폭 상태에서 적 <color=#FFFF00>1</color>명을 처치하면 ESP <color=#FFFF00>2</color>포인트를 획득한다.",
  str_skill_upgrade_desc_17010716 = "장비 스킬 강화: 턴 시작 시 주변 <color=#FFFF00>십자형 4칸</color>에 적 <color=#FFFF00>1</color>명이 있을 때마다 ESP <color=#FFFF00>1</color>포인트를 획득한다.",
  str_skill_upgrade_desc_17010813 = "액티브 스킬 강화: 액티브 스킬 피해가 <color=#FFFF00>60%</color> 증가한다.",
  str_skill_upgrade_desc_17010816 = "액티브 스킬 강화: 스킬을 1회 시전할 때마다 이번 전투의 기본 공격력이 <color=#FFFF00>3%</color> 증가한다.",
  str_skill_upgrade_desc_16011213 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.\n액티브 스킬 선택 범위가 전체화면으로 확대된다.",
  str_skill_upgrade_desc_16011216 = "액티브 스킬 강화: 적의 위치 중 최소 1칸을 불 속성으로 전환한다.",
  str_skill_upgrade_desc_15011312 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15011315 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_upgrade_desc_15011412 = "액티브 스킬 강화: 액티브 스킬 시전 후 이번 턴의 연쇄 스킬이 범위 내의 적 전체를 공격할 수 있게 된다.",
  str_skill_upgrade_desc_15011415 = "액티브 스킬 강화: 단일 적 명중 시 액티브 스킬을 재사용할 수 있다(턴마다 1회 한정).",
  str_skill_upgrade_desc_14012714 = "액티브 스킬 강화: 선택한 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_upgrade_desc_16011713 = "액티브 스킬 강화: 액티브 스킬 피해가 <color=#FFFF00>30%</color> 증가한다.",
  str_skill_upgrade_desc_16011716 = "액티브 스킬 강화: 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_upgrade_desc_16011913 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16011916 = "액티브 스킬 강화: 번개가 대상에게 명중할 때마다 피해가 <color=#00F6FF>20%</color> 감소하며, 최대 <color=#00F6FF>5</color>회의 피해를 입힌다.",
  str_skill_upgrade_desc_16012212 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16012215 = "액티브 스킬 강화: 범위 내의 <color=#00F6FF>칸 파괴</color> 효과를 제거한다.",
  str_skill_upgrade_desc_16012113 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16012116 = "액티브 스킬 강화: 피해 범위 내 첫 <color=#00F6FF>3</color>칸이 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환되며, 덩굴이 1칸 늘어날 때마다 피해가 <color=#FFFF00>15%</color> 증가한다.",
  str_skill_upgrade_desc_16011512 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16011515 = "액티브 스킬 강화: 범위 내의 칸 1개를 추가로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_upgrade_desc_13006514 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16012613 = "액티브 스킬 강화: 액티브 스킬 피해가 <color=#FFFF00>120%</color> 증가한다.",
  str_skill_upgrade_desc_16012616 = "액티브 스킬 강화: 오로라 타임 진입 시 1회 더 시전할 수 있다(웨이브당 1회 발동).",
  str_skill_upgrade_desc_16012913 = "액티브 스킬 강화: <link=\"30022\"><#FFAE07><u>소울 시드</u></color></link> 1개마다 추가로 <color=#00F6FF>10%</color>의 피해를 입히며, 소울 시드 한도가 <color=#00F6FF>12</color>개로 증가한다.",
  str_skill_upgrade_desc_16012916 = "액티브 스킬 강화: 웨이브가 시작될 때마다 추가로 <link=\"30023\"><#FFAE07><u>소울 시드</u></color></link>를 2개 획득한다.",
  str_skill_upgrade_desc_16012013 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_upgrade_desc_16012016 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16012312 = "액티브 스킬 강화: 액티브 스킬 피해가 <color=#FFFF00>40%</color> 증가한다.",
  str_skill_upgrade_desc_16012315 = "액티브 스킬 강화: 대상에게 첫 명중 시 1턴간 스턴시킨다.",
  str_skill_upgrade_desc_15001514 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16013113 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16013116 = "액티브 스킬 강화: 액티브 스킬의 실드 계수가 <color=#FFFF00>30%</color> 증가한다.",
  str_skill_upgrade_desc_15013212 = "액티브 스킬 강화: 턴 종료 시 이번 액티브 스킬의 피해가 회복된 경우 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
