  str_skill_desc_300050 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_320050 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 넉백당한 적의 방어력이 10% 감소한다.",
  str_skill_desc_300022 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_303022 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_310022 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_313022 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_300047 = "파티의 HP를 조르아의 공격력의 <color=#00F6FF>150%</color>만큼 회복시키며, 필드의 물 속성 칸 1개마다 회복이 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_desc_303047 = "파티의 HP를 조르아의 공격력의 <color=#00F6FF>150%</color>만큼 회복시키며, 필드의 물 속성 칸 1개마다 회복이 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_desc_320047 = "파티의 HP를 조르아의 공격력의 <color=#00F6FF>150%</color>만큼 회복시키며, 필드의 물 속성 칸 1개마다 회복이 <color=#00F6FF>8%</color> 증가한다.",
  str_skill_desc_323047 = "파티의 HP를 조르아의 공격력의 <color=#00F6FF>150%</color>만큼 회복시키며, 필드의 물 속성 칸 1개마다 회복이 <color=#00F6FF>8%</color> 증가한다.",
  str_skill_desc_300049 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303049 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320049 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 공격 범위의 불 속성 칸을 다른 속성으로 초기화한다.",
  str_skill_desc_323049 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 공격 범위의 불 속성 칸을 다른 속성으로 초기화한다.",
  str_skill_desc_300051 = "공격 방향 1곳을 선택해, 명중한 첫 번째 적 및 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>240%</color>의 피해를 입힌다.",
  str_skill_desc_310051 = "공격 방향 1곳을 선택해, 명중한 첫 번째 적 및 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>240%</color>의 피해를 입힌다.",
  str_skill_desc_320051 = "공격 방향 1곳을 선택해, 명중한 첫 번째 적 및 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>240%</color>의 피해를 입히고 2턴간 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 부여한다(첫 번째 적은 2개, 나머지는 1개 부여).",
  str_skill_desc_300052 = "선택한 방향 3칸 범위 내의 지정 위치로 순간이동해 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_310052 = "선택한 방향 3칸 범위 내의 지정 위치로 순간이동해 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320052 = "선택한 방향 3칸 범위 내의 지정 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300007 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320007 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 대상이 중독 상태일 시 해당 중독 상태의 개수를 2배로 증가시키며, 중독 상태 개수가 한도인 5회 도달 시 액티브 스킬의 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_300008 = "이동 가능한 칸 1개를 선택해 불 속성 <link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>으로 전환한다.",
  str_skill_desc_310008 = "움직일 수 있는 칸 1개를 선택해 불 속성 <link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>으로 전환한다.",
  str_skill_desc_300032 = "랜덤으로 필드 내 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>6~10</color>회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_310032 = "랜덤으로 필드 내 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>6~10</color>회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_300035 = "자신의 <color=#00F6FF>주변 2서클</color> 내 선택한 위치로 순간이동한다.",
  str_skill_desc_310035 = "자신의 <color=#00F6FF>주변 2서클</color> 내 선택한 위치로 순간이동한다.",
  str_skill_desc_320035 = "자신의 <color=#00F6FF>주변 2서클</color> 내 선택한 위치로 순간이동한다.",
  str_skill_desc_300058 = "1칸을 선택해 깃발을 배치한다. 에이미와 깃발의 거리가 가까울수록 방어력이 증가하며, 방어력은 최대 <color=#00F6FF>100%</color>까지 증가한다. 깃발은 적에게 닿으면 사라진다.",
  str_skill_desc_303058 = "1칸을 선택해 깃발을 배치한다. 에이미와 깃발의 거리가 가까울수록 방어력이 증가하며, 방어력은 최대 <color=#00F6FF>100%</color>까지 증가한다. 깃발은 적에게 닿으면 사라진다.",
  str_skill_desc_310058 = "1칸을 선택해 깃발을 배치한다. 에이미와 깃발의 거리가 가까울수록 방어력이 증가하며, 방어력은 최대 <color=#00F6FF>100%</color>까지 증가한다. 깃발은 적에게 닿으면 사라진다.",
  str_skill_desc_313058 = "1칸을 선택해 깃발을 배치한다. 에이미와 깃발의 거리가 가까울수록 방어력이 증가하며, 방어력은 최대 <color=#00F6FF>100%</color>까지 증가한다. 깃발은 적에게 닿으면 사라진다.",
  str_skill_desc_300053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>1.5</color>배의 피해를 입힌다.",
  str_skill_desc_303053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>1.5</color>배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있다.",
  str_skill_desc_310053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>1.5</color>배의 피해를 입힌다.",
  str_skill_desc_313053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>1.5</color>배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있다.",
  str_skill_desc_320053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>2</color>배의 피해를 입힌다.",
  str_skill_desc_323053 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명만 있을 시 <color=#00F6FF>2</color>배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있다.",
  str_skill_desc_300074 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 자신의 주변으로 끌어당긴다.",
  str_skill_desc_310074 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 자신의 주변으로 끌어당긴다.",
  str_skill_desc_320074 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 자신의 주변으로 끌어당긴다. 적이 <color=#00F6FF>1</color>칸 당겨질 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_300017 = "지정 위치로 순간이동하고 해당 위치 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 넉백시킨다.",
  str_skill_desc_320017 = "지정 위치로 순간이동하고 해당 위치 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 넉백시킨다.",
  str_skill_desc_300040 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내의 모든 칸을 초기화한다.",
  str_skill_desc_330040 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내의 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다.",
  str_skill_desc_300041 = "<color=#00F6FF>십자형 4칸</color>을 물 속성으로 전환한다.",
  str_skill_desc_304041 = "<color=#00F6FF>십자형 4칸</color>을 물 속성으로 전환하며, 칸 생성 시 일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>이 생성된다. 최대 2칸을 초과할 수 없다.",
  str_skill_desc_300021 = "필드의 모든 칸을 초기화하며, <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 수량은 유지한 채 다시 배치한다.",
  str_skill_desc_310021 = "필드의 모든 칸을 초기화하며, <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 수량은 유지한 채 다시 배치한다.",
  str_skill_desc_330021 = "필드의 모든 칸을 초기화하며, <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 수량은 유지한 채 다시 배치한다. <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>이 숲 속성 칸에 등장할 확률이 증가한다.",
  str_skill_desc_300004 = "1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320004 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_330004 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 공격 범위 내 랜덤 <color=#00F6FF>2</color>칸을 물 속성으로 전환한다.",
  str_skill_desc_300073 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320073 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 피해를 입힌다. 선택한 칸에는 <color=#00F6FF>300%</color>의 피해를, 주변 <color=#00F6FF>십자형 4칸</color>에는 <color=#00F6FF>225%</color>의 피해를, 나머지 칸에는 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_300061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>150%</color>의 피해를 1회 입힌다.",
  str_skill_desc_304061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>180%</color>의 피해를 1회 입힌다.",
  str_skill_desc_310061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>150%</color>의 피해를 1회 입힌다.",
  str_skill_desc_314061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>180%</color>의 피해를 1회 입힌다.",
  str_skill_desc_330061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>150%</color>의 피해를 1회 입힌다. 액티브 스킬로 적 처치 시 재시전할 수 있다.",
  str_skill_desc_334061 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>180%</color>의 피해를 1회 입힌다. 액티브 스킬로 적 처치 시 재시전할 수 있다.",
  str_skill_desc_31100611 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>128%</color>의 피해를 <color=#00F6FF>2</color>회 입힌다.",
  str_skill_desc_32100611 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>132%</color>의 피해를 <color=#00F6FF>2</color>회 입힌다.",
  str_skill_desc_33100611 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>135%</color>의 피해를 <color=#00F6FF>2</color>회 입힌다.",
