  str_skill_desc_32340615 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>72%</color>의 피해를 <color=#00F6FF>6</color>회 입힌다. 액티브 스킬로 적 처치 시 재시전할 수 있다.",
  str_skill_desc_33340615 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>6</color>회 입힌다. 액티브 스킬로 적 처치 시 재시전할 수 있다.",
  str_skill_desc_34340615 = "적이 밟고 있는 칸 1개를 선택해 해당 칸의 적에게 <color=#00F6FF>108%</color>의 피해를 <color=#00F6FF>6</color>회 입힌다. 액티브 스킬로 적 처치 시 재시전할 수 있다.",
  str_skill_desc_300054 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_310054 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_330054 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3100542 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3300542 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3100543 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3300543 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3100544 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_3300544 = "2턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다. 파티가 등잔을 지나갈 때마다 공격력의 <color=#00F6FF>180%</color>만큼 HP를 회복하며, 등잔은 적에게 닿으면 사라진다.",
  str_skill_desc_300016 = "주변 <color=#00F6FF>8</color>개 방향 중 2개 방향을 선택해 사격하거나, 한 방향을 선택해 2회 사격하여 해당 방향의 모든 칸에 회당 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_310016 = "주변 <color=#00F6FF>8</color>개 방향 중 2개 방향을 선택해 사격하거나, 한 방향을 선택해 2회 사격하여 해당 방향의 모든 칸에 회당 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_320016 = "<color=#00F6FF>2</color>칸을 선택해 사격하거나, 한 칸을 선택해 2회 사격하여 해당 방향의 모든 칸에 회당 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_300044 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환한다.",
  str_skill_desc_305044 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환한다.",
  str_skill_desc_320044 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환하며, 이번 턴에 모든 번개 속성 오로리안의 연쇄 시전 조건이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_325044 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환하며, 이번 턴에는 모든 번개 속성 오로리안의 연쇄 시전 조건이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_300048 = "1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_302048 = "1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환한다.",
  str_skill_desc_320048 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_322048 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 번개 속성으로 전환한다.",
  str_skill_desc_300009 = "가장 가까운 번개 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환한다.",
  str_skill_desc_302009 = "가장 가까운 번개 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_305009 = "가장 가까운 번개 속성 <color=#00F6FF>5</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330009 = "가장 가까운 번개 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환하며, 일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>이 생성된다. 최대 2칸을 초과할 수 없다.",
  str_skill_desc_332009 = "가장 가까운 번개 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_335009 = "가장 가까운 번개 속성 <color=#00F6FF>5</color>칸을 불 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300012 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 번개 속성으로 전환한다.",
  str_skill_desc_302012 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 번개 속성으로 전환한다.",
  str_skill_desc_300013 = "물 속성 칸 1개마다 노아의 HP의 <color=#00F6FF>8%</color>에 해당하는 실드를 1턴간 획득한다.",
  str_skill_desc_305013 = "물 속성 칸 1개마다 노아의 HP의 <color=#00F6FF>10%</color>에 해당하는 실드를 1턴간 획득한다.",
  str_skill_desc_320013 = "물 속성 칸 1개마다 노아의 HP의 <color=#00F6FF>8%</color>에 해당하는 실드를 1턴간 획득한다. 액티브 스킬 시전 시 노아의 방어력이 1턴간 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_325013 = "물 속성 칸 1개마다 노아의 HP의 <color=#00F6FF>10%</color>에 해당하는 실드를 1턴간 획득한다. 액티브 스킬 시전 시 노아의 방어력이 1턴간 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_300018 = "솔라스톰 폭발을 일으켜 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 자신을 중심으로 명중한 적을 넉백시킨다.",
  str_skill_desc_305018 = "솔라스톰 폭발을 일으켜 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 자신을 중심으로 명중한 적을 넉백시킨다.",
  str_skill_desc_300033 = "랜덤으로 필드의 적에게 <color=#00F6FF>80%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_305033 = "랜덤으로 필드의 적에게 <color=#00F6FF>80%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_320033 = "랜덤으로 필드의 적에게 <color=#00F6FF>95%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_325033 = "랜덤으로 필드의 적에게 <color=#00F6FF>95%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_300036 = "사용 시 이번 턴에 물 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 물 계열 오로리안의 공격력은 휴라드의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_305036 = "사용 시 이번 턴에 물 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 물 계열 오로리안의 공격력은 휴라드의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_330036 = "사용 시 이번 턴에 물 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 물 계열 오로리안의 공격력은 휴라드의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_335036 = "사용 시 이번 턴에 물 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 물 계열 오로리안의 공격력은 휴라드의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_300010 = "사용 시 이번 턴에 숲 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 숲 계열 오로리안의 공격력은 루이스의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_305010 = "사용 시 이번 턴에 숲 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 숲 계열 오로리안의 공격력은 루이스의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_330010 = "사용 시 이번 턴에 숲 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 숲 계열 오로리안의 공격력은 루이스의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_335010 = "사용 시 이번 턴에 숲 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 숲 계열 오로리안의 공격력은 루이스의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_300014 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color> 및 대상의 현재 HP의 <color=#00F6FF>10%</color>에 해당하는 추가 피해를 1회 입힌다.",
  str_skill_desc_302014 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color> 및 대상의 현재 HP의 <color=#00F6FF>10%</color>에 해당하는 추가 피해를 1회 입힌다(보스를 제외한 HP <color=#00F6FF>10%</color> 미만의 몬스터 즉시 처치).",
  str_skill_desc_320014 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color> 및 대상의 현재 HP의 <color=#00F6FF>10%</color>에 해당하는 추가 피해를 1회 입힌다. 솔라드의 방어력이 높을수록 액티브 스킬이 입히는 피해가 증가하며, 최대 <color=#00F6FF>5%</color>까지 증가한다.",
  str_skill_desc_322014 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color> 및 대상의 현재 HP의 <color=#00F6FF>10%</color>에 해당하는 추가 피해를 1회 입힌다(보스를 제외한 HP <color=#00F6FF>10%</color> 미만의 몬스터 즉시 처치). 솔라드의 방어력이 높을수록 액티브 스킬이 입히는 피해가 증가하며, 최대 <color=#00F6FF>5%</color>까지 증가한다.",
  str_skill_desc_300078 = "1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_302078 = "1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_320078 = "1칸을 선택해 <color=#00F6FF>마름모 13</color>칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_322078 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적의 위치 중 최대 1칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_300076 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다.",
  str_skill_desc_302076 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_305076 = "가장 가까운 숲 속성 <color=#00F6FF>5</color>칸을 물 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330076 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성). 최대 2칸을 초과할 수 없다.",
  str_skill_desc_332076 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_335076 = "가장 가까운 숲 속성 <color=#00F6FF>5</color>칸을 물 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300042 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위의 칸을 물 속성으로 전환한다.",
  str_skill_desc_302042 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위의 칸을 물 속성으로 전환한다.",
  str_skill_desc_300001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환한다.",
  str_skill_desc_303001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하며, 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_306001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하며, 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환한다(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성). 최대 2칸을 초과할 수 없다.",
  str_skill_desc_333001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_336001 = "가장 가까운 불 또는 번개 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300011 = "지정 위치로 순간이동해 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320011 = "지정 위치로 순간이동하며, <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 용아의 인장 <color=#00F6FF>2</color>개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_desc_330011 = "지정 위치로 순간이동하며, <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 용아의 인장 <color=#00F6FF>2</color>개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_desc_300019 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 25%에 해당하는 HP를 회복한다.",
  str_skill_desc_303019 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다.",
  str_skill_desc_306019 = "가장 가까운 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다.",
  str_skill_desc_320019 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 25%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_desc_323019 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_desc_326019 = "가장 가까운 적 3명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_desc_300023 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303023 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_306023 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300002 = "<color=#00F6FF>2</color>칸을 선택해 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 각 칸의 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>200%</color>의 피해를 입힌다.",
