  str_skill_desc_320002 = "<color=#00F6FF>2</color>칸을 선택해 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 각 칸의 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>200%</color>의 피해를 입힌다.",
