  str_skill_desc_326002 = "<color=#00F6FF>2</color>칸을 선택해 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 각 칸의 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>240%</color>의 피해를 입힌다.",
  str_skill_desc_16000213 = "2칸을 선택해 숲 속성 강화 칸으로 전환하며, 각 칸의 십자형 최대 범위에 피해를 입힌다.",
  str_skill_desc_300005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_306005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_310005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_316005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_330005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_336005 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가).",
  str_skill_desc_300006 = "지정 위치로 순간이동해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위의 칸을 물 속성으로 전환한다.",
  str_skill_desc_303006 = "지정 위치로 순간이동해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위의 칸을 물 속성으로 전환한다.",
  str_skill_desc_300025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화한다.",
  str_skill_desc_306025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 범위 내 <color=#00F6FF>불 속성이 아닌</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다.",
  str_skill_desc_320025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.5배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화한다.",
  str_skill_desc_326025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.5배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다.",
  str_skill_desc_300026 = "<color=#00F6FF>불 속성이 아닌 모든</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다. 적의 위치 중 최소 1칸을 불 속성으로 전환한다.",
  str_skill_desc_306026 = "<color=#00F6FF>불 속성이 아닌 모든</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다. 적의 위치 중 최소 1칸을 불 속성으로 전환한다.",
  str_skill_desc_300028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>200%</color>만큼 회복시키며, <color=#00F6FF>주변 3서클 내에서 물 속성이 아닌</color> 칸을 초기화한다.",
  str_skill_desc_306028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>200%</color>만큼 회복시키며, <color=#00F6FF>주변 3서클 내에서 물 속성이 아닌</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 물 속성 칸을 생성한다.",
  str_skill_desc_330028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>200%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화한다.",
  str_skill_desc_336028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>200%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 물 속성 칸을 생성한다.",
  str_skill_desc_300029 = "물, 불, 번개 속성 칸 중의 <color=#00F6FF>1</color>종을 선택해 다른 속성으로 초기화한다(칸의 강화 속성 유지).",
  str_skill_desc_306029 = "물, 불, 번개 속성 칸 중의 <color=#00F6FF>1</color>종을 선택해 다른 속성으로 초기화한다(칸의 강화 속성 유지).",
  str_skill_desc_320029 = "물, 불, 번개 속성 칸 중의 <color=#00F6FF>1</color>종을 선택해 다른 속성으로 초기화한다(칸의 강화 속성 유지). <color=#00F6FF>10</color>칸을 초기화할 때마다 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개가 반드시 생성된다.",
  str_skill_desc_326029 = "물, 불, 번개 속성 칸 중의 <color=#00F6FF>1</color>종을 선택해 다른 속성으로 초기화한다(칸의 강화 속성 유지). <color=#00F6FF>10</color>칸을 초기화할 때마다 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개가 반드시 생성된다.",
  str_skill_desc_300038 = "가장 가까운 물 및 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환한다.",
  str_skill_desc_303038 = "가장 가까운 물 및 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_306038 = "가장 가까운 물 및 불 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300077 = "<color=#00F6FF>4</color>칸을 선택해 물 속성으로 전환한다.",
  str_skill_desc_303077 = "<color=#00F6FF>5</color>칸을 선택해 물 속성으로 전환한다.",
  str_skill_desc_306077 = "<color=#00F6FF>5</color>칸을 선택해 물 속성으로 전환한다.",
  str_skill_desc_300092 = "가장 가까운 불 속성 칸 <color=#00F6FF>4</color>개를 숲 속성으로 전환한다.",
  str_skill_desc_302092 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_305092 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330092 = "가장 가까운 <color=#00F6FF>4</color>개의 불 속성 칸을 숲 속성으로 전환하며, 생성된 칸에 일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>이 나타난다. 최대 2칸을 초과할 수 없다.",
  str_skill_desc_332092 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_335092 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_302075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_305075 = "적 <color=#00F6FF>전체</color>에 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_320075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_322075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_325075 = "적 <color=#00F6FF>전체</color>에 {1}%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_300086 = "우라이아 HP 한도의 <color=#00F6FF>60%</color>만큼 파티 HP를 회복한다. 회복한 HP가 한도를 초과할 경우, 가장 가까운 숲 속성 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_304086 = "우라이아의 HP 한도의 <color=#00F6FF>70%</color>만큼 파티의 HP를 회복한다. 회복한 HP가 한도를 초과할 경우, 가장 가까운 숲 속성 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_330086 = "우라이아 HP 한도의 <color=#00F6FF>60%</color>만큼 파티 HP를 회복한다. 회복한 HP가 한도를 초과할 경우, 가장 가까운 숲 속성 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. <link=\"30010\"><#FFAE07><u>오로라 타임</u></color></link> 발동 시 액티브 스킬을 다시 시전할 수 있다.",
  str_skill_desc_334086 = "우라이아의 HP 한도의 <color=#00F6FF>70%</color>만큼 파티의 HP를 회복한다. 회복한 HP가 한도를 초과할 경우, 가장 가까운 숲 속성 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. <link=\"30010\"><#FFAE07><u>오로라 타임</u></color></link> 발동 시 액티브 스킬을 다시 시전할 수 있다.",
  str_skill_desc_300068 = "선택한 위치로 순간이동하고 기존 위치에 웬디의 깃털 1개를 생성하며, 웬디의 깃털 터치 시 기존 위치로 돌아간다. 필드 내 웬디의 깃털은 동시에 1개만 존재할 수 있다.",
  str_skill_desc_320068 = "전투 시작 시 필드에 웬디의 깃털 1개를 생성한다. 액티브 스킬 시전 시 순간이동 후 기존 위치에 웬디의 깃털 1개를 생성하며, 웬디의 깃털 터치 시 기존 위치로 돌아간다. 필드 내 웬디의 깃털은 1개만 존재할 수 있다.",
  str_skill_desc_300082 = "<color=#00F6FF>2</color>칸을 선택해 속성을 전환한다.",
  str_skill_desc_320082 = "<color=#00F6FF>2</color>칸의 속성을 전환한다. 전환된 칸이 숲 속성일 경우 해당 칸은 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환된다.",
  str_skill_desc_300057 = "선택한 위치로 순간이동해 필리시의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시키며, 순간이동 위치의 <color=#00F6FF>주변 2서클</color> 내의 적 1명마다 회복 효과가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_305057 = "선택한 위치로 순간이동해 필리시의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시키며, 순간이동 위치의 <color=#00F6FF>주변 3서클</color> 내의 적 1명마다 회복 효과가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_320057 = "선택한 위치로 순간이동해 필리시의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시키며, 순간이동 후 <color=#00F6FF>주변 2서클</color> 내의 적 1명마다 필리시에게 HP 한도의 <color=#00F6FF>30%</color>에 해당하는 실드 및 <color=#00F6FF>10%</color>의 회복 효과를 제공한다.",
  str_skill_desc_325057 = "선택한 위치로 순간이동해 필리시의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시키며, 순간이동 후 <color=#00F6FF>주변 3서클</color> 내의 적 1명마다 필리시에게 HP 한도의 <color=#00F6FF>30%</color>에 해당하는 실드 및 <color=#00F6FF>15%</color>의 회복 효과를 제공한다.",
  str_skill_desc_300091 = "시전 시 필드의 물 속성 칸의 개수마다 출전 멤버에게 크로이의 공격력의 <color=#00F6FF>0.5%</color>에 해당하는 공격 보너스를 추가한다. 2턴간 지속.",
  str_skill_desc_320091 = "<link=\"30006\"><#FFAE07><u>협주의 인장</u></color></link>을 획득할 수 있다. 시전 시 필드의 물 속성 칸과 인장의 개수마다 출전 멤버에게 크로이의 공격력의 <color=#00F6FF>0.5%</color>에 해당하는 공격 보너스를 추가한다. 2턴간 지속.",
  str_skill_desc_300079 = "<color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 모든 칸을 초기화한다.",
  str_skill_desc_330079 = "<color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>물 속성이 아닌</color> 모든 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 물 속성 칸을 생성한다.",
  str_skill_desc_300085 = "<color=#00F6FF>HP가 가장 낮은</color> 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320085 = "<color=#00F6FF>HP가 가장 낮은</color> 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있다.",
  str_skill_desc_330085 = "<color=#00F6FF>HP가 가장 낮은</color> 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. <link=\"30005\"><#FFAE07><u>증인의 인장</u></color></link>을 획득하며, 인장의 개수마다 물 속성 오로리안의 공격력이 <color=#00F6FF>1%</color> 증가한다. 액티브 스킬로 대상 처치 시 재사용할 수 있다.",
  str_skill_desc_300089 = "<color=#00F6FF>2</color>칸을 선택해 번개 속성의 <link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>으로 전환한다.",
  str_skill_desc_16008901 = "2칸을 선택해 번개 속성의 프리즘 칸으로 전환한다.",
  str_skill_desc_303089 = "<color=#00F6FF>2</color>칸을 선택해 번개 속성의 프리즘 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_300027 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303027 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 이동 거리에 따라 선택 위치에서 연쇄 스킬을 즉시 1회 시전한다.",
  str_skill_desc_330027 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입힌다.",
  str_skill_desc_333027 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입히며, 이동 거리에 따라 선택 위치에서 연쇄 스킬을 즉시 1회 시전한다.",
  str_skill_desc_300060 = "정오 상태에 진입. 요나의 공격이 <color=#00F6FF>10%</color>, 연쇄 스킬 피해가 <color=#00F6FF>30%</color> 증가한다. 2턴간 지속.",
  str_skill_desc_303060 = "정오 상태에 진입. 요나의 공격이 <color=#00F6FF>10%</color>, 연쇄 스킬 피해가 <color=#00F6FF>30%</color> 증가한다. 2턴간 지속.",
  str_skill_desc_306060 = "정오 상태에 진입. 요나의 공격이 <color=#00F6FF>15%</color>, 연쇄 스킬 피해가 <color=#00F6FF>30%</color> 증가한다. 2턴간 지속.",
  str_skill_desc_330060 = "정오 상태에 진입, 요나의 공격을 <color=#00F6FF>10%</color>, 연쇄 스킬 피해를 <color=#00F6FF>30%</color> 증가시키며, 불 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>2</color>개 감소한다. 2턴간 지속.",
  str_skill_desc_333060 = "정오 상태에 진입, 요나의 공격을 <color=#00F6FF>10%</color>, 연쇄 스킬 피해를 <color=#00F6FF>30%</color> 증가시키며, 불 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>2</color>개 감소한다. 2턴간 지속.",
  str_skill_desc_336060 = "정오 상태에 진입, 요나의 공격을 <color=#00F6FF>15%</color>, 연쇄 스킬 피해를 <color=#00F6FF>30%</color> 증가시키며, 불 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>2</color>개 감소한다, 2턴간 지속.",
  str_skill_desc_300064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_303064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_306064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_320064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_323064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_326064 = "오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_desc_300070 = "랜덤으로 필드의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_302070 = "랜덤으로 필드의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_305070 = "랜덤으로 필드의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_300088 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위 내의 칸을 불 속성으로 전환한다.",
  str_skill_desc_302088 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위 내의 칸을 불 속성으로 전환한다.",
  str_skill_desc_305088 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위 내의 칸을 불 속성으로 전환한다.",
  str_skill_desc_300084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력은 이스타반의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_302084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력은 이스타반의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_305084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력은 이스타반의 공격력의 <color=#00F6FF>70%</color>가 적용된다.",
  str_skill_desc_330084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력에 이스타반의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_332084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력에 이스타반의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_335084 = "사용 시 이번 턴에 불 계열 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 불 계열 오로리안의 공격력에 이스타반의 공격력의 <color=#00F6FF>85%</color>가 적용된다.",
  str_skill_desc_300090 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 불 속성 칸의 적을 반드시 스턴시킨다.",
  str_skill_desc_302090 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 불 속성 칸의 적을 반드시 스턴시킨다.",
  str_skill_desc_320090 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 불 속성 칸의 적을 반드시 스턴시키며, <color=#00F6FF>35%</color> 확률로 다른 속성 칸의 적을 스턴시킨다.",
  str_skill_desc_322090 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 불 속성 칸의 적을 반드시 스턴시키며, <color=#00F6FF>35%</color> 확률로 다른 속성 칸의 적을 스턴시킨다.",
  str_skill_desc_300045 = "1칸에 자신의 현재 HP의 <color=#00F6FF>15%</color>를 소모, <color=#00F6FF>정방형 9칸</color> 범위 내의 적에게 손실 HP와 동일한 방어무시 피해를 1회 입히며, <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_320045 = "1칸에 자신의 현재 HP의 <color=#00F6FF>15%</color>를 소모, <color=#00F6FF>정방형 9칸</color> 범위 내의 적에게 손실 HP와 동일한 방어무시 피해를 1회 입히며, 출혈 상태를 <link=\"30004\"><#FFAE07><u>1회</u></color></link> 부여한다. 2턴간 지속.",
  str_skill_desc_330045 = "1칸에 자신의 현재 HP의 <color=#00F6FF>15%</color>를 소모, <color=#00F6FF>정방형 9칸</color> 범위 내의 적에게 손실 HP와 동일한 방어무시 피해를 1회 입히며, 출혈 상태를 <link=\"30004\"><#FFAE07><u>1회</u></color></link> 부여한다. 2턴간 지속. 나일즈의 기본 HP 한도가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_300081 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적 전체를 자신의 주변으로 끌어당긴다.",
  str_skill_desc_320081 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적 전체를 자신의 주변으로 끌어당긴다. 적군이 1칸 이동할 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_300083 = "1칸을 선택해 해당 위치의 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_320083 = "1칸을 선택해 해당 위치의 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_330083 = "1칸 위치의 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 추가로 해당 피해의 퍼센트만큼 대상의 방어를 감소시킨다. 2턴간 지속.",
  str_skill_desc_300059 = "자신의 <color=#00F6FF>주변 1서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_3000591 = "자신의 <color=#00F6FF>주변 1서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_3000592 = "자신의 <color=#00F6FF>주변 2서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_3000593 = "자신의 <color=#00F6FF>주변 3서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_3000594 = "자신의 <color=#00F6FF>주변 4서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_3000595 = "자신의 <color=#00F6FF>주변 5서클</color> 내 선택한 위치로 이동한다.",
  str_skill_desc_300080 = "1칸을 선택한 뒤 깡통을 던져 해당 칸을 번개 속성으로 전환한다. 동시에 낙뢰 결정, 운석 결정, 붕대, 공격과 방어 중 랜덤으로 하나를 해당 칸에 생성한다.",
  str_skill_desc_320080 = "1칸을 선택한 뒤 깡통을 던져 해당 칸을 번개 속성의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 동시에 낙뢰 결정, 운석 결정, 붕대, 공격과 방어 중 랜덤으로 하나를 해당 칸에 생성한다.",
  str_skill_desc_300093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다.",
  str_skill_desc_306093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 액티브 스킬로 적 처치 시 재사용할 수 있다(턴마다 1회 한정).",
  str_skill_desc_310093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다.",
  str_skill_desc_316093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 액티브 스킬로 적 처치 시 재사용할 수 있다(턴마다 1회 한정).",
  str_skill_desc_320093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다.",
  str_skill_desc_326093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다. 액티브 스킬로 적 처치 시 재사용할 수 있다(턴마다 1회 한정).",
  str_skill_desc_330093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다.",
  str_skill_desc_336093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다. 액티브 스킬로 적 처치 시 재사용할 수 있다(턴마다 1회 한정).",
  str_skill_desc_300097 = "선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>480%</color>까지 증가한다.",
  str_skill_desc_302097 = "선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>600%</color>까지 증가한다.",
  str_skill_desc_300095 = "1칸을 선택해 해당 위치 <color=#00F6FF>및 X형 4칸</color>에 지뢰를 각 1발씩 배치한다. 지뢰를 건드린 적에게 <color=#00F6FF>190%</color>의 피해를 입히고 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_320095 = "1칸을 선택해 해당 위치 <color=#00F6FF>및 X형 4칸</color>에 지뢰를 각 1발씩 배치한다. 지뢰를 건드린 적에게 <color=#00F6FF>190%</color>의 피해를 입히고(선택한 칸은 피해 2배) <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_330095 = "1칸을 선택해 해당 위치 <color=#00F6FF>및 X형 4칸</color>에 지뢰를 각 1발씩 배치한다. 지뢰를 건드린 적에게 <color=#00F6FF>190%</color>의 피해를 입히고(선택한 칸은 피해 2배) <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_300062 = "자신의 주변 <color=#00F6FF>8</color>개 방향 중 가장 멀리 있는 1칸을 선택해 해당 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320062 = "필드 가장자리 중 1칸을 선택, 해당 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>2</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다.",
  str_skill_desc_305024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>2</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다.",
  str_skill_desc_320024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>2</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 모두 <color=#00F6FF>30%</color> 증가).",
  str_skill_desc_325024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>2</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 모두 <color=#00F6FF>30%</color> 증가).",
  str_skill_desc_330024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>1.5</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 모두 <color=#00F6FF>30%</color> 증가).",
  str_skill_desc_335024 = "1칸에 표식을 남긴 후 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>1.5</color>배에 도달하면 표식 위치에서 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 모두 <color=#00F6FF>30%</color> 증가).",
  str_skill_desc_300087 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환한다.",
  str_skill_desc_302087 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_305087 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330087 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환한다(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성). 최대 2칸을 초과할 수 없다.",
  str_skill_desc_332087 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_335087 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3020871 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3050871 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3320871 = "가장 가까운 불 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3350871 = "가장 가까운 불 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300101 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내의 모든 칸을 초기화한다.",
  str_skill_desc_330101 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내의 <color=#00F6FF>번개 속성이 아닌</color> 모든 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 번개 속성 칸을 생성한다.",
  str_skill_desc_300102 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택해 해당 방향 및 인접 행 또는 열의 모든 적을 자신의 근처로 끌어당기며, 끌어당긴 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300099 = "마검을 사용해 자신의 이번 턴 공격력을 <color=#00F6FF>20%</color> 증가시킨다. 종료 후 공격력 및 방어력이 <color=#00F6FF>50%</color> 감소한다. 1턴간 지속.",
  str_skill_desc_305099 = "마검을 사용해 자신의 이번 턴 공격력을 <color=#00F6FF>25%</color> 증가시킨다. 종료 후 공격력 및 방어력이 <color=#00F6FF>50%</color> 감소한다. 1턴간 지속.",
  str_skill_desc_330099 = "마검을 사용해 자신의 이번 턴 공격력을 <color=#00F6FF>20%</color> 증가시킨다. 종료 후 공격력 및 방어력이 <color=#00F6FF>50%</color> 감소한다. 1턴간 지속. 마검 사용 중 적 처치 시 공격력 및 방어 감소 상태에 면역된다.",
  str_skill_desc_335099 = "마검을 사용해 자신의 이번 턴 공격력을 <color=#00F6FF>25%</color> 증가시킨다. 종료 후 공격력 및 방어력이 <color=#00F6FF>50%</color> 감소한다. 1턴간 지속. 마검 사용 중 적 처치 시 공격력 및 방어 감소 상태에 면역된다.",
  str_skill_desc_300100 = "십자형 최대 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위 내의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_302100 = "십자형 최대 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다. 동시에 공격 범위 내의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_300098 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다.",
  str_skill_desc_305098 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다.",
  str_skill_desc_330098 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다. 인장을 지닌 적 처치 시 대상 <color=#00F6FF>주변 1서클</color> 내의 적에게 쿠스쿠타의 공격력의 <color=#00F6FF>40%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_desc_335098 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다. 인장을 지닌 적 처치 시 대상 <color=#00F6FF>주변 1서클</color> 내의 적에게 쿠스쿠타의 공격력의 <color=#00F6FF>40%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_desc_300094 = "현재 위치를 기록, 오로리안 연쇄 스킬 시전 종료 또는 이동 종료 후 기록된 위치로 돌아온다.",
  str_skill_desc_300096 = "가장 가까운 불 또는 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다.",
  str_skill_desc_303096 = "가장 가까운 불 또는 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_306096 = "가장 가까운 불 또는 숲 속성 <color=#00F6FF>5</color>칸을 물 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330096 = "가장 가까운 불 또는 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성). 최대 2칸을 초과할 수 없다.",
  str_skill_desc_333096 = "가장 가까운 불 또는 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환하며(일정 확률로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 생성), 최대 2칸을 초과할 수 없다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
