  str_skill_desc_3061031 = "가장 가까운 물 또는 숲 속성 <color=#00F6FF>5</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_300067 = "이번 턴에서 다음에 입는 피해가 <color=#00F6FF>30%</color> 감소하며, 앨리스의 HP 한도의 <color=#00F6FF>2</color>배를 초과할 수 없다.",
  str_skill_desc_304067 = "이번 턴에서 다음에 입는 피해가 <color=#00F6FF>40%</color> 감소하며, 앨리스의 HP 한도의 <color=#00F6FF>2</color>배를 초과할 수 없다.",
  str_skill_desc_320067 = "이번 턴에서 다음에 입는 피해가 <color=#00F6FF>30%</color> 감소하며, 피해를 입었을 때 파티가 즉시 손실 HP의 <color=#00F6FF>10%</color>를 회복한다. 피해 감소와 HP 회복은 모두 최대 앨리스의 HP 한도의 <color=#00F6FF>2</color>배를 초과할 수 없다.",
  str_skill_desc_324067 = "이번 턴에서 다음에 입는 피해가 <color=#00F6FF>40%</color> 감소하며, 피해를 입었을 때 파티가 즉시 손실 HP의 <color=#00F6FF>10%</color>를 회복한다. 피해 감소와 HP 회복은 모두 최대 앨리스의 HP 한도의 <color=#00F6FF>2</color>배를 초과할 수 없다.",
  str_skill_desc_300104 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_310104 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320104 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 명중한 적의 수가 2명 이하일 경우 이번 턴에 1회 더 시전할 수 있다.",
  str_skill_desc_300030 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 2.5배).",
  str_skill_desc_306030 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 3배).",
  str_skill_desc_320030 = "자신의 주변 <color=#00F6FF>십자형 8칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 2.5배). 외곽 칸 선택 시 사메야마가 앞으로 1칸 이동한 후 스킬을 시전한다.",
  str_skill_desc_326030 = "자신의 주변 <color=#00F6FF>십자형 8칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 3배). 외곽 칸 선택 시 사메야마가 앞으로 1칸 이동한 후 스킬을 시전한다.",
  str_skill_desc_330030 = "자신의 주변 <color=#00F6FF>십자형 8칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 2.5배). 외곽 칸 선택 시 사메야마가 앞으로 1칸 이동한 후 스킬을 시전한다.",
  str_skill_desc_336030 = "자신의 주변 <color=#00F6FF>십자형 8칸</color> 중 1곳을 선택, 해당 방향 부채꼴 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다(적이 사메야마와 가까울수록 피해 증가, 최대 3배). 외곽 칸 선택 시 사메야마가 앞으로 1칸 이동한 후 스킬을 시전한다.",
  str_skill_desc_300071 = "<color=#00F6FF>십자</color> 방향 내 한 칸을 선택해 불 속성 강화 칸으로 전환하고, 플레임 드래곤을 해방해 경로상의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 플레임 드래곤이 선택한 칸에 도달하면 <color=#00F6FF>좌우 양쪽</color>의 최대 범위로 확산되어 80%의 피해를 입힌다.",
  str_skill_desc_305071 = "<color=#00F6FF>십자</color> 방향 내 한 칸을 선택해 불 속성 강화 칸으로 전환하고, 플레임 드래곤을 해방해 경로상의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 플레임 드래곤이 선택한 칸에 도달하면 <color=#00F6FF>좌우 양쪽</color>의 최대 범위로 확산되어 80%의 피해를 입히며, 가장 먼 거리의 칸을 불 속성으로 전환한다.",
  str_skill_desc_320071 = "<color=#00F6FF>십자</color> 방향 내 한 칸을 선택해 불 속성 강화 칸으로 전환하고, 플레임 드래곤을 해방해 경로상의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 플레임 드래곤이 선택한 칸에 도달하면 <color=#00F6FF>좌우 양쪽</color>의 최대 범위로 확산되어 80%의 피해를 입힌다. 플레임 드래곤이 피해를 입히기 전 대상에게 작열의 낙인을 부여한다.",
  str_skill_desc_325071 = "<color=#00F6FF>십자</color> 방향 내 한 칸을 선택해 불 속성 강화 칸으로 전환하고, 플레임 드래곤을 해방해 경로상의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 플레임 드래곤이 선택한 칸에 도달하면 <color=#00F6FF>좌우 양쪽</color>의 최대 범위로 확산되어 80%의 피해를 입히며, 가장 먼 거리의 칸을 불 속성으로 전환한다. 플레임 드래곤이 피해를 입히기 전 대상에게 작열의 낙인을 부여한다.",
  str_skill_desc_300105 = "적이 밟고 있는 칸을 1개 선택해 대상에게 <color=#00F6FF>40%</color>의 피해를 20회 입히고, 적 처치 시 해당 적과 가장 가까운 적을 대상으로 선택한다. 자신의 위치 <color=#00F6FF>주변 1서클</color> 내에 번개 속성 칸이 1개 있을 때마다 액티브 스킬이 추가로 1회의 피해를 입힌다.",
  str_skill_desc_306105 = "적이 밟고 있는 칸을 1개 선택해 대상에게 <color=#00F6FF>40%</color>의 피해를 20회 입히고, 적 처치 시 해당 적과 가장 가까운 적을 대상으로 선택한다. 자신의 위치 <color=#00F6FF>주변 2서클</color> 내에 번개 속성 칸이 1개 있을 때마다 액티브 스킬이 추가로 1회의 피해를 입힌다.",
  str_skill_desc_330105 = "적이 밟고 있는 칸을 1개 선택해 대상에게 <color=#00F6FF>40%</color>의 피해를 20회 입히고, 회당 피해 계수가 <color=#00F6FF>0.8%</color> 증가한다. 적 처치 시 해당 적과 가장 가까운 적을 대상으로 선택하며, 마지막 공격 대상의 방어력이 10% 1턴간 감소한다. 자신의 위치 <color=#00F6FF>주변 1서클</color> 내에 번개 속성 칸이 1개 있을 때마다 액티브 스킬이 추가로 1회의 피해를 입힌다.",
  str_skill_desc_336105 = "적이 밟고 있는 칸을 1개 선택해 대상에게 <color=#00F6FF>40%</color>의 피해를 20회 입히고, 회당 피해 계수가 <color=#00F6FF>0.8%</color> 증가한다. 적 처치 시 해당 적과 가장 가까운 적을 대상으로 선택하며, 마지막 공격 대상의 방어력이 10% 1턴간 감소한다. 자신의 위치 <color=#00F6FF>주변 2서클</color> 내에 번개 속성 칸이 1개 있을 때마다 액티브 스킬이 추가로 1회의 피해를 입힌다.",
  str_skill_desc_330109 = "ESP <color=#00F6FF>10</color>포인트를 소모하고 남은 ESP 포인트를 제거해 선택한 방향과 인접한 칸에 있는 적에게 <color=#00F6FF><color=#00F6FF>150%</color></color>의 피해를 입힌다. 제거된 ESP 1포인트마다 최종 피해가 <color=#00F6FF>8%</color> 증가한다.",
  str_skill_desc_330110 = "ESP <color=#00F6FF>10</color>포인트를 소모하고 남은 ESP 포인트를 제거해 적 전체에 <color=#00F6FF>150%</color>의 피해를 입힌다. 제거된 ESP 1포인트마다 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_336110 = "ESP <color=#00F6FF>10</color>포인트를 소모하고 남은 ESP 포인트를 제거해 적 전체에 <color=#00F6FF>150%</color>의 피해를 입힌다. 제거된 ESP 1포인트마다 피해가 <color=#00F6FF>15%</color> 증가하며, 대상의 방어를 <color=#00F6FF>1%</color> 무시한다.",
  str_skill_desc_330107 = "ESP <color=#00F6FF>10</color>포인트를 소모하여 해당 턴에 증폭 상태가 된다. 증폭 상태: 사선 방향의 일반공격이 가능하고, 공격과 연쇄 피해가 <color=#00F6FF>20%</color> 증가한다(중복 시전 시 중첩 가능).",
  str_skill_desc_333107 = "ESP <color=#00F6FF>10</color>포인트를 소모하여 해당 턴에 증폭 상태가 된다. 증폭 상태: 사선 방향의 일반공격이 가능하고, 공격과 연쇄 피해가 <color=#00F6FF>20%</color> 증가한다(중복 시전 시 중첩 가능). 증폭 상태에서 적 1명을 처치할 때마다 2포인트를 획득한다.",
  str_skill_desc_336107 = "ESP <color=#00F6FF>10</color>포인트를 소모하여 해당 턴에 증폭 상태가 된다. 증폭 상태: 사선 방향의 일반공격이 가능하고, 공격과 연쇄 피해가 <color=#00F6FF>20%</color> 증가한다(중복 시전 시 중첩 가능). 증폭 상태에서 적 1명을 처치할 때마다 2포인트를 획득한다.",
  str_skill_desc_330108 = "ESP <color=#00F6FF>10</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 절반의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_333108 = "ESP <color=#00F6FF>10</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 절반의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_336108 = "ESP <color=#00F6FF>10</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 절반의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 1회 시전할 때마다 기본 공격력이 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_300112 = "자신의 <color=#00F6FF>주변 3서클</color> 내 원하는 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다.",
  str_skill_desc_301112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다.",
  str_skill_desc_303112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화하며, 적의 위치 중 최소 1칸을 불 속성으로 전환한다.",
  str_skill_desc_320112 = "자신의 <color=#00F6FF>주변 3서클</color> 내 원하는 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다.",
  str_skill_desc_321112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다.",
  str_skill_desc_323112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화하며, 적의 위치 중 최소 1칸을 불 속성으로 전환한다.",
  str_skill_desc_330112 = "자신의 <color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다. <color=#00F6FF>불의 입맞춤</color> 효과 발동 후 대상의 불의 입맞춤 인장은 초기화된다.",
  str_skill_desc_331112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화한다. <color=#00F6FF>불의 입맞춤</color> 효과 발동 후 대상의 불의 입맞춤 인장은 초기화된다.",
  str_skill_desc_333112 = "선택한 위치로 순간이동하며, 해당 위치의 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 범위 내 <color=#00F6FF>불 속성이 아닌</color> 모든 칸을 초기화하며, 적의 위치 중 최소 1칸을 불 속성으로 전환한다. <color=#00F6FF>불의 입맞춤</color> 효과 발동 후 대상의 불의 입맞춤 인장은 초기화된다.",
  str_skill_desc_300113 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 필드 내 보스를 제외한 모든 단일 칸의 적을 선택한 방향으로 1칸 강제 이동시키며, 필드 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_305113 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 필드 내 보스를 제외한 모든 단일 칸의 적을 선택한 방향으로 1칸 강제 이동시키며, 필드 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_330113 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 필드 내 보스를 제외한 모든 단일 칸의 적을 선택한 방향으로 1칸 강제 이동시키며, 필드 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 명중한 적의 수가 2명 이하일 경우 이번 턴에 1회 더 시전할 수 있다.",
  str_skill_desc_335113 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 필드 내 보스를 제외한 모든 단일 칸의 적을 선택한 방향으로 1칸 강제 이동시키며, 필드 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 명중한 적의 수가 2명 이하일 경우 이번 턴에 1회 더 시전할 수 있다.",
  str_skill_desc_300114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_302114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬 시전 후 이번 턴의 연쇄 스킬이 범위 내의 적 전체를 공격할 수 있게 된다.",
  str_skill_desc_305114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬이 단일 적 명중 시 이번 턴에 1회 더 시전할 수 있으며, 액티브 스킬 시전 후 이번 턴의 연쇄 스킬이 범위 내의 적 전체를 공격할 수 있게 된다.",
  str_skill_desc_320114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬 시전 후 이번 턴의 연쇄 스킬 범위가 1서클 증가한다.",
  str_skill_desc_322114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬 시전 후 이번 턴의 연쇄 스킬 범위가 1서클 증가하고, 범위 내의 적 전체를 공격할 수 있게 된다.",
  str_skill_desc_325114 = "자신의 주변 8방향 L자형 위치로 순간이동해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬이 단일 적 명중 시 이번 턴에 1회 더 시전할 수 있으며, 액티브 스킬 시전 후 이번 턴의 연쇄 스킬 범위가 1서클 증가하고, 이번 턴의 연쇄 스킬이 범위 내의 적 전체를 공격할 수 있게 된다.",
  str_skill_desc_300127 = "칸 1개를 선택(심연 칸 선택 가능), 종이학 1마리를 배치하며, 해당 칸을 숲 속성으로 전환한다. 파티가 종이학을 지날 경우 종이학은 사라진다.",
  str_skill_desc_304127 = "칸 1개를 선택(심연 칸 선택 가능), 종이학 1마리를 배치하며, 해당 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 파티가 종이학을 지날 경우 종이학은 사라진다.",
  str_skill_desc_320127 = "칸 1개를 선택(심연 칸 선택 가능), 종이학 1마리를 배치하며, 해당 칸을 숲 속성으로 전환한다. 파티가 종이학을 지날 경우 종이학은 사라지며, 종이학이 사라질 시 해당 위치의 칸을 숲 속성으로 전환한다(심연 칸 제외).",
  str_skill_desc_324127 = "칸 1개를 선택(심연 칸 선택 가능), 종이학 1마리를 배치하며, 해당 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 파티가 종이학을 지날 경우 종이학은 사라지며, 종이학이 사라질 시 해당 위치의 칸을 숲 속성으로 전환한다(심연 칸 제외).",
  str_skill_desc_300117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_306117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_3061171 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_320117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다.",
  str_skill_desc_323117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다.",
  str_skill_desc_326117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_3261171 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_330117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다.",
  str_skill_desc_333117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다.",
  str_skill_desc_336117 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_3361171 = "자신의 <color=#00F6FF>주변 마름모 12칸</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 20칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 바깥쪽 서클에 안쪽 서클의 1.5배에 해당하는 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_300119 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 전방 3열 범위에 3갈래의 번개를 발사, <color=#00F6FF>250%</color>의 피해를 입힌다. 번개가 대상에게 명중할 때마다 피해가 <color=#00F6FF>40%</color> 감소하며, 최대 <color=#00F6FF>3</color>회의 피해를 입힌다.",
  str_skill_desc_306119 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개를 선택, 전방 3열 범위에 3갈래의 번개를 발사, <color=#00F6FF>250%</color>의 피해를 입힌다. 번개가 대상에게 명중할 때마다 피해가 <color=#00F6FF>20%</color> 감소하며, 최대 <color=#00F6FF>5</color>회의 피해를 입힌다.",
  str_skill_desc_300122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_305122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내의 <color=#00F6FF>칸 파괴</color> 효과를 제거한다.",
  str_skill_desc_320122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 선택한 칸에 방어무시 피해를 입힌다.",
  str_skill_desc_325122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸에 방어무시 피해를 입히며, 범위 내의 <color=#00F6FF>칸 파괴</color> 효과를 제거한다.",
  str_skill_desc_330122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 선택한 칸에 방어무시 피해를 입힌다. 축복이 10단계에 도달하면 액티브 스킬의 범위가 <color=#00F6FF>쌍십자형 최대</color>로 변경된다.",
  str_skill_desc_3301221 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 선택한 칸에 방어무시 피해를 입힌다. 축복이 10단계에 도달하면 액티브 스킬의 범위가 <color=#00F6FF>쌍십자형 최대</color>로 변경된다.",
  str_skill_desc_335122 = "1칸을 선택해 <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸에 방어무시 피해를 입히며, 범위 내의 <color=#00F6FF>칸 파괴</color> 효과를 제거한다. 축복이 10단계에 도달하면 액티브 스킬의 범위가 <color=#00F6FF>쌍십자형 최대</color>로 변경된다.",
  str_skill_desc_300121 = "1칸을 선택, 해당 칸을 중심으로 1개 방향을 선택해 주변 칸으로 덩굴을 뻗으며, 해당 범위에 <color=#00F6FF>360%</color>의 피해를 입히고 첫 <color=#00F6FF>2</color>칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 덩굴이 1칸 늘어날 때마다 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_306121 = "1칸을 선택, 해당 칸을 중심으로 1개 방향을 선택해 주변 칸으로 덩굴을 뻗으며, 해당 범위에 <color=#00F6FF>360%</color>의 피해를 입히고 첫 <color=#00F6FF>3</color>칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 덩굴이 1칸 늘어날 때마다 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_320121 = "1칸을 선택, 해당 칸을 중심으로 1개 방향을 선택해 주변 칸으로 덩굴을 뻗으며, 해당 범위에 <color=#00F6FF>360%</color>의 피해를 입히고 첫 <color=#00F6FF>2</color>칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 덩굴이 피해를 입힌 후 십자 방향으로 각 <color=#00F6FF>3</color>칸씩 늘어나며, 적 1명당 덩굴 확장 효과는 최대 1회만 발동한다. 덩굴이 1칸 늘어날 때마다 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_326121 = "1칸을 선택, 해당 칸을 중심으로 1개 방향을 선택해 주변 칸으로 덩굴을 뻗으며, 해당 범위에 <color=#00F6FF>360%</color>의 피해를 입히고 첫 <color=#00F6FF>3</color>칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 덩굴이 피해를 입힌 후 십자 방향으로 각 <color=#00F6FF>3</color>칸씩 늘어나며, 적 1명당 덩굴 확장 효과는 최대 1회만 발동한다. 덩굴이 1칸 늘어날 때마다 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_300065 = "자신의 <color=#00F6FF>주변 2서클</color> 또는 필드 전체의 물 속성 칸 중에 선택한 위치로 순간이동한다.",
  str_skill_desc_330065 = "자신의 <color=#00F6FF>주변 2서클</color> 또는 필드 전체의 물 속성 칸 중에 선택한 위치로 순간이동한다. 오로라 타임 진입 시 1회 더 시전할 수 있다.",
  str_skill_desc_300115 = "지정 위치로 순간이동해 <color=#00F6FF>주변 2서클</color> 및 나머지 랜덤 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>하고, 정화 범위 내 <color=#00F6FF>3</color>개의 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_305115 = "지정 위치로 순간이동해 <color=#00F6FF>주변 2서클</color> 및 나머지 랜덤 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>하고, 정화 범위 내 <color=#00F6FF>4</color>개의 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_320115 = "지정 위치로 순간이동해 <color=#00F6FF>주변 3서클</color> 및 나머지 랜덤 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>하고, 정화 범위 내 <color=#00F6FF>4</color>개의 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_325115 = "지정 위치로 순간이동해 <color=#00F6FF>주변 3서클</color> 및 나머지 랜덤 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>하고, 정화 범위 내 <color=#00F6FF>5</color>개의 칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_300126 = "이동 가능한 칸 1개를 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_306126 = "이동 가능한 칸 1개를 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 오로라 타임 진입 시 1회 더 시전할 수 있다(웨이브당 1회 발동).",
  str_skill_desc_310126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_313126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_316126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 오로라 타임 진입 시 1회 더 시전할 수 있다(웨이브당 1회 발동).",
  str_skill_desc_320126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_323126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_326126 = "이동 가능한 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 오로라 타임 진입 시 1회 더 시전할 수 있다(웨이브당 1회 발동).",
  str_skill_desc_300129 = "모든 <link=\"30021\"><#FFAE07><u>소울 시드</u></color></link>를 소모해 적 1명에게 피해를 입히며, <link=\"30021\"><#FFAE07><u>소울 시드</u></color></link> 1개마다 <color=#00F6FF>40%</color>의 피해를 입힌다.",
  str_skill_desc_303129 = "모든 <link=\"30022\"><#FFAE07><u>소울 시드</u></color></link>를 소모해 적 1명에게 피해를 입히며, <link=\"30022\"><#FFAE07><u>소울 시드</u></color></link> 1개마다 <color=#00F6FF>50%</color>의 피해를 입힌다.",
  str_skill_desc_306129 = "모든 <link=\"30023\"><#FFAE07><u>소울 시드</u></color></link>를 소모해 적 1명에게 피해를 입히며, <link=\"30023\"><#FFAE07><u>소울 시드</u></color></link> 1개마다 <color=#00F6FF>50%</color>의 피해를 입힌다.",
  str_skill_desc_300055 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입히고 넉백시킨다.",
  str_skill_desc_302055 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입히고 넉백시킨다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_desc_3020551 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입히고 넉백시킨다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_desc_305055 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입히고 넉백시키며, 적이 <color=#00F6FF>1</color>칸 넉백될 때마다 최종 피해가 <color=#00F6FF>5%</color> 증가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_desc_3050551 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입히고 넉백시키며, 적이 <color=#00F6FF>1</color>칸 넉백될 때마다 최종 피해가 <color=#00F6FF>5%</color> 증가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_desc_300120 = "지정 위치로 순간이동해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 공격 범위의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_16012001 = "지정 위치의 세로 1열에 소량의 피해를 입히고 적을 넉백시키며, 공격 범위의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_16012002 = "지정 위치의 세로 1열 범위 내의 적을 넉백시키며, 범위 내 칸을 숲 속성으로 전환한다.",
  str_skill_desc_303120 = "지정 위치로 순간이동해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 공격 범위의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_300123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상에게 첫 명중 시 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가하며, 2번째 명중 시 1턴간 <color=#00F6FF><color=#00F6FF>스턴</color></color> 효과를 추가한다.",
  str_skill_desc_302123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상에게 첫 명중 시 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가하며, 2번째 명중 시 1턴간 <color=#00F6FF>스턴</color> 효과를 추가한다.",
  str_skill_desc_305123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상의 첫 2회 명중이 모두 1턴간 <color=#00F6FF>스턴</color> 효과를 추가한다.",
  str_skill_desc_320123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상에게 첫 명중 시 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가하며, 2번째 명중 시 1턴간 <color=#00F6FF>스턴</color> 효과를 추가한다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_322123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상에게 첫 명중 시 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가하며, 2번째 명중 시 1턴간 <color=#00F6FF>스턴</color> 효과를 추가한다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_325123 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동일 대상의 첫 2회 명중이 모두 1턴간 <color=#00F6FF>스턴</color> 효과를 추가한다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_300015 = "이동 가능한 칸 1개를 선택해 실버를 소환하고 실버의 방향을 결정, 해당 방향으로 수류탄 1개를 투척하며, 수류탄은 실버가 선택한 방향의 가장 먼 곳으로 다시 날려진다. 수류탄이 이동하는 경로 내의 적에게 <color=#00F6FF>200%</color>의 피해를 입힌다.",
  str_skill_desc_330015 = "이동 가능한 칸 1개를 선택해 실버를 소환하고 실버의 방향을 결정, 해당 방향으로 수류탄 1개를 투척하며, 수류탄은 실버가 선택한 방향의 가장 먼 곳으로 다시 날려진다. 수류탄이 이동하는 경로 내의 적에게 <color=#00F6FF>200%</color>의 피해를 입힌다. 실버가 사선 방향을 선택할 수 있다.",
  str_skill_desc_300131 = "파티의 HP를 노비오의 공격력의 <color=#00F6FF>220%</color>만큼 회복시키며, 노비오의 HP의 <color=#00F6FF>90%</color>에 해당하는 실드를 획득한다. 회복한 HP가 한도를 초과할 경우, <color=#00F6FF>마름모 12칸</color>의 적에게 초과한 HP 수치와 동일한 방어무시 피해를 입힌다.",
  str_skill_desc_306131 = "파티의 HP를 노비오의 공격력의 <color=#00F6FF>220%</color>만큼 회복시키며, 노비오의 HP의 <color=#00F6FF>120%</color>에 해당하는 실드를 획득한다. 회복한 HP가 한도를 초과할 경우, <color=#00F6FF>마름모 12칸</color>의 적에게 초과한 HP 수치와 동일한 방어무시 피해를 입힌다.",
  str_skill_desc_320131 = "파티의 HP를 노비오의 공격력의 <color=#00F6FF>220%</color>만큼 회복시키며, 노비오의 HP의 <color=#00F6FF>90%</color>에 해당하는 실드를 획득한다. 회복한 HP가 한도를 초과할 경우, <color=#00F6FF>주변 2서클</color>의 적에게 초과한 HP 수치와 동일한 방어무시 피해를 입힌다. 오로라 타임 진입 시 최대 HP를 초과하지 않는 실드 수치를 HP로 전환한다.",
  str_skill_desc_326131 = "파티의 HP를 노비오의 공격력의 <color=#00F6FF>220%</color>만큼 회복시키며, 노비오의 HP의 <color=#00F6FF>120%</color>에 해당하는 실드를 획득한다. 회복한 HP가 한도를 초과할 경우, <color=#00F6FF>주변 2서클</color>의 적에게 초과한 HP 수치와 동일한 방어무시 피해를 입힌다. 오로라 타임 진입 시 최대 HP를 초과하지 않는 실드 수치를 HP로 전환한다.",
  str_skill_desc_300132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다.",
  str_skill_desc_302132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_305132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_320132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 오로라 타임 진입 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_3201321 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 오로라 타임 진입 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_322132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다. 오로라 타임에 진입할 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_3221321 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다. 오로라 타임에 진입할 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_325132 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다. 오로라 타임에 진입할 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_3251321 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 턴 종료 시 해당 적이 생존한 경우, 해당 적이 이번 액티브 스킬 피해만큼 HP를 회복한다. 만약 턴 종료 시 이번 액티브 스킬의 피해가 회복될 경우, 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다. 오로라 타임에 진입할 시 턴 종료 후 적이 HP를 회복하지 않는다.",
  str_skill_desc_300133 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_302133 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_300137 = "적 1명을 선택해 적이 밟고 있는 물 속성이 아닌 칸을 최대 <color=#00F6FF>2</color>칸까지 물 속성으로 전환한다.",
  str_skill_desc_310137 = "적 1명을 선택해 적이 밟고 있는 물 속성이 아닌 칸을 최대 <color=#00F6FF>2</color>칸까지 물 속성으로 전환한다.",
  str_skill_desc_304137 = "적 1명을 선택해 적이 밟고 있는 물 속성이 아닌 칸을 최대 <color=#00F6FF>3</color>칸까지 물 속성으로 전환한다.",
  str_skill_desc_314137 = "적 1명을 선택해 적이 밟고 있는 물 속성이 아닌 칸을 최대 <color=#00F6FF>3</color>칸까지 물 속성으로 전환한다.",
  str_skill_desc_300135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>45도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 30%까지 감소한다.",
  str_skill_desc_302135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>45도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 30%까지 감소한다.",
  str_skill_desc_305135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>45도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 40%까지 감소한다.",
  str_skill_desc_320135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>90도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 30%까지 감소한다.",
  str_skill_desc_322135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>90도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 30%까지 감소한다.",
  str_skill_desc_325135 = "주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향의 양쪽 중 한 방향을 선택해 난사하여, <color=#00F6FF>90도</color> 범위 구역에 공격력의 <color=#00F6FF>340%</color>에 해당하는 피해를 입힌다. 난사 중 피해가 점차 감소하며, 초기의 40%까지 감소한다.",
  str_skill_desc_300134 = "칸 1개를 선택해 해당 방향 경로 및 인접 칸의 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고 끝까지 넉백시킨다.",
  str_skill_desc_303134 = "칸 1개를 선택해 해당 방향 경로 및 인접 칸의 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고 끝까지 넉백시킨다.",
  str_skill_desc_320134 = "칸 1개를 선택해 해당 방향 <color=#00F6FF>경로</color> 및 <color=#00F6FF>인접</color> 칸의 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고 끝까지 넉백시킨다. <color=#00F6FF>경로</color>의 적에게는 <color=#00F6FF>1.3</color>배의 피해를 입힌다.",
  str_skill_desc_323134 = "칸 1개를 선택해 해당 방향 <color=#00F6FF>경로</color> 및 <color=#00F6FF>인접</color> 칸의 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고 끝까지 넉백시킨다. <color=#00F6FF>경로</color>의 적에게는 <color=#00F6FF>1.3</color>배의 피해를 입힌다.",
  str_skill_desc_300136 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_302136 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_320136 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속. 액티브 스킬이 피해를 입히기 전 적에게 속세의 인장을 <color=#00F6FF>2회</color> 추가한다.",
  str_skill_desc_322136 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속. 액티브 스킬이 피해를 입히기 전 적에게 속세의 인장을 <color=#00F6FF>2회</color> 추가한다.",
  str_skill_desc_325136 = "적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속. 액티브 스킬이 피해를 입히기 전 적에게 속세의 인장을 <color=#00F6FF>3회</color> 추가한다.",
  str_skill_passive_desc_410022 = "액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410051 = "액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410047 = "연쇄 스킬 회복 계수가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410049 = "<color=#00F6FF>{1}</color> 확률로 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_passive_desc_410050 = "연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410052 = "액티브 스킬이 <color=#00F6FF>{1}</color> 확률로 적을 <link=\"10006\"><#FFAE07><u>둔화</u></color></link>시킨다. 2턴간 지속.",
  str_skill_passive_desc_410074 = "액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410008 = "액티브 스킬 사용 시 타이니의 이번 턴 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410007 = "연쇄 스킬를 시전할 때 왕복 공격을 한 첫 번째 적의 피해가 <color=#00F6FF>{1}</color> 증가하며, 2턴간 적에게 중독 효과를 1회 부여한다.",
  str_skill_passive_desc_410032 = "액티브 스킬의 각 번개가 <color=#00F6FF>15%</color> 확률로 <color=#00F6FF>{1}</color>의 피해를 추가로 입힌다.",
  str_skill_passive_desc_410053 = "액티브 스킬이 준비되면 연쇄 스킬의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410058 = "턴 종료 시 깃발이 존재할 경우 에이미의 방어의 <color=#00F6FF>{1}</color>배만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_400035 = "위치이동 스킬 사용 시 에호의 이번 턴 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410035 = "위치이동 스킬 사용 시 에호의 이번 턴 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420035 = "위치이동 스킬 사용 시 에호의 이번 턴 일반공격 및 연쇄 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410017 = "아군 오로리안이 적을 넉백시킬 시 라비가 해당 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_passive_desc_430017 = "아군 오로리안이 적을 넉백시킬 시 라비가 해당 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 적이 1칸 넉백당할 때마다 방어무시 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_410040 = "턴이 시작될 때마다 비스코스 인장을 1개 획득한다. 연쇄 스킬이 적에게 명중 시 인장 개수마다 <color=#00F6FF>{1}</color> 확률로 대상에게 2턴간 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 부여하며, 웨이브가 시작될 때마다 인장이 초기화된다.",
  str_skill_passive_desc_420040 = "턴 시작 및 액티브 스킬을 사용할 때마다 비스코스 인장을 1개 획득한다. 연쇄 스킬이 적에게 명중 시 인장 개수마다 <color=#00F6FF>{1}</color> 확률로 대상에게 2턴간 <link=\"10002\"><#FFAE07><u>작열</u></color></link>을 부여하며, 웨이브가 시작될 때마다 인장이 초기화된다.",
  str_skill_passive_desc_410041 = "HP가 최대일 시 Ms. 블랑의 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420041 = "HP가 70%보다 높을 시 Ms. 블랑의 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430041 = "HP가 70%보다 높을 시 Ms. 블랑의 공격력이 <color=#00F6FF>{1}</color> 증가하며, 다른 출전한 물 속성 오로리안의 공격력이 Ms. 블랑의 공격력의 <color=#00F6FF>{2}</color>만큼 증가한다.",
  str_skill_passive_desc_410021 = "액티브 스킬 쿨다운 턴 동안 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420021 = "액티브 스킬 쿨다운 턴 동안 연쇄 스킬 피해가 <color=#00F6FF>{1}</color>, 일반공격 피해가 <color=#00F6FF>{2}</color> 증가한다.",
  str_skill_passive_desc_410004 = "파티의 HP 한도가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410073 = "연결 시작 지점에 연쇄 스킬을 추가로 1회 시전하며, 기존의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_430073 = "연결 시작 지점에 연쇄 스킬을 추가로 1회 시전하며, 기존의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 시작 지점 연쇄와 본체 연쇄 공격 범위가 겹칠 경우, 겹치는 구역의 피해가 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_passive_desc_410061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>3</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다.",
  str_skill_passive_desc_420061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다. 또한 인장 개수마다 연쇄 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_430061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다. 또한 인장 개수마다 연쇄 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_414061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>3</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다.",
  str_skill_passive_desc_424061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다. 또한 인장 개수마다 연쇄 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_434061 = "액티브 스킬을 시전할 때마다 추락의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해 횟수가 1회 증가하며, 최종 피해가 <color=#00F6FF>{1}</color> 감소한다. 또한 인장 개수마다 연쇄 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_410054 = "등잔의 턴 수가 끝나 사라질 때 <color=#00F6FF>주변 1서클</color>에 빛을 방출해 <color=#00F6FF>{1}</color>의 피해를 입히며, <color=#00F6FF>{2}</color> 확률로 적을 1턴간 <link=\"10005\"><#FFAE07><u>실명</u></color></link>시킨다.",
  str_skill_passive_desc_430054 = "등잔이 유지되면 턴 수가 종료될 때마다 빛을 방출해 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 입히며, <color=#00F6FF>{2}</color> 확률로 적을 1턴간 <link=\"10005\"><#FFAE07><u>실명</u></color></link>시킨다.",
  str_skill_passive_desc_410016 = "번개 속성 칸을 1개 지날 때마다 에너지 충전을 1회 획득하며, 최대 99회까지 중첩된다. 에너지 충전 개수마다 액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가하며, 액티브 스킬 시전 시 에너지 충전이 초기화된다.",
  str_skill_passive_desc_410046 = "조소의 인장 개수마다 번개 속성 오로리안의 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430046 = "조소의 인장을 지닌 적 처치 시 모든 적의 인장 개수가 <color=#00F6FF>1</color> 증가하며, 인장 개수마다 번개 속성 오로리안의 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410044 = "연쇄 스킬이 모든 적에게 피해를 입힐 시 이번 턴에 번개 속성 오로리안이 비비안의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다.",
  str_skill_passive_desc_430044 = "연쇄 스킬로 모든 적에게 피해를 입힐 시 물, 번개 속성 및 일루미나 진영의 오로리안이 2턴간 비비안의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다.",
  str_skill_passive_desc_410048 = "디나가 번개 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430048 = "디나가 번개 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 파티 내 다른 번개 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_passive_desc_410009 = "턴이 시작될 때마다 <color=#00F6FF>{1}</color> 확률로 적에게 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 부여한다. 1턴간 지속.",
  str_skill_passive_desc_420009 = "턴이 시작될 때마다 <color=#00F6FF>{1}</color> 확률로 적을 1턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태에 빠트린다. <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태의 적 처치 시 폭발이 발생하며, 주변 1서클 내의 적에게 HP 한도의 <color=#00F6FF>10%</color>만큼 피해를 입힌다.",
  str_skill_passive_desc_410012 = "연쇄 스킬이 적 1명에게 명중할 때마다 심판의 인장을 1개 획득한다. 인장 개수마다 자신의 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장이 사라진다.",
  str_skill_passive_desc_420012 = "연쇄 스킬이 적 1명에게 명중할 때마다 심판의 인장을 1개 획득한다(액티브 스킬은 2개 획득). 인장 개수마다 자신의 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장 개수의 절반만 유지된다.",
  str_skill_passive_desc_430012 = "연쇄 스킬이 적 1명에게 명중할 때마다 심판의 인장을 1개 획득한다(액티브 스킬은 2개 획득). 인장 개수마다 자신의 공격력이 <color=#00F6FF>3%</color>, 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장 개수의 절반만 유지된다.",
  str_skill_passive_desc_410013 = "실드가 사라질 시 남은 실드 수치의 <color=#00F6FF>{1}</color>만큼 HP로 전환한다.",
  str_skill_passive_desc_430013 = "실드가 사라질 시 남은 실드 수치의 <color=#00F6FF>{1}</color>만큼 HP로 전환하며, 실드 보유 시 노아의 방어력이 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_passive_desc_410018 = "연쇄 스킬이 적과의 거리가 가까울수록 피해가 증가하며, 최대 <color=#00F6FF>{1}</color>까지 증가한다. 적과의 거리가 3칸 초과 시 증가하지 않는다.",
  str_skill_passive_desc_420018 = "적과의 거리가 가까울수록 액티브 스킬과 연쇄 스킬 피해가 증가하며, 최대 <color=#00F6FF>{1}</color>까지 증가한다. 적과의 거리가 3서클 초과 시 증가하지 않는다.",
  str_skill_passive_desc_430018 = "<color=#00F6FF>주변 8칸</color> 범위에 적이 1명 있을 때마다 공격력이 <color=#00F6FF>5%</color> 증가한다. 적과의 거리가 가까울수록 액티브 스킬과 연쇄 스킬 피해가 증가하며, 최대 <color=#00F6FF>{1}</color>까지 증가한다. 적과의 거리가 3서클 초과 시 증가하지 않는다.",
  str_skill_passive_desc_410033 = "바이스가 피해를 입힐 때마다 주시의 인장을 1개 획득하며, 인장 개수마다 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 후 인장은 초기화된다.",
  str_skill_passive_desc_430033 = "바이스가 피해를 입힐 때마다 주시의 인장을 1개 획득하며, 인장 개수마다 피해가 <color=#00F6FF>{1}</color> 증가한다(연쇄 스킬은 <color=#00F6FF>{2}</color> 증가). 턴 종료 후 인장은 초기화된다.",
  str_skill_passive_desc_410036 = "턴이 시작될 때마다 울프스피릿 1개를 획득하며, 첫 공격을 받을 시 울프스피릿 1개를 소모해 공격한 대상에게 휴라드의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 턴 종료 시 울프스피릿은 초기화된다.",
  str_skill_passive_desc_420036 = "턴이 시작될 때마다 울프스피릿 1개를 획득하며, 공격을 받을 시 울프스피릿 1개를 소모해 공격한 대상에게 휴라드의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 턴 종료 시 울프스피릿은 <color=#00F6FF>초기화되지 않는다</color>.",
  str_skill_passive_desc_410010 = "<link=\"30010\"><#FFAE07><u>오로라 타임</u></color></link> 발동 시 루이스의 HP 한도의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 즉시 회복시킨다.",
  str_skill_passive_desc_420010 = "<link=\"30010\"><#FFAE07><u>오로라 타임</u></color></link> 발동 시 루이스의 HP 한도의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 즉시 회복시키며, 루이스의 방어력이 <color=#00F6FF>50%</color> 증가한다. 2턴간 지속.",
  str_skill_passive_desc_410014 = "출전 멤버에 번개 속성 또는 백야성 진영의 오로리안이 1명 존재할 때마다 솔라드의 방어력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430014 = "출전 멤버에 번개 속성 또는 백야성 진영의 오로리안이 1명 존재할 때마다 솔라드의 방어력이 {1} 증가하며, 해당 증가량의 실제 수치만큼 공격력이 증가한다.",
  str_skill_passive_desc_410078 = "로빈이 숲 속성 칸의 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430078 = "로빈이 숲 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 파티 내 다른 숲 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_passive_desc_410076 = "연쇄 스킬 시전 후 주변 <color=#00F6FF>십자형 4칸</color>에 닿은 HP가 가장 낮은 적의 HP가 <color=#00F6FF>{1}</color> 미만일 경우 해당 적에게 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 부여한다. 1턴간 지속.",
  str_skill_passive_desc_420076 = "연쇄 스킬 시전 시 자신의 주변 <color=#00F6FF>십자형 4칸</color> 내 HP가 가장 낮으면서 <color=#00F6FF>{1}</color> 미만인 적에게 1턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 부여한다. <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태인 적 처치 시 <color=#00F6FF>50%</color> 확률로 대상의 주변 <color=#00F6FF>십자형 4칸</color>의 적을 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태에 빠트린다.",
  str_skill_passive_desc_410042 = "일반공격 시 사선 방향으로 사격할 수 있으며, <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420042 = "일반공격 시 사선 방향의 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고 화력의 인장을 2턴간 추가한다. 바튼이 인장을 지닌 적에게 주는 일반공격 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_430042 = "일반공격 시 사선 방향의 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고 화력의 인장을 2턴간 추가한다. 바튼이 인장을 지닌 적에게 주는 <color=#00F6FF>모든 피해</color>가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_410001 = "전투 시작 시 미러 디멘션 인장을 획득할 수 있다. 인장이 존재하는 동안 나시리스의 방어력이 <color=#00F6FF>{1}</color> 증가하며, HP가 감소하면 인장은 사라진다. <color=#00F6FF>액티브 스킬 사용</color> 시 인장을 갱신할 수 있다.",
  str_skill_passive_desc_420001 = "전투 시작 시 미러 디멘션 인장을 획득할 수 있다. 인장이 존재하는 동안 나시리스의 방어력이 <color=#00F6FF>{1}</color> 증가하며, HP가 감소하면 인장은 사라진다. <color=#00F6FF>액티브 스킬 사용 또는 오로라 타임 진입</color> 시 인장을 갱신할 수 있다.",
  str_skill_passive_desc_410011 = "일반공격 시 적에게 용아의 인장을 1개 추가하며, 최대 <color=#00F6FF>4</color>개까지 중첩된다. 개수마다 시로나의 연쇄 스킬 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430011 = "일반공격 시 적에게 용아의 인장을 1개 추가하며, 최대 <color=#00F6FF>6</color>개까지 중첩된다. 개수마다 시로나의 <color=#00F6FF>액티브 스킬</color> 및 연쇄 스킬 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_440011 = "일반공격 시 적에게 용아의 인장을 1개 추가하며, 최대 <color=#00F6FF>7</color>개까지 중첩된다. 개수마다 시로나의 <color=#00F6FF>액티브 스킬</color> 및 연쇄 스킬 최종 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_410019 = "연쇄 스킬로 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 지닌 적 명중 시 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 개수마다 빅토리아 최대 HP의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_420019 = "연쇄 스킬로 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 지닌 적 명중 시 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 개수마다 빅토리아 최대 HP의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_430019 = "연쇄 스킬이 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 지닌 적에게 명중 시 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 개수마다 빅토리아의 최대 HP의 <color=#00F6FF>{1}</color>만큼 HP를 회복하며, 적의 HP 퍼센트가 파티보다 높을 경우 회복 효과가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_passive_desc_410023 = "연쇄 스킬 시전 시 전율의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가하며, 액티브 스킬 사용 시 인장 개수와 동일한 수의 적을 <color=#00F6FF>1</color>턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태에 빠트리며, <color=#00F6FF>인장은 초기화되지 않는다</color>.",
  str_skill_passive_desc_430023 = "연쇄 스킬 시전 시 전율의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가하며, 액티브 스킬 사용 시 인장 개수와 동일한 수의 적을 <color=#00F6FF>1</color>턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태에 빠트리며, <color=#00F6FF>인장은 초기화되지 않는다</color>. 연쇄 스킬을 시전하기 전 이미 5개의 인장을 지니고 있을 경우, 이번 연쇄 스킬이 추가로 가장 가까운 적 1명에게 피해를 입힌다.",
  str_skill_passive_desc_410002 = "턴이 시작될 때마다 히이로가 거합 상태에 진입, 다음 일반공격 시 적에게 <color=#00F6FF>{1}</color>의 피해를 입히며, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{2}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420002 = "턴이 시작되거나 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지나갈 때 히이로가 거합 상태에 진입, 다음 일반공격 시 적에게 <color=#00F6FF>{1}</color>의 피해를 입히며, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{2}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430002 = "턴이 시작되거나 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지나갈 때 히이로가 거합 상태에 진입, 다음 일반공격 시 적에게 <color=#00F6FF>{1}</color>의 피해를 입히며, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>{2}</color>의 피해를 입힌다. 이번 턴에 거합베기를 1회 시전할 때마다 공격력이 <color=#00F6FF>4%</color> 증가하며, 최대 <color=#00F6FF>20%</color>까지 증가한다.",
  str_skill_passive_desc_410005 = "미아가 액티브 스킬로 적 처치 시 영혼 1개를 획득한다(최대 5개). 영혼 개수마다 단일 적에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 충격을 1회 시전한다.",
  str_skill_passive_desc_420005 = "미아가 액티브 스킬로 적 처치 시 영혼 1개를 획득한다(최대 5개). 영혼 개수마다 단일 적에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 충격을 1회 시전하며, 미아의 연쇄 피해가 <color=#00F6FF>5%</color>, 일반공격 피해가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_430005 = "<color=#00F6FF>오로리안</color> 액티브 스킬로 적 처치 시 영혼 1개를 획득한다(최대 <color=#00F6FF>7</color>개). 영혼 개수마다 단일 적에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 충격을 1회 시전하며, 미아의 연쇄 피해가 <color=#00F6FF>5%</color>, 일반공격 피해가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_410006 = "물 속성 칸 위를 1칸 이동할 때마다 카렌의 이번 턴 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다(최대 <color=#00F6FF>{2}</color>).",
  str_skill_passive_desc_420006 = "물 속성 칸 위를 1칸 이동할 때마다 카렌의 이번 턴 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다(최대 <color=#00F6FF>{2}</color>). 액티브 스킬 시전 후 보너스 효과가 2배로 증가한다.",
  str_skill_passive_desc_430006 = "물 속성 칸 위를 1칸 이동할 때마다 카렌의 이번 턴 공격력이 <color=#00F6FF>{1}</color> 증가한다(최대 <color=#00F6FF>{2}</color>). 액티브 스킬 시전 후 보너스 효과가 2배로 증가한다. 카렌이 물 속성 칸에서 일반공격 시 적을 관통하며, 적의 후방 1칸의 대상에게 <color=#00F6FF>40%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410025 = "일반공격 시 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 추가한다.",
  str_skill_passive_desc_430025 = "일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있으며, 일반공격에 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 추가한다.",
  str_skill_passive_desc_410026 = "<link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태의 개수마다 불 속성 오로리안의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430026 = "턴이 시작할 때마다 불 속성 칸에 위치한 적에게 2턴간 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여하며, <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태의 개수마다 불 속성 오로리안의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410028 = "지도에 물 속성 칸이 생성될 때마다 칸 1개당 라파엘의 HP 한도의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_420028 = "지도에 물 속성 칸이 생성될 때마다 칸 1개당 라파엘의 HP 한도의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 <color=#00F6FF>100%의 보너스</color>를 제공한다.",
  str_skill_passive_desc_410029 = "이번 턴에 숲 속성 칸을 <color=#00F6FF>{1}</color>칸 지날 때마다 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개가 반드시 생성된다.",
  str_skill_passive_desc_430029 = "이번 턴에 숲 속성 칸을 <color=#00F6FF>{1}</color>칸 지날 때마다 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개가 반드시 생성되며, 숲 속성 칸을 우선 강화한다.",
  str_skill_passive_desc_410038 = "3턴마다 자기폭풍을 1회 획득, 다음 연쇄 스킬이 범위 내 적 1명에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입히며, <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다. 1턴간 지속.",
  str_skill_passive_desc_420038 = "3턴마다 자기폭풍을 1회 획득, 다음 연쇄 스킬이 범위 내 적 1명에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입히며, 추가로 1턴의 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다. <color=#00F6FF>50%</color> 확률로 적 1명을 추가로 공격한다.",
  str_skill_passive_desc_430038 = "전투 시작 시 자기폭풍(3턴마다 1회)을 획득, 다음 연쇄 스킬 사용 시 범위 내 적 1명에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입히고 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여하며, <color=#00F6FF>50%</color> 확률로 적 1명을 더 공격한다.",
  str_skill_passive_desc_410077 = "액티브 스킬을 시전한 오로리안은 이번 턴에 베들레헴의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 보너스를 획득한다.",
  str_skill_passive_desc_420077 = "이번 턴에 액티브 스킬을 시전한 오로리안은 베들레헴의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 보너스를 획득하며, 오로라 타임 진입 시 이번 턴에 전체 파티가 베들레헴의 기본 공격력의 <color=#00F6FF>{2}</color>에 해당하는 보너스를 획득한다.",
  str_skill_passive_desc_430077 = "이번 턴에 액티브 스킬을 시전한 오로리안은 베들레헴의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 보너스를 획득하며, 추가로 베들레헴의 기본 공격력이 <color=#00F6FF>{2}</color> 증가한다(해당 턴에 베들레헴이 획득하는 공격력 보너스는 중첩 가능). 오로라 타임 진입 시 이번 턴에 전체 파티가 베들레헴의 기본 공격력의 <color=#00F6FF>{2}</color>에 해당하는 보너스를 획득한다.",
  str_skill_passive_desc_400092 = "표식을 지닌 적 사망 시 대상의 HP 한도의 <color=#00F6FF>{1}</color>만큼 HP 한도 및 <link=\"30007\"><#FFAE07><u>회복 효과</u></color></link>를 증가시킨다.",
  str_skill_passive_desc_410092 = "표식을 지닌 적 사망 시 대상의 HP 한도의 <color=#00F6FF>{1}</color>만큼 HP 한도 및 <link=\"30007\"><#FFAE07><u>회복 효과</u></color></link>를 증가시킨다.",
  str_skill_passive_desc_420092 = "표식을 지닌 적 사망 시 대상의 HP 한도의 <color=#00F6FF>{1}</color>만큼 HP 한도 및 <link=\"30007\"><#FFAE07><u>회복 효과</u></color></link>를 증가시키고, 동시에 적의 위치 중 최대 1칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_passive_desc_400075 = "일반공격 시 <color=#00F6FF>{1}</color> 확률로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_410075 = "일반공격 시 <color=#00F6FF>{1}</color> 확률로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_430075 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있으며, <color=#00F6FF>{1}</color> 확률로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_400086 = "숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 우라이아의 방어력의 <color=#00F6FF>{1}</color>만큼 HP를 즉시 회복한다.",
  str_skill_passive_desc_410086 = "숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 우라이아의 방어력의 <color=#00F6FF>{1}</color>만큼 HP를 즉시 회복한다.",
  str_skill_passive_desc_400068 = "오로리안 순간이동 시 도착 위치가 시작 위치에서 1서클을 벗어날 때마다 웬디가 인장을 1개 획득하며, 인장 개수마다 웬디의 다음 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다. 일반공격 후 인장이 초기화된다.",
  str_skill_passive_desc_410068 = "오로리안 순간이동 시 도착 위치가 시작 위치에서 1서클을 벗어날 때마다 웬디가 인장을 1개 획득하며, 인장 개수마다 웬디의 다음 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다. 일반공격 후 인장이 초기화된다.",
  str_skill_passive_desc_430068 = "오로리안 순간이동 시 도착 위치가 시작 위치에서 1서클을 벗어날 때마다 웬디가 인장을 1개 획득하며, 인장 개수마다 웬디의 다음 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다. 일반공격 후 인장 개수의 <color=#00F6FF>30%</color>가 보존된다.",
  str_skill_passive_desc_400082 = "연쇄 스킬이 <color=#00F6FF>{1}</color> 확률로 적에게 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_410082 = "연쇄 스킬이 <color=#00F6FF>{1}</color> 확률로 적에게 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_400057 = "턴이 시작될 때마다 필리시의 공격력의 <color=#00F6FF>{1}</color> 및 파티가 잃은 HP의 <color=#00F6FF>{2}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_410057 = "턴이 시작될 때마다 필리시의 공격력의 <color=#00F6FF>{1}</color> 및 파티가 잃은 HP의 <color=#00F6FF>{2}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_430057 = "턴이 시작될 때마다 필리시의 공격력의 <color=#00F6FF>{1}</color> 및 파티가 잃은 HP의 <color=#00F6FF>{2}</color>만큼 파티의 HP를 회복한다. 파티가 <color=#00F6FF>5%</color>의 HP를 잃을 때마다 필리시의 공격력이 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_passive_desc_400091 = "액티브 스킬 및 연쇄 스킬 시전 시 자신의 <color=#00F6FF>주변 1서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_410091 = "액티브 스킬 및 연쇄 스킬 시전 시 자신의 <color=#00F6FF>주변 1서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_420091 = "액티브 스킬 및 연쇄 스킬 시전 시 자신의 <color=#00F6FF>주변 1서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_430091 = "액티브 스킬 및 연쇄 스킬 시전 시 자신의 <color=#00F6FF>주변 2서클</color> 내 적의 공격과 방어를 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_400079 = "대상의 HP 퍼센트가 아군보다 높을 경우, 공격받을 시 미제니의 공격력이 방어력으로 <color=#00F6FF>{1}</color>만큼 전환된다.",
  str_skill_passive_desc_410079 = "대상의 HP 퍼센트가 아군보다 높을 경우, 공격받을 시 미제니의 공격력이 방어력으로 <color=#00F6FF>{1}</color>만큼 전환된다.",
  str_skill_passive_desc_420079 = "대상의 HP 퍼센트가 아군보다 높을 경우, 공격받을 시 미제니의 공격력이 방어력으로 <color=#00F6FF>{1}</color>만큼 전환된다. 미제니가 피해를 입힐 시 동일한 퍼센트의 방어력이 공격으로 전환된다.",
  str_skill_passive_desc_400085 = "액티브 스킬로 적에게 피해를 줄 경우, 적 HP가 <color=#00F6FF>{1}</color> 감소할 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_410085 = "액티브 스킬로 적에게 피해를 줄 경우, 적 HP가 <color=#00F6FF>{1}</color> 감소할 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_400089 = "<link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>을 지날 때마다 금택의 인장을 1개 획득하며, 인장 개수마다 연쇄 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410089 = "<link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>을 지날 때마다 금택의 인장을 1개 획득하며, 인장 개수마다 연쇄 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420089 = "<link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>을 지날 때마다 금택의 인장을 1개 획득하며, 인장 개수마다 연쇄 스킬 피해가 <color=#00F6FF>{1}</color>, 일반공격 피해가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_430089 = "<link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>을 지날 때마다 금택의 인장을 1개 획득하며, 인장 개수마다 연쇄 스킬 피해가 <color=#00F6FF>{1}</color>, 일반공격 피해가 <color=#00F6FF>3%</color> 증가한다. <link=\"30010\"><#FFAE07><u>오로라 타임</u></color></link> 발동 시 출발 칸을 <link=\"30001\"><#FFAE07><u>프리즘 칸</u></color></link>으로 전환한다.",
  str_skill_passive_desc_400027 = "턴이 시작될 때마다 경뢰의 인장을 1개 획득한다. 일반공격 시 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_passive_desc_410027 = "턴이 시작될 때마다 경뢰의 인장을 1개 획득한다. 일반공격 시 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_passive_desc_420027 = "턴 시작, 액티브 스킬 시전 및 연쇄 스킬 시전 시마다 경뢰의 인장을 1개 획득한다. 일반공격 시 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_passive_desc_400060 = "정오 상태에서 일반공격 시 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_passive_desc_410060 = "정오 상태에서 일반공격 시 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_passive_desc_420060 = "정오 상태에서 일반공격 피해가 <color=#00F6FF>20%</color> 증가하며, 동시에 일반공격이 적 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_passive_desc_430060 = "정오 상태에서 일반공격 피해가 <color=#00F6FF>20%</color> 증가하며, 동시에 일반공격이 적 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_passive_desc_400064 = "<link=\"30008\"><#FFAE07><u>탄약을 비축</u></color></link>할 수 있다. 연쇄 스킬이 피해를 1회 입힐 때마다 탄약 1발을 소모해 <color=#00F6FF>{1}</color>의 최종 피해를 증가시킨다(오버로드 모드에서는 매회 최대 <color=#00F6FF>3</color>발의 탄약 소모 가능).",
  str_skill_passive_desc_410064 = "<link=\"30008\"><#FFAE07><u>탄약을 비축</u></color></link>할 수 있다. 연쇄 스킬이 피해를 1회 입힐 때마다 탄약 1발을 소모해 <color=#00F6FF>{1}</color>의 최종 피해를 증가시킨다(오버로드 모드에서는 매회 최대 <color=#00F6FF>3</color>발의 탄약 소모 가능).",
  str_skill_passive_desc_430064 = "<link=\"30009\"><#FFAE07><u>탄약을 비축</u></color></link>할 수 있다. 연쇄 스킬이 피해를 1회 입힐 때마다 탄약 1발을 소모해 <color=#00F6FF>{1}</color>의 최종 피해를 증가시킨다(오버로드 모드에서는 매회 최대 <color=#00F6FF>3</color>발의 탄약 소모 가능).",
  str_skill_passive_desc_400070 = "일반공격 시 <color=#00F6FF>{1}</color>의 확률로 레드 드래곤이 1회 공격한다. 레오나 일반공격 피해의 <color=#00F6FF>50%</color>만큼 피해를 입힌다.",
  str_skill_passive_desc_410070 = "일반공격 시 <color=#00F6FF>{1}</color>의 확률로 레드 드래곤이 1회 공격한다. 레오나 일반공격 피해의 <color=#00F6FF>50%</color>만큼 피해를 입힌다.",
  str_skill_passive_desc_420070 = "일반공격 시 <color=#00F6FF>{1}</color> 확률로 레드 드래곤의 공격이 1회 발동, 레오나의 일반공격 피해의 <color=#00F6FF>50%</color>만큼 피해를 입히고 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_400088 = "콤보 <color=#00F6FF>10</color>회마다 마지의 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410088 = "콤보 <color=#00F6FF>10</color>회마다 마지의 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420088 = "콤보 <color=#00F6FF>10</color>회마다 마지의 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가하며, 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_passive_desc_430088 = "콤보 <color=#00F6FF>8</color>회마다 마지의 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가하며, 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_passive_desc_400084 = "연쇄 스킬 시전 종료 후 자신의 <color=#00F6FF>주변 1서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다.",
  str_skill_passive_desc_410084 = "연쇄 스킬 시전 종료 후 자신의 <color=#00F6FF>주변 1서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다.",
  str_skill_passive_desc_420084 = "연쇄 스킬 시전 종료 후 자신의 <color=#00F6FF>주변 2서클</color> 내 적의 공격을 <color=#00F6FF>{1}</color> 감소시킨다.",
  str_skill_passive_desc_400090 = "바바라가 불 속성 칸의 적에게 주는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410090 = "바바라가 불 속성 칸의 적에게 주는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430090 = "바바라가 불 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 파티 내 다른 불 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_passive_desc_400045 = "HP 퍼센트가 낮을수록 나일즈의 공격력 및 방어력이 증가하며, 최대 <color=#00F6FF>{1}</color>까지 증가한다.",
  str_skill_passive_desc_410045 = "HP 퍼센트가 낮을수록 나일즈의 공격력 및 방어력이 증가하며, 최대 <color=#00F6FF>{1}</color>까지 증가한다.",
  str_skill_passive_desc_400081 = "액티브 스킬 시전 시 <color=#00F6FF>주변 1서클</color> 내의 적 1명마다 불 속성 오로리안의 공격력이 렉커의 공격력의 <color=#00F6FF>{1}</color>만큼 증가한다.",
  str_skill_passive_desc_410081 = "액티브 스킬 시전 시 <color=#00F6FF>주변 1서클</color> 내의 적 1명마다 불 속성 오로리안의 공격력이 렉커의 공격력의 <color=#00F6FF>{1}</color>만큼 증가한다.",
  str_skill_passive_desc_430081 = "액티브 스킬 시전 시 <color=#00F6FF>주변 2서클</color> 내의 적 1명마다 불 속성 오로리안의 공격력이 렉커의 공격력의 <color=#00F6FF>{1}</color>만큼 증가한다.",
  str_skill_passive_desc_400083 = "액티브 스킬이 <color=#00F6FF>{1}</color> 확률로 적의 이동 범위를 <color=#00F6FF>50%</color> 감소시킨다.",
  str_skill_passive_desc_410083 = "액티브 스킬이 <color=#00F6FF>{1}</color> 확률로 적의 이동 범위를 <color=#00F6FF>50%</color> 감소시킨다.",
  str_skill_passive_desc_430083 = "액티브 스킬이 <color=#00F6FF>{1}</color> 확률로 적의 이동 범위를 <color=#00F6FF>50%</color> 감소시킨다.",
  str_skill_passive_desc_400059 = "<link=\"30002\"><#FFAE07><u>페피의 인장</u></color></link>을 획득하며, 최대 <color=#00F6FF>{1}</color>개 획득할 수 있다. 액티브 스킬의 이동 범위가 인장 개수만큼 주변 서클 수로 변경되며, 액티브 스킬 사용 시 인장을 초기화한다.",
  str_skill_passive_desc_410059 = "<link=\"30002\"><#FFAE07><u>페피의 인장</u></color></link>을 획득하며, 최대 <color=#00F6FF>{1}</color>개 획득할 수 있다. 액티브 스킬의 이동 범위가 인장 개수만큼 주변 서클 수로 변경되며, 액티브 스킬 사용 시 인장을 초기화한다.",
  str_skill_passive_desc_420059 = "<link=\"30003\"><#FFAE07><u>페피의 인장</u></color></link>을 획득하며, 최대 <color=#00F6FF>{1}</color>개 획득할 수 있다. 액티브 스킬의 이동 범위가 인장 개수만큼 주변 서클 수로 변경되며, 액티브 스킬 사용 시 인장을 초기화한다.",
  str_skill_passive_desc_400080 = "연쇄 스킬 범위 내에 적이 없을 시 유니메트의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_410080 = "연쇄 스킬 범위 내에 적이 없을 시 유니메트의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_400093 = "연쇄 스킬 또는 액티브 스킬 시전 후 대상의 HP가 <color=#00F6FF>{1}</color> 미만일 시 대상에게 공격력의 <color=#00F6FF>{2}</color>에 해당하는 방어무시 피해를 추가로 1회 입힌다.",
  str_skill_passive_desc_410093 = "연쇄 스킬 또는 액티브 스킬 시전 후 대상의 HP가 <color=#00F6FF>{1}</color> 미만일 시 대상에게 공격력의 <color=#00F6FF>{2}</color>에 해당하는 방어무시 피해를 추가로 1회 입힌다.",
  str_skill_passive_desc_430093 = "연쇄 스킬 또는 액티브 스킬 시전 후 대상의 HP가 <color=#00F6FF>{1}</color> 미만일 시 대상에게 공격력의 <color=#00F6FF>{2}</color>에 해당하는 방어무시 피해를 추가로 1회 입힌다. 추가 공격 후 대상의 HP가 미자드의 공격력보다 낮을 경우 대상을 즉시 처치한다.",
  str_skill_passive_desc_400097 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다.",
  str_skill_passive_desc_410097 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다.",
  str_skill_passive_desc_420097 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다. 공격 시마다 <color=#00F6FF>20%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_passive_desc_430097 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다. 공격 시마다 <color=#00F6FF>20%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가하며, 1회 콤보마다 발동 확률이 추가로 0.5% 증가, 최대 50%까지 증가한다.",
  str_skill_passive_desc_400095 = "<link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태의 적에게 피해를 입힐 시 중독 상태 개수마다 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410095 = "<link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태의 적에게 피해를 입힐 시 중독 상태 개수마다 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420095 = "<link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태의 적에게 피해를 입힐 시 중독 상태 개수마다 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430095 = "<link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태의 적에게 피해를 입힐 시 중독 상태 개수마다 최종 피해가 <color=#00F6FF>{1}</color> 증가한다. 중독 상태인 적에게 액티브 스킬 및 연쇄 스킬 명중 시 대상에게 중독 상태를 추가로 1회 부여한다.",
  str_skill_passive_desc_400062 = "일반공격, 연쇄 스킬 및 액티브 스킬이 1명의 적에게만 피해를 입힐 시 해당 피해가 대상의 방어를 <color=#00F6FF>{1}</color> 무시한다.",
  str_skill_passive_desc_410062 = "일반공격, 연쇄 스킬 및 액티브 스킬이 1명의 적에게만 피해를 입힐 시 해당 피해가 대상의 방어를 <color=#00F6FF>{1}</color> 무시한다.",
  str_skill_passive_desc_430062 = "일반공격, 연쇄 스킬 및 액티브 스킬이 1명의 적에게만 피해를 입힐 시 해당 피해가 대상의 방어를 <color=#00F6FF>{1}</color> 무시한다. 필드에 적이 1명만 있을 경우, 파티 내 다른 숲 속성 오로리안의 액티브 스킬이 피해를 입힐 시 절반의 보너스 효과를 획득한다.",
  str_skill_passive_desc_400024 = "일반공격 시 불 속성 칸의 적에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_410024 = "일반공격 시 불 속성 칸의 적에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_400087 = "연쇄 스킬이 대상 명중 시 대상의 <color=#00F6FF>주변 1서클</color> 내 랜덤 <color=#00F6FF>{1}</color>개의 대상에게 피해를 입히며(동일 대상은 피해를 1회만 입음), 회당 피해가 <color=#00F6FF>{2}</color> 감소한다.",
  str_skill_passive_desc_410087 = "연쇄 스킬이 대상 명중 시 대상의 <color=#00F6FF>주변 1서클</color> 내 랜덤 <color=#00F6FF>{1}</color>개의 대상에게 피해를 입히며(동일 대상은 피해를 1회만 입음), 회당 피해가 <color=#00F6FF>{2}</color> 감소한다.",
  str_skill_passive_desc_420087 = "연쇄 스킬이 대상 명중 시 대상의 <color=#00F6FF>주변 2서클</color> 내 랜덤으로 <color=#00F6FF>{1}</color>개의 대상에게 피해를 입히며(동일 대상은 피해를 1회만 입음), 매번 피해가 <color=#00F6FF>{2}</color> 감소한다.",
  str_skill_passive_desc_400101 = "안시아가 필드 가장자리의 적에게 입히는 모든 피해가 증가하며(적이 모퉁이에 있을 때 최대 보너스), 최종 피해가 최대 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410101 = "안시아가 필드 가장자리의 적에게 입히는 모든 피해가 증가하며(적이 모퉁이에 있을 때 최대 보너스), 최종 피해가 최대 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_400102 = "파티 내 번개 속성 오로리안이 액티브 스킬 시전 시 테사의 인장 1개를 획득하며, 액티브 스킬 시전 시 인장 개수마다 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 액티브 스킬 시전 후 인장이 초기화된다.",
  str_skill_passive_desc_410102 = "파티 내 번개 속성 오로리안이 액티브 스킬 시전 시 테사의 인장 1개를 획득하며, 액티브 스킬 시전 시 인장 개수마다 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 액티브 스킬 시전 후 인장이 초기화된다.",
  str_skill_passive_desc_420102 = "파티 내 번개 속성 오로리안이 액티브 스킬 시전 또는 테사가 연쇄 스킬 시전 시 테사의 인장 1개를 획득하며, 액티브 스킬 시전 시 인장 개수마다 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 액티브 스킬 시전 후 인장이 초기화된다.",
  str_skill_passive_desc_430102 = "파티 내 번개 속성 오로리안이 액티브 스킬 시전 또는 테사가 연쇄 스킬 시전 시 테사의 인장 1개를 획득하며, 액티브 스킬 시전 시 인장 개수마다 <color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 액티브 스킬 시전 후 인장이 초기화된다.",
  str_skill_passive_desc_400099 = "마검 사용 중 일반공격 시 적을 관통하며, 적의 후방 1칸에 있는 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_410099 = "마검 사용 중 일반공격 시 적을 관통하며, 적의 후방 1칸에 있는 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_400100 = "스칼렛이 적에게 첫 공격 시 대상의 영혼을 수확하며, 대상에게 즉시 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_passive_desc_410100 = "스칼렛이 적에게 첫 공격 시 대상의 영혼을 수확하며, 대상에게 즉시 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_passive_desc_430100 = "스칼렛이 적에게 첫 공격 시 대상의 영혼을 수확하며, 대상에게 즉시 공격력의 <color=#00F6FF>{1}</color> 및 현재 HP의 <color=#00F6FF>5%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_passive_desc_400098 = "연쇄 스킬이 적 명중 시 대상에게 분리의 인장을 1개 추가하며, 최대 5회 중첩될 수 있다. 인장 개수마다 쿠스쿠타의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410098 = "연쇄 스킬이 적 명중 시 대상에게 분리의 인장을 1개 추가하며, 최대 5회 중첩될 수 있다. 인장 개수마다 쿠스쿠타의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420098 = "연쇄 스킬이 적 명중 시 대상에게 분리의 인장을 1개 추가하며, 최대 5회 중첩될 수 있다. 인장 개수마다 쿠스쿠타의 피해가 <color=#00F6FF>{1}</color> 증가한다. 일반공격 시 <color=#00F6FF>30%</color> 확률로 인장을 1개 추가한다.",
  str_skill_passive_desc_4200981 = "연쇄 스킬이 적 명중 시 대상에게 분리의 인장을 1개 추가하며, 최대 10회 중첩될 수 있다. 인장 개수마다 쿠스쿠타의 피해가 <color=#00F6FF>6%</color> 증가한다. 일반공격 시 <color=#00F6FF>30%</color> 확률로 인장을 1개 추가한다.",
  str_skill_passive_desc_400094 = "연쇄 스킬이 대상 명중 시 대상의 공격력을 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_410094 = "연쇄 스킬이 대상 명중 시 대상의 공격력을 <color=#00F6FF>{1}</color> 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_400096 = "<link=\"30013\"><#FFAE07><u>샤리의 인장</u></color></link>을 획득하며, 최대 8개까지 중첩된다. 인장 개수마다 샤리의 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장 개수의 절반만 유지된다.",
  str_skill_passive_desc_410096 = "<link=\"30013\"><#FFAE07><u>샤리의 인장</u></color></link>을 획득하며, 최대 8개까지 중첩된다. 인장 개수마다 샤리의 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장 개수의 절반만 유지된다.",
  str_skill_passive_desc_420096 = "<link=\"30013\"><#FFAE07><u>샤리의 인장</u></color></link>을 획득하며, 최대 8개까지 중첩된다. 인장 개수마다 샤리의 방어력이 <color=#00F6FF>{1}</color> 증가한다. 손실 HP에 따라 방어 효과가 증가하며, 최대 <color=#00F6FF>50%</color>까지 증가한다. 턴 종료 시 인장 개수의 절반만 유지된다.",
  str_skill_passive_desc_400056 = "일반공격 또는 액티브 스킬이 피해를 입힐 시(최고치 기준) 피해 수치의 <color=#00F6FF>{1}</color>만큼 공격으로 전환된다. 해당 턴에만 효력이 적용된다.",
  str_skill_passive_desc_410056 = "일반공격 또는 액티브 스킬이 피해를 입힐 시(최고치 기준) 피해 수치의 <color=#00F6FF>{1}</color>만큼 공격으로 전환된다. 해당 턴에만 효력이 적용된다.",
  str_skill_passive_desc_430056 = "일반공격 또는 액티브 스킬이 피해를 입힐 시(최고치 기준) 피해 수치의 <color=#00F6FF>{1}</color>만큼 공격으로 전환된다. 해당 턴에만 효력이 적용된다. 필드에 적이 1명만 있을 시 물 속성 오로리안의 공격력이 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_400103 = "3턴마다 공허 상태를 1회 획득한다(미사용 시 해당 상태 유지). 공허 상태에서 연쇄 스킬이 대상에게 엘시의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 동일 수치의 HP를 회복한다.",
  str_skill_passive_desc_410103 = "3턴마다 공허 상태를 1회 획득한다(미사용 시 해당 상태 유지). 공허 상태에서 연쇄 스킬이 대상에게 엘시의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 동일 수치의 HP를 회복한다.",
  str_skill_passive_desc_430103 = "3턴마다 공허 상태를 1회 획득한다(미사용 시 해당 상태 유지). 공허 상태에서 연쇄 스킬이 대상에게 엘시의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 동일 수치의 HP를 회복한다. 파티의 HP가 낮을수록 회복 효과가 증가하며, 최대 <color=#00F6FF>50%</color>까지 증가한다.",
  str_skill_passive_desc_410067 = "이번 턴에 HP를 회복하면 이번 턴에 앨리스의 기본 방어력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430067 = "이번 턴에 HP를 회복하면 이번 턴에 앨리스의 기본 방어력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_400030 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>하며, 사선 방향의 일반공격이 대상에게 붕괴 상태를 1회 추가한다. 최대 5회까지 추가할 수 있으며, 회당 대상의 방어를 사메야마의 기본 방어의 <color=#00F6FF>{1}</color>만큼 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_410030 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>하며, 사선 방향의 일반공격이 대상에게 붕괴 상태를 1회 추가한다. 최대 5회까지 추가할 수 있으며, 회당 대상의 방어를 사메야마의 기본 방어의 <color=#00F6FF>{1}</color>만큼 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_430030 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>하며, 사선 방향의 일반공격, 액티브 스킬 및 연쇄 스킬이 대상에게 붕괴 상태를 1회 추가한다(최대 5회). 회당 대상의 방어를 사메야마의 기본 방어의 <color=#00F6FF>{1}</color>만큼 감소시킨다. 1턴간 지속.",
  str_skill_passive_desc_410104 = "액티브 스킬이 공격당한 적에게 표식을 추가하며, 도엔의 액티브 스킬 및 연쇄 스킬이 표식을 지닌 적 공격 시 표식을 소모해 이번 피해의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복한다.",
  str_skill_passive_desc_430104 = "액티브 스킬이 공격당한 적에게 표식을 추가하며, 도엔의 액티브 스킬 및 연쇄 스킬이 표식을 지닌 적 공격 시 표식을 소모해 이번 피해의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복한다. 파티의 HP가 최대일 시 이번 공격의 최종 피해가 <color=#00F6FF>25%</color> 증가한다.",
  str_skill_passive_desc_410071 = "턴이 시작될 때마다 HP 퍼센트가 가장 높은 적에게 작열의 낙인을 부여하며, 타키가 대상에게 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430071 = "턴이 시작될 때마다 HP 퍼센트가 가장 높은 적에게 작열의 낙인을 부여하며, 타키가 대상에게 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가한다. 작열의 낙인을 지닌 적을 처치할 때마다 타키의 공격력이 <color=#00F6FF>3%</color> 증가하며, 최대 <color=#00F6FF>30%</color>까지 증가한다.",
  str_skill_passive_desc_400105 = "액티브 스킬, 연쇄 스킬 및 일반공격이 피해를 입힐 시 <color=#00F6FF>10</color>회마다 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_410105 = "액티브 스킬, 연쇄 스킬 및 일반공격이 피해를 입힐 시 <color=#00F6FF>10</color>회마다 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_420105 = "액티브 스킬, 연쇄 스킬 및 일반공격이 피해를 입힐 시 <color=#00F6FF>8</color>회마다 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_430105 = "액티브 스킬, 연쇄 스킬 및 일반공격이 피해를 입힐 시 <color=#00F6FF>8</color>회마다 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_430109 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_passive_desc_433109 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 턴마다 첫 일반공격 시 ESP <color=#00F6FF>1</color>포인트를 획득하며, 해당 일반공격의 피해가 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_passive_desc_430110 = "턴 시작 시마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 일반공격 시 <color=#00F6FF>30%</color> 확률로 자신으로부터 거리가 가장 먼 적에게 뇌격을 1회 시전한다.",
  str_skill_passive_desc_433110 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 액티브 스킬로 적 1명을 처치할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득하며, 일반공격 시 <color=#00F6FF>30%</color> 확률로 자신으로부터 거리가 가장 먼 적에게 뇌격을 1회 시전한다.",
  str_skill_passive_desc_430107 = "전투 시작 시 ESP 10포인트를 획득한다. 비증폭 상태에서 턴이 종료되면 ESP <color=#00F6FF>5</color>포인트를 획득한다(손실 HP 20%마다 ESP 1포인트 추가 획득).",
  str_skill_passive_desc_436107 = "전투 시작 시 ESP 10포인트를 획득한다. 턴 시작 시 주변 <color=#00F6FF>십자형 4칸</color>에 적 1명이 있을 때마다 ESP <color=#00F6FF>1</color>포인트를 획득한다. 비증폭 상태에서 턴이 종료되면 ESP <color=#00F6FF>5</color>포인트를 획득한다(손실 HP 20%마다 ESP 1포인트 추가 획득).",
  str_skill_passive_desc_430108 = "턴 시작 시마다 ESP <color=#00F6FF>5</color>포인트를 획득하며, 액티브 스킬로 대상을 처치하면 ESP <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_passive_desc_400116 = "HP가 40% 미만인 적에게 플뢰르가 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410112 = "스모키가 <color=#00F6FF>모든</color> 적에게 가하는 <color=#00F6FF>액티브 스킬, 연쇄 스킬, 매 턴의 첫 일반공격</color>이 <color=#00F6FF>불의 입맞춤</color>을 발동해 추가로 스모키의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 중복 발동 시 효과가 감소하며, 기존 효과의 <color=#00F6FF>20%</color>까지 감소한다.",
  str_skill_passive_desc_420112 = "스모키가 <color=#00F6FF>모든</color> 적에게 가하는 <color=#00F6FF>액티브 스킬, 연쇄 스킬, 매 턴의 첫 일반공격</color>이 <color=#00F6FF>불의 입맞춤</color>을 발동해 추가로 스모키의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 중복 발동 시 효과가 감소하며, 기존 효과의 <color=#00F6FF>20%</color>까지 감소한다. <color=#00F6FF>불의 입맞춤</color>이 불 속성 칸의 적에게 <color=#00F6FF>2배</color>의 피해를 입힌다.",
  str_skill_passive_desc_430112 = "스모키가 <color=#00F6FF>모든</color> 적에게 가하는 <color=#00F6FF>액티브 스킬, 연쇄 스킬, 매 턴의 첫 일반공격</color>이 <color=#00F6FF>불의 입맞춤</color>을 발동해 추가로 스모키의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 중복 발동 시 효과가 감소하며, 기존 효과의 <color=#00F6FF>20%</color>까지 감소한다. <color=#00F6FF>불의 입맞춤</color>이 불 속성 칸의 적에게 <color=#00F6FF>2배</color>의 피해를 입힌다.",
  str_skill_passive_desc_400113 = "전투가 시작되거나 액티브 스킬 사용 시 울림의 인장을 획득할 수 있다. 인장이 존재하는 동안 보나시외의 방어력이 <color=#00F6FF>{1}</color> 증가하며, HP가 감소하면 인장은 사라진다.",
  str_skill_passive_desc_410113 = "전투가 시작되거나 액티브 스킬 사용 시 울림의 인장을 획득할 수 있다. 인장이 존재하는 동안 보나시외의 방어력이 <color=#00F6FF>{1}</color> 증가하며, HP가 감소하면 인장은 사라진다.",
  str_skill_passive_desc_420113 = "전투가 시작되거나 액티브 스킬 사용 시 울림의 인장을 획득할 수 있다. 인장이 존재하는 동안 보나시외의 방어력이 <color=#00F6FF>{1}</color> 증가하며, HP가 감소하면 인장은 사라진다. 인장이 존재할 시 출전한 번개 속성 오로리안의 연쇄 스킬 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_400114 = "액티브 스킬이 피해를 입힐 시 이번 피해의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_410114 = "액티브 스킬이 피해를 입힐 시 이번 피해의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_430114 = "액티브 스킬이 피해를 입힐 시 이번 피해의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 출전한 불 속성 오로리안의 이번 턴 연쇄 스킬 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_410127 = "턴이 시작될 때마다 자신의 <color=#00F6FF>주변 2서클</color> 내에 적이 있을 경우 적 1명에게 단검을 투척, 대상에게 <color=#00F6FF>{1}</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_430127 = "턴이 시작될 때마다 자신의 <color=#00F6FF>주변 2서클</color> 내에 적이 있을 경우 적 1명에게 단검을 투척, 대상에게 <color=#00F6FF>{1}</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속. 종이학을 지날 경우에도 단검 투척 효과가 발생한다.",
  str_skill_desc_3351221 = "1칸을 선택해 <color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸에 방어무시 피해를 입히며, 범위 내의 <color=#00F6FF>칸 파괴</color> 효과를 제거한다. 축복이 10단계에 도달하면 액티브 스킬의 범위가 <color=#00F6FF>쌍십자형 최대</color>로 변경된다.",
  str_skill_passive_desc_410117 = "<link=\"30016\"><#FFAE07><u>용맹</u></color></link> 상태를 획득하며, 용맹 단계가 높아질 때마다 그람의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430117 = "<link=\"30017\"><#FFAE07><u>용맹</u></color></link> 상태를 획득하며, 용맹 단계가 높아질 때마다 그람의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 액티브 스킬로 획득하는 용맹은 한도가 없으며, 웨이브 종료 시 초기화된다. 용맹이 1단계 제거될 때마다 그람의 최대 HP의 <color=#00F6FF>5%</color>에 해당하는 HP가 회복된다.",
  str_skill_passive_desc_410119 = "<link=\"30018\"><#FFAE07><u>무위</u></color></link> 상태를 획득하며, 무위 단계가 높아질 때마다 레비의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420119 = "<link=\"30018\"><#FFAE07><u>무위</u></color></link> 상태를 획득하며, 무위 단계가 높아질 때마다 레비의 기본 공격력이 <color=#00F6FF>{1}</color>, 액티브 스킬 피해가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_430119 = "<link=\"30018\"><#FFAE07><u>무위</u></color></link> 상태를 획득하며, 무위 단계가 높아질 때마다 레비의 기본 공격력이 <color=#00F6FF>{1}</color>, 액티브 스킬 피해가 <color=#00F6FF>5%</color> 증가한다. 일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있다.",
  str_skill_passive_desc_410122 = "<link=\"30019\"><#FFAE07><u>축복</u></color></link> 상태를 획득하며, 축복 단계가 높아질 때마다 알루라의 액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410121 = "<link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 가시의 인장을 1개 획득하며, 인장 개수마다 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 인장의 절반이 유지된다.",
  str_skill_passive_desc_430121 = "<link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 가시의 인장을 1개 획득하며, 인장 개수마다 연쇄 스킬 및 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 인장의 절반이 유지된다.",
  str_skill_passive_desc_410065 = "연쇄 스킬이 적 1명에게 명중할 때마다 박새의 인장을 1개 획득한다. 인장 개수마다 자신의 방어력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 인장이 사라진다.",
  str_skill_passive_desc_410115 = "<link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 비취의 인장을 1개 획득하며, 인장 개수마다 나로세르의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 인장의 절반이 유지된다.",
  str_skill_passive_desc_430115 = "<link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 지날 때마다 비취의 인장을 1개 획득하며, 인장 개수마다 전체 파티의 기본 공격력이 나로세르의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 증가한다. 턴 종료 시 인장의 절반이 유지된다.",
  str_skill_passive_desc_410126 = "액티브 스킬로 선택한 칸에 <link=\"30024\"><#FFAE07><u>프랭크</u></color></link>를 소환한다. 아군이 액티브 스킬을 시전할 때마다 프랭크가 <color=#00F6FF>포효</color>해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 프랭크가 사라질 때도 <color=#00F6FF>포효</color>를 발동한다.",
  str_skill_passive_desc_420126 = "액티브 스킬로 선택한 칸에 <link=\"30024\"><#FFAE07><u>프랭크</u></color></link>를 소환한다. 아군이 액티브 스킬을 시전할 때마다 프랭크가 <color=#00F6FF>포효</color>해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 효과가 <color=#00F6FF>크로우 어택</color>으로 변경되며, 피해가 <color=#00F6FF>50%</color> 증가한다. 프랭크가 사라질 때도 <color=#00F6FF>포효</color>를 발동한다.",
  str_skill_passive_desc_410129 = "액티브 스킬과 연쇄 스킬이 피해를 1회 입힐 때마다 적에게 패러사이트 표식을 1회 추가하며, 최대 <color=#00F6FF>9</color>회까지 추가할 수 있다. 적이 1칸을 이동할 때마다 패러사이트 표식 개수당 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420129 = "액티브 스킬과 연쇄 스킬이 피해를 1회 입힐 때마다 적에게 패러사이트 표식을 1회 추가하며, 최대 <color=#00F6FF>9</color>회까지 추가할 수 있다. 적이 1칸을 이동할 때마다 패러사이트 표식 개수당 <color=#00F6FF>{1}</color>의 피해를 입히며, 루크가 가장 많은 표식을 지닌 적에게 입히는 일반공격 및 연쇄 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_430129 = "액티브 스킬과 연쇄 스킬이 피해를 1회 입힐 때마다 적에게 패러사이트 표식을 1회 추가하며, 최대 <color=#00F6FF>9</color>회까지 추가할 수 있다. 적이 1칸을 이동할 때마다 패러사이트 표식 개수당 <color=#00F6FF>{1}</color>의 피해를 입히며, 해당 적의 표식 개수가 최대일 경우 해당 피해가 <color=#00F6FF>{2}</color>까지 증가한다. 루크가 가장 많은 표식을 지닌 적에게 입히는 일반공격 및 연쇄 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_410055 = "공격을 받을 시 전투의 흔적을 1회 획득하며, 최대 <color=#00F6FF>15</color>회까지 획득할 수 있다. 전투의 흔적 상태마다 공격력이 <color=#00F6FF>{1}</color> 증가하며, 전투의 흔적은 턴마다 개수가 50% 감소한다.",
  str_skill_passive_desc_420055 = "공격을 받을 시 전투의 흔적을 1회 획득하며, 최대 <color=#00F6FF>15</color>회까지 획득할 수 있다. 전투의 흔적 상태마다 공격력과 방어력이 <color=#00F6FF>{1}</color> 증가하며, 전투의 흔적은 턴마다 개수가 50% 감소한다.",
  str_skill_passive_desc_430055 = "공격을 받을 시 전투의 흔적을 1회 획득하며, 최대 <color=#00F6FF>15</color>회까지 획득할 수 있다. 전투의 흔적 상태마다 공격력과 방어력이 <color=#00F6FF>{1}</color> 증가하며, 전투의 흔적은 턴마다 개수가 50% 감소한다. 전투의 흔적이 1개 감소할 때마다 피트만의 최대 HP의 <color=#00F6FF>12%</color>에 해당하는 실드를 획득한다.",
  str_skill_passive_desc_410120 = "연쇄 스킬 및 액티브 스킬 시전 시 폼페이가 나타나 헤이디를 대신해 공격하며, 폼페이의 공격력은 헤이디의 공격력의 <color=#00F6FF>{1}</color>가 적용된다.",
  str_skill_passive_desc_430120 = "연쇄 스킬 및 액티브 스킬 시전 시 폼페이가 나타나 헤이디를 대신해 공격하며, 폼페이의 공격력은 헤이디의 공격력의 <color=#00F6FF>{1}</color>가 적용된다. 오로라 타임 진입 시 한 칸을 연결할 때마다 폼페이의 공격력이 <color=#00F6FF>2%</color> 증가하며, 최대 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_410123 = "<color=#00F6FF>마름모 12칸</color> 범위에 적이 1명 있을 때마다 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430123 = "<color=#00F6FF>주변 2서클</color> 범위에 적이 1명 있을 때마다 공격력과 방어력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410015 = "액티브 스킬이 적에게 피해를 입히기 전 수류탄이 1서클을 이동할 때마다 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420015 = "액티브 스킬이 적에게 피해를 입히기 전 수류탄이 1서클을 이동할 때마다 최종 피해가 <color=#00F6FF>{1}</color> 증가하며, 연쇄 스킬이 적에게 피해를 입히기 전 수류탄이 1서클을 이동할 때마다 최종 피해가 <color=#00F6FF>{2}</color> 증가한다.",
  str_skill_passive_desc_410131 = "일반공격 전 파티의 HP가 최대치가 아닐 시 이번 일반공격의 효과가 노비오의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복하는 것으로 변경된다.",
  str_skill_passive_desc_430131 = "일반공격 전 파티의 HP가 최대치가 아닐 시 이번 일반공격의 효과가 노비오의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복하는 것으로 변경된다. HP가 최대치일 경우 일반공격과 연쇄 스킬 피해가 <color=#00F6FF>10%</color> 증가하며, 실드 보유 시 해당 피해 보너스가 <color=#00F6FF>25%</color>로 증가한다.",
  str_skill_passive_desc_410132 = "오로라 타임 내 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430132 = "오로라 타임 내 공격력이 <color=#00F6FF>{1}</color> 증가한다. 어떤 속성의 칸을 지나가도 모두 연쇄 스킬을 시전하며, 연쇄 스킬 피해는 숲 속성을 기준으로 한다.",
  str_skill_passive_desc_410133 = "콤보마다 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430133 = "콤보마다 연쇄 스킬 피해가 <color=#00F6FF>{1}</color>, 스플래시 피해가 <color=#00F6FF>{2}</color> 증가한다.",
  str_skill_passive_desc_410137 = "액티브 스킬이 선택한 적에게 피해를 입히며, 적이 밟고 있는 칸에 물 속성 칸이 <color=#00F6FF>1</color>개 있을 때마다 파프닐의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_430137 = "액티브 스킬이 선택한 적에게 피해를 입히며, 적이 밟고 있는 칸에 물 속성 칸이 <color=#00F6FF>1</color>개 있을 때마다 파프닐의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 다른 메이드래곤 콜라보 캐릭터의 액티브 스킬이 적에게 명중할 경우에도 해당 피해 효과가 발동한다.",
  str_skill_passive_desc_410134 = "칸나가 액티브 스킬 시전 시 에너지 충전을 3회 획득하고, 나머지 번개 속성 오로리안 또는 다른 메이드래곤 콜라보 캐릭터가 액티브 스킬 시전 시 1회 획득하며(최대 10단계), 단계마다 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 에너지 충전 단계가 초기화된다.",
  str_skill_passive_desc_430134 = "칸나가 액티브 스킬 시전 시 에너지 충전을 3회 획득하고, 나머지 번개 속성 오로리안 또는 다른 메이드래곤 콜라보 캐릭터가 액티브 스킬 시전 시 1회 획득하며(최대 10단계), 단계마다 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 에너지 충전 단계가 절반 유지된다.",
  str_skill_passive_desc_416134 = "칸나가 액티브 스킬 시전 시 에너지 충전을 3회 획득하고, 나머지 번개 속성 오로리안 또는 다른 메이드래곤 콜라보 캐릭터가 액티브 스킬 시전 시 1회 획득하며(최대 10단계), 단계마다 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 에너지 충전 단계가 초기화되며, 웨이브가 시작될 때마다 칸나가 에너지 충전을 추가로 2회 획득한다.",
  str_skill_passive_desc_436134 = "칸나가 액티브 스킬 시전 시 에너지 충전을 3회 획득하고, 나머지 번개 속성 오로리안 또는 다른 메이드래곤 콜라보 캐릭터가 액티브 스킬 시전 시 1회 획득하며(최대 10단계), 단계마다 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 에너지 충전 단계가 절반 유지되며, 웨이브가 시작될 때마다 칸나가 에너지 충전을 추가로 2회 획득한다.",
  str_skill_passive_desc_410135 = "현재 HP가 최대일 시 일반공격 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430135 = "현재 HP가 최대일 시 일반공격, 연쇄 스킬, 액티브 스킬 피해가 모두 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_410136 = "연쇄 스킬이 적 명중 시 대상에게 속세의 인장을 추가하며, 인장 개수마다 해당 적이 모든 오로리안에게 받는 액티브 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다. 인장은 최대 <color=#00F6FF>10</color>회 중첩되며, 이번 전투 동안 유지된다.",
  str_skill_desc_200501 = "<color=#00F6FF>X형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_210501 = "<color=#00F6FF>X형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200221 = "<color=#00F6FF>십자형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시킨다.",
  str_skill_desc_200471 = "조르아의 공격력의 <color=#00F6FF>160%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_210471 = "조르아의 공격력의 <color=#00F6FF>210%</color>만큼 파티의 HP를 회복시킨다.",
