  str_skill_desc_200991 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_220991 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 마검 사용 중 연쇄 스킬이 아이리나의 공격력 <color=#00F6FF>1.5</color>배보다 HP가 낮은 적을 즉시 처치한다.",
