  str_skill_desc_221001 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 대상의 영혼이 수확될 경우 방어무시 피해를 입는다.",
  str_skill_desc_200981 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200941 = "<color=#00F6FF>주변 2서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_210941 = "<color=#00F6FF>주변 2서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_220941 = "<color=#00F6FF>주변 3서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200961 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_200561 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001031 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201031 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200671 = "앨리스의 공격력의 <color=#00F6FF>160%</color>만큼 파티의 HP를 회복시킨다.",
