  str_skill_desc_230301 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200711 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001051 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>45%</color>의 피해를 3회 입힌다.",
  str_skill_desc_2301091 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 ESP 1포인트를 획득한다.",
  str_skill_desc_2361091 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 ESP 1포인트를 획득한다. <color=#00F6FF>30%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가한다(ESP 1포인트마다 발동 확률 1% 증가).",
  str_skill_desc_2301101 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 피해를 입혔을 시 거리가 가장 먼 적에게 동일한 피해의 뇌격을 1회 시전한다.",
  str_skill_desc_2301071 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2301081 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 1명에게 명중할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득한다.",
  str_skill_desc_2001121 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001111 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001131 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
