  str_skill_desc_2201141 = "<color=#00F6FF>주변 3서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2221141 = "<color=#00F6FF>주변 3서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001271 = "<color=#00F6FF>X형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
