  str_skill_desc_2001151 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001261 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001262 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001263 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2301261 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 프랭크가 범위 내에 있을 경우 프랭크가 가장 가까운 적 근처의 칸으로 순간이동하고 적을 공격한다.",
  str_skill_desc_2301262 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 프랭크가 범위 내에 있을 경우 프랭크가 가장 가까운 적 근처의 칸으로 순간이동하고 적을 공격한다.",
  str_skill_desc_2301263 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 프랭크가 범위 내에 있을 경우 프랭크가 가장 가까운 적 근처의 칸으로 순간이동하고 적을 공격한다.",
  str_skill_desc_200551 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200552 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200553 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001291 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>155%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001292 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>160%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001293 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>165%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001201 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001202 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001203 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201201 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>16%</color>의 추가 피해를 1회 입힌다.",
