  str_skill_desc_2201203 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>20%</color>의 추가 피해를 1회 입힌다.",
  str_skill_desc_2001231 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001232 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
