  str_skill_desc_200152 = "가장 가까운 적 1명 및 해당 적과 가장 가까운 다른 적 1명에게 수류탄을 발사해 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_desc_2001311 = "<color=#00F6FF>마름모 12칸</color>에 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고, 노비오의 공격력의 <color=#00F6FF>140%</color>만큼 HP를 회복한다.",
  str_skill_desc_2001312 = "<color=#00F6FF>쌍십자형 16칸</color>에 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고, 노비오의 공격력의 <color=#00F6FF>160%</color>만큼 HP를 회복한다.",
