  str_skill_desc_2201372 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적이 밟고 있는 칸에서 물 속성 칸의 비율에 따라 최대 <color=#00F6FF>40%</color> 확률로 적에게 <color=#00F6FF>1</color>턴간 공포 상태를 부여한다.",
