  str_skill_desc_210922 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속되며, 해당 대상에게 표식을 추가한다.",
  str_skill_desc_220922 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속되며, 해당 대상에게 표식을 추가한다.",
