  str_skill_desc_206642 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>50%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_220642 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 오버로드 모드에서 스플래시 범위가 <color=#00F6FF>주변 1서클</color>까지 증가한다.",
  str_skill_desc_226642 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>50%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 오버로드 모드에서 스플래시 범위가 <color=#00F6FF>주변 1서클</color>까지 증가한다.",
