  str_skill_desc_213942 = "<color=#00F6FF>주변 2서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_223942 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200962 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>140%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_200562 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001032 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
