  str_skill_desc_2361092 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 ESP 2포인트를 획득한다. <color=#00F6FF>30%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가한다(ESP 1포인트마다 발동 확률 1% 증가).",
  str_skill_desc_2301102 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 피해를 입혔을 시 거리가 가장 먼 적에게 동일한 피해의 뇌격을 1회 시전한다.",
