  str_skill_desc_2301082 = "<color=#00F6FF>주변 4서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 1명에게 명중할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득한다.",
