  str_skill_desc_220263 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다. <color=#00F6FF>30%</color> 확률로 1회 더 부여한다(최대 5회 중첩). 2턴간 지속.",
