  str_skill_desc_210773 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200923 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속되며, 해당 대상에게 표식을 추가한다.",
  str_skill_desc_210923 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속되며, 해당 대상에게 표식을 추가한다.",
  str_skill_desc_220923 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 동시에 숲 속성 칸의 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속되며, 해당 대상에게 표식을 추가한다.",
  str_skill_desc_200753 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_200573 = "필리시의 공격력의 <color=#00F6FF>240%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_200893 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200273 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200603 = "<color=#00F6FF>주변 4서클</color> 내의 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200643 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_206643 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>50%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_220643 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 오버로드 모드에서 스플래시 범위가 <color=#00F6FF>주변 1서클</color>까지 증가한다.",
  str_skill_desc_226643 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 <color=#00F6FF>50%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 오버로드 모드에서 스플래시 범위가 <color=#00F6FF>주변 1서클</color>까지 증가한다.",
  str_skill_desc_200703 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_230703 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. <link=\"10002\">매 <#FFAE07><u>작열</u></color></link> 시 연쇄 스킬 피해가 <color=#00F6FF>5%</color> 증가한다.",
