  str_skill_desc_220993 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 마검 사용 중 연쇄 스킬이 아이리나의 공격력 <color=#00F6FF>1.5</color>배보다 HP가 낮은 적을 즉시 처치한다.",
  str_skill_desc_201003 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_221003 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 대상의 영혼이 수확될 경우 방어무시 피해를 입는다.",
  str_skill_desc_200983 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_200963 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>150%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001033 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201033 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2301093 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 ESP 3포인트를 획득한다.",
  str_skill_desc_2361093 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 ESP 3포인트를 획득한다. <color=#00F6FF>30%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가한다(ESP 1포인트마다 발동 확률 1% 증가).",
  str_skill_desc_2301103 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 피해를 입혔을 시 거리가 가장 먼 적에게 동일한 피해의 뇌격을 1회 시전한다.",
  str_skill_desc_2301073 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2301083 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 1명에게 명중할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득한다.",
  str_skill_desc_2001123 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001113 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
