  str_skill_desc_2001153 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_500223 = "피니가 에너지를 사용해 모두의 HP를 회복시킨다.",
  str_skill_desc_540223 = "피니가 에너지를 사용해 모두의 HP를 회복시키고, 3단계의 실드를 추가한다.",
  str_skill_desc_1002410 = "섬광의 행진",
  str_skill_desc_1002411 = "모르페우스 블링크",
  str_skill_desc_1002412 = "보이드의 연회",
  str_skill_desc_1002413 = "보이드의 부활",
  str_skill_name_1002410 = "대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가한다.",
  str_skill_name_1002411 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 3마리를 던진다.",
  str_skill_name_1002412 = "모르페우스가 랜덤 위치에 보이드 9마리를 던진다.",
  str_skill_name_1002413 = "오로리안이 접근 시 폭발하며, 아무도 접근하지 않을 시 일정 턴 이후 자폭해 자신이 있던 자리에 파괴된 칸 1칸을 만든다.",
  str_skill_desc_1002414 = "오로리안이 접근 시 폭발하며, 아무도 접근하지 않을 시 일정 턴 이후 자폭해 자신이 있던 자리에 2턴간 존재하는 위험 영역 1개를 만든다.",
  str_skill_desc_280043111 = "공격 범위 내 대상에게 화염을 뿜어 피해를 입히고 대상을 작열시키며, 범위 내의 칸을 부순다.",
  str_skill_name_29106811 = "모르페우스 블링크",
  str_skill_desc_29106811 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 2마리를 던진다.",
  str_skill_name_29106812 = "모르페우스 블링크",
  str_skill_desc_29106812 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 3마리를 던진다.",
  str_skill_name_29106813 = "모르페우스 블링크",
  str_skill_desc_29106813 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 1마리, 블라스터 1마리를 던진다.",
  str_skill_name_29106814 = "모르페우스 블링크",
  str_skill_desc_29106814 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 2마리, 블라스터 1마리를 던진다.",
  str_skill_name_29106815 = "보이드의 연회",
  str_skill_desc_29106815 = "모르페우스가 랜덤 위치에 보이드 5마리를 던진다.",
  str_skill_name_29106816 = "보이드의 연회",
  str_skill_desc_29106816 = "모르페우스가 랜덤 위치에 보이드 9마리를 던진다.",
  str_skill_name_290140110 = "스파이키호그·맹공",
  str_skill_desc_290140110 = "그레텔이 지면을 강하게 타격해 주변 2서클 범위에 피해를 입히고 가시를 소환한다.",
  str_skill_name_290140120 = "스파이키호그·공포",
  str_skill_desc_290140120 = "그레텔이 대상을 향해 이동한 후 전방 2열 범위에 피해를 입힌 후 대상을 넉백시키며, 경로상에 무딘 가시를 소환한다.",
  str_skill_name_290140130 = "소생의 세례",
  str_skill_desc_290140130 = "그레텔이 분신을 회수한 후 다시 내보내며, 전체화면 범위에 피해를 입힌다.",
  str_skill_name_1020111 = "무딘 가시",
  str_skill_desc_1020111 = "부드러워진 가시, 다음 턴에 사라진다. 다른 가시와 합쳐진 후 새로운 날카로운 가시를 생성한다.",
  str_skill_name_1020121 = "날카로운 가시",
  str_skill_desc_1020121 = "날카로운 가시, 다음 턴에 무딘 가시로 변한다. 다른 가시와 합쳐진 후 새로운 날카로운 가시를 생성한다.",
  str_skill_name_290150110 = "바실리스크·깨물기",
  str_skill_desc_290150110 = "그레텔이 대상을 향해 이동한 후 분신을 소환해 전방 단거리에 깨물기 스킬을 시전한다.",
  str_skill_name_290150120 = "바실리스크·꼬리 휩쓸기",
  str_skill_desc_290150120 = "그레텔의 분신이 꼬리로 넓은 범위를 공격하며, 대상을 공격 범위 밖으로 넉백시킨다.",
  str_skill_name_290150130 = "소생의 세례",
  str_skill_desc_290150130 = "그레텔이 분신을 회수한 후 다시 내보내며, 전체화면 범위에 피해를 입힌다.",
  str_skill_name_290160110 = "아이언스톰프·대지 균열",
  str_skill_desc_290160110 = "제자리의 바닥을 밟아 주변에 피해를 입히고 부서진 칸을 생성한다.",
  str_skill_name_290160120 = "아이언스톰프·대지 분쇄",
  str_skill_desc_290160120 = "대상을 향해 이동한 후 주변 1서클에 피해를 입히고 부서진 칸을 생성하며, 이동 중에도 경로상에 부서진 칸을 생성한다.",
  str_skill_name_290160130 = "소생의 세례",
  str_skill_desc_290160130 = "아이언스톰프를 불러들여 에너지를 보충한 후 다시 내보내며, 전체화면 범위에 피해를 입힌다.",
  str_skill_name_290170110 = "키티푸스·물놀이",
  str_skill_desc_290170110 = "적을 향해 이동한 후 촉수로 십자형 범위 내의 적을 때려 피해를 입힌다.",
  str_skill_name_290170120 = "키티푸스·심연",
  str_skill_desc_290170120 = "제자리에서 촉수로 X자 범위 내의 적을 때려 대량의 피해를 입힌다.",
  str_skill_name_290170130 = "소생의 세례",
  str_skill_desc_290170130 = "키티푸스를 불러들여 에너지를 보충한 후 다시 내보내며, 전체화면 범위에 피해를 입힌다.",
  str_skill_name_200140110 = "텐타클로·피하기",
  str_skill_desc_200140110 = "피해를 입으면 키티푸스의 본체로 피해를 전달하나, 오로리안이 이동을 시작하면 텐타클로가 몸을 숨겨 공격을 피한다.",
  str_skill_name_300139 = "리버스 펜타클",
  str_skill_name_302139 = "리버스 펜타클",
  str_skill_name_320139 = "리버스 펜타클",
  str_skill_name_322139 = "리버스 펜타클",
  str_skill_name_2001391 = "미지의 회전전파",
  str_skill_name_2001392 = "미지의 회전전파",
  str_skill_name_2001393 = "미지의 회전전파",
  str_skill_passive_name_410139 = "초연의 우레",
  str_skill_passive_name_430139 = "초연의 우레",
  str_skill_upgrade_desc_15013912 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15013915 = "액티브 스킬 강화: 주변 <color=#FFFF00>8</color>방향을 선택할 수 있게 된다.",
  str_skill_desc_300139 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향 경로 및 인접한 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내 <color=#00F6FF>번개 속성이 아닌 칸</color>을 초기화한다.",
  str_skill_desc_302139 = "자신의 주변 <color=#00F6FF>8</color>개 방향 중 1개 방향을 선택, 해당 방향 경로 및 인접한 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 범위 내 <color=#00F6FF>번개 속성이 아닌 칸</color>을 초기화한다.",
  str_skill_desc_320139 = "자신의 주변 <color=#00F6FF>4</color>개 방향 중 1개 방향을 선택, 해당 방향 경로 및 인접한 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 랜덤으로 범위 내 1명의 적에게 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가한다. 범위 내 <color=#00F6FF>번개 속성이 아닌 칸</color>을 초기화한다.",
  str_skill_desc_322139 = "자신의 주변 <color=#00F6FF>8</color>개 방향 중 1개 방향을 선택, 해당 방향 경로 및 인접한 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 랜덤으로 범위 내 1명의 적에게 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 효과를 추가한다. 범위 내 <color=#00F6FF>번개 속성이 아닌 칸</color>을 초기화한다.",
  str_skill_desc_2001391 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001392 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001393 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410139 = "번개 속성 칸의 적에게 피해를 입힐 시 해당 적과의 거리가 1서클 멀 때마다 에리카의 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430139 = "번개 속성 칸의 적에게 피해를 입힐 시 해당 적과의 거리가 1서클 멀 때마다 에리카의 피해가 <color=#00F6FF>{1}</color> 증가하며, 파티 내 다른 번개 속성 오로리안이 절반의 피해 보너스를 획득한다.",
  str_skill_name_300138 = "팔족 학도의 영역",
  str_skill_name_320138 = "팔족 학도의 영역",
  str_skill_name_330138 = "팔족 학도의 영역",
  str_skill_name_2001381 = "거미의 행렬",
  str_skill_name_2001382 = "거미의 행렬",
  str_skill_name_2001383 = "거미의 행렬",
  str_skill_passive_name_410138 = "거미줄 방패",
  str_skill_passive_name_416138 = "거미줄 방패",
  str_skill_upgrade_desc_16013813 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16013816 = "장비 스킬 강화: <link=\"30025\"><#FFAE07><u>거미줄 인장</u></color></link>을 통해 실드를 획득할 때 인장의 수가 10개 이상일 경우, 시오반의 HP의 <color=#00F6FF>15%</color>에 해당하는 실드를 추가로 획득한다.",
  str_skill_desc_300138 = "1칸을 선택한 후 다시 2*2 또는 1*4 범위를 선택해 범위 내의 칸을 숲 속성으로 전환한다.",
  str_skill_desc_320138 = "1칸을 선택한 후 다시 2*2 또는 1*4 범위를 선택해 범위 내의 칸을 숲 속성으로 전환하며, 시전 과정에서 선택한 2개의 칸은 모두 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환된다.",
  str_skill_desc_330138 = "1칸을 선택한 후 다시 2*2 또는 1*4 범위를 선택해 범위 내의 칸을 숲 속성으로 전환하며, 시전 과정에서 선택한 2개의 칸은 모두 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환된다. 오로라 타임 중 15연쇄 달성 시 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_2001381 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001382 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001383 = "<color=#00F6FF>주변 4서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410138 = "<link=\"30025\"><#FFAE07><u>거미줄 인장</u></color></link>을 획득할 수 있다. 공격받기 전 인장 개수를 초기화하며, 개수마다 시오반의 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 부여한다.",
  str_skill_passive_desc_416138 = "<link=\"30025\"><#FFAE07><u>거미줄 인장</u></color></link>을 획득할 수 있다. 공격받기 전 인장 개수를 초기화하며, 개수마다 시오반의 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 부여한다. <link=\"30025\"><#FFAE07><u>거미줄 인장</u></color></link>을 통해 실드를 획득할 때 인장의 수가 10개 이상일 경우, 시오반의 HP의 <color=#00F6FF>15%</color>에 해당하는 실드를 추가로 획득한다.",
  str_skill_upgrade_desc_16014113 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16014116 = "액티브 스킬 강화: 밟고 있는 칸을 터치하면 넉백 및 색 변경 방향을 역방향으로 전환할 수 있다.",
  str_skill_desc_2001411 = "가장 가까운 적 2명에게 <color=#00F6FF>115%</color>의 피해를 입히며, 적이 1명일 시 2회의 피해를 입힌다.",
  str_skill_desc_2001412 = "가장 가까운 적 2명에게 <color=#00F6FF>130%</color>의 피해를 입히며, 적이 1명일 시 2회의 피해를 입힌다.",
  str_skill_desc_2001413 = "가장 가까운 적 2명에게 <color=#00F6FF>150%</color>의 피해를 입히며, 적이 1명일 시 2회의 피해를 입힌다.",
  str_skill_desc_300141 = "<color=#00F6FF>십자형 최대</color> 또는 <color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 물 속성으로 전환한다.",
  str_skill_desc_306141 = "<color=#00F6FF>십자형 최대</color> 또는 <color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 물 속성으로 전환한다. 밟고 있는 칸을 터치하면 넉백 및 색 변경 방향을 역방향으로 전환할 수 있다.",
  str_skill_desc_320141 = "<color=#00F6FF>십자형 최대</color> 또는 <color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 물 속성으로 전환한다. 명중한 적에게 현재 장비 스킬 레벨에 비례하는 피해를 1회 입힌다.",
  str_skill_desc_326141 = "<color=#00F6FF>십자형 최대</color> 또는 <color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 동시에 공격 범위의 칸을 물 속성으로 전환한다. 밟고 있는 칸을 터치하면 넉백 및 색 변경 방향을 역방향으로 전환할 수 있다. 명중한 적에게 현재 장비 스킬 레벨에 비례하는 피해를 1회 입힌다.",
  str_skill_passive_desc_410141 = "연쇄 스킬이 동일 대상에게 <color=#00F6FF>3</color>회 피해를 입힐 때마다 대상의 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_passive_desc_420141 = "연쇄 스킬이 동일 대상에게 <color=#00F6FF>3</color>회 피해를 입힐 때마다 대상의 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_passive_desc_430141 = "연쇄 스킬이 동일 대상에게 <color=#00F6FF>3</color>회 피해를 입힐 때마다 대상의 현재 HP의 <color=#00F6FF>{1}</color>에 해당하는 추가 피해를 입히며, 추가 피해는 루비의 기본 방어력의 <color=#00F6FF>{2}</color>보다 높은 수치로 정해진다.",
