  str_skill_desc_2001422 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001423 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300142 = "주변 <color=#00F6FF>마름모 13칸</color> 내 1개의 칸을 선택, 해당 칸 및 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 보스를 제외한 적을 해당 칸 방향으로 <color=#00F6FF>2</color>칸 강제로 이동시킨다. 피해 계수는 서클마다 53% 감소한다.",
  str_skill_desc_302142 = "주변 <color=#00F6FF>마름모 13칸</color> 내 1개의 칸을 선택, 해당 칸 및 <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 보스를 제외한 적을 해당 칸 방향으로 <color=#00F6FF>2</color>칸 강제로 이동시킨다. 피해 계수는 서클마다 53% 감소한다.",
  str_skill_desc_320142 = "주변 <color=#00F6FF>마름모 13칸</color> 내 1개의 칸을 선택, 해당 칸 및 <color=#00F6FF>주변 3서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 보스를 제외한 적을 해당 칸 방향으로 <color=#00F6FF>3</color>칸 강제로 이동시킨다. 피해 계수는 서클마다 53% 감소한다.",
  str_skill_desc_322142 = "주변 <color=#00F6FF>마름모 13칸</color> 내 1개의 칸을 선택, 해당 칸 및 <color=#00F6FF>주변 3서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 보스를 제외한 적을 해당 칸 방향으로 <color=#00F6FF>3</color>칸 강제로 이동시킨다. 피해 계수는 서클마다 53% 감소한다.",
  str_skill_passive_desc_410142 = "<color=#00F6FF>3</color>번째 일반공격마다 대상의 현재 HP 퍼센트에 따라 이번 일반공격 피해가 증가하며, 대상의 HP가 최대일 시 가장 많은 <color=#00F6FF>{1}</color>의 보너스를 받는다.",
  str_skill_passive_desc_420142 = "<color=#00F6FF>3</color>번째 및 <color=#00F6FF>5</color>번째 일반공격마다 대상의 현재 HP 퍼센트에 따라 이번 일반공격 피해가 증가하며, 대상의 HP가 최대일 시 가장 많은 <color=#00F6FF>{1}</color>의 보너스를 받는다.",
  str_skill_upgrade_desc_16014013 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16014016 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
