  str_skill_desc_2001401 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001402 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001403 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>80%</color>가 적용된다.",
  str_skill_desc_306140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>80%</color>가 적용된다.",
  str_skill_desc_320140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>80%</color>가 적용된다. 동시에 번개 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_desc_326140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>80%</color>가 적용된다. 동시에 번개 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_desc_330140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>95%</color>가 적용된다. 동시에 번개 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_desc_336140 = "사용 시 이번 턴에 번개 속성 오로리안의 연쇄 스킬이 <color=#00F6FF>2</color>회 시전되며, <color=#00F6FF>2</color>번째 시전 시 모든 번개 계열 오로리안의 공격력은 플로리나의 공격력의 <color=#00F6FF>95%</color>가 적용된다. 동시에 번개 속성 오로리안 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color>개 감소한다.",
  str_skill_passive_desc_410140 = "모든 번개 속성 오로리안의 단계별 연쇄 스킬 피해 계수가 각각 <color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color> 증가한다.",
  str_skill_name_200150110 = "오니·가르기",
  str_skill_desc_200150110 = "발톱을 휘둘러 범위 내 대상을 찢어버린다.",
  str_skill_name_290200101 = "그림자 노부토라",
  str_skill_desc_290200101 = "적이 자신의 주변 2서클 내에 있을 시 적으로부터 6칸 떨어진 위치로 순간이동 후 제자리에 그림자 노부토라 1개를 남긴다.",
  str_skill_name_290200102 = "각퇴격",
  str_skill_desc_290200102 = "적이 주변 2서클 내에 있지 않을 시 범위 내의 적에게 원거리 공격을 가하고, 오로리안의 편대 순서를 변경한다.",
  str_skill_name_290200112 = "각퇴격",
  str_skill_desc_290200112 = "적이 주변 2서클 내에 있지 않을 시 범위 내의 적에게 원거리 공격을 가하고, 오로리안의 편대 순서를 변경한다. 후지쿠모 노부토라와 적이 멀수록 피해가 증가한다.",
  str_skill_name_290200201 = "그림자 습격",
  str_skill_desc_290200201 = "그림자 노부토라가 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_upgrade_desc_16014313 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16014316 = "장비 스킬 강화: 이번 전투의 리더 변경 횟수가 <color=#FFFF00>1</color>회 증가한다.",
  str_skill_desc_2001431 = "<color=#00F6FF>주변 2서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001432 = "<color=#00F6FF>주변 3서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001433 = "<color=#00F6FF>주변 4서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300143 = "자신을 중심으로 <color=#00F6FF>주변 2서클</color> 범위에 2턴간 지속되는 결계를 소환하며, 소환 시 또는 턴 종료 시 결계 범위 내 랜덤 <color=#00F6FF>3</color>개의 불 속성이 아닌 칸을 불 속성 칸으로 전환하고, 범위 내 모든 불 속성 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>한다.",
  str_skill_desc_306143 = "자신을 중심으로 <color=#00F6FF>주변 2서클</color> 범위에 2턴간 지속되는 결계를 소환하며, 소환 시 또는 턴 종료 시 결계 범위 내 랜덤 <color=#00F6FF>3</color>개의 불 속성이 아닌 칸을 불 속성 칸으로 전환하고, 범위 내 모든 불 속성 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>한다.",
  str_skill_desc_330143 = "자신을 중심으로 <color=#00F6FF>주변 2서클</color> 범위에 2턴간 지속되는 결계를 소환하며, 소환 시 또는 턴 종료 시 결계 범위 내 랜덤 <color=#00F6FF>3</color>개의 불 속성이 아닌 칸을 불 속성 칸으로 전환하고, 범위 내 모든 불 속성 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>한다. 결계 내에 있을 시 린네의 방어력이 <color=#00F6FF>50%</color> 증가하며, 파티 내 다른 불 속성 오로리안의 방어력이 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_desc_336143 = "자신을 중심으로 <color=#00F6FF>주변 2서클</color> 범위에 2턴간 지속되는 결계를 소환하며, 소환 시 또는 턴 종료 시 결계 범위 내 랜덤 <color=#00F6FF>3</color>개의 불 속성이 아닌 칸을 불 속성 칸으로 전환하고, 범위 내 모든 불 속성 칸을 <link=\"30020\"><#FFAE07><u>정화</u></color></link>한다. 결계 내에 있을 시 린네의 방어력이 <color=#00F6FF>50%</color> 증가하며, 파티 내 다른 불 속성 오로리안의 방어력이 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_410143 = "린네가 어떤 방식으로든 리더가 될 경우 린네의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복하며, 턴마다 최대 <color=#00F6FF>1</color>회 발동한다.",
  str_skill_passive_desc_416143 = "린네가 어떤 방식으로든 리더가 될 경우 린네의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복하며, 턴마다 최대 <color=#00F6FF>1</color>회 발동한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_420143 = "린네가 어떤 방식으로든 리더가 될 경우 린네의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복하며, 발동 후 HP가 최대치가 될 경우 가장 가까운 물 속성 칸을 불 속성 칸으로 전환한다. 턴마다 최대 <color=#00F6FF>1</color>회 발동한다.",
  str_skill_passive_desc_426143 = "린네가 어떤 방식으로든 리더가 될 경우 린네의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 HP를 회복하며, 발동 후 HP가 최대치가 될 경우 가장 가까운 물 속성 칸을 불 속성 칸으로 전환한다. 턴마다 최대 <color=#00F6FF>1</color>회 발동한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_name_2001431 = "축마혼",
