  str_skill_upgrade_desc_15014415 = "장비 스킬 강화: 이번 전투의 리더 변경 횟수가 <color=#FFFF00>1</color>회 증가한다.",
  str_skill_desc_2001441 = "<color=#00F6FF>주변 2서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001442 = "<color=#00F6FF>주변 3서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001443 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300144 = "현재의 리더와 위치를 교체한다.",
  str_skill_desc_302144 = "선택한 다른 팀원과 위치를 교체한다.",
  str_skill_desc_305144 = "선택한 다른 팀원과 위치를 교체한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_310144 = "현재의 리더와 위치를 교체한다.",
  str_skill_desc_312144 = "선택한 다른 팀원과 위치를 교체한다.",
  str_skill_desc_315144 = "선택한 다른 팀원과 위치를 교체한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_410144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득).",
  str_skill_passive_desc_420144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득). 위치가 뒤로 더 많이 밀릴수록 보너스가 증가하며, 최대 기본 수치의 2.5배를 획득한다.",
  str_skill_passive_desc_430144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득). 위치가 뒤로 더 많이 밀릴수록 보너스가 증가하며, 최대 기본 수치의 2.5배를 획득한다. 현재 리더가 카야노와 동일한 공격 보너스를 획득한다.",
  str_skill_passive_desc_415144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득). 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_425144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득). 위치가 뒤로 더 많이 밀릴수록 보너스가 증가하며, 최대 기본 수치의 2.5배를 획득한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_435144 = "카야노가 편대의 후미에 있지 않을 경우 후미로 이동하며, 나머지 팀원은 위로 1칸 전진한다. 이번 턴에 파티 내 <color=#00F6FF>위치가 뒤로 밀린</color> 오로리안은 카야노의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 공격 보너스를 획득한다(여러 차례 발동할 시 최고 보너스만 획득). 위치가 뒤로 더 많이 밀릴수록 보너스가 증가하며, 최대 기본 수치의 2.5배를 획득한다. 현재 리더가 카야노와 동일한 공격 보너스를 획득한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
