  str_skill_passive_name_435144 = "등 뒤의 영혼",
  str_skill_name_290190110 = "명토의 유검·습",
  str_skill_desc_290190110 = "대상의 전방으로 돌진해 대량의 피해를 입히고, 리더를 편대의 마지막 자리로 떨어트린다. 대상이 십자형 범위에 있지 않고 거리가 멀 경우 원거리 사격을 가한다.",
  str_skill_name_290190120 = "명토의 유검·격",
  str_skill_desc_290190120 = "근접한 대상을 가로로 베어 대량의 피해를 입힌다. 십자형 범위에 있지 않고 거리가 멀 경우 원거리 사격을 가한다.",
  str_skill_desc_490190120 = "돌격 종료 후, 근접한 대상을 가로로 베어 대량의 피해를 입힌다.",
  str_skill_name_290190130 = "명토의 유검·낙",
  str_skill_desc_290190130 = "보드의 중심으로 이동한 후 화승총을 뽑아 십자형 범위에 있지 않고 거리가 먼 대상에게 원거리 피해를 입힌다.",
  str_skill_desc_490190130 = "화승총을 뽑아 베어 가른 범위 밖의 대상에게 원거리 피해를 입힌다.",
  str_skill_name_290191110 = "나기·광도 이연격",
  str_skill_desc_290191110 = "가까운 위협에 대응하기 위해 가로베기와 찌르기 공격을 연달아 가한다.",
  str_skill_name_290191120 = "나기·광도 돌진",
  str_skill_desc_290191120 = "대상과 거리가 멀 경우 대상의 근처까지 추격해 피해를 입힌다.",
  str_skill_name_290191130 = "나기·광도 순폭",
  str_skill_desc_290191130 = "전장 중앙 위치로 순간이동해 자신 주변 넓은 범위에 피해를 입힌다. 명중 시 리더를 편대의 마지막 자리로 떨어트린다.",
  str_skill_name_290210101 = "악령의 회오리",
  str_skill_desc_290210101 = "대상이 범위 내에 있을 시 전방 2서클 범위 내 오로리안과 「오니」를 삼켜 오로리안에게 피해를 입힌다. 이후 대상을 외곽으로 토해내고 현재 오로리안 리더를 저주해 편대의 후미로 떨어트린다.",
  str_skill_desc_291210101 = "대상이 범위 내에 있을 시 전방 2서클 범위 내 오로리안과 「오니」를 삼켜 오로리안에게 피해를 입힌다. 이후 대상을 외곽으로 토해내고 리더를 저주해 편대의 후미로 떨어트린다.",
  str_skill_name_290210102 = "악령의 소멸",
  str_skill_desc_290210102 = "대상이 범위 내에 있을 시 대상에게 대량의 피해를 입히고, 오로리안 편대 순서를 변경하며, 대상 주변의 모든 「오니」를 처치한다.",
  str_skill_name_290210201 = "악령의 진",
  str_skill_desc_290210201 = "대상이 범위 내에 있을 시 대량의 「오니」를 소환하며, 필드 내 모든 「오니」를 강화한다.",
  str_skill_desc_291210201 = "대상이 범위 내에 있을 시 대량의 「오니」를 소환하며, 필드 내 모든 「오니」를 강화하고 치료한다.",
  str_skill_name_290210301 = "악령의 회오리",
  str_skill_desc_290210301 = "대상이 범위 내에 있을 시 전방 2서클 범위 내 오로리안과 「오니」를 삼켜 오로리안에게 고정피해를 입히며, 삼킨 「오니」의 수가 많을수록 피해가 증가한다. 이후 대상을 외곽으로 토해내고 현재 오로리안 리더를 저주해 편대의 후미로 떨어트린다.",
  str_skill_name_290042201 = "사룡의 발톱",
  str_skill_desc_290042201 = "하크도마가 눈앞의 공간을 갈라 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_290042211 = "사룡의 발톱",
  str_skill_desc_290042211 = "하크도마가 눈앞의 공간을 갈라 공격 범위 내 대상에게 피해를 입히고, 필드 내 일부 칸을 부순다.",
  str_skill_name_290042202 = "하크도마의 윤회",
  str_skill_desc_290042202 = "하크도마가 도약을 위해 힘을 축적하고, 자신의 날개를 들어 대상을 외곽까지 넉백시키며, 필드에 스파이크를 소환한다.",
  str_skill_name_290042204 = "격류의 사자",
  str_skill_desc_290042204 = "하크도마가 날아올라 모든 칸을 위로 4칸 이동시키며, 고정 구역을 폭격한다.",
  str_skill_name_290042214 = "격류의 사자",
  str_skill_desc_290042214 = "하크도마가 날아올라 고정 구역을 폭격하며, 대상 명중 여부에 관계없이 대상을 외곽까지 넉백시킨다. 하크도마가 착지할 때 자신의 앞에 스파이크를 소환한다.",
  str_skill_upgrade_desc_16014513 = "액티브 스킬 강화: 웨이브가 시작될 때마다 추가로 인력 <color=#FFFF00>1</color>포인트를 획득한다.",
  str_skill_upgrade_desc_16014516 = "장비 스킬 강화: 이번 전투의 리더 변경 횟수가 <color=#FFFF00>1</color>회 증가한다.",
  str_skill_name_2001451 = "무정무식",
  str_skill_name_2001452 = "무정무식",
  str_skill_name_2001453 = "무정무식",
  str_skill_desc_2001451 = "<color=#00F6FF>십자형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001452 = "<color=#00F6FF>마름모 12</color>칸에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 이동 가능한 랜덤 <color=#00F6FF>1</color>칸에 닌자도 1자루를 소환한다.",
  str_skill_desc_2001453 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 이동 가능한 랜덤 <color=#00F6FF>2</color>칸에 닌자도 1자루를 소환한다.",
