  str_skill_desc_300145 = "<link=\"30028\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 선택한 <color=#00F6FF>1</color>개의 이동 가능한 칸에 닌자도 1자루를 소환한다. 만약 선택한 칸에 닌자도가 있을 시 해당 위치로 순간이동 후 닌자도를 회수하며, 즉시 <link=\"30028\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_desc_330145 = "<link=\"30028\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 선택한 <color=#00F6FF>1</color>개의 이동 가능한 칸에 닌자도 1자루를 소환한다. 만약 선택한 칸에 닌자도가 있을 시 해당 위치로 순간이동 후 닌자도를 회수하며, 즉시 <link=\"30028\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_desc_303145 = "<link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 선택한 <color=#00F6FF>1</color>개의 이동 가능한 칸에 닌자도 1자루를 소환한다. 만약 선택한 칸에 닌자도가 있을 시 해당 위치로 순간이동 후 닌자도를 회수하며, 즉시 <link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_desc_333145 = "<link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 선택한 <color=#00F6FF>1</color>개의 이동 가능한 칸에 닌자도 1자루를 소환한다. 만약 선택한 칸에 닌자도가 있을 시 해당 위치로 순간이동 후 닌자도를 회수하며, 즉시 <link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득한다.",
