  str_skill_passive_name_426145 = "칼날의 질풍",
  str_skill_passive_name_430145 = "칼날의 질풍",
  str_skill_passive_name_433145 = "칼날의 질풍",
  str_skill_passive_name_436145 = "칼날의 질풍",
  str_skill_passive_desc_410145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다.",
  str_skill_passive_desc_413145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다.",
  str_skill_passive_desc_416145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_420145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다.",
  str_skill_passive_desc_423145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다.",
  str_skill_passive_desc_426145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_430145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다. 아메모리가 어떤 방식으로든 리더가 될 경우 <link=\"30028\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다.",
  str_skill_passive_desc_433145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다. 아메모리가 어떤 방식으로든 리더가 될 경우 <link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다.",
  str_skill_passive_desc_436145 = "액티브 스킬로 순간이동 후 모든 닌자도를 회수하며, 회수하는 닌자도 1자루마다 가장 가까운 적 <color=#00F6FF>1</color>명에게 <color=#00F6FF>{1}</color>의 방어무시 피해를 입힌다. 거리가 멀수록 피해가 감소하며, 기존 피해의 20%까지 감소한다. 최소 <color=#00F6FF>4</color>자루의 닌자도를 회수할 시 닌자도 <color=#00F6FF>1</color>자루를 다시 소환한다. 아메모리가 어떤 방식으로든 리더가 될 경우 <link=\"30029\"><#FFAE07><u>인력</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_upgrade_desc_16014613 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16014616 = "장비 스킬 강화: 이번 전투의 리더 변경 횟수가 <color=#FFFF00>1</color>회 증가한다.",
