  str_skill_name_2001463 = "추권세",
  str_skill_desc_20014601 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20014602 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20014603 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001461 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, <color=#00F6FF>주변 4칸</color>에 2배의 피해를 입힌다.",
  str_skill_desc_2001462 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, <color=#00F6FF>주변 4칸</color>에 2배의 피해를 입힌다.",
  str_skill_desc_2001463 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, <color=#00F6FF>주변 4칸</color>에 2배의 피해를 입힌다.",
  str_skill_name_300146 = "천인합일",
