  str_skill_name_330146 = "천인합일",
  str_skill_name_333146 = "천인합일",
  str_skill_desc_300146 = "현재의 리더와 위치를 교체하고, 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_desc_303146 = "현재의 리더와 위치를 교체하고, 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_desc_320146 = "현재의 리더와 위치를 교체하고, <link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 1개 획득한다. 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_desc_323146 = "현재의 리더와 위치를 교체하고, <link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 1개 획득한다. 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_desc_330146 = "현재의 리더와 위치를 교체하고, <link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 1개 획득한다. 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_desc_333146 = "현재의 리더와 위치를 교체하고, <link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 1개 획득한다. 이번 턴의 연쇄 스킬이 <color=#00F6FF>인접 4칸</color>에 입히는 피해가 2배 증가하며, 턴 종료 시 후미의 오로리안과 위치를 교체한다.",
  str_skill_passive_name_410146 = "경락지합",
  str_skill_passive_name_416146 = "경락지합",
  str_skill_passive_name_430146 = "경락지합",
  str_skill_passive_name_436146 = "경락지합",
  str_skill_passive_desc_410146 = "<link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 획득할 수 있다. 요우가 아군 턴에 리더가 된 적이 있을 경우 이번 턴에 인장 개수마다 요우의 기본 공격력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 초기화된다.",
  str_skill_passive_desc_416146 = "<link=\"30026\"><#FFAE07><u>의협의 인장</u></color></link>을 획득할 수 있다. 요우가 아군 턴에 리더가 된 적이 있을 경우 이번 턴에 인장 개수마다 요우의 기본 공격력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 초기화된다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_430146 = "<link=\"30027\"><#FFAE07><u>의협의 인장</u></color></link>을 획득할 수 있다. 요우가 아군 턴에 리더가 된 적이 있을 경우 이번 턴에 인장 개수마다 요우의 기본 공격력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 초기화된다. 요우가 어떤 방식으로든 리더가 될 때마다 <link=\"30027\"><#FFAE07><u>의협의 인장</u></color></link>을 <color=#00F6FF>1</color>단계 획득한다.",
  str_skill_passive_desc_436146 = "<link=\"30027\"><#FFAE07><u>의협의 인장</u></color></link>을 획득할 수 있다. 요우가 아군 턴에 리더가 된 적이 있을 경우 이번 턴에 인장 개수마다 요우의 기본 공격력이 <color=#00F6FF>{1}</color> 증가하며, 턴 종료 시 초기화된다. 요우가 어떤 방식으로든 리더가 될 때마다 <link=\"30027\"><#FFAE07><u>의협의 인장</u></color></link>을 <color=#00F6FF>1</color>단계 획득한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_upgrade_desc_15014712 = "액티브 스킬 강화: 리더가 될 때마다 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다.",
  str_skill_upgrade_desc_15014715 = "장비 스킬 강화: 이번 전투의 리더 변경 횟수가 <color=#FFFF00>1</color>회 증가한다.",
  str_skill_desc_2001471 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>150%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001472 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>160%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001473 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>160%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_300147 = "<color=#00F6FF>주변 3서클</color> 내의 칸 1개를 선택해 <color=#00F6FF>{1}%</color>의 피해를 <color=#00F6FF>8</color>회 입힌다.",
  str_skill_desc_302147 = "<color=#00F6FF>주변 3서클</color> 내의 칸 1개를 선택해 <color=#00F6FF>{1}%</color>의 피해를 <color=#00F6FF>8</color>회 입힌다. 리더가 될 때마다 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다.",
  str_skill_desc_320147 = "<color=#00F6FF>주변 3서클</color> 내의 칸 1개를 선택해 <color=#00F6FF>{1}%</color>의 피해를 <color=#00F6FF>8</color>회 입히고, 해당 칸 및 <color=#00F6FF>주변 1서클</color> 범위에 <color=#00F6FF>188%</color>의 추가 피해를 1회 입힌다.",
  str_skill_desc_322147 = "<color=#00F6FF>주변 3서클</color> 내의 칸 1개를 선택해 <color=#00F6FF>{1}%</color>의 피해를 <color=#00F6FF>8</color>회 입히고, 해당 칸 및 <color=#00F6FF>주변 1서클</color> 범위에 <color=#00F6FF>188%</color>의 추가 피해를 1회 입힌다. 리더가 될 때마다 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소하며, 턴마다 최대 <color=#00F6FF>3</color>회 발동한다.",
  str_skill_passive_desc_410147 = "턴이 시작될 때마다 모모&안즈가 강제로 리더가 되며, 나머지 팀원은 1칸씩 뒤로 이동한다. 모모&안즈가 리더가 될 때마다 <link=\"30030\"><#FFAE07><u>「특별 해가 요리」</u></color></link>를 획득하며, <color=#00F6FF>{1}</color> 확률로 <color=#00F6FF>1개를 추가로 획득</color>한다.",
  str_skill_passive_desc_415147 = "턴이 시작될 때마다 모모&안즈가 강제로 리더가 되며, 나머지 팀원은 1칸씩 뒤로 이동한다. 모모&안즈가 리더가 될 때마다 <link=\"30030\"><#FFAE07><u>「특별 해가 요리」</u></color></link>를 획득하며, <color=#00F6FF>{1}</color> 확률로 <color=#00F6FF>1개를 추가로 획득</color>한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_passive_desc_430147 = "턴이 시작될 때마다 모모&안즈가 강제로 리더가 되며, 나머지 팀원은 1칸씩 뒤로 이동한다. 모모&안즈가 리더가 될 때마다 <link=\"30030\"><#FFAE07><u>「특별 해가 요리」</u></color></link>를 획득하며, 매회 <color=#00F6FF>{1}</color> 확률로 <color=#00F6FF>한 그릇 더</color> 획득한다.",
  str_skill_passive_desc_435147 = "턴이 시작될 때마다 모모&안즈가 강제로 리더가 되며, 나머지 팀원은 1칸씩 뒤로 이동한다. 모모&안즈가 리더가 될 때마다 <link=\"30030\"><#FFAE07><u>「특별 해가 요리」</u></color></link>를 획득하며, 매회 <color=#00F6FF>{1}</color> 확률로 <color=#00F6FF>한 그릇 더</color> 획득한다. 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가한다.",
