  str_skill_desc_2001511 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 매회 최종 피해가 <color=#00F6FF>15%</color> 감소한다.",
  str_skill_desc_2001512 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 매회 최종 피해가 <color=#00F6FF>10%</color> 감소한다.",
  str_skill_desc_2001513 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 매회 최종 피해가 <color=#00F6FF>5%</color> 감소한다.",
  str_skill_desc_23015101 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25</color> 이하일 시 추가로 1|2회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>15%</color> 감소한다.",
  str_skill_desc_23015102 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25</color> 이하일 시 추가로 1|2회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>10%</color> 감소한다.",
  str_skill_desc_23015103 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25</color> 이하일 시 추가로 1|2회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>5%</color> 감소한다.",
  str_skill_desc_23015161 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25|0</color> 이하일 시 추가로 1|2|3회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>15%</color> 감소한다.",
  str_skill_desc_23015162 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25|0</color> 이하일 시 추가로 1|2|3회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>10%</color> 감소한다.",
