  str_skill_desc_2301517 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25|0</color> 이하일 시 추가로 1|2|3회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>15%</color> 감소한다.",
  str_skill_desc_2301518 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25|0</color> 이하일 시 추가로 1|2|3회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>10%</color> 감소한다.",
  str_skill_desc_2301519 = "HP 퍼센트가 가장 낮은 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 2회 입히며, 이성 수치가 <color=#00F6FF>60|25|0</color> 이하일 시 추가로 1|2|3회의 피해를 입힌다. 매회 최종 피해가 <color=#00F6FF>5%</color> 감소한다.",
  str_skill_desc_300151 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다.",
  str_skill_desc_3001510 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있고, 필요한 이성 수치와 최종 피해가 모두 2배 증가한다.",
  str_skill_desc_3001511 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>30</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있고, 필요한 이성 수치와 최종 피해가 모두 2배 증가한다.",
  str_skill_desc_3001512 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>60</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있고, 필요한 이성 수치와 최종 피해가 모두 2배 증가한다.",
  str_skill_desc_3001513 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>120</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있고, 필요한 이성 수치와 최종 피해가 모두 2배 증가한다.",
  str_skill_desc_3001514 = "길스가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>240</color>포인트를 소모, 1칸을 선택해 대상 칸과 <color=#00F6FF>인접한 십자형 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 자신이 있는 칸을 선택할 경우 2배의 피해를 입힌다. 액티브 스킬로 대상 처치 시 재사용할 수 있고, 필요한 이성 수치와 최종 피해가 모두 2배 증가한다.",
  str_skill_passive_desc_410151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가한다(최대 <color=#00F6FF>{1}</color> 증가).",
  str_skill_passive_desc_413151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가하며(최대 <color=#00F6FF>{1}</color> 증가), <color=#00F6FF>레프타</color> 처치 시 추가로 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_416151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가하며(최대 <color=#00F6FF>{1}</color> 증가), <color=#00F6FF>레프타</color> 처치 시 추가로 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_430151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가한다(최대 <color=#00F6FF>{1}</color> 증가).",
  str_skill_passive_desc_433151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가하며(최대 <color=#00F6FF>{1}</color> 증가), <color=#00F6FF>레프타</color> 처치 시 추가로 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_passive_desc_436151 = "현재 턴에 <color=#00F6FF>적 처치 시 발동</color>하며, 길스가 피해를 입힐 시 현재 이성 수치에 따라 피해가 증가한다. 이성 수치가 낮을수록 보너스 효과가 증가하며(최대 <color=#00F6FF>{1}</color> 증가), <color=#00F6FF>레프타</color> 처치 시 추가로 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_upgrade_desc_16015113 = "장비 스킬 강화: <color=#00F6FF>레프타</color> 처치 시 보너스가 추가로 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_upgrade_desc_16015116 = "연쇄 스킬 강화: 이성 수치가 0일 시 추가로 <color=#00F6FF>3</color>회의 피해를 발동시킨다(각성 3단계 달성 시 적용).",
  str_skill_name_300152 = "베이비 플라워",
  str_skill_name_302152 = "베이비 플라워",
