  str_skill_passive_name_435152 = "영리한 이성",
  str_skill_desc_300152 = "메이가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 현재 HP의 <color=#00F6FF>20%</color>를 잃고, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복한다.",
  str_skill_desc_302152 = "메이가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 현재 HP의 <color=#00F6FF>15%</color>를 잃고, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복한다.",
  str_skill_desc_305152 = "메이가 이번 전투의 <link=\"30040\"><#FFAE07><u>[이성 시스템]</u></color></link>을 변경해 이성 시스템 디버프 효과의 영향을 덜 받게 되며, 디버프 효과가 감소한다. 현재 HP의 <color=#00F6FF>15%</color>를 잃고, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복한다.",
  str_skill_desc_2001521 = "<color=#00F6FF>X형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001522 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001523 = "<color=#00F6FF>X형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시킨다.",
  str_skill_passive_desc_415152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시킨다.",
  str_skill_passive_desc_420152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시키며, 이성 수치가 감소할수록 메이의 방어력이 증가한다(최대 <color=#00F6FF>100%</color> 증가).",
  str_skill_passive_desc_425152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시키며, 이성 수치가 감소할수록 메이의 방어력이 증가한다(최대 <color=#00F6FF>100%</color> 증가).",
  str_skill_passive_desc_430152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시키며, 이성 수치가 낮을수록 회복량이 증가한다(최대 <color=#00F6FF>100%</color> 증가). 이성 수치가 감소할수록 메이의 방어력이 증가한다(최대 <color=#00F6FF>100%</color> 증가).",
  str_skill_passive_desc_435152 = "이성 수치가 1 감소할 때마다 메이의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복시키며, 이성 수치가 낮을수록 회복량이 증가한다(최대 <color=#00F6FF>100%</color> 증가). 이성 수치가 감소할수록 메이의 방어력이 증가한다(최대 <color=#00F6FF>100%</color> 증가).",
  str_skill_upgrade_desc_15015212 = "액티브 스킬 강화: 현재 HP의 <color=#00F6FF>15%</color>를 잃고, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복한다.",
  str_skill_upgrade_desc_15015215 = "이번 전투의 이성 시스템 변경: 이성 시스템의 디버프 효과의 영향을 덜 받게 되며, 디버프 효과가 감소한다.",
  str_skill_name_20015011 = "더블 스윕",
  str_skill_name_20015012 = "더블 스윕",
  str_skill_name_20015013 = "더블 스윕",
  str_skill_name_3001501 = "피의 바다",
  str_skill_name_3031501 = "피의 바다",
  str_skill_passive_name_410150 = "인형의 악몽",
  str_skill_upgrade_desc_16015013 = "액티브 스킬 강화: 액티브 스킬이 피해를 1회 입힐 때마다 레노어의 HP 한도가 <color=#FFFF00>3%</color> 증가한다.",
  str_skill_upgrade_desc_16015016 = "연쇄 스킬 강화: 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#FFFF00>100%</color> 증가한다(각성 3단계 달성 시 적용).",
  str_skill_desc_20015011 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20015012 = "<color=#00F6FF>가로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20015013 = "<color=#00F6FF>가로 5열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_22015011 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_22015012 = "<color=#00F6FF>가로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_22015013 = "<color=#00F6FF>가로 5열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 <color=#00F6FF>75</color> 이하일 시 연쇄 스킬 발동 조건이 <color=#00F6FF>15</color>칸으로 감소하며, <color=#00F6FF>광기 상태</color>일 시 <color=#00F6FF>5</color>칸으로 감소한다.",
  str_skill_desc_23015011 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>80%</color> 증가한다.",
  str_skill_desc_23015012 = "<color=#00F6FF>가로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>80%</color> 증가한다.",
  str_skill_desc_23015013 = "<color=#00F6FF>가로 5열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 <color=#00F6FF>75</color> 이하일 시 연쇄 스킬 발동 조건이 <color=#00F6FF>15</color>칸으로 감소하며, <color=#00F6FF>광기 상태</color>일 시 <color=#00F6FF>5</color>칸으로 감소한다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>80%</color> 증가한다.",
  str_skill_desc_23615011 = "<color=#00F6FF>가로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_desc_23615012 = "<color=#00F6FF>가로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_desc_23615013 = "<color=#00F6FF>가로 5열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이성 수치가 <color=#00F6FF>75</color> 이하일 시 연쇄 스킬 발동 조건이 <color=#00F6FF>15</color>칸으로 감소하며, <color=#00F6FF>광기 상태</color>일 시 <color=#00F6FF>5</color>칸으로 감소한다. 이성 수치가 낮을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_desc_3001501 = "레노어가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 칸에 <color=#00F6FF>333%</color>의 피해를 입힌다. 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>3</color>포인트 차감하며, 동일 적에게 여러 차례 피해를 입힐 시 후속 피해는 <color=#00F6FF>33%</color>의 효과만 발생한다.",
  str_skill_desc_3031501 = "레노어가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 칸에 <color=#00F6FF>333%</color>의 피해를 입힌다. 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>3</color>포인트 차감하며, 동일 적에게 여러 차례 피해를 입힐 시 후속 피해는 <color=#00F6FF>33%</color>의 효과만 발생한다. 액티브 스킬이 피해를 1회 입힐 때마다 레노어의 최대 HP가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_410150 = "턴이 시작될 때마다 <color=#00F6FF>침착한 상태</color>가 아닐 시 모든 적에게 파티의 최대 HP의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 이성 수치가 낮을수록 피해가 증가하며, 파티의 최대 HP의 <color=#00F6FF>{2}</color>까지 증가한다.",
  str_skill_name_290220101 = "밤의 극파",
  str_skill_desc_290220101 = "스킬 범위 내 적에게 강력한 공격을 가한다.",
  str_skill_name_290220102 = "밤의 증오",
  str_skill_desc_290220102 = "주변 2서클 내 대상에게 대량의 피해를 입히고, 50%의 적혈 수치를 HP로 전환한다.",
  str_skill_name_290220103 = "밤의 반격",
  str_skill_desc_290220103 = "오로리안이 액티브 스킬을 시전할 때마다 주변 2서클 내 대상에게 대량의 피해를 입히고, 50%의 적혈 수치를 HP로 전환한다.",
  str_skill_name_290220201 = "둠 크로우",
  str_skill_desc_290220201 = "날카로운 발톱으로 머리 부분 주변 5칸 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_290220202 = "달려들기",
  str_skill_desc_290220202 = "적에게 달려들며, 착지 시 발밑의 장치를 파괴해 주변 1서클 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_290220203 = "테일 컷",
  str_skill_desc_290220203 = "적이 자신의 전방에 있지 않을 경우, 즉시 꼬리를 사용해 자신의 방향을 바꾸어 적의 방향을 바라본다. 만약 방향을 바꾸어 꼬리가 위치할 칸이 장애물 또는 필드 밖일 경우, 즉시 맹렬한 도약을 1회 시전한다.",
  str_skill_name_290220204 = "맹렬한 도약",
  str_skill_desc_290220204 = "높이 뛰어올라 적 주변으로 달려들며, 공중에서 착지 시 주변 1서클 범위 내의 적에게 대량의 피해를 입히고 모든 행동을 종료한다.",
  str_skill_name_29026011 = "글룸·드라그넷",
  str_skill_desc_29026011 = "적을 향해 이동한 후 낫을 휘둘러 주변의 적에게 피해를 입힌다.",
  str_skill_name_29026012 = "글룸·사이드",
  str_skill_desc_29026012 = "제자리에서 필드 외곽에 낫을 소환한 후 회수해 쌍십자형 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_29026021 = "글룸·블레이드레인",
  str_skill_desc_29026021 = "적을 향해 이동한 후 적이 공격 범위 내에 있을 시 팔을 휘둘러 전방 2칸 내의 적에게 피해를 입힌다.\n범위에 없다면 은신 상태가 되고, 일반공격을 회피한다. (제어 효과를 받으면 은신 상태 해제)",
  str_skill_name_29026023 = "글룸·블러드",
  str_skill_desc_29026023 = "제자리에서 스킬을 시전해 전체화면 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_290270101 = "노라의 부름",
  str_skill_desc_290270101 = "노라가 랜덤 위치에 2마리의 암귀를 소환한다.",
  str_skill_name_290270102 = "힘의 발산",
  str_skill_desc_290270102 = "노라가 필드의 모든 오로리안과 암귀를 넉백시키고, 오로리안에게 피해를 입힌다.",
  str_skill_name_290270103 = "쇠락의 엄습",
  str_skill_desc_290270103 = "오로리안의 이전 턴 위치 및 주변 1서클에 공격을 시전하며, 오로리안이 범위 내에 있을 대상에게 대량의 피해를 입힌다.",
  str_skill_name_290270111 = "어둠의 진격",
  str_skill_desc_290270111 = "노라가 필드에 어둠의 영역을 소환해 오로리안의 행동 범위를 제한한다.",
  str_skill_upgrade_desc_16015413 = "연쇄 스킬 강화: 연쇄 스킬 최종 피해 횟수가 <color=#FFFF00>1회</color> 증가한다.",
  str_skill_upgrade_desc_16015416 = "연쇄 스킬 강화: 연쇄 스킬 피해 계수가 <color=#FFFF00>20%</color> 증가한다.",
  str_skill_name_200154 = "현재의 화살",
  str_skill_name_203154 = "현재의 화살",
  str_skill_name_206154 = "현재의 화살",
  str_skill_name_300154 = "과거의 속박",
  str_skill_name_3001541 = "과거의 속박",
  str_skill_name_320154 = "과거의 속박",
  str_skill_name_330154 = "과거의 속박",
  str_skill_desc_300154 = "적 1명을 선택해 <color=#00F6FF>조준</color>한다. 필드 내 최대 <color=#00F6FF>1</color>개 대상만 조준할 수 있으며, 조준 대상이 생존해 있는 동안 바이스 더 킨사이트의 연쇄 스킬은 항상 <color=#00F6FF>해당 대상만 공격</color>한다. 이미 조준 중인 적을 선택하면 <color=#00F6FF>100%</color>의 피해를 1회 입힌다.",
  str_skill_desc_330154 = "적 1명을 선택해 <color=#00F6FF>조준</color>한다. 필드 내 최대 <color=#00F6FF>1</color>개 대상만 조준할 수 있으며, 조준 대상이 생존해 있는 동안 바이스 더 킨사이트의 연쇄 스킬은 항상 <color=#00F6FF>해당 대상만 공격</color>한다. 이미 조준 중인 적을 선택하면 <color=#00F6FF>100%</color>의 피해를 1회 입히며, 대상이 지닌 <link=\"30042\"><#FFAE07><u>무한의 인장</u></color></link> 단계마다 추가로 <color=#00F6FF>5%</color>의 피해를 입힌다.",
  str_skill_desc_200154 = "<color=#00F6FF>3</color>칸을 연결해 이동할 때마다 가장 가까운 대상에게 <color=#00F6FF>80%</color>의 피해를 1회 입힌다. 해당 피해는 연쇄 칸 수량 보너스가 적용되지 않는다.",
  str_skill_desc_203154 = "<color=#00F6FF>3</color>칸을 연결해 이동할 때마다 가장 가까운 대상에게 <color=#00F6FF>80%</color>의 피해를 1회 입히며, 연쇄 스킬 최종 피해 횟수가 <color=#00F6FF>1회</color> 증가한다. 해당 피해는 연쇄 칸 수량 보너스가 적용되지 않는다.",
  str_skill_desc_206154 = "<color=#00F6FF>3</color>칸을 연결해 이동할 때마다 가장 가까운 대상에게 <color=#00F6FF>100%</color>의 피해를 1회 입히며, 연쇄 스킬 최종 피해 횟수가 <color=#00F6FF>1회</color> 증가한다. 해당 피해는 연쇄 칸 수량 보너스가 적용되지 않는다.",
  str_skill_passive_name_410154 = "무한의 인장",
  str_skill_passive_name_420154 = "무한의 인장",
  str_skill_passive_desc_410154 = "조준 대상에게 <link=\"30041\"><#FFAE07><u>무한의 인장</u></color></link>을 추가하고, <link=\"30041\"><#FFAE07><u>무한의 인장</u></color></link> 단계마다 바이스 더 킨사이트에게 받는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_420154 = "조준 대상에게 <link=\"30042\"><#FFAE07><u>무한의 인장</u></color></link>을 추가하고, <link=\"30042\"><#FFAE07><u>무한의 인장</u></color></link> 단계마다 바이스 더 킨사이트에게 받는 피해가 <color=#00F6FF>{1}</color> 증가한다. 조준 대상이 아군에게 <color=#00F6FF>3%</color>의 피해를 입힐 때마다 바이스 더 킨사이트가 대상에게 무한의 인장을 1단계 추가한다.",
  str_skill_name_300155 = "블레이드 링크",
