  str_skill_passive_name_410155 = "고독의 숨결",
  str_skill_passive_name_416155 = "고독의 숨결",
  str_skill_passive_name_420155 = "고독의 숨결",
  str_skill_passive_name_426155 = "고독의 숨결",
  str_skill_passive_name_430155 = "고독의 숨결",
  str_skill_passive_name_436155 = "고독의 숨결",
  str_skill_desc_300155 = "20포인트의 <link=\"30045\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_303155 = "20포인트의 <link=\"30046\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_306155 = "20포인트의 <link=\"30047\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_310155 = "20포인트의 <link=\"30045\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_313155 = "20포인트의 <link=\"30046\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_316155 = "20포인트의 <link=\"30047\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_320155 = "20포인트의 <link=\"30045\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_323155 = "20포인트의 <link=\"30046\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_326155 = "20포인트의 <link=\"30047\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>10</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 10포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_2001551 = "<color=#00F6FF>정상 상태</color>: 고독 수치 <color=#00F6FF>3</color>포인트를 획득하고, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>고독한 용맹 상태</color>: <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_2001552 = "<color=#00F6FF>정상 상태</color>: 고독 수치 <color=#00F6FF>4</color>포인트를 획득하고, <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>고독한 용맹 상태</color>: <color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>190%</color>의 피해를 입힌다.",
  str_skill_desc_2001553 = "<color=#00F6FF>정상 상태</color>: 고독 수치 <color=#00F6FF>5</color>포인트를 획득하고, <color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>고독한 용맹 상태</color>: <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>210%</color>의 피해를 입힌다.",
  str_skill_desc_20015510 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20015520 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20015530 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410155 = "<color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_416155 = "<color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_420155 = "<color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <color=#00F6FF>고독한 용맹 상태</color>에서 턴마다 각각의 적에게 입히는 첫 일반공격이 추가로 1회의 일반공격을 가하며, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_426155 = "<color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <color=#00F6FF>고독한 용맹 상태</color>에서 턴마다 각각의 적에게 입히는 첫 일반공격이 추가로 1회의 일반공격을 가하며, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430155 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있다. <color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <color=#00F6FF>고독한 용맹 상태</color>에서 턴마다 각각의 적에게 입히는 첫 일반공격이 추가로 1회의 일반공격을 가하며, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_436155 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있다. <color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <color=#00F6FF>고독한 용맹 상태</color>에서 턴마다 각각의 적에게 입히는 첫 일반공격이 추가로 1회의 일반공격을 가하며, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_upgrade_desc_16015513 = "액티브 스킬 강화: 전투 시작 시 고독 수치 <color=#00F6FF>20</color>포인트를 획득한다.",
  str_skill_upgrade_desc_16015516 = "액티브 스킬 강화: 액티브 스킬 시전 즉시 고독 수치 <color=#00F6FF>5</color>포인트를 획득한다.",
  str_skill_passive_desc_440153 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있다. <color=#00F6FF>고독한 용맹 상태</color>에서 일반공격이 자신의 <color=#00F6FF>주변 1서클</color>에 피해를 입히며, 대상이 아닌 칸에는 정상 피해의 <color=#00F6FF>65%</color>에 해당하는 피해를 입힌다. <color=#00F6FF>고독한 용맹 상태</color>에서 턴마다 각각의 적에게 입히는 첫 일반공격이 추가로 1회의 일반공격을 가하며, <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>65%</color>의 피해를 입힌다.",
  str_skill_desc_350155 = "20포인트의 <link=\"30045\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_353155 = "20포인트의 <link=\"30046\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_356155 = "20포인트의 <link=\"30047\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_360155 = "16포인트의 <link=\"30045\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_363155 = "16포인트의 <link=\"30046\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_desc_366155 = "16포인트의 <link=\"30047\"><#FFAE07><u>고독 수치</u></color></link>를 소모해 이번 턴에 <color=#00F6FF>고독한 용맹 상태</color>에 진입하며, 연쇄 스킬 범위와 피해가 증가한다. 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_upgrade_refine_desc_16015511 = "장비 스킬 강화: 고독한 용맹 상태에서 일반공격이 대상이 아닌 칸에 정상 피해의 <color=#00F6FF>65%</color>에 해당하는 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16015512 = "액티브 스킬 강화: 턴 종료 시 남은 고독 수치가 <color=#00F6FF>8</color>포인트 이상일 경우 고독 수치가 <color=#00F6FF>절반</color>으로 감소하며(최소 8포인트 차감), 다음 턴에 <color=#00F6FF>고독한 용맹 상태가 지속된다</color>.",
  str_skill_upgrade_refine_desc_16015513 = "액티브 스킬 강화: 고독 수치 소모량이 <color=#00F6FF>16</color>포인트로 감소한다.",
  str_skill_upgrade_desc_16015313 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.\n장비 스킬 강화: 전투 진입 후 즉시 종결 수치 <color=#FFFF00>2</color>포인트를 획득한다(각성 1단계 달성 시 적용).",
  str_skill_upgrade_desc_16015316 = "액티브 스킬 강화: 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.\n장비 스킬 강화: 짙은 칸을 지날 때마다 연쇄 스킬 피해 계수가 <color=#FFFF00>2%</color> 증가한다(각성 2단계 달성 시 적용).",
  str_skill_name_2001531 = "여명의 충격",
  str_skill_name_2001532 = "여명의 충격",
  str_skill_name_2001533 = "여명의 충격",
  str_skill_name_300153 = "여명의 종결",
  str_skill_name_306153 = "여명의 종결",
  str_skill_name_320153 = "여명의 종결",
  str_skill_name_326153 = "여명의 종결",
  str_skill_name_330153 = "여명의 종결",
  str_skill_name_336153 = "여명의 종결",
  str_skill_desc_300153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다.",
  str_skill_desc_306153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다.",
  str_skill_desc_320153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트의 <link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_desc_326153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트의 <link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_desc_330153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트의 <link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_desc_336153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>5</color>포인트의 <link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_desc_2001531 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001532 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001533 = "<color=#00F6FF>주변 4서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_name_410153 = "여명의 힘",
  str_skill_passive_name_413153 = "여명의 힘",
  str_skill_passive_name_420153 = "여명의 힘",
  str_skill_passive_name_423153 = "여명의 힘",
  str_skill_passive_name_426153 = "여명의 힘",
  str_skill_passive_name_430153 = "여명의 힘",
  str_skill_passive_name_433153 = "여명의 힘",
  str_skill_passive_name_436153 = "여명의 힘",
  str_skill_passive_desc_410153 = "<link=\"30043\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_413153 = "<link=\"30043\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득한다.",
  str_skill_passive_desc_420153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_423153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_426153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 연쇄 스킬 피해 계수가 <color=#00F6FF>2%</color> 증가한다. 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치 및 연쇄 스킬 보너스는 사라진다.",
  str_skill_passive_desc_430153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_433153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_436153 = "<link=\"300442\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>{1}</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 연쇄 스킬 피해 계수가 <color=#00F6FF>2%</color> 증가한다. 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치 및 연쇄 스킬 보너스는 사라진다.",
  str_skill_upgrade_refine_desc_16015311 = "액티브 스킬 강화: 종결 상태 진입 후 <color=#00F6FF>6</color>포인트의 추가 종결 수치를 획득한다.",
  str_skill_upgrade_refine_desc_16015312 = "연쇄 스킬 강화: 피해 계수가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16015313 = "액티브 스킬 강화: 종결 상태 진입 후 연쇄 스킬이 동일 칸에 여러 차례의 피해를 입힐 시 하락하는 후속 최종 피해량이 <color=#00F6FF>15%</color>로 감소한다.",
  str_skill_desc_2501531 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2501532 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2501533 = "<color=#00F6FF>주변 4서클</color> 내의 적 전체에 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_340153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>20%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>6</color>포인트의 <link=\"300443\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_desc_360153 = "<color=#00F6FF>4</color>칸을 선택해 <color=#00F6FF>2</color>턴간 존재하는 공습 마커를 소환한 후 <color=#00F6FF>종결 상태</color>에 진입한다. 2턴간 지속. 종결 상태에서 자신의 일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있고, 연쇄 스킬이 추가로 공습 마커가 있는 모든 칸과 주변 4칸에 연쇄 스킬의 50% 피해를 입힌다. 같은 칸에 여러 번 피해를 입힐 경우, 이어지는 최종 피해가 회당 <color=#00F6FF>15%</color>씩 감소한다. 종결 상태 지속 중 한도를 초과할 수 있는 <color=#00F6FF>6</color>포인트의 <link=\"300443\"><#FFAE07><u>종결 수치</u></color></link>를 추가로 획득한다.",
  str_skill_passive_desc_450153 = "<link=\"300443\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>3%</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_453153 = "<link=\"300443\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>3%</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치는 사라진다.",
  str_skill_passive_desc_456153 = "<link=\"300443\"><#FFAE07><u>종결 수치</u></color></link>를 획득하며, 종결 수치 포인트당 자신의 공격력이 <color=#00F6FF>3%</color> 증가한다. 파티 내 <color=#00F6FF>번개 속성</color> 또는 <color=#00F6FF>일루미나 연방</color>의 오로리안이 <color=#00F6FF>자신의 공격력</color>에 따라 종결 수치 보너스의 절반을 획득한다. 전투 진입 즉시 종결 수치 <color=#00F6FF>2</color>포인트를 획득하고, 짙은 칸을 지날 때마다 한도를 초과할 수 있는 추가 종결 수치를 <color=#00F6FF>1</color>포인트 획득하며, 연쇄 스킬 피해 계수가 <color=#00F6FF>2%</color> 증가한다. 오로라 타임 진입 또는 아군 턴 종료 시 추가 종결 수치 및 연쇄 스킬 보너스는 사라진다.",
  str_skill_name_290230101 = "추락",
  str_skill_name_290230102 = "추락",
  str_skill_name_290230103 = "추락",
  str_skill_name_290230104 = "추락",
  str_skill_name_290230201 = "도약 가르기",
  str_skill_name_290230202 = "도약 가르기",
  str_skill_name_290230203 = "도약 가르기",
  str_skill_name_290230301 = "절명 베기",
  str_skill_name_290230401 = "제단석 소환",
  str_skill_name_290240101 = "돌진 습격",
  str_skill_desc_290230101 = "클라우디아가 지면에 있을 시 적의 십자 범위 내 모든 제단석을 소환해 충돌시켜, 적에게 여러 차례의 피해를 입힌다.",
  str_skill_desc_290230102 = "클라우디아가 제단석 위에 있을 시 적의 십자 범위 내 모든 제단석을 소환해 충돌시킨다. 클라우디아가 해당 범위 내에 있을 시 적을 스턴시킨다.",
  str_skill_desc_290230103 = "클라우디아가 아시르 위에 있을 시 적의 십자 범위 내 모든 제단석을 소환해 충돌시킨다. 아시르도 해당 범위 내에 있을 시 적을 스턴시키고 넉백시킨다.",
  str_skill_desc_290230104 = "적의 십자 범위 내에 제단석이 없을 시 클라우디아가 필드 중앙 5*5 범위 내 랜덤 위치에 4개의 제단석을 소환하고, 필드 내 적과 거리가 가장 먼 위치에 제단석을 소환하고 해당 위치로 순간이동한다.",
  str_skill_desc_290230201 = "적이 공격 범위 내에 있을 시 클라우디아가 적 주변으로 순간이동해 대량의 피해를 입히고 일정 거리를 물러난다. 적이 공격 범위에 없을 시 필드 중앙 5*5 범위 내에 제단석을 소환하고 적과 거리가 가장 먼 위치로 순간이동한다.",
  str_skill_desc_290230202 = "적이 공격 범위 내에 있을 시 클라우디아가 적 주변으로 순간이동해 대량의 피해를 입히고 일정 거리를 물러난다. 적이 공격 범위에 없을 시 필드 중앙 5*5 범위 내에 제단석을 소환하고 적과 거리가 가장 먼 위치로 순간이동한다.",
  str_skill_desc_290230203 = "적이 공격 범위 내에 있을 시 클라우디아가 적 주변으로 순간이동해 대량의 피해를 입히고 일정 거리를 물러난다. 적이 공격 범위에 없을 시 필드 중앙 5*5 범위 내에 제단석을 소환하고 적과 거리가 가장 먼 위치로 순간이동한다.",
  str_skill_desc_290230301 = "필드 중앙과 적의 발 아래에 제단석을 소환하며, 제단석 위로 순간이동한 후 베어 갈라 전체화면 범위의 적에게 피해를 입힌다.",
  str_skill_desc_290230401 = "턴이 시작될 때 필드 가장자리에 최대 10개의 제단석을 소환한다.",
  str_skill_desc_290240101 = "아시르가 공격 범위 내에 접근한 적에게 피해를 1회 입히고, 경로상의 모든 제단석을 분쇄한다. 공격할 수 있는 적이 없을 경우 제자리에서 웅크린다.",
  str_skill_name_290250101 = "희생의 종결",
  str_skill_desc_290250101 = "미노스가 일정 시간 동안 필드를 랜덤으로 이동하며, 지나간 모든 칸을 초기화한다. 이동 종료 후 미노스가 플레이어에게 사격을 가해 대량의 피해를 1회 입힌다.",
  str_skill_name_290250102 = "신기루의 공세",
  str_skill_desc_290250102 = "미노스가 이동할 때 강화 칸을 지날 시 강화 칸 위에 신기루를 소환해 플레이어에게 피해를 1회 입힌다. 미노스의 인장 수가 많을수록 신기루가 입히는 피해가 증가한다.",
  str_skill_name_290250201 = "신기루의 세례",
  str_skill_desc_290250201 = "미노스가 필드의 모든 강화 칸과 약화 칸을 흡수하며, 플레이어에게 사격을 가해 피해를 입힌다. 미노스가 강화 칸을 1개 흡수할 때마다 추가로 1회의 피해를 입히며, 미노스의 인장 수가 많을수록 사격이 입히는 피해가 증가한다.",
  str_skill_name_390250101 = "루인-신기루의 공세",
  str_skill_desc_390250101 = "루인-미노스가 약화 칸이 가장 많은 경로를 선택해 5칸을 이동, 지나는 강화 칸 및 약화 칸을 흡수하며, 약화 칸을 흡수할 때마다 신기루를 소환해 플레이어에게 피해를 1회 입힌다. 이번 이동 중 약화 칸을 흡수하지 않았거나 필드에 약화 칸이 없을 경우, 자신의 주변 3서클에 약화 칸 7개를 소환한다.",
  str_skill_name_390250102 = "루인-희생의 종결",
  str_skill_desc_390250102 = "루인-미노스가 전체화면 범위 내 대상에게 사격을 가해 피해를 입힌다.",
  str_skill_name_390310106 = "루인-달콤한 키스",
  str_skill_desc_390310106 = "루인-바바라가 타일을 연결해 대상과 가장 먼 위치로 이동한 후, 일부 안전 구역을 제외한 넓은 범위에 피해를 입히고, 안전 구역 외의 불 속성 칸을 부순다.",
  str_skill_name_390310107 = "루인-종언의 천인",
  str_skill_desc_390310107 = "루인-바바라가 타일을 연결해 대상과 가장 먼 위치로 이동한 후, 필드 중앙에 동료를 소환하고, 전체화면 범위 내 대상에게 피해를 입히고 넉백시킨다.",
  str_skill_name_390320102 = "루인-전율의 협주곡",
  str_skill_name_390320103 = "루인-어비스 카코포니",
  str_skill_desc_390320102 = "루인-코놀리가 타일을 연결해 대상을 공격할 수 있는 가장 먼 위치로 이동한 후, 주변 2서클 내의 모든 대상에게 피해를 입힌다. 이번 이동 중 대상을 공격하지 못한 경우, 필드 내 랜덤 위치에 촉수를 소환한다.",
  str_skill_desc_390320103 = "루인-코놀리가 타일을 연결해 대상과 가장 먼 위치로 이동한 후, 전체화면 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_390330102 = "루인-무언의 만개",
  str_skill_name_390330103 = "루인-핏빛 수정 영역",
  str_skill_desc_390330102 = "루인-베릴이 타일을 연결해 대상을 공격할 수 있는 가장 먼 위치로 이동한 후, 주변 쌍십자형 16칸 내의 모든 대상에게 피해를 입힌다. 이번 이동 중 대상을 공격하지 못한 경우, 필드 내 랜덤 위치에 수정을 소환한다.",
  str_skill_desc_390330103 = "루인-베릴이 타일을 연결해 대상과 가장 먼 위치로 이동한 후, 전체화면 범위 내 대상에게 피해를 입힌다.",
