  str_skill_name_336156 = "양산과 검의 비",
  str_skill_name_3361560 = "양산과 검의 비",
  str_skill_passive_name_410156 = "니나의 창고지기",
  str_skill_passive_name_420156 = "니나의 창고지기",
  str_skill_desc_2001561 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 2명에게 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2001562 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 3명에게 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2001563 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 4명에게 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_2001564 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 2명에게 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2001565 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 3명에게 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2001566 = "<color=#00F6FF>양산 파지 상태</color>: <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.\n<color=#00F6FF>빈손 상태</color>: 가장 가까운 적 4명에게 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_300156 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌 후, <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>640%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 적에게 밟힐 경우 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3001560 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌 후, <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>640%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 적에게 밟힐 경우 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 증가한다.",
