  str_skill_desc_333156 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌 후, 낙하 지점에서 추가로 장비 스킬을 1회 발동하고 <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>640%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 아군|적에게 덮일 경우 스킬 쿨다운 턴 수가 1 <color=#00F6FF>감소</color>|<color=#00F6FF>증가</color>한다.",
  str_skill_desc_3331560 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌 후, 낙하 지점에서 추가로 장비 스킬을 1회 발동하고 <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>640%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 아군|적에게 덮일 경우 스킬 쿨다운 턴 수가 1 <color=#00F6FF>감소</color>|<color=#00F6FF>증가</color>한다.",
  str_skill_desc_336156 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>100%</color>의 피해를 입힌 후, 낙하 지점에서 추가로 장비 스킬을 1회 발동하고 <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>1000%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 아군|적에게 덮일 경우 스킬 쿨다운 턴 수가 1 <color=#00F6FF>감소</color>|<color=#00F6FF>증가</color>한다.",
  str_skill_desc_3361560 = "<color=#00F6FF>양산 파지 상태</color>: 이동 가능한 칸 1개를 선택해 양산을 던져 경로상의 적에게 <color=#00F6FF>100%</color>의 피해를 입힌 후, 낙하 지점에서 추가로 장비 스킬을 1회 발동하고 <color=#00F6FF>빈손 상태</color>로 전환한다.\n<color=#00F6FF>빈손 상태</color>: 양산을 회수해 경로상의 적에게 <color=#00F6FF>1000%</color>의 피해를 입힌 후, <color=#00F6FF>양산 파지 상태</color>로 전환한다.\n필드의 양산이 덮이거나 제거될 경우 <color=#00F6FF>양산 파지 상태</color>로 전환되며, 아군|적에게 덮일 경우 스킬 쿨다운 턴 수가 1 <color=#00F6FF>감소</color>|<color=#00F6FF>증가</color>한다.",
  str_skill_passive_desc_410156 = "어떠한 방식으로든지 <color=#00F6FF>빈손 상태</color>에서 <color=#00F6FF>양산 파지 상태</color>로 전환될 시 자신의 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_420156 = "<color=#00F6FF>빈손 상태</color>에서 일반공격이 <color=#00F6FF>사선 방향의 적을 공격할 수 있다</color>. 어떠한 방식으로든지 <color=#00F6FF>빈손 상태</color>에서 <color=#00F6FF>양산 파지 상태</color>로 전환될 시 자신의 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}</color>의 피해를 1회 입힌다.",
  str_skill_upgrade_desc_16015613 = "액티브 스킬 강화: 던진 양산이 선택한 위치의 <color=#00F6FF>주변 1서클</color>에 추가로 장비 스킬 피해를 1회 입힌다.",
  str_skill_upgrade_desc_16015616 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>양산 파지 상태</color>에서 <color=#00F6FF>100%</color>로 증가하며, <color=#00F6FF>빈손 상태</color>에서 <color=#00F6FF>1000%</color>로 증가한다.",
  str_skill_upgrade_desc_15015712 = "액티브 스킬 강화: 전투 진입 시 피브릴 수치를 <color=#00F6FF>2</color>포인트 보유한다.",
  str_skill_upgrade_desc_15015715 = "액티브 스킬 강화: 전투 진입 시 피브릴 수치를 <color=#00F6FF>4</color>포인트 보유한다.",
