  str_skill_passive_name_420157 = "실타래의 유희",
  str_skill_passive_name_430157 = "실타래의 유희",
  str_skill_desc_2001571 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001572 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001573 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300157 = "1칸을 선택한 후 <link=\"30050\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_310157 = "1칸을 선택한 후 <link=\"30050\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_320157 = "1칸을 선택한 후 <link=\"30050\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_330157 = "1칸을 선택한 후 <link=\"30050\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다. 오로라 타임 시 마나에를 추가로 1회 더 이동시킬 수 있다.",
  str_skill_desc_302157 = "1칸을 선택한 후 <link=\"30048\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_312157 = "1칸을 선택한 후 <link=\"30048\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_322157 = "1칸을 선택한 후 <link=\"30048\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_332157 = "1칸을 선택한 후 <link=\"30048\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다. 오로라 타임 시 마나에를 추가로 1회 더 이동시킬 수 있다.",
  str_skill_desc_305157 = "1칸을 선택한 후 <link=\"30049\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
