  str_skill_desc_3251570 = "1칸을 선택한 후 <link=\"30049\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다.",
  str_skill_desc_3351570 = "1칸을 선택한 후 <link=\"30049\"><#FFAE07><u>피브릴 수치</u></color></link> <color=#00F6FF>3</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 소환하거나, <color=#00F6FF>1</color>포인트를 소모해 <color=#00F6FF>마나에</color>를 이동시키며, 아군 턴 종료 시 마나에를 회수한다. 이동 중 마나에는 최대한 사나에와 <color=#00F6FF>일정한 거리를 유지</color>하며, 부딪히는 대상에게 <color=#00F6FF>마나에의 공격력과 동일한</color> 방어무시 피해를 입힌다. 마나에는 사나에의 기본 공격력의 <color=#00F6FF>70%</color>를 계승한다. 오로라 타임 시 마나에를 추가로 1회 더 이동시킬 수 있다.",
  str_skill_passive_desc_410157 = "마나에가 피해를 입힐 때마다 실타래의 인장을 1개 획득하며, 인장 개수마다 마나에가 사나에의 공격력을 계승하는 퍼센트가 <color=#00F6FF>{1}</color> 증가한다(최대 30개).",
  str_skill_passive_desc_420157 = "마나에가 피해를 입힐 때마다 실타래의 인장을 1개 획득하며, 인장 개수마다 마나에가 사나에의 공격력을 계승하는 퍼센트가 <color=#00F6FF>{1}</color> 증가한다(최대 30개). 실타래의 인장이 한도에 도달하거나 단일 턴에 마나에가 <color=#00F6FF>5</color>개 이상의 인장을 획득할 경우 마나에가 사나에와 <color=#00F6FF>동시에 연쇄 스킬을 시전한다</color>.",
  str_skill_upgrade_desc_16015813 = "장비 스킬 강화: 조커가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_upgrade_desc_16015816 = "장비 스킬 강화: 조커가 리더 또는 팀원 자리를 오갈 때 리더 변경 횟수를 1회 획득하며, 해당 효과는 턴마다 1회 발동한다.",
  str_skill_desc_300158 = "조커가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 <color=#00F6FF>2배</color>로 만든다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_320158 = "조커가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 <color=#00F6FF>2배</color>로 만들며, 액티브 스킬이 이전 턴에 준비되면 <color=#00F6FF>3배</color>로 만든다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_3201580 = "조커가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 <color=#00F6FF>2배</color>로 만들며, 액티브 스킬이 이전 턴에 준비되면 <color=#00F6FF>3배</color>로 만든다. 대상이 차지하는 칸이 넓을수록 액티브 스킬 피해가 증가한다.",
  str_skill_desc_2001581 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>3단계</color> 추가한다.",
  str_skill_desc_2001582 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>5단계</color> 추가한다.",
  str_skill_desc_2001583 = "<color=#00F6FF>주변 4서클</color> 내 모든 적에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>7단계</color> 추가한다.",
  str_skill_passive_desc_410158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다.",
  str_skill_passive_desc_413158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다. 조커가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_passive_desc_416158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다. 조커가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다. 조커가 리더 또는 팀원 자리를 오갈 때 리더 변경 횟수를 1회 획득하며, 해당 효과는 턴마다 1회 발동한다.",
  str_skill_passive_desc_430158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다.",
  str_skill_passive_desc_433158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 조커가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_passive_desc_436158 = "적을 처치할 때마다 대상의 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 남은 적에게 분배하며, 적 1명당 최대 <color=#00F6FF>{1}</color>단계를 획득한다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 조커가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다. 조커가 리더 또는 팀원 자리를 오갈 때 리더 변경 횟수를 1회 획득하며, 해당 효과는 턴마다 1회 발동한다.",
  str_skill_upgrade_desc_16015913 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16015916 = "장비 스킬 강화: 퀸이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_300159 = "퀸이 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 1회 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>6단계</color> 추가한다.",
  str_skill_desc_320159 = "퀸이 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 1회 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>6단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>12단계</color>를 추가한다.",
  str_skill_desc_2001591 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>2단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>4단계</color>를 추가한다.",
  str_skill_desc_2001592 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>3단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>6단계</color>를 추가한다.",
  str_skill_desc_2001593 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>4단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>8단계</color>를 추가한다.",
  str_skill_passive_desc_410159 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다.",
  str_skill_passive_desc_416159 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매번 피해를 입힌다. 퀸이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_passive_desc_430159 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매회 피해를 입힌다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다.",
  str_skill_passive_desc_436159 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>{1}</color>만큼 매회 피해를 입힌다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가하며, 물 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다. 퀸이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_300160 = "폭스가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>9단계</color> 추가한다.",
  str_skill_desc_320160 = "폭스가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. <color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>9단계</color> 추가하며, 불 속성 적에게는 <color=#00F6FF>18단계</color>를 추가한다.",
  str_skill_desc_2001601 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 불 속성 적에게는 <color=#00F6FF>3단계</color>를 추가한다.",
  str_skill_desc_2001602 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>2단계</color> 추가한다. 불 속성 적에게는 <color=#00F6FF>4단계</color>를 추가한다.",
  str_skill_desc_2001603 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>3단계</color> 추가한다. 불 속성 적에게는 <color=#00F6FF>6단계</color>를 추가한다.",
  str_skill_passive_desc_410160 = "턴마다 첫 일반공격 시 정상 피해의 <color=#00F6FF>{1}</color>배를 입힌다.",
  str_skill_passive_desc_415160 = "턴마다 첫 일반공격 시 정상 피해의 <color=#00F6FF>{1}</color>배를 입히며, 폭스가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_passive_desc_430160 = "매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가하며, 불 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다. 턴마다 첫 일반공격 시 입히는 피해 및 추가하는 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계가 정상 수치의 <color=#00F6FF>{1}</color>배가 된다.",
  str_skill_passive_desc_435160 = "매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가하며, 불 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다. 턴마다 첫 일반공격 시 입히는 피해 및 추가하는 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계가 정상 수치의 <color=#00F6FF>{1}</color>배가 되며, 폭스가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_upgrade_desc_15016012 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15016015 = "장비 스킬 강화: 폭스가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>15%</color> 증가한다.",
  str_skill_desc_300161 = "바이올렛이 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>9단계</color> 추가한다.",
  str_skill_desc_320161 = "바이올렛이 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>9단계</color> 추가하며, 숲 속성 적에게는 <color=#00F6FF>18단계</color>를 추가한다.",
  str_skill_desc_2001611 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>2단계</color> 추가한다. 숲 속성 적에게는 <color=#00F6FF>4단계</color>를 추가한다.",
  str_skill_desc_2001612 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>3단계</color> 추가한다. 숲 속성 적에게는 <color=#00F6FF>6단계</color>를 추가한다.",
  str_skill_desc_2001613 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 모든 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>4단계</color> 추가한다. 숲 속성 적에게는 <color=#00F6FF>8단계</color>를 추가한다.",
  str_skill_passive_desc_410161 = "바이올렛이 <color=#00F6FF>WEAK</color> 상태의 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_415161 = "바이올렛이 <color=#00F6FF>WEAK</color> 상태의 적에게 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가하며, 바이올렛이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_passive_desc_430161 = "바이올렛이 <color=#00F6FF>WEAK</color> 상태의 적에게 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 숲 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다.",
  str_skill_passive_desc_435161 = "바이올렛이 <color=#00F6FF>WEAK</color> 상태의 적에게 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가하며, 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 숲 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다. 바이올렛이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_upgrade_desc_15016112 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15016115 = "장비 스킬 강화: 바이올렛이 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_upgrade_desc_15016212 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15016215 = "장비 스킬 강화: 모나가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_desc_3001621 = "모나가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 1칸을 선택해 해당 방향 경로 및 인접 칸에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>5단계</color> 추가한다.",
  str_skill_desc_3201621 = "모나가 전투 진입 시 <link=\"30051\"><#FFAE07><u>[특수기]</u></color></link>를 보유한다. 1칸을 선택해 해당 방향 경로 및 인접 칸에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 명중한 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>5단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>10단계</color>를 추가한다.",
  str_skill_desc_2001621 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>3단계</color>를 추가한다.",
  str_skill_desc_2001622 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>2단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>4단계</color>를 추가한다.",
  str_skill_desc_2001623 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>3단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>5단계</color>를 추가한다.",
  str_skill_passive_desc_410162 = "모나가 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 추가할 때마다 <color=#00F6FF>{1}</color> 확률로 효과가 2배로 증가하며, <color=#00F6FF>{2}</color> 확률로 즉시 <color=#00F6FF>WEAK</color> 상태로 만든다.",
  str_skill_passive_desc_415162 = "모나가 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 추가할 때마다 <color=#00F6FF>{1}</color> 확률로 효과가 2배로 증가하며, <color=#00F6FF>{2}</color> 확률로 즉시 <color=#00F6FF>WEAK</color> 상태로 만든다. 모나가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_passive_desc_430162 = "모나가 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 추가할 때마다 <color=#00F6FF>{1}</color> 확률로 효과가 2배로 증가하며, <color=#00F6FF>{2}</color> 확률로 즉시 <color=#00F6FF>WEAK</color> 상태로 만든다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다.",
  str_skill_passive_desc_435162 = "모나가 적에게 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link> 단계를 추가할 때마다 <color=#00F6FF>{1}</color> 확률로 효과가 2배로 증가하며, <color=#00F6FF>{2}</color> 확률로 즉시 <color=#00F6FF>WEAK</color> 상태로 만든다. 매회 일반공격이 <link=\"30052\"><#FFAE07><u>약점 노출</u></color></link>을 <color=#00F6FF>1단계</color> 추가한다. 번개 속성 적에게는 <color=#00F6FF>2단계</color>를 추가한다. 모나가 처음으로 팀원에서 리더가 될 시 이번 턴 일반공격의 피해가 <color=#00F6FF>20%</color> 증가한다.",
