  str_skill_name_4001580 = "특수기",
  str_skill_desc_4001580 = "출전한 P5R 콜라보 캐릭터 수에 따라 적 전체에게 피해를 입힌다. <color=#00F6FF>WEAK 상태</color>의 적에게 더 높은 피해를 입히며, <color=#00F6FF>WEAK 상태</color>를 초기화한다. 모든 적이 <color=#00F6FF>WEAK 상태</color>일 시 <color=#00F6FF>특수기 연출</color>이 발동한다.",
  str_skill_desc_1207103 = "대상의 이전 턴 위치 및 주변 2서클에 공격을 시전한다. 중심에 가까울수록 피해가 증가하며, 중심의 대상을 즉시 처치한다.",
  str_skill_desc_12071031 = "대상의 이전 턴 위치 및 주변 2서클에 공격을 시전한다. 스킬 중심 및 주변 1서클의 대상을 즉시 처치한다.",
  str_skill_desc_12071032 = "대상의 이전 턴 위치 및 주변 2서클에 돌격을 시전하며, 스킬 범위 내의 적을 즉시 처치한다.",
  str_skill_name_29030011 = "포화 포격",
  str_skill_desc_29030011 = "전방의 적 대상에게 피해를 입히고 1칸 넉백시킨다. 장애물 뒤에 숨어 피해를 회피할 수 있다.",
  str_skill_desc_29130011 = "전방의 적 대상에게 피해를 입히고 3칸 넉백시킨다. 장애물 뒤에 숨어 피해를 회피할 수 있다.",
  str_skill_desc_290300111 = "전방의 적 대상에게 피해를 입히고 2칸 넉백시킨다. 장애물 뒤에 숨어 피해를 회피할 수 있다.",
  str_skill_desc_290300112 = "전방의 적 대상에게 피해를 입히고 4칸 넉백시킨다. 장애물 뒤에 숨어 피해를 회피할 수 있다.",
  str_skill_desc_290300113 = "전방의 적 대상에게 피해를 입히고 7칸 넉백시킨다. 장애물 뒤에 숨어 피해를 회피할 수 있다.",
  str_skill_name_29030012 = "구역 소탕",
  str_skill_desc_29030012 = "큐브 양측의 적 대상에게 피해를 입히고 1칸 넉백시킨다.",
  str_skill_desc_29130012 = "큐브 양측의 적 대상에게 피해를 입히고 3칸 넉백시킨다.",
  str_skill_desc_290300121 = "큐브 양측의 적 대상에게 피해를 입히고 2칸 넉백시킨다.",
  str_skill_desc_290300122 = "큐브 양측의 적 대상에게 피해를 입히고 4칸 넉백시킨다.",
  str_skill_desc_290300123 = "큐브 양측의 적 대상에게 피해를 입히고 7칸 넉백시킨다.",
