  str_skill_desc_2001652 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001653 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2101651 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2101652 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2101653 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2301651 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2301652 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2301653 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_3001651 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환한다.",
