  str_skill_desc_3301652 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 번개 속성으로 전환하고 <color=#00F6FF>태양의 화살 지뢰</color>를 남긴다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3351652 = "가장 가까운 숲 속성 <color=#00F6FF>5</color>칸을 번개 속성으로 전환하고 <color=#00F6FF>태양의 화살 지뢰</color>를 남긴다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_passive_name_400165 = "아폴론의 영역",
  str_skill_passive_desc_400165 = "연쇄 스킬이 대상에게 <color=#00F6FF>명중할 때마다</color> 대상의 <color=#00F6FF>주변 1서클</color> 내 랜덤 칸에 <color=#00F6FF>태양의 화살 지뢰</color>를 남기며, 적이 지나갈 때 <color=#00F6FF>폭발</color>을 일으켜 <color=#00F6FF>십자형 5칸</color>에 시엘의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. <color=#00F6FF>태양의 화살 지뢰</color>는 <color=#00F6FF>폭발</color>하거나 <color=#00F6FF>턴 종료</color> 시 사라진다.",
  str_skill_passive_name_420165 = "아폴론의 영역",
  str_skill_passive_desc_420165 = "연쇄 스킬이 대상에게 <color=#00F6FF>명중할 때마다</color> 대상의 <color=#00F6FF>주변 1서클</color> 내 랜덤 칸에 <color=#00F6FF>태양의 화살 지뢰</color>를 남기며, 적이 지나가거나 <color=#00F6FF>턴 종료</color> 시 <color=#00F6FF>폭발</color>을 일으켜 <color=#00F6FF>십자형 5칸</color>에 시엘의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_upgrade_desc_15016512 = "액티브 스킬 강화: 이전 턴에 스킬이 준비되면 이번 턴의 색 변경 수량이 <color=#FFFF00>1</color> 증가한다.",
