  str_skill_desc_2001642 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001643 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300164 = "<link=\"30053\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환한다.",
  str_skill_desc_303164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환한다.",
  str_skill_desc_306164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환한다.",
  str_skill_desc_320164 = "<link=\"30053\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_323164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_326164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_330164 = "<link=\"30053\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 명중 시 <link=\"30053\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>1</color>회 발동한다.",
  str_skill_desc_333164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 명중 시 <link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>1</color>회 발동한다.",
  str_skill_desc_336164 = "<link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 <color=#00F6FF>십자형 16칸</color> 범위 내 원하는 위치로 순간이동하고, 해당 위치의 <color=#00F6FF>전후 2칸</color>을 불 속성으로 전환하며, <color=#00F6FF>경로 및 전방 1칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 적 명중 시 <link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>2</color>회 발동한다.",
  str_skill_passive_name_410164 = "빛의 평정",
  str_skill_passive_desc_410164 = "카렌 더 스몰더링 소울이 불 속성 칸의 적에게 일반공격 시 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 추가한다.",
  str_skill_upgrade_desc_16016413 = "액티브 스킬 강화: 전투 진입 시 <link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link>를 <color=#00F6FF>2</color>포인트 보유한다.",
  str_skill_upgrade_desc_16016416 = "액티브 스킬 강화: 적 명중 시 <link=\"30054\"><#FFAE07><u>빛의 혼 수치</u></color></link> <color=#00F6FF>1</color>포인트를 획득하며, 턴마다 최대 <color=#00F6FF>2</color>회 발동한다(각성 3단계 달성 시 적용).",
  str_skill_desc_5220011 = "이동 가능한 칸 <color=#00F6FF>1</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_name_2001681 = "풍랑 저격",
  str_skill_name_2001682 = "풍랑 저격",
  str_skill_name_2001683 = "풍랑 저격",
  str_skill_name_300168 = "하이퍼 스프레이",
  str_skill_name_320168 = "하이퍼 스프레이",
  str_skill_name_330168 = "하이퍼 스프레이",
  str_skill_desc_2001681 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 발밑 랜덤 1칸에 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 생성한다.",
  str_skill_desc_2001682 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 발밑 랜덤 1칸에 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 생성한다.",
  str_skill_desc_2001683 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상의 발밑 랜덤 1칸에 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 생성한다.",
  str_skill_desc_300168 = "필드 내 모든 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 활성화하며, 인장마다 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>240%</color>의 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 피해가 감소하며, 기존 효과의 <color=#00F6FF>10%</color>까지 감소한다.",
  str_skill_desc_320168 = "필드 내 모든 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 활성화하며, 인장마다 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>240%</color>의 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 피해가 감소하며, 기존 효과의 <color=#00F6FF>10%</color>까지 감소한다.",
  str_skill_desc_330168 = "필드 내 모든 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 활성화하며, 인장마다 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>240%</color>의 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 피해가 감소하며, 기존 효과의 <color=#00F6FF>10%</color>까지 감소한다. <color=#00F6FF>3</color>개의 활성화된 인장 범위가 중첩된 칸에 샤워헤드 인장이 없을 경우, 해당 칸에 새로운 샤워헤드 인장을 1개 생성한다.",
  str_skill_passive_name_410168 = "스트로크 실드",
  str_skill_passive_name_415168 = "스트로크 실드",
  str_skill_passive_desc_410168 = "연결이 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 지날 시 레인보우의 기본 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 제공하며, 1턴간 지속된다.",
  str_skill_passive_desc_415168 = "연결이 <link=\"30061\"><#FFAE07><u>샤워헤드 인장</u></color></link>을 지날 시 레인보우의 기본 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 제공하며, 1턴간 지속된다. 턴이 시작될 때마다 필드 내 랜덤 <color=#00F6FF>1</color>개의 물 속성 칸에 샤워헤드 인장을 생성한다.",
  str_skill_upgrade_desc_15016812 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15016815 = "장비 스킬 강화: 턴이 시작될 때마다 필드 내 랜덤 <color=#00F6FF>1</color>개의 물 속성 칸에 샤워헤드 인장을 생성한다.",
  str_skill_name_2001671 = "플라잉 카드",
  str_skill_name_2001672 = "플라잉 카드",
  str_skill_name_2001673 = "플라잉 카드",
  str_skill_name_300167 = "셔플 매직 핸드",
  str_skill_name_303167 = "셔플 매직 핸드",
  str_skill_name_306167 = "셔플 매직 핸드",
  str_skill_name_320167 = "셔플 매직 핸드",
  str_skill_name_323167 = "셔플 매직 핸드",
  str_skill_name_326167 = "셔플 매직 핸드",
  str_skill_desc_2001671 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001672 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001673 = "<color=#00F6FF>주변 3서클</color> 내의 적 전체에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300167 = "제노가 전투 진입 후 자신에게 <link=\"30058\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다.",
  str_skill_desc_303167 = "제노가 전투 진입 후 자신에게 <link=\"30059\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다.",
  str_skill_desc_306167 = "제노가 전투 진입 후 자신에게 <link=\"30060\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다.",
  str_skill_desc_320167 = "제노가 전투 진입 후 자신에게 <link=\"30058\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다. 오로리안이 「모여드는 빛」과 「달과 별의 기세」 강화를 동시에 받을 경우, 이성 수치가 낮을수록 공격 보너스가 증가하며, 최대 <color=#00F6FF>66.6%</color> 증가한다.",
  str_skill_desc_323167 = "제노가 전투 진입 후 자신에게 <link=\"30059\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다. 오로리안이 「모여드는 빛」과 「달과 별의 기세」 강화를 동시에 받을 경우, 이성 수치가 낮을수록 공격 보너스가 증가하며, 최대 <color=#00F6FF>66.6%</color> 증가한다.",
  str_skill_desc_326167 = "제노가 전투 진입 후 자신에게 <link=\"30060\"><#FFAE07><u>[기원의 카드]</u></color></link>와 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 <color=#00F6FF>{1}</color>포인트 소모해 랜덤으로 기원의 카드 1장을 획득하며, 턴 내에 재시전할 경우 소모량이 <color=#00F6FF>5</color>포인트 증가한다. 오로리안이 「모여드는 빛」과 「달과 별의 기세」 강화를 동시에 받을 경우, 이성 수치가 낮을수록 공격 보너스가 증가하며, 최대 <color=#00F6FF>66.6%</color> 증가한다.",
  str_skill_passive_name_410167 = "카운터 카드",
  str_skill_passive_desc_410167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다.",
  str_skill_passive_name_413167 = "카운터 카드",
  str_skill_passive_desc_413167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다. 전투 시작 시 랜덤으로 기원의 카드 <color=#00F6FF>2</color>장을 획득한다.",
  str_skill_passive_name_416167 = "카운터 카드",
  str_skill_passive_desc_416167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다. 전투 시작 시 랜덤으로 기원의 카드 <color=#00F6FF>2</color>장을 획득한다.",
  str_skill_passive_name_430167 = "카운터 카드",
  str_skill_passive_desc_430167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다. 오로라 타임 진입 시 랜덤으로 기원의 카드 1장을 획득한다.",
  str_skill_passive_name_433167 = "카운터 카드",
  str_skill_passive_desc_433167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다. 전투 시작 시 랜덤으로 기원의 카드 <color=#00F6FF>2</color>장을 획득하며, 오로라 타임 진입 시 랜덤으로 기원의 카드 1장을 획득한다.",
  str_skill_passive_name_436167 = "카운터 카드",
  str_skill_passive_desc_436167 = "[기원의 카드]를 시전할 때마다 제노의 기본 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 해당 효과는 이성 시스템의 영향을 받지 않는다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 2배 증가한다. 전투 시작 시 랜덤으로 기원의 카드 <color=#00F6FF>2</color>장을 획득하며, 오로라 타임 진입 시 랜덤으로 기원의 카드 1장을 획득한다.",
  str_skill_upgrade_desc_16016713 = "전투 진입 시 랜덤으로 <link=\"30059\"><#FFAE07><u>[기원의 카드]</u></color></link> <color=#00F6FF>2</color>장을 획득한다.",
  str_skill_upgrade_desc_16016716 = "기원의 카드 스킬 강화: 「이색의 광채」 효과가 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복시킨다.",
  str_skill_name_3001670 = "달과 별의 기세",
  str_skill_desc_3001670 = "<color=#00F6FF>현재 편대의 후미</color> 오로리안이 제노의 기본 공격력의 <color=#00F6FF>7%</color>에 해당하는 추가 공격력을 획득한다.",
  str_skill_name_3001671 = "모여드는 빛",
  str_skill_desc_3001671 = "<color=#00F6FF>현재 리더</color> 오로리안이 제노의 기본 공격력의 <color=#00F6FF>8%</color>에 해당하는 추가 공격력을 획득한다.",
  str_skill_name_3001674 = "이색의 광채",
  str_skill_desc_3001674 = "이번 전투의 리더 변경 횟수가 1회 증가하며, 감소한 이성 수치의 <color=#00F6FF>25%</color>를 회복시킨다.",
  str_skill_name_30016740 = "이색의 광채",
  str_skill_desc_30016740 = "이번 전투의 리더 변경 횟수가 1회 증가하며, 감소한 이성 수치의 <color=#00F6FF>18%</color>를 회복시킨다.",
  str_skill_name_10071413 = "이성의 파동",
  str_skill_desc_10071413 = "텐타클로가 오로리안의 이성 수치에 영향을 주어, 턴이 시작될 때마다 생존한 텐타클로의 수마다 이성 수치가 2포인트 감소하며, 텐타클로 처치 시 이성 수치를 3포인트 회복한다.",
  str_skill_upgrade_desc_16016613 = "액티브 스킬 강화: 웨이브가 시작될 때마다 추가로 미끼 수치 <color=#00F6FF>1</color>포인트를 획득한다.",
  str_skill_upgrade_desc_16016616 = "액티브 스킬 강화: 사냥의 표식이 <color=#00F6FF>2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>350%/500%</color>의 피해를 입힌다.",
  str_skill_passive_name_410166 = "구름의 파도",
  str_skill_passive_name_430166 = "구름의 파도",
  str_skill_passive_desc_410166 = "피아가 <color=#00F6FF>물 속성</color> 칸 이동 시 빠르게 활주해 인접한 적에게 피해를 입히며, <link=\"30057\"><#FFAE07><u>선회</u></color></link> 시 <color=#00F6FF>주변 1서클</color>에 피해를 입히고, 대상에게 1턴간 지속되는 습기 효과를 추가한다(받는 상성 속성 피해 계수 <color=#00F6FF>{1}</color> 증가).",
  str_skill_passive_desc_430166 = "피아가 <color=#00F6FF>물 속성</color> 칸 이동 시 빠르게 활주해 인접한 적에게 피해를 입히며, <link=\"30057\"><#FFAE07><u>선회</u></color></link> 시 <color=#00F6FF>주변 1서클</color>에 피해를 입히고, 대상에게 1턴간 지속되는 습기 효과를 추가한다(받는 상성 속성 피해 계수 <color=#00F6FF>{1}</color> 증가). 습기 효과가 불 속성 적에게는 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_name_300166 = "키아로 프로젝트",
  str_skill_name_320166 = "키아로 프로젝트",
  str_skill_name_303166 = "키아로 프로젝트",
  str_skill_name_306166 = "키아로 프로젝트",
  str_skill_name_323166 = "키아로 프로젝트",
  str_skill_name_326166 = "키아로 프로젝트",
  str_skill_desc_300166 = "<link=\"30055\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/250%/300%</color>의 피해를 입힌다.",
  str_skill_desc_320166 = "<link=\"30055\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/250%/300%</color>의 피해를 입히고, 이번 턴에 대상의 기본 방어력을 <color=#00F6FF>5%</color> 감소시킨다(효과 중첩 가능).",
  str_skill_desc_303166 = "<link=\"30056\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/250%/300%</color>의 피해를 입힌다.",
  str_skill_desc_306166 = "<link=\"30056\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/350%/500%</color>의 피해를 입힌다.",
  str_skill_desc_323166 = "<link=\"30056\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/250%/300%</color>의 피해를 입히고, 이번 턴에 대상의 기본 방어력을 <color=#00F6FF>5%</color> 감소시킨다(효과 중첩 가능).",
  str_skill_desc_326166 = "<link=\"30056\"><#FFAE07><u>미끼 수치</u></color></link>를 <color=#00F6FF>1</color>포인트 소모, 칸 1개를 선택해 사냥의 표식을 추가하거나, 사냥의 표식 1개를 선택해 「키아로」를 소환한다. 사냥의 표식이 <color=#00F6FF>0/1/2/3</color>턴간 존재할 시 「키아로」가 <color=#00F6FF>사냥의 표식 위치 칸/십자형 5칸/마름모 13칸/정방형 25칸</color> 범위에 <color=#00F6FF>150%/200%/350%/500%</color>의 피해를 입히고, 이번 턴에 대상의 기본 방어력을 <color=#00F6FF>5%</color> 감소시킨다(효과 중첩 가능).",
  str_skill_name_2001661 = "파도의 가리킴",
  str_skill_name_2001662 = "파도의 가리킴",
  str_skill_name_2001663 = "파도의 가리킴",
  str_skill_desc_2001661 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001662 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001663 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_29039011 = "원샷 원킬-습격",
  str_skill_name_29039013 = "도망칠 수 없어-해방",
  str_skill_desc_29039011 = "오로리안이 십자형 최대 범위 내에 없을 시 오로리안의 위치를 향해 이동하고, 오로리안의 인접 4칸에 있을 시 공격을 발동한다.",
  str_skill_desc_290390111 = "오로리안이 쌍십자형 최대 범위 내에 없을 시 오로리안의 위치를 향해 이동하고, 오로리안의 주변 1서클에 있을 시 공격을 발동한다.",
  str_skill_desc_29039013 = "오로리안이 십자형 최대 범위 내에 있을 시 제자리에서 스킬을 시전해 오로리안에게 피해를 입힌다.",
  str_skill_desc_290390131 = "오로리안이 쌍십자형 최대 범위에 있을 시 제자리에서 스킬을 시전해 오로리안에게 피해를 입힌다.",
  str_skill_name_291030101 = "거울의 상 공격",
  str_skill_name_291030102 = "거울의 상 순간이동",
  str_skill_name_291030103 = "그림자 소환",
  str_skill_desc_291030101 = "네포리스가 이동한 후 거울의 상을 통해 전방의 대상에게 피해를 입힌다.",
  str_skill_desc_291030102 = "네포리스의 본체가 플레이어와 더 가까울 경우 본체가 거울의 상과 위치를 변경하며, 경로상의 대상에게 피해를 입힌다.",
  str_skill_desc_291030103 = "그림자를 소환하며, 그림자는 다음 턴에 사라지면서 랜덤 오로리안에게 2턴간 저주를 추가한다.",
  str_skill_name_5220011 = "폭염 마름쇠",
  str_skill_name_2001301 = "주심재판관이외다",
  str_skill_name_2001302 = "주심재판관이외다",
  str_skill_name_2001303 = "주심재판관이외다",
  str_skill_desc_2001301 = "<color=#00F6FF>주변 1서클</color> 내 <link=\"30062\"><#FFAE07><u>율법의 상</u></color></link>의 <color=#00F6FF>레벨을 1 높인다</color>.",
  str_skill_desc_2001302 = "<color=#00F6FF>마름모 12칸</color> 내 <link=\"30062\"><#FFAE07><u>율법의 상</u></color></link>의 <color=#00F6FF>레벨을 1 높인다</color>.",
  str_skill_desc_2001303 = "<color=#00F6FF>주변 2서클</color> 내 <link=\"30062\"><#FFAE07><u>율법의 상</u></color></link>의 <color=#00F6FF>레벨을 1 높인다</color>.",
  str_skill_name_300130 = "착석하시오",
  str_skill_desc_300130 = "이동 가능한 칸을 선택, 해당 칸 및 주변 2서클 범위 내 <link=\"30062\"><#FFAE07><u>율법의 상</u></color></link>을 전부 <color=#00F6FF>파괴</color>하고, 선택한 칸에 1개의 새로운 율법의 상을 생성하며, 레벨은 파괴한 율법의 상의 <color=#00F6FF>레벨 총합</color>이다. 범위 내에 율법의 상이 없을 경우 선택한 칸에 1레벨의 율법의 상을 1개 생성한다.",
  str_skill_passive_name_400130 = "법의 심판 있으라",
  str_skill_passive_desc_400130 = "5칸을 연결해 이동할 때마다 직전 한 칸 위치에 1레벨 <link=\"30062\"><#FFAE07><u>율법의 상</u></color></link> 1개를 생성한다. 이미 율법의 상이 있을 경우 <color=#00F6FF>레벨을 1 높인다</color>.",
  str_skill_name_2001711 = "도망칠 수 없어",
  str_skill_name_2001712 = "도망칠 수 없어",
  str_skill_name_2001713 = "도망칠 수 없어",
  str_skill_name_2201711 = "도망칠 수 없어",
  str_skill_name_2201712 = "도망칠 수 없어",
  str_skill_name_2201713 = "도망칠 수 없어",
  str_skill_name_3001711 = "건 카타",
  str_skill_name_3021711 = "건 카타",
  str_skill_name_3051711 = "건 카타",
  str_skill_passive_name_400171 = "원샷 원킬",
  str_skill_passive_name_430171 = "원샷 원킬",
  str_skill_desc_2001711 = "<color=#00F6FF>십자형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001712 = "<color=#00F6FF>십자형 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001713 = "<color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201711 = "<color=#00F6FF>십자형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 장애물에 닿으면 좌우 양측으로 1칸 확산된다.",
  str_skill_desc_2201712 = "<color=#00F6FF>십자형 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 장애물에 닿으면 좌우 양측으로 1칸 확산된다.",
  str_skill_desc_2201713 = "<color=#00F6FF>십자형 최대 범위</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 장애물에 닿으면 좌우 양측으로 1칸 확산된다.",
  str_skill_desc_3001711 = "<link=\"30063\"><#FFAE07><u>카타 에너지</u></color></link>를 <color=#00F6FF>2</color>포인트 소모하고 남은 카타 에너지를 제거, 이번 턴의 연쇄 스킬 종료 후 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>200%</color>의 피해를 입힌다. 제거되는 카타 에너지 1포인트마다 최종 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_desc_3021711 = "<link=\"30064\"><#FFAE07><u>카타 에너지</u></color></link>를 <color=#00F6FF>2</color>포인트 소모하고 남은 카타 에너지를 제거, 이번 턴의 연쇄 스킬 종료 후 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>200%</color>의 피해를 입힌다. 제거되는 카타 에너지 1포인트마다 최종 피해가 <color=#00F6FF>20%</color> 증가한다.",
  str_skill_desc_3051711 = "<link=\"30064\"><#FFAE07><u>카타 에너지</u></color></link>를 <color=#00F6FF>2</color>포인트 소모하고 남은 카타 에너지를 제거, 이번 턴의 연쇄 스킬 종료 후 <color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>200%</color>의 피해를 입힌다. 제거되는 카타 에너지 1포인트마다 최종 피해가 <color=#00F6FF>25%</color> 증가한다.",
  str_skill_passive_desc_400171 = "연결이 숲 속성 칸 또는 강화 칸을 1칸 지날 때마다 <color=#00F6FF>적의 약점</color>을 1개 발견한다. 6개 누적 시 다음 일반공격이 치명타가 되어 <color=#00F6FF>120%~{1}</color> 사이의 랜덤 피해를 입히며, <color=#00F6FF>적의 약점</color>을 모두 제거한다.",
  str_skill_passive_desc_430171 = "연결이 숲 속성 칸 또는 강화 칸을 1칸 지날 때마다 <color=#00F6FF>적의 약점</color>을 1개 발견한다. 6개 누적 시 다음 일반공격이 치명타가 되어 <color=#00F6FF>120%~{1}</color> 사이의 랜덤 피해를 입히며, <color=#00F6FF>적의 약점</color>을 모두 제거하고 카타 에너지를 1포인트 획득한다.",
  str_skill_upgrade_desc_15017112 = "액티브 스킬 강화: 전투 시작 시 카타 에너지 <color=#00F6FF>2</color>포인트를 획득한다.",
  str_skill_upgrade_desc_15017115 = "액티브 스킬 강화: 카타 에너지를 1포인트 제거할 때마다 최종 피해가 <color=#00F6FF>25%</color> 증가한다.",
  str_skill_name_2001701 = "블랙 레인",
  str_skill_name_2001702 = "블랙 레인",
  str_skill_name_2001703 = "블랙 레인",
  str_skill_name_300170 = "탄환 확산",
  str_skill_name_306170 = "탄환 확산",
  str_skill_name_320170 = "탄환 확산",
  str_skill_name_326170 = "탄환 확산",
  str_skill_name_330170 = "탄환 확산",
  str_skill_name_336170 = "탄환 확산",
  str_skill_passive_name_410170 = "정밀 조준",
  str_skill_passive_name_420170 = "정밀 조준",
  str_skill_desc_2001701 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001702 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자 방향으로 이어지는 모든 번개 속성 칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001703 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>8방향으로 이어지는 모든 번개 속성 칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다.",
  str_skill_desc_306170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다.",
  str_skill_desc_320170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다. 동시에 해당 열에 <color=#00F6FF>250%</color>의 피해를 입힌다.",
  str_skill_desc_326170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다. 동시에 해당 열에 <color=#00F6FF>250%</color>의 피해를 입힌다.",
  str_skill_desc_330170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다. 동시에 해당 열에 <color=#00F6FF>250%</color>의 피해를 입힌다. 만약 선택한 칸에 <color=#00F6FF>1칸 크기의 적</color>이 있을 시 대상을 선택한 방향으로 1칸 강제 이동시킨다.",
  str_skill_desc_336170 = "칸 1개를 선택한 후 좌우 2개 방향 중 하나를 선택, 해당 방향 절반 구역 모든 칸의 색상이 선택한 방향으로 1칸씩 전진하며, <color=#00F6FF>선택한 칸이 속한 열</color>의 모든 칸을 번개 속성으로 전환한다. 동시에 해당 열에 <color=#00F6FF>250%</color>의 피해를 입힌다. 만약 선택한 칸에 <color=#00F6FF>1칸 크기의 적</color>이 있을 시 대상을 선택한 방향으로 1칸 강제 이동시킨다.",
  str_skill_passive_desc_410170 = "연쇄 스킬이 피해를 입힐 시 대상이 멀수록 피해가 증가한다(서클당 <color=#00F6FF>{1}</color> 증가).",
  str_skill_passive_desc_420170 = "연쇄 스킬과 액티브 스킬이 피해를 입힐 시 대상이 멀수록 피해가 증가한다(서클당 <color=#00F6FF>{1}</color> 증가).",
  str_skill_upgrade_desc_16017013 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16017016 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_name_290370121 = "전장 주포-진동",
  str_skill_desc_290370121 = "1칸 이동 후 주포가 진동 공격을 가해 전방 4칸 범위에 충격을 일으켜, 범위 내 대상에게 피해를 입히고 3칸 넉백시킨다.",
  str_skill_desc_290370123 = "주포가 진동 공격을 가해 전방 4칸 범위에 충격을 일으켜, 범위 내 대상에게 피해를 입히고 3칸 넉백시킨다.",
  str_skill_name_290370122 = "주포 최대출력-진동",
  str_skill_desc_290370122 = "2칸 이동 후 주포가 진동 공격을 가해 전방 4칸 범위에 충격을 일으켜, 범위 내 대상에게 대량의 피해를 입히고 3칸 넉백시킨다.",
  str_skill_name_290370131 = "보조포 난사-좌측",
  str_skill_desc_290370131 = "1칸 이동 후 부채꼴 범위 내 적에게 연속 사격을 가해 일정량의 피해를 입힌다.",
  str_skill_desc_290370133 = "부채꼴 범위 내 적에게 연속 사격을 가해 일정량의 피해를 입힌다.",
  str_skill_name_290370132 = "보조포 최대출력-좌측",
  str_skill_desc_290370132 = "2칸 이동 후 부채꼴 범위 내 적에게 연속 사격을 가해 대량의 피해를 입힌다.",
  str_skill_name_290370141 = "보조포 난사-우측",
  str_skill_desc_290370141 = "1칸 이동 후 부채꼴 범위 내 적에게 연속 사격을 가해 일정량의 피해를 입힌다.",
  str_skill_desc_290370143 = "부채꼴 범위 내 적에게 연속 사격을 가해 일정량의 피해를 입힌다.",
  str_skill_name_290370142 = "보조포 최대출력-우측",
  str_skill_desc_290370142 = "2칸 이동 후 부채꼴 범위 내 적에게 연속 사격을 가해 대량의 피해를 입힌다.",
  str_skill_name_290370151 = "최대출력",
  str_skill_desc_290370151 = "최대출력 상태에 진입해 이동 거리와 공격력이 증가한다.",
  str_skill_name_490370401 = "긴급 수리",
  str_skill_desc_490370401 = "HP 수치가 고정되며, 긴급 수리를 시작한다. 주포가 오로리안을 필드 가장자리까지 넉백시키며, 자신에게 실드를 추가, 1턴 후 2배의 HP로 전환된다.",
  str_skill_name_40004451 = "오염",
  str_skill_desc_40004451 = "레지스터가 범위 내의 대상을 공격하고 넉백시킨다.",
  str_skill_name_49004213 = "윤회의 사자",
  str_skill_desc_49004213 = "맥거핀·스모가 곧 닥칠 백야의 파도를 위해 힘을 축적하며, 센터를 소환해 자신을 지킨다.",
  str_skill_name_49004215 = "백야의 파도",
  str_skill_desc_49004215 = "맥거핀·스모가 필드의 고정 구역을 돌아가며 폭격하며, 범위 내의 칸을 잠근다.",
  str_skill_name_400060101 = "전투력 증가",
  str_skill_desc_400060101 = "허거가 주변 1서클 내의 암귀에게 빙의해 실드를 추가하고 공격력과 행동력을 강화한다.",
  str_skill_name_400060201 = "강화 회복",
  str_skill_desc_400060201 = "도엔의 주변 1서클에 다가갈 시 체내에 녹아들어 도엔의 HP를 회복하고 공격력을 증가시키며, 실드를 추가한다.",
  str_skill_desc_400071502 = "자신의 주변 쌍십자형 최대 범위의 대상에게 대상의 최대 HP 퍼센트를 기준으로 피해를 입힌다. 자신의 주변 8방향에 대상이 없을 경우 자신에게 방어 배리어를 추가한다.",
  str_skill_desc_400072502 = "자신의 주변 쌍십자형 최대 범위의 대상에게 대상의 최대 HP 퍼센트를 기준으로 피해를 입힌다. 자신의 주변 8방향에 대상이 없을 경우 아군 대상의 HP를 회복시킨다.",
  str_skill_desc_490050302 = "솔모프가 범위 내 대상에게 피해를 입히고 자신의 곁으로 끌어당긴다. 대상 공격 성공 여부와 관계없이 자신의 주변 2서클의 칸을 초기화한다. 대상을 공격할 경우 대상 주변 1서클의 칸을 잠근다.",
  str_skill_desc_491050301 = "솔모프가 대상이 있는 방향을 향해 두 행 넓이의 충격파 1개를 발사해 명중한 대상에게 피해를 입히고, 공격 범위 내의 칸을 초기화한다.",
  str_skill_desc_491050302 = "솔모프가 범위 내 대상에게 피해를 입히고 자신의 곁으로 끌어당긴다. 대상 공격 성공 여부와 관계없이 자신의 주변 3서클의 칸을 초기화한다.",
  str_skill_desc_490028304 = "다크 서머너가 비컨 4개를 소환한 후 모든 비컨의 HP를 회복시킨다.",
  str_skill_desc_491028304 = "다크 서머너가 비컨 4개를 소환한 후 모든 비컨의 HP를 회복시킨다.",
  str_skill_desc_490025102 = "광폭한 고스트의 환영을 1개 소환해 고스트 본체와 함께 싸운다. 필드에 이미 환영이 있을 경우 기존 환영을 회수한 후 새로운 환영을 다시 소환한다. 환영 회수 성공 시 고스트 본체의 공격력이 영구적으로 일정량 증가한다.",
  str_skill_desc_490025201 = "광폭한 고스트가 공격을 2회 진행하며, 환영을 소환해 함께 싸운다.",
  str_skill_name_491025203 = "환영 회수",
  str_skill_desc_491025203 = "필드에 환영이 존재할 시 환영을 회수하며, HP를 회복하고 공격력이 증가한다. 행동력 증가 효과는 사라진다. 필드 내에 환영이 없을 경우 자신의 행동력을 증가시킨다.",
  str_skill_name_215007811 = "일반공격",
  str_skill_desc_215007811 = "로빈이 범위 내 대상을 공격한다.",
  str_skill_name_215007812 = "암행의 추",
  str_skill_desc_215007812 = "주변 2서클 내의 대상에게 피해를 입힌다.",
  str_skill_name_215007813 = "브레스",
  str_skill_desc_215007813 = "필드 내 대상에게 피해를 입힌다.",
  str_skill_name_214004811 = "팔피테이션",
  str_skill_desc_214004811 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_name_214004812 = "기행의 새",
  str_skill_desc_214004812 = "필드 내 대상에게 피해를 입힌다.",
  str_skill_name_212005011 = "피의 탐식",
  str_skill_desc_212005011 = "범위 내 대상에게 피해를 입히고 넉백시킨다.",
  str_skill_name_212005012 = "사방 분열",
  str_skill_desc_212005012 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_name_213004911 = "도약 가르기",
  str_skill_desc_213004911 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_name_213004912 = "거센 포효",
  str_skill_desc_213004912 = "주변 1서클 내의 대상에게 피해를 입히며, 범위 내의 물 속성이 아닌 칸을 초기화한다.",
  str_skill_name_214009111 = "리사이틀",
  str_skill_desc_214009111 = "시전 시 필드의 물 속성 칸 마다 이번 턴에 아군 멤버에게 0.5%의 공격력 보너스를 제공한다.",
  str_skill_name_214009112 = "클리어 운드",
  str_skill_desc_214009112 = "필드 내 대상에게 피해를 입힌다.",
  str_skill_name_214009121 = "리사이틀",
  str_skill_desc_214009121 = "시전 시 이번 턴에 아군 멤버의 행동력을 1 증가시키고, 필드의 물 속성 칸 마다 아군 멤버에게 0.5%의 공격력 보너스를 제공한다.",
  str_skill_desc_490022306 = "보레돔이 힘을 응축해 대규모 십자 범위에 불 속성 공격을 준비하며, 명중한 대상에게 피해를 입히고 작열 효과를 부여한다. 힘을 응축할 때는 드레드블레이드를 소환해 자신을 지키며, 소환 완료 후 필드 내 나머지 암귀의 행동력을 증가시킨다.",
  str_skill_desc_490022310 = "보레돔이 힘을 응축해 대규모 십자 범위에 번개 속성 공격을 준비하며, 명중한 대상에게 피해를 입히고 마비 효과를 부여한다. 힘을 응축할 때는 드레드블레이드를 소환해 자신을 지키며, 소환 완료 후 필드 내 나머지 암귀의 행동력을 증가시킨다.",
  str_skill_desc_490064302 = "레체가 에너지를 발산해 가로+세로 4열 범위에 피해를 입힌다.",
  str_skill_desc_490060103 = "필드 내 랜덤으로 2*2 범위 7곳에 피해를 입히며, 범위 내에 화염을 생성한다. 오로리안 명중 시 대상 위치 주변 1서클 칸의 속성을 변경하고, 오로리안 파티의 리더를 저주한다.",
  str_skill_desc_49006811 = "모르페우스가 대상과 거리가 먼 필드의 가장자리로 순간이동해 원거리 공격을 가하고, 자신과 오로리안 사이의 일정 범위 내 랜덤 위치에 보이드 2마리와 블라스터 1마리를 던진다.",
  str_skill_desc_49006812 = "모르페우스가 랜덤 위치에 보이드 4마리를 던진다.",
  str_skill_desc_490091202 = "대상의 이전 턴 위치에 광선 타격을 시전하며, 경로 위치 및 목표 위치의 대상에게 피해를 입힌다. 대상 명중 시 오로리안 파티의 리더를 저주한다.",
  str_skill_desc_490091203 = "범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_490006301 = "맥거핀이 눈앞의 공간을 왜곡하고 갈라 속성 피해를 입힌다. 오로리안 명중 시 오로리안을 실명시킨다.",
  str_skill_desc_490006302 = "맥거핀이 오로리안을 넉백시키고, 곧 닥칠 폭풍을 위해 힘을 축적한다.",
  str_skill_desc_490006304 = "맥거핀이 고정 구역을 돌아가며 폭격하고, 각 구역 내에 금제의 비석을 소환한다.",
  str_skill_desc_490006306 = "맥거핀이 고정 구역을 돌아가며 폭격하고, 각 구역 내에 금제의 비석을 소환한다.",
  str_skill_desc_491006304 = "맥거핀이 고정 구역을 돌아가며 폭격하고, 구역 내의 칸을 부순다.",
  str_skill_desc_491006305 = "맥거핀이 고정 구역을 돌아가며 폭격하고, 구역 내의 칸을 부순다.",
  str_skill_desc_491006302 = "맥거핀이 오로리안을 넉백시키고, 필드에 센터를 소환하며, 곧 닥칠 폭풍을 위해 힘을 축적한다.",
  str_skill_desc_492006306 = "맥거핀이 고정 구역을 돌아가며 폭격하고, 구역 내의 칸을 부순다.",
  str_skill_desc_490110101 = "마우트가 자신의 전방 2칸 사각형 최대 범위에 충격파를 방출해 범위 내 대상에게 피해를 입힌다. 대상 명중 시 자신의 HP를 회복한다.",
  str_skill_desc_490110201 = "마우트가 자신의 전방 2칸 사각형 최대 범위에 충격파를 방출해 범위 내 대상에게 피해를 입힌다. 대상 명중 시 대상에게 극한의 피로 상태를 추가한다.",
  str_skill_name_490110301 = "소로스의 나팔",
  str_skill_desc_490110301 = "마우트가 필드 내 암귀의 공격력과 행동력을 증가시킨다.",
  str_skill_name_400040101 = "크로스 다크매터",
  str_skill_desc_400040101 = "다크 서머너가 에너지 축적 시 비컨이 십자형 범위 내 대상을 공격한다.",
  str_skill_name_810410092 = "암초 소환",
  str_skill_desc_810410092 = "특수 룬 2개를 소환하며, 일정 턴 이후 금제의 비석으로 변한다.",
  str_skill_desc_490040103 = "슈모르가 번개의 힘을 소환해 필드의 여러 십자형 구역에 피해를 입히고, 십자형 구역 중앙의 적을 즉시 처치한다.",
  str_skill_desc_490040106 = "슈모르가 번개의 힘을 소환해 필드의 여러 십자형 구역에 피해를 입히고, 여러 마리의 소형 암귀를 소환한다.",
  str_skill_desc_490040108 = "슈모르가 콜로서스를 제어해 음파 공격으로 필드의 모든 대상을 공격하고, 소형 암귀를 즉시 처치한다. 처치한 암귀 1마리마다 자신의 HP를 1% 회복한다.",
  str_skill_desc_490067201 = "슈모르가 콜로서스를 제어해 음파 공격으로 필드의 모든 대상을 공격하고, 필드 내 특정 칸의 색을 변경한다.",
  str_skill_desc_490067202 = "슈모르가 광폭의 에너지를 발산해 모든 적을 공격하고, 특정 칸의 색을 변경한다. 공격당하는 대상이 슈모르와 멀수록 받는 피해가 증가한다.",
  str_skill_desc_490021101 = "아비시어가 전장 내 랜덤 위치에 암석 4개를 소환하고, 턴 시작 시 오로리안의 위치 근처에 금제의 비석을 1개 소환한다.",
  str_skill_desc_490021102 = "아비시어가 플레이어와 멀리 떨어지며, 플레이어의 인접 위치에 암석을 4개 소환한다.",
  str_skill_name_490310101 = "응원의 불길",
  str_skill_desc_490310101 = "적이 2서클 범위 안에 있을 시 피해를 입히고 대상을 1칸 넉백시킨다.",
  str_skill_name_490310102 = "응원의 부름",
  str_skill_desc_490310102 = "적이 2서클 범위 밖에 있을 시 보이드 4마리를 소환한다.",
  str_skill_name_490310105 = "바바라 일반공격",
  str_skill_desc_490310105 = "적에게 접근해 공격하고 넉백시킨다.",
  str_skill_name_491018101 = "종언의 천인",
  str_skill_desc_491018101 = "적이 자신의 주변 1서클 안에 있을 시 솔라스톰 폭발을 일으켜 피해를 입히고, 자신을 중심으로 명중한 적을 넉백시킨다.",
  str_skill_name_491018102 = "레지나 일반공격",
  str_skill_desc_491018102 = "대상 근처로 이동해 공격한다.",
  str_skill_name_491105101 = "적안의 폭풍-소",
  str_skill_desc_491105101 = "주변 2서클 범위에 적이 있을 시 적과 일정 거리를 벌린 후 대상에게 10회의 피해를 입힌다.",
  str_skill_name_491105102 = "적안의 폭풍-대",
  str_skill_desc_491105102 = "적이 자신의 2서클 범위 밖에 있을 시 적을 고정하고 대상에게 20회의 피해를 입힌다.",
  str_skill_name_491030101 = "사메야마 일반공격",
  str_skill_desc_491030101 = "적에게 접근해 공격한다.",
  str_skill_name_491030102 = "적사의 분쇄",
  str_skill_desc_491030102 = "쌍십자형 최대 범위에 대량의 피해를 입힌다.",
  str_skill_desc_490060101 = "범위 내의 대상을 자신의 주변으로 충돌시키며, 자신의 위치 및 주변 3서클 칸의 속성을 변경한다.",
  str_skill_upgrade_desc_16017313 = "액티브 스킬 강화: 액티브 스킬이 피해를 1회 입힐 때마다 객중의 인장이 1단계 감소한다.\n장비 스킬 강화: 객중의 인장 제거 시 기본 공격력이 <color=#FFFF00>25%</color> 증가한다.\n(각성 2단계 달성 시 적용)",
  str_skill_upgrade_desc_16017316 = "액티브 스킬 강화: 오로라 타임 진입 시 <color=#FFFF00>1</color>회 더 시전할 수 있다.",
  str_skill_name_3001731 = "미노스의 속결",
  str_skill_name_3061731 = "미노스의 속결",
  str_skill_name_3201731 = "미노스의 속결",
  str_skill_name_3231731 = "미노스의 속결",
  str_skill_name_3261731 = "미노스의 속결",
  str_skill_name_3301731 = "미노스의 속결",
  str_skill_name_3331731 = "미노스의 속결",
  str_skill_name_3361731 = "미노스의 속결",
  str_skill_desc_3001731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_3061731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가한다. 오로라 타임 진입 시 1회 더 시전할 수 있다.",
  str_skill_desc_3201731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_3231731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가한다. 피해를 1회 입힐 때마다 객중의 인장이 추가로 1단계 감소한다.",
  str_skill_desc_3261731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가한다. 피해를 1회 입힐 때마다 객중의 인장이 추가로 1단계 감소한다. 오로라 타임 진입 시 1회 더 시전할 수 있다.",
  str_skill_desc_3301731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가하며, 객중의 인장이 추가로 1단계 감소한다.",
  str_skill_desc_3331731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가하며, 피해를 1회 입히거나 강화 칸 1개를 흡수할 때마다 객중의 인장이 추가로 1단계 감소한다.",
  str_skill_desc_3361731 = "1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 사각형 구역을 만들어 해당 구역 내 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 <link=\"30065\"><#FFAE07><u>흡수</u></color></link>, 구역 내 적에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 강화 칸 1개를 흡수할 때마다 최종 피해가 <color=#00F6FF>50%</color> 증가하며, 피해를 1회 입히거나 강화 칸 1개를 흡수할 때마다 객중의 인장이 추가로 1단계 감소한다. 오로라 타임 진입 시 1회 더 시전할 수 있다.",
  str_skill_name_2001731 = "환상의 종결",
  str_skill_name_2001732 = "환상의 종결",
  str_skill_name_2001733 = "환상의 종결",
  str_skill_name_2301731 = "환상의 종결",
  str_skill_name_2301732 = "환상의 종결",
  str_skill_name_2301733 = "환상의 종결",
  str_skill_desc_2001731 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>140%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_desc_2001732 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>160%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_desc_2001733 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>180%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_desc_2301731 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>140%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_desc_2301732 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>160%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_desc_2301733 = "가장 가까운 대상과 가장 멀리 있는 대상에게 <color=#00F6FF>180%</color>의 피해를 입히고, 동일 대상에 대한 후속 피해가 <color=#00F6FF>절반으로 감소</color>한다. 대상의 발밑에 <color=#00F6FF>최대 1개</color>의 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 소환한다.",
  str_skill_passive_name_410173 = "디라이브 어택",
  str_skill_passive_name_420173 = "디라이브 어택",
  str_skill_passive_name_423173 = "디라이브 어택",
  str_skill_passive_desc_410173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>20%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬이 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_passive_desc_423173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>25%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬이 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_name_2001721 = "세로로! 리테이크!",
  str_skill_name_2001722 = "세로로! 리테이크!",
