  str_skill_name_2061721 = "세로로! 리테이크!",
  str_skill_name_2061722 = "세로로! 리테이크!",
  str_skill_name_2061723 = "세로로! 리테이크!",
  str_skill_name_3001721 = "깜짝 등장",
  str_skill_name_3201721 = "깜짝 등장",
  str_skill_name_3031721 = "깜짝 등장",
  str_skill_name_3231721 = "깜짝 등장",
  str_skill_name_3061721 = "깜짝 등장",
  str_skill_name_3261721 = "깜짝 등장",
  str_skill_passive_name_410172 = "카메라 실드",
  str_skill_passive_name_430172 = "카메라 실드",
  str_skill_desc_2001721 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. <color=#00F6FF>플래시 필드</color> 외부에 있을 시 현재 위치에 <color=#00F6FF>주변 1서클</color> 범위의 플래시 필드를 생성한다.",
  str_skill_desc_2001722 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. <color=#00F6FF>플래시 필드</color> 외부에 있을 시 현재 위치에 <color=#00F6FF>주변 1서클</color> 범위의 플래시 필드를 생성한다.",
  str_skill_desc_2001723 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. <color=#00F6FF>플래시 필드</color> 외부에 있을 시 현재 위치에 <color=#00F6FF>마름모 12칸</color> 범위의 플래시 필드를 생성한다.",
  str_skill_desc_3001721 = "<link=\"30066\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동한다. 동시에 최대 <color=#00F6FF>2</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_desc_3201721 = "<link=\"30066\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동하며, <color=#00F6FF>플래시 필드</color> 구역 내의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동시에 최대 <color=#00F6FF>2</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_desc_3031721 = "<link=\"30067\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동한다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_desc_3231721 = "<link=\"30067\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동하며, <color=#00F6FF>플래시 필드</color> 구역 내의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_desc_3061721 = "<link=\"30068\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동한다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_desc_3261721 = "<link=\"30068\"><#FFAE07><u>플래시 필드</u></color></link> 내 선택한 위치로 순간이동하며, <color=#00F6FF>플래시 필드</color> 구역 내의 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_passive_desc_410172 = "<color=#00F6FF>플래시 필드</color> 내에서 1칸을 이동할 때마다 리리카의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 획득한다.",
  str_skill_passive_desc_430172 = "<color=#00F6FF>플래시 필드</color> 내에서 1칸을 이동할 때마다 리리카의 현재 방어력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 획득한다. 턴 종료 시 모든 <color=#00F6FF>플래시 필드</color> 범위에 현재 실드 수치와 동일한 값의 고정피해를 입힌다.",
  str_skill_upgrade_desc_16017213 = "액티브 스킬 강화: 동시에 최대 <color=#00F6FF>3</color>개의 플래시 필드를 유지할 수 있다.",
  str_skill_upgrade_desc_16017216 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 전투 시작 후 초기 위치에 <color=#00F6FF>마름모 12칸</color> 범위의 플래시 필드가 생성된다.",
  str_skill_name_29038011 = "여기 있었구나!",
  str_skill_desc_29038011 = "오로리안이 에스더 주변에 있으면 에스더가 플레이어를 향해 몸을 돌리고, 자신의 주변 마름모 범위에 있는 대상에게 피해를 입히고 넉백시킨다.",
  str_skill_name_29038012 = "도망치려고?",
  str_skill_desc_29038012 = "오로리안이 에스더의 십자형 범위 내에 있으면 에스더가 몸을 돌려 플레이어를 향해 돌격, 맞은 편에 있는 대상에게 피해를 입히고 넉백시킨다.",
  str_skill_upgrade_desc_14016912 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_14016915 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>3</color>칸 넉백시킨다.",
  str_skill_name_2001691 = "빵빵 크래시",
  str_skill_name_2001692 = "빵빵 크래시",
  str_skill_name_2001693 = "빵빵 크래시",
  str_skill_desc_2001691 = "<color=#00F6FF>십자형 8칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001692 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001693 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_300169 = "붕붕 플라이",
  str_skill_name_305169 = "붕붕 플라이",
  str_skill_name_330169 = "붕붕 플라이",
  str_skill_name_335169 = "붕붕 플라이",
  str_skill_desc_300169 = "<color=#00F6FF>십자형 범위에 인접</color>한 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 2칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다.",
  str_skill_desc_305169 = "<color=#00F6FF>십자형 범위에 인접</color>한 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 3칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다.",
  str_skill_desc_330169 = "<color=#00F6FF>십자형 범위에 인접</color>한 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 2칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다. 장애물이 다른 적일 시 해당 적도 피해 및 스턴 효과를 받는다.",
  str_skill_desc_335169 = "<color=#00F6FF>십자형 범위에 인접</color>한 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 3칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다. 장애물이 다른 적일 시 해당 적도 피해 및 스턴 효과를 받는다.",
  str_skill_passive_name_410169 = "스윙 히트",
  str_skill_passive_name_420169 = "스윙 히트",
  str_skill_passive_desc_410169 = "새디의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 매회 연결 이동 시 새디가 최대 <color=#00F6FF>3</color>회까지 일반공격을 진행하며, 3회 이후의 일반공격은 <color=#00F6FF>스맥다운 포인트</color>를 1점 획득하는 것으로 변경된다. 스맥다운 포인트 1점마다 액티브 스킬 피해 계수가 <color=#00F6FF>{2}</color> 증가하며, 액티브 스킬 시전 후 초기화된다.",
  str_skill_passive_desc_420169 = "새디의 기본 공격력이 <color=#00F6FF>{1}</color> 증가한다. 매회 연결 이동 시 새디가 최대 <color=#00F6FF>3</color>회까지 일반공격을 진행하고, 3번째 일반공격은 2배의 피해를 입히며, 3회 이후의 일반공격은 <color=#00F6FF>스맥다운 포인트</color>를 1점 획득하는 것으로 변경된다. 스맥다운 포인트 1점마다 액티브 스킬 피해 계수가 <color=#00F6FF>{2}</color> 증가하며, 액티브 스킬 시전 후 초기화된다.",
  str_skill_desc_1601751001 = "프리즘 칸",
  str_skill_desc_1601751003 = "쿠나이",
  str_skill_desc_1601751004 = "공습 마커",
  str_skill_desc_1601751005 = "라이트닝 드론",
  str_skill_desc_1601751006 = "태양의 화살 지뢰",
  str_skill_desc_1601751007 = "깃발",
  str_skill_desc_1601751008 = "등잔",
  str_skill_desc_1601751009 = "사족 강철 도마뱀",
  str_skill_desc_1601751010 = "짙은 칸",
  str_skill_desc_160175101 = "큐빅 에너지를 <color=#00F6FF>2</color>포인트 소모, 칸 1개를 선택해 프리즘 칸으로 전환한다.",
  str_skill_desc_160175103 = "큐빅 에너지를 <color=#00F6FF>2</color>포인트 소모, 이동 가능하며 쿠나이가 없는 칸 1개를 선택해 해당 칸에 쿠나이 1자루를 소환한다.",
  str_skill_desc_160175104 = "큐빅 에너지를 <color=#00F6FF>1</color>포인트 소모, 공습 마커가 없는 칸 1개를 선택해 해당 칸에 공습 마커 1개를 소환한다.",
  str_skill_desc_160175105 = "큐빅 에너지를 <color=#00F6FF>1</color>포인트 소모, 주변 3서클 내 이동 가능하며 라이트닝 드론이 없는 칸 1개를 선택해 해당 칸에 라이트닝 드론 1마리를 소환한다. 라이트닝 드론은 필드에 최대 4마리까지 동시에 존재할 수 있다.",
  str_skill_desc_160175106 = "큐빅 에너지를 <color=#00F6FF>1</color>포인트 소모, 이동 가능하며 태양의 화살 지뢰가 없는 칸 1개를 선택해 해당 칸에 태양의 화살 지뢰 1개를 소환한다.",
  str_skill_desc_160175107 = "큐빅 에너지를 <color=#00F6FF>3</color>포인트 소모, 이동 가능하며 깃발이 없는 칸 1개를 선택해 해당 칸에 깃발 1개를 소환한다. 깃발은 필드에 최대 1개까지 동시에 존재할 수 있다.",
  str_skill_desc_160175108 = "큐빅 에너지를 <color=#00F6FF>4</color>포인트 소모, 이동 가능하며 등잔이 없는 칸 1개를 선택해 해당 칸에 등잔 1개를 소환한다. 등잔은 필드에 최대 1개까지 동시에 존재할 수 있다.",
  str_skill_desc_160175109 = "큐빅 에너지를 <color=#00F6FF>2</color>포인트 소모, 이동 가능하며 사족 강철 도마뱀이 없는 칸을 선택해 해당 칸에 사족 강철 도마뱀 1마리를 소환한다.",
  str_skill_desc_160175110 = "큐빅 에너지를 <color=#00F6FF>2</color>포인트 소모, 칸 1개를 선택해 짙은 칸으로 전환한다.",
  str_skill_upgrade_desc_16017513 = "액티브 스킬 강화: 전투 진입 시 큐빅 에너지를 <color=#FFFF00>2</color>포인트 보유한다.",
  str_skill_upgrade_desc_16017516 = "액티브 스킬 강화: 큐어 볼이 0/1/2턴간 존재한 상태에서 아군이 지날 시 회복 계수가 <color=#FFFF00>40%/100%/250%</color>로 증가한다.\n액티브 스킬로 흡수 시 회복 계수가 <color=#FFFF00>80%/180%/400%</color>로 증가한다.",
  str_skill_name_30017511 = "전역 통제",
  str_skill_name_30317511 = "전역 통제",
  str_skill_name_30617511 = "전역 통제",
  str_skill_name_32017511 = "전역 통제",
  str_skill_name_32317511 = "전역 통제",
  str_skill_name_32617511 = "전역 통제",
  str_skill_name_33017511 = "전역 통제",
  str_skill_name_33317511 = "전역 통제",
  str_skill_name_33617511 = "전역 통제",
  str_skill_name_30017513 = "전역 통제",
  str_skill_desc_30017511 = "<link=\"30069\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라진다.",
  str_skill_desc_30317511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라진다.",
  str_skill_desc_30617511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30073\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라진다.",
  str_skill_desc_32017511 = "<link=\"30069\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다.",
  str_skill_desc_32317511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다.",
  str_skill_desc_32617511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30073\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다.",
  str_skill_desc_33017511 = "<link=\"30069\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다. 또한 악셀리아가 <link=\"30071\"><#FFAE07><u>제어 모듈</u></color></link>을 사용해 일부 번개 속성 오로리안의 액티브 스킬 소환물을 소환할 수 있다.",
  str_skill_desc_33317511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30072\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다. 또한 악셀리아가 <link=\"30071\"><#FFAE07><u>제어 모듈</u></color></link>을 사용해 일부 번개 속성 오로리안의 액티브 스킬 소환물을 소환할 수 있다.",
  str_skill_desc_33617511 = "<link=\"30070\"><#FFAE07><u>큐빅 에너지</u></color></link>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 <link=\"30073\"><#FFAE07><u>큐어 볼</u></color></link> 1개를 소환하거나, 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다. 또한 악셀리아가 <link=\"30071\"><#FFAE07><u>제어 모듈</u></color></link>을 사용해 일부 번개 속성 오로리안의 액티브 스킬 소환물을 소환할 수 있다.",
  str_skill_desc_330175111 = "<color=#D1970C><b>큐빅 에너지</b></color>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 큐어 볼 1개를 소환하며, 큐어 볼이 <color=#D1970C><b>0/1/2</b></color>턴간 존재한 상태에서 오로리안이 지날 시 악셀리아의 공격력의 <color=#D1970C><b>40%/100%/200%</b></color>에 해당하는 HP를 회복한다. 또는 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 악셀리아의 공격력의 <color=#D1970C><b>40%/100%/200%</b></color>에 해당하는 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다.",
  str_skill_desc_336175111 = "<color=#D1970C><b>큐빅 에너지</b></color>를 1포인트 소모, 이동 가능한 칸 1개를 선택해 큐어 볼 1개를 소환하며, 큐어 볼이 <color=#D1970C><b>0/1/2</b></color>턴간 존재한 상태에서 오로리안이 지날 시 악셀리아의 공격력의 <color=#D1970C><b>40%/100%/250%</b></color>에 해당하는 HP를 회복한다. 또는 필드에 존재하는 큐어 볼을 선택해 흡수, 존재한 턴 수에 따라 악셀리아의 공격력의 <color=#D1970C><b>80%/180%/400%</b></color>에 해당하는 HP를 회복한다. 큐어 볼은 적에게 닿으면 사라지며, 큐빅 에너지 1포인트를 반환한다.",
  str_skill_passive_name_4101751 = "큐빅 시프트",
  str_skill_passive_desc_4101751 = "파티 내 번개 속성 오로리안이 액티브 스킬 시전 시 악셀리아가 전이 에너지 <color=#00F6FF>1</color>포인트를 획득하며, 연쇄 스킬 시전 시 모든 전이 에너지를 소모, 전이 에너지 1포인트마다 현재 필드 내 HP가 가장 높은 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_name_2001751 = "천상의 손길",
  str_skill_name_2001752 = "천상의 손길",
  str_skill_name_2001753 = "천상의 손길",
  str_skill_desc_2001751 = "악셀리아의 공격력의 <color=#00F6FF>135%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_2001752 = "악셀리아의 공격력의 <color=#00F6FF>160%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_2001753 = "악셀리아의 공격력의 <color=#00F6FF>190%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_name_29036011 = "독 흡수",
  str_skill_desc_29036011 = "오로리안이 디아볼라 주변 1서클에 있을 시 대상에게 대량의 피해를 입히고 맹독 상태를 추가한다.",
  str_skill_name_29036012 = "곤충 유인",
  str_skill_desc_29036012 = "오로리안이 디아볼라와 멀어질 시 필드 주변의 랜덤 위치에 새벽의 정령을 여러 마리 소환한다.",
  str_skill_name_20006091 = "강화",
  str_skill_desc_20006091 = "디아볼라의 주변 1서클에 다가갈 시 체내에 녹아들어 대상의 공격력을 증가시킨다.",
  str_skill_name_200190101 = "랜턴 스피릿-공생의 사슬",
  str_skill_desc_200190101 = "랜턴 스피릿이 공격 시 오로리안을 통과할 경우 피해를 입히고 오로리안과 사슬을 형성하며, 통과하지 못할 경우 오로리안에게 피해를 입히고 자신의 행동력을 증가시킨다.",
  str_skill_name_290340101 = "아스모데우스-악몽의 사슬",
  str_skill_desc_290340101 = "아스모데우스가 범위 내 오로리안을 공격하며, 명중 후 악몽의 사슬로 자신을 오로리안과 연결한다. 악몽의 사슬에 연결된 오로리안은 1칸을 이동할 때마다 피해를 입으며, 공격 시 오로리안이 이미 악몽의 사슬로 연결된 경우 피해가 증가하고 흡혈 효과가 추가된다.",
  str_skill_name_290341101 = "아스모데우스-악몽의 사슬",
  str_skill_desc_290341101 = "아스모데우스가 범위 내 오로리안을 공격하며, 명중 후 악몽의 사슬로 자신을 오로리안과 연결한다. 악몽의 사슬이 끊어질 시 오로리안에게 대량의 피해를 입힌다. 공격 시 오로리안이 이미 악몽의 사슬로 연결된 경우 피해가 증가하고 흡혈 효과가 추가된다.",
  str_skill_name_290340102 = "아스모데우스-맹렬화",
  str_skill_desc_290340102 = "아스모데우스가 오로리안을 공격할 수 없을 시, 오로리안을 공격할 수 있을 때까지 자신의 행동력을 증가시킨다.",
  str_skill_name_290340201 = "아스모데우스-분신 관통",
  str_skill_desc_290340201 = "아스모데우스가 오로리안을 공격할 수 있는 가장 먼 위치로 순간이동하며, 오로리안을 공격한다.",
  str_skill_name_2001761 = "오스트랄리스의 바람",
  str_skill_name_2001762 = "오스트랄리스의 바람",
  str_skill_name_2001763 = "오스트랄리스의 바람",
  str_skill_name_3001761 = "보레알리스의 빛",
  str_skill_name_3021761 = "보레알리스의 빛",
  str_skill_name_3051761 = "보레알리스의 빛",
  str_skill_name_3201761 = "보레알리스의 빛",
  str_skill_name_3221761 = "보레알리스의 빛",
  str_skill_name_3251761 = "보레알리스의 빛",
  str_skill_name_3301761 = "보레알리스의 빛",
  str_skill_name_3321761 = "보레알리스의 빛",
  str_skill_name_3351761 = "보레알리스의 빛",
  str_skill_passive_name_4101761 = "깃털의 바늘",
  str_skill_passive_name_4151761 = "깃털의 바늘",
  str_skill_passive_name_4201761 = "깃털의 바늘",
  str_skill_passive_name_4251761 = "깃털의 바늘",
  str_skill_passive_name_4301761 = "깃털의 바늘",
  str_skill_passive_name_4351761 = "깃털의 바늘",
  str_skill_desc_2001761 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>60%</color>의 피해를 2회 입히며, 피해마다 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 1개 추가한다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001762 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>80%</color>의 피해를 3회 입히며, 피해마다 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 1개 추가한다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2001763 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>100%</color>의 피해를 4회 입히며, 피해마다 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 1개 추가한다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_3001761 = "<color=#00F6FF>주변 2서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입힌다.",
  str_skill_desc_3021761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입힌다.",
  str_skill_desc_3051761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%~120%</color>의 피해를 입힌다. 대상의 현재 HP가 낮을수록 피해 계수가 증가한다.",
  str_skill_desc_3201761 = "<color=#00F6FF>주변 2서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%</color>만큼 HP를 회복한다.",
  str_skill_desc_3221761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%</color>만큼 HP를 회복한다.",
  str_skill_desc_3251761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%~120%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%</color>만큼 HP를 회복한다. 대상의 현재 HP가 낮을수록 피해 계수가 증가한다.",
  str_skill_desc_3301761 = "<color=#00F6FF>주변 2서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3321761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3351761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>80%~120%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 대상의 현재 HP가 낮을수록 피해 계수가 증가하며, 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_passive_desc_4101761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4151761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4201761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4251761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4301761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4351761 = "베르타의 <color=#00F6FF>{1}</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_upgrade_desc_15017612 = "액티브 스킬 강화: 스킬 범위가 <color=#FFFF00>주변 3서클</color>까지 확대된다.",
  str_skill_upgrade_desc_15017615 = "액티브 스킬 강화: 대상의 현재 HP가 낮을수록 피해 계수가 증가한다(최대 <color=#00F6FF>40%</color> 증가).",
  str_skill_name_290350103 = "래비드후프-지면 충돌",
  str_skill_desc_290350103 = "래비드후프가 밟고 있는 칸을 부수고, 오로리안에게 부딪혀 넉백시키며, 경로상의 암석을 파괴한다. 오로리안이 충돌할 경우 극한의 피로 효과를 획득한다.",
  str_skill_name_290350104 = "래비드후프-파괴의 일격",
  str_skill_desc_290350104 = "래비드후프가 이동 후 전방 2칸을 강타해 대량의 피해를 입히고 칸을 부순다.",
  str_skill_desc_290350203 = "래비드후프가 밟고 있는 칸을 부수고, 오로리안에게 부딪혀 넉백시키며, 경로상의 암석을 파괴한다.",
  str_skill_desc_290350204 = "래비드후프가 이동 후 전방 2칸을 강타해 대량의 피해를 입히고 칸을 부순다. 오로리안이 공격을 받으면 극한의 피로 효과를 획득한다.",
  str_skill_name_216003811 = "메가쇼크!",
  str_skill_desc_216003811 = "환영 그로누가 세로 1열에 피해를 입힌다.",
  str_skill_name_91001641 = "강화",
  str_skill_desc_91001641 = "자신을 제외한 모든 암귀의 행동력과 공격력을 증가시키며, 효과가 중첩된다.",
  str_skill_name_290290101 = "탐욕 분쇄",
  str_skill_desc_290290101 = "인접 위치에 있는 오로리안을 깔아뭉개 대량의 방어무시 피해를 입히고 1칸 넉백시킨다. 오로리안의 인접 4칸이 모두 막힌 경우 즉시 처치한다.",
  str_skill_desc_290291131 = "인접 위치의 오로리안을 깔아뭉개 즉시 처치한다.",
  str_skill_name_290290104 = "탐욕 가르기",
  str_skill_desc_290290104 = "오로리안이 인접 위치에 있지 않을 시 오로리안의 현재 위치 방향으로 1칸 이동하며, 머리와 인접한 1서클 범위에 피해를 입힌다.",
  str_skill_name_290290100 = "요르문간드의 몸",
  str_skill_desc_290290100 = "요르문간드의 몸은 특수한 에너지의 보호를 받으며, 모든 공격을 무효화한다. 몸에는 자가복제 능력이 있다.",
  str_skill_name_290290102 = "요르문간드의 꼬리",
  str_skill_desc_290290102 = "받은 피해가 머리로 전달된다.",
