  str_skill_desc_303180 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_305180 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3031801 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3051801 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_310180 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다.",
  str_skill_desc_313180 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_315180 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3131801 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3151801 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_330180 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 이후 감시의 기록이 있는 최대 <color=#00F6FF>3</color>명의 적의 발아래에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다.",
  str_skill_desc_333180 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 이후 감시의 기록이 있는 최대 <color=#00F6FF>3</color>명의 적의 발아래에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_335180 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 이후 감시의 기록이 있는 최대 <color=#00F6FF>3</color>명의 적의 발아래에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3331801 = "가장 가까운 물 속성 <color=#00F6FF>4</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 이후 감시의 기록이 있는 최대 <color=#00F6FF>3</color>명의 적의 발아래에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3351801 = "가장 가까운 물 속성 <color=#00F6FF>5</color>칸을 숲 속성으로 전환하고, 랜덤으로 필드 내 절반의 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다. 이후 감시의 기록이 있는 최대 <color=#00F6FF>3</color>명의 적의 발아래에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_2001801 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001802 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001803 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201801 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <color=#00F6FF>감시의 기록</color>을 추가한다.",
  str_skill_desc_2201802 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <color=#00F6FF>감시의 기록</color>을 추가한다.",
  str_skill_desc_2201803 = "가장 가깝고 <color=#00F6FF>체형이 가장 작은</color> 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 <color=#00F6FF>감시의 기록</color>을 추가한다.",
  str_skill_passive_desc_410180 = "액티브 스킬이 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다(감시의 기록: 타깃형 연쇄 스킬의 최종 피해 <color=#00F6FF>{1}</color> 증가, 오로리안 턴 종료 시까지 지속).",
  str_skill_passive_desc_420180 = "액티브 스킬과 연쇄 스킬이 적에게 <color=#00F6FF>감시의 기록</color>을 추가한다(감시의 기록: 타깃형 연쇄 스킬의 최종 피해 <color=#00F6FF>{1}</color> 증가, 오로리안 턴 종료 시까지 지속).",
