  str_skill_name_20017832 = "환상과 퇴각",
  str_skill_name_3001780 = "수색과 습격",
  str_skill_desc_2001781 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_desc_2001782 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>120%</color>의 피해를 입힌다.",
  str_skill_desc_2001783 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_desc_20017812 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>100%</color>의 피해를 입힌다. 이번 연결이 물 속성 칸일 시 동물 동료를 불러 각자의 대상을 공격하며, 목표는 동일할 수 있다.",
  str_skill_desc_20017822 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>120%</color>의 피해를 입힌다. 이번 연결이 물 속성 칸일 시 동물 동료를 불러 각자의 대상을 공격하며, 목표는 동일할 수 있다.",
  str_skill_desc_20017832 = "필드 내 서로 다른 적 3명에게 <color=#00F6FF>140%</color>의 피해를 입힌다. 이번 연결이 물 속성 칸일 시 동물 동료를 불러 각자의 대상을 공격하며, 목표는 동일할 수 있다.",
  str_skill_desc_3001780 = "세 마리의 환상동물 동료를 불러 각자의 대상에게 <color=#00F6FF>200%</color>의 피해를 입힌다.\n타래: 상태 표식이 가장 많은 대상\n비카: HP가 가장 낮은 대상\n가골빼미: 거리가 가장 먼 대상",
  str_skill_passive_name_410178 = "파견과 추적",
  str_skill_passive_name_420178 = "파견과 추적",
  str_skill_passive_name_430178 = "파견과 추적",
  str_skill_passive_name_436178 = "파견과 추적",
  str_skill_passive_desc_410178 = "이번 연결이 물 속성 칸일 시 일반공격이 1칸을 이동할 때마다 동물 동료들이 각자의 대상에게 <color=#00F6FF>{1}</color> 피해의 공격을 가하는 것으로 변경된다.\n동물 동료들이 입히는 모든 피해는 연결 보너스를 받지 않는다.",
  str_skill_passive_desc_420178 = "이번 연결이 물 속성 칸일 시 일반공격이 1칸을 이동할 때마다 동물 동료들이 각자의 대상에게 <color=#00F6FF>{1}</color> 피해의 공격을 가하는 것으로 변경된다.\n동물 동료들이 입히는 모든 피해는 연결 보너스를 받지 않는다.",
  str_skill_passive_desc_430178 = "이번 연결이 물 속성 칸일 시 일반공격이 1칸을 이동할 때마다 동물 동료들이 각자의 대상에게 <color=#00F6FF>{1}</color> 피해의 공격을 가하는 것으로 변경된다.\n동물 동료들이 입히는 모든 피해는 연결 보너스를 받지 않으며, 대상이 조건을 만족할 경우 최종 피해가 <color=#00F6FF>10%</color> 증가한다.\n타래: 상태 표식이 최소 <color=#00F6FF>4</color>개인 대상\n비카: 현재 HP가 <color=#00F6FF>30%</color> 미만인 대상\n가골빼미: 거리가 최소 <color=#00F6FF>4</color>칸 이상인 대상",
  str_skill_passive_desc_436178 = "이번 연결이 물 속성 칸일 시 일반공격이 1칸을 이동할 때마다 동물 동료들이 각자의 대상에게 <color=#00F6FF>{1}</color> 피해의 공격을 가하는 것으로 변경된다.\n동물 동료들이 입히는 모든 피해는 연결 보너스를 받지 않으며, 대상이 조건을 만족할 경우 최종 피해가 <color=#00F6FF>30%</color> 증가한다.\n타래: 상태 표식이 최소 <color=#00F6FF>4</color>개인 대상\n비카: 현재 HP가 <color=#00F6FF>30%</color> 미만인 대상\n가골빼미: 거리가 최소 <color=#00F6FF>4</color>칸 이상인 대상",
  str_skill_upgrade_desc_16017813 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16017816 = "장비 스킬 강화: 동물 동료들이 입히는 모든 피해가 대상이 조건을 만족할 경우 최종 피해가 <color=#00F6FF>30%</color> 증가한다(각성 3단계 달성 시 적용).",
  str_skill_name_2001771 = "피어나는 찬란",
