  str_skill_passive_name_410177 = "최강의 음악",
  str_skill_desc_2001771 = "<color=#00F6FF>아이돌 상태(5체인)</color>: 골디의 공격력의 <color=#00F6FF>140%</color>만큼 파티의 HP를 회복시킨다. / <color=#00F6FF>전투 찬가 상태(7체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>120%</color>의 피해를 입힌다.",
  str_skill_desc_2001772 = "<color=#00F6FF>아이돌 상태(9체인)</color>: 골디의 공격력의 <color=#00F6FF>170%</color>만큼 파티의 HP를 회복시킨다. / <color=#00F6FF>전투 찬가 상태(11체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2001773 = "<color=#00F6FF>아이돌 상태(13체인)</color>: 골디의 공격력의 <color=#00F6FF>210%</color>만큼 파티의 HP를 회복시킨다. / <color=#00F6FF>전투 찬가 상태(15체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다.",
  str_skill_desc_2201771 = "<color=#00F6FF>아이돌 상태(5체인)</color>: 골디의 공격력의 <color=#00F6FF>140%</color>만큼 파티의 HP를 회복시키고 랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>1</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. / <color=#00F6FF>전투 찬가 상태(7체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>120%</color>의 피해를 입힌다.",
  str_skill_desc_2201772 = "<color=#00F6FF>아이돌 상태(9체인)</color>: 골디의 공격력의 <color=#00F6FF>170%</color>만큼 파티의 HP를 회복시키고 랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. / <color=#00F6FF>전투 찬가 상태(11체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2201773 = "<color=#00F6FF>아이돌 상태(13체인)</color>: 골디의 공격력의 <color=#00F6FF>210%</color>만큼 파티의 HP를 회복시키고 랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>3</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. / <color=#00F6FF>전투 찬가 상태(15체인)</color>: 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다.",
  str_skill_desc_300177 = "이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_303177 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이<color=#00F6FF> 모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_306177 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있다. 액티브 스킬이 이전 턴에 준비되면 이상의 효과가 오로라 타임 중에도 적용된다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_3061771 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있다. 액티브 스킬이 이전 턴에 준비되면 이상의 효과가 오로라 타임 중에도 적용된다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_330177 = "이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있고, 일시적으로 모든 강화 칸을 만색 칸으로 간주한다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_333177 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있고, 일시적으로 모든 강화 칸을 만색 칸으로 간주한다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_336177 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있고, 일시적으로 모든 강화 칸을 만색 칸으로 간주한다. 액티브 스킬이 이전 턴에 준비되면 이상의 효과가 오로라 타임 중에도 적용된다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_desc_3361771 = "랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하며, 이번 턴에 <color=#00F6FF>아이돌 상태</color>에서 <color=#00F6FF>전투 찬가 상태</color>로 진입 시 <color=#00F6FF>다음 연결</color>에 적이 있는 칸을 통과할 수 있고, 일시적으로 모든 강화 칸을 만색 칸으로 간주한다. 액티브 스킬이 이전 턴에 준비되면 이상의 효과가 오로라 타임 중에도 적용된다.\n<color=#00F6FF>아이돌 상태</color>: 일반공격을 할 수 없으며, 연쇄 스킬이 HP를 회복한다.\n<color=#00F6FF>전투 찬가 상태</color>: 일반공격을 할 수 있으며, 연쇄 스킬이 <color=#00F6FF>모든 적</color>에게 피해를 주는 대신 시전 조건이 2칸 증가한다.",
  str_skill_passive_desc_410177 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>{1}</color>개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) 가장 가까운 <color=#00F6FF>숲 속성이 아닌 칸</color> 1개를 강화 칸으로 전환한다.",
  str_skill_upgrade_desc_16017713 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 랜덤으로 <color=#00F6FF>숲 속성이 아닌 칸</color> <color=#00F6FF>2</color>개를 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_upgrade_desc_16017716 = "액티브 스킬 강화: 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다. 액티브 스킬이 이전 턴에 준비되면 전투 찬가 상태 진입 시 <color=#00F6FF>오로라 타임</color> 중에도 적이 있는 칸을 통과할 수 있고, <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 만색 칸으로 간주한다(각성 3단계 달성 시 적용).",
  str_skill_desc_290420101 = "오로리안을 향해 이동한 후 팔을 휘둘러 전방 2칸 내의 적에게 피해를 입힌다.",
  str_skill_desc_290420102 = "전체화면 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_200200101 = "포이즌 볼",
  str_skill_desc_200200101 = "범위 내의 대상에게 포이즌 볼을 토해내 피해를 입힌다. 포이즌 볼은 십자형 4칸으로 퍼지며, 스플래시 범위 내의 적과 아군에게 중독 상태를 추가한다.",
  str_skill_name_200210001 = "그레이홀트-습격",
  str_skill_desc_200210001 = "그림자늪의 대기 시간이 끝나면 숨어 있던 그레이홀트가 나타나 오로리안을 공격하며, 이후 다시 그림자늪으로 들어간다.",
  str_skill_name_200210101 = "그레이홀트-습격",
  str_skill_desc_200210101 = "그림자늪의 대기 시간이 끝나면 숨어 있던 그레이홀트가 나타나 오로리안을 공격하며, 이후 다시 그림자늪으로 들어간다.",
  str_skill_name_200210102 = "그레이홀트-습격",
  str_skill_desc_200210102 = "그림자늪의 대기 시간이 끝나면 숨어 있던 그레이홀트가 나타나 오로리안을 공격하며, 이후 다시 그림자늪으로 들어간다.",
  str_skill_name_290400101 = "벤누-강력한 타격",
  str_skill_desc_290400101 = "벤누 가디언이 무기를 휘둘러 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_290400102 = "벤누-도약 타격",
  str_skill_desc_290400102 = "벤누 가디언이 대상을 향해 도약하며, 착지 시 지면을 강타해 주변 1서클 내 대상에게 대량의 피해를 입힌다.",
  str_skill_name_290400103 = "벤누-공포 폭발",
  str_skill_desc_290400103 = "격노한 벤누 가디언이 강력한 스킬을 사용해 전체화면 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_5220012 = "치료 용액",
  str_skill_desc_5220012 = "파티의 최대 HP의 <color=#00F6FF>20%</color>를 회복한다.",
  str_skill_name_5220013 = "궤적 분석기",
  str_skill_desc_5220013 = "장치를 가동해 필드 내 이동 가능한 칸으로 순간이동한다.",
  str_skill_name_290430101 = "프리토리언-한풍",
  str_skill_desc_290430101 = "프리토리언이 자신의 속성과 필드에 있는 다른 전설 오로리안 1명의 속성 칸을 연결해 이동하고, 대상에 접근해 8방향으로 일반공격을 시전한다. 연결이 종료되면 주변 1서클에 피해를 입힌다.",
  str_skill_name_290440101 = "레퀴엠-성창",
  str_skill_desc_290440101 = "레퀴엠이 자신의 속성과 필드에 있는 다른 전설 오로리안 1명의 속성 칸을 연결해 이동하고, 대상에 접근해 4방향으로 일반공격을 시전한다. 연결이 종료되면 주변 1서클에 피해를 입힌다. 일반공격을 3회 시전할 때마다 추가로 대상에게 최대 HP의 일정 퍼센트만큼 피해를 입힌다.",
  str_skill_name_290450101 = "히에로플람마-운석",
  str_skill_desc_290450101 = "히에로플람마가 자신의 속성과 필드에 있는 다른 전설 오로리안 1명의 속성 칸을 연결, 대상과 먼 위치를 향해 이동하고, 이동이 종료되면 전체화면 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_290460101 = "네니아-우거진 숲",
  str_skill_desc_290460101 = "네니아가 자신의 속성과 필드에 있는 다른 전설 오로리안 1명의 속성 칸을 연결, 대상과 먼 위치를 향해 이동하고, 이동이 종료되면 전체화면 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_2801101 = "지휘 표식",
  str_skill_desc_2801101 = "오로리안이 지나갈 시 획득하며, 리더 변경 가능 횟수를 증가시킨다.",
  str_skill_name_5000881 = "칼날",
  str_skill_desc_5000881 = "오로리안이 지나갈 시 획득하며, 오로리안의 공격력을 증가시킴",
  str_skill_name_5000891 = "실드",
  str_skill_desc_5000891 = "오로리안이 지나갈 시 획득하며, 오로리안의 방어력을 증가시킴",
  str_skill_name_2002101 = "검 버프",
  str_skill_desc_2002101 = "획득 시 침묵 상태가 되나 공격력이 대폭 증가함",
  str_skill_desc_2002201 = "획득 시 연쇄 스킬 피해 8% 증가",
  str_skill_upgrade_desc_15018312 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15018315 = "액티브 스킬 강화: 효과 중복 적용 횟수가 <color=#00F6FF>2~5</color>회가 된다(각성 3단계 달성 시 적용).",
  str_skill_name_3001831 = "명현고",
  str_skill_name_3051831 = "명현고",
  str_skill_name_3201831 = "명현고",
  str_skill_name_3251831 = "명현고",
  str_skill_desc_3001831 = "적 1명을 선택, 적 턴 시작 전까지 해당 적의 HP가 <color=#00F6FF>1 미만으로 떨어지지 않게 하며</color>, 대상에게 다음 효과 중 1종을 랜덤으로 부여한다: 아군이 대상에게 입히는 <color=#00F6FF>일반공격/연쇄/액티브 스킬</color> 최종 피해 <color=#00F6FF>5%/5%/7%</color> 증가.",
  str_skill_desc_3201831 = "적 1명을 선택, 적 턴 시작 전까지 해당 적의 HP가 <color=#00F6FF>1 미만으로 떨어지지 않게 하며</color>, 대상에게 다음 효과 중 1종을 랜덤으로 부여한다: 아군이 대상에게 입히는 <color=#00F6FF>일반공격/연쇄/액티브 스킬</color> 최종 피해 <color=#00F6FF>5%/5%/7%</color> 증가(<color=#00F6FF>1~3</color>회 중복 적용)",
  str_skill_desc_3251831 = "적 1명을 선택, 적 턴 시작 전까지 해당 적의 HP가 <color=#00F6FF>1 미만으로 떨어지지 않게 하며</color>, 대상에게 다음 효과 중 1종을 랜덤으로 부여한다: 아군이 대상에게 입히는 <color=#00F6FF>일반공격/연쇄/액티브 스킬</color> 최종 피해 <color=#00F6FF>5%/5%/7%</color> 증가(<color=#00F6FF>2~5</color>회 중복 적용)",
  str_skill_name_2001831 = "만응산",
  str_skill_name_2001832 = "만응산",
  str_skill_name_2001833 = "만응산",
  str_skill_desc_2001831 = "리청의 공격력의 <color=#00F6FF>155%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_2001832 = "리청의 공격력의 <color=#00F6FF>190%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_2001833 = "리청의 공격력의 <color=#00F6FF>225%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_410183 = "리청의 일반공격이 더는 피해를 입히지 않고, 대상에게 모래뜸 상태를 1회 부여하며, 턴 종료 시 폭발한다. 모래뜸 상태는 개당 <color=#00F6FF>{1}</color>의 피해를 입힌다. 해당 상태는 <color=#00F6FF>2턴</color>간 지속되고, 상태마다 별도로 계산된다.",
  str_skill_passive_desc_430183 = "리청의 일반공격이 더는 피해를 입히지 않고, 대상에게 모래뜸 상태를 1회 부여하며, 턴 종료 시 폭발한다. 모래뜸 상태는 개당 <color=#00F6FF>{1}</color>의 피해를 입히고, 대상에게 부여된 모래뜸 상태 수마다 최종 피해가 <color=#00F6FF>3%</color>씩 증가한다. 해당 상태는 <color=#00F6FF>2턴</color>간 지속되고, 상태마다 별도로 계산된다.",
