  str_skill_desc_2061824 = "세 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 세 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 25칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 연쇄 시전 조건이 <color=#00F6FF>7</color>칸으로 감소한다.",
  str_skill_desc_2301821 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2301822 = "첫 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 첫 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대된다.",
