  str_skill_desc_2331824 = "세 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 세 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대되고, 연쇄 시전 조건이 <color=#00F6FF>7</color>칸으로 감소한다.",
  str_skill_desc_2361821 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 오로라 타임 중 연쇄 시전 조건이 <color=#00F6FF>0</color>칸으로 감소한다.",
  str_skill_desc_2361822 = "첫 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 첫 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대되고, 연쇄 시전 조건이 <color=#00F6FF>0</color>칸으로 감소한다.",
  str_skill_desc_2361823 = "두 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 두 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대되고, 연쇄 시전 조건이 <color=#00F6FF>3</color>칸으로 감소한다.",
  str_skill_desc_2361824 = "세 번째 「정룡의 광휘」가 이미 점등된 경우 <color=#00F6FF>이전 단계</color> 연쇄 스킬의 시전 판정을 진행한다. 점등되지 않은 경우 세 번째 「정룡의 광휘」를 점등하고, <color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 25칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다. 오로라 타임 중 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대되고, 연쇄 시전 조건이 <color=#00F6FF>7</color>칸으로 감소한다.",
  str_skill_desc_3001821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link>가 <color=#00F6FF>3</color>개 점등되면 액티브 스킬이 준비된다. 1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>300%</color>의 피해를 입히며, 액티브 스킬 시전 후 모든 「정룡의 광휘」가 꺼진다.",
  str_skill_desc_3101821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link>가 <color=#00F6FF>3</color>개 점등되면 액티브 스킬이 준비된다. 1칸을 선택해 <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>300%</color>의 피해를 입히며, 액티브 스킬 시전 후 모든 「정룡의 광휘」가 꺼진다.",
  str_skill_desc_3201821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link>가 <color=#00F6FF>3</color>개 점등되면 액티브 스킬이 준비된다. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>300%</color>의 피해를 입히며, 액티브 스킬 시전 후 모든 「정룡의 광휘」가 꺼진다.",
  str_skill_passive_name_410182 = "혈유의 비기",
  str_skill_passive_name_413182 = "혈유의 비기",
  str_skill_passive_name_423182 = "혈유의 비기",
  str_skill_passive_name_430182 = "혈유의 비기",
  str_skill_passive_name_433182 = "혈유의 비기",
  str_skill_passive_desc_410182 = "액티브 스킬 발동 시 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_413182 = "액티브 스킬 발동 시 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_423182 = "액티브 스킬 발동 시 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430182 = "액티브 스킬 발동 시 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_433182 = "액티브 스킬 발동 시 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_upgrade_desc_16018213 = "연쇄 스킬 강화: 오로라 타임 중 연쇄 스킬 시전 조건 칸 수가 <color=#00F6FF>6</color> 감소한다.",
  str_skill_upgrade_desc_16018216 = "연쇄 스킬 강화: <color=#00F6FF>2|3|4</color>단계 연쇄 스킬 피해 범위가 <color=#00F6FF>마름모 13칸|쌍십자형 17칸|정방형 25칸</color>으로 확대된다.",
  str_skill_name_29041011 = "곤(困)",
  str_skill_desc_29041011 = "우룡이 강력한 환술을 시전해 오로리안을 환술 공간으로 끌어들인다.\n해당 기간에 궤도가 고정된 다수의 탄환이 소환되어 필드를 비행하며, 플레이어에게 닿으면 대량의 피해를 입힌다.\n플레이어는 5회 이동할 수 있으나, 회당 1칸만 이동이 가능하다.",
  str_skill_name_29041012 = "속(束)",
  str_skill_desc_29041012 = "필드에 탄환이 있을 때 우룡이 필드의 모든 탄환을 제어해 오로리안에게 날려 피해를 입힌다.\n필드에 탄환이 없을 시 우룡이 분신을 만들고 그 안으로 숨어들며, 피해를 입으면 본체와 분신이 구분된다.",
  str_skill_name_29041013 = "실재의 거짓",
  str_skill_desc_29041013 = "필드에 탄환이 있을 때 우룡이 필드의 모든 탄환을 제어해 오로리안에게 날려 피해를 입힌다.\n필드에 탄환이 없을 시 우룡이 분신을 만들고 그 안으로 숨어들며, 피해를 입으면 본체와 분신이 구분된다.",
  str_skill_name_29041014 = "언(言)",
  str_skill_desc_29041014 = "이동 후 우룡과 분신이 자신의 전방 직선 범위의 대상에게 피해를 입히며, 이후 제자리에 탄환을 남긴다.",
  str_skill_name_29041015 = "산(散)",
  str_skill_desc_29041015 = "우룡과 분신이 전체화면 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_20022013 = "충돌",
  str_skill_desc_20022013 = "\"문\"이 전방 경고 범위 내의 대상에게 대량의 피해를 입힌다.",
  str_skill_name_20022022 = "속(束)",
  str_skill_desc_20022022 = "환상 기간이 아닐 때 우룡은 “자”를 탄환으로 삼아 오로리안을 직접 공격할 수 있다. (오로리안은 해당 기간에 “글자”를 제거해 공격을 막을 수 있음)",
  str_skill_name_490310106 = "루인-달콤한 키스",
  str_skill_desc_490310106 = "루인-바바라가 일부 안전 구역을 제외한 넓은 범위에 피해를 입히고, 안전 구역 외의 불 속성 칸을 부순다.",
  str_skill_name_490310107 = "루인-종언의 천인",
  str_skill_desc_490310107 = "루인-바바라가 필드 중앙에 동료를 소환하고, 전체화면 범위 내 대상에게 피해를 입히고 넉백시킨다.",
  str_skill_desc_490023202 = "피니가 에너지를 구동해 공격 범위 내 대상에게 원거리 공격을 가한다. 명중 시 대상에게 극한의 피로 상태를 추가한다.",
  str_skill_desc_490023212 = "피니가 에너지를 구동해 공격 범위 내 대상에게 원거리 공격을 가한다. 명중 시 대상에게 실명 상태를 추가한다.",
  str_skill_desc_480043414 = "마레이셀이 필드에 여러 블라스터를 소환한다. 소환되는 블라스터의 수량은 마레이셀이 첫 웨이브에서 누적한 「블라스터 행진」의 단계 수에 따라 결정된다.",
  str_skill_desc_400012401 = "턴마다 블라스터를 전장에 소환한다.",
  str_skill_upgrade_desc_16018113 = "장비 스킬 강화: 전투 진입 시 통찰력을 5포인트 획득하며, 웨이브가 시작될 때마다 통찰력을 <color=#00F6FF>5</color>포인트 획득한다.",
  str_skill_upgrade_desc_16018116 = "장비 스킬 강화: 통찰력의 획득 조건이 종서가 <color=#00F6FF>임의의 속성의 칸</color>을 지나도 획득하는 것으로 변경된다.",
  str_skill_name_2001811 = "무정의 화염",
  str_skill_name_2001812 = "무정의 화염",
  str_skill_name_2001813 = "무정의 화염",
  str_skill_desc_2001811 = "<color=#00F6FF>주변 2서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001812 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001813 = "<color=#00F6FF>주변 4서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_3001811 = "단멸의 불길",
  str_skill_name_30018112 = "불변의 전략",
  str_skill_name_300181121 = "불변의 전략",
  str_skill_name_300181122 = "불변의 전략",
  str_skill_name_300181123 = "불변의 전략",
  str_skill_name_32018112 = "불변의 전략",
  str_skill_name_320181121 = "불변의 전략",
  str_skill_name_320181122 = "불변의 전략",
  str_skill_name_320181123 = "불변의 전략",
  str_skill_name_33018112 = "불변의 전략",
  str_skill_name_330181121 = "불변의 전략",
  str_skill_name_330181122 = "불변의 전략",
  str_skill_name_330181123 = "불변의 전략",
  str_skill_desc_3001811 = "<color=#00F6FF>1</color>칸을 선택해 홍염을 소환하고 불 속성으로 전환한다. 홍염을 적의 발밑에 소환하면 대상을 따라 이동한다. <color=#00F6FF>칸을 연결해 이동하기 전</color>, 홍염의 경로상의 모든 칸이 <color=#00F6FF>불 속성으로 전환</color>되며, 적에게 붙은 홍염은 파티가 <color=#00F6FF>연결 이동 후</color> 사라진다.",
  str_skill_desc_30018112 = "통찰력을 8포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다.",
  str_skill_desc_300181121 = "통찰력을 7포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다.",
  str_skill_desc_300181122 = "통찰력을 6포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다.",
  str_skill_desc_300181123 = "통찰력을 5포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다.",
  str_skill_desc_32018112 = "통찰력을 8포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>8</color>포인트씩 증가한다.",
  str_skill_desc_320181121 = "통찰력을 7포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>7</color>포인트씩 증가한다.",
  str_skill_desc_320181122 = "통찰력을 6포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>6</color>포인트씩 증가한다.",
  str_skill_desc_320181123 = "통찰력을 5포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>5</color>포인트씩 증가한다.",
  str_skill_desc_33018112 = "통찰력을 8포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 홍염을 1칸 이동시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>8/8</color>포인트씩 증가한다.",
  str_skill_desc_330181121 = "통찰력을 7포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 홍염을 1칸 이동시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>7/8</color>포인트씩 증가한다.",
  str_skill_desc_330181122 = "통찰력을 6포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 홍염을 1칸 이동시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>6/8</color>포인트씩 증가한다.",
  str_skill_desc_330181123 = "통찰력을 5포인트 소모해 보스를 제외한 적 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 홍염을 1칸 이동시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>5/8</color>포인트씩 증가한다.",
