  str_skill_passive_desc_410181 = "신규 액티브 스킬 획득: <link=\"30075\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_413181 = "신규 액티브 스킬 획득: <link=\"30076\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_416181 = "신규 액티브 스킬 획득: <link=\"30077\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 1회만 시전할 수 있다. 종서가 <color=#00F6FF>임의의 속성의 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_420181 = "신규 액티브 스킬 획득: <link=\"30075\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>{1}</color>포인트씩 증가한다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_423181 = "신규 액티브 스킬 획득: <link=\"30076\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>{1}</color>포인트씩 증가한다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_426181 = "신규 액티브 스킬 획득: <link=\"30077\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시킨다. 한 턴에 여러 번 시전 시 소모하는 통찰력이 <color=#00F6FF>{1}</color>포인트씩 증가한다. 종서가 <color=#00F6FF>임의의 속성의 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_430181 = "신규 액티브 스킬 획득: <link=\"30075\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 <color=#00F6FF>홍염을 1칸 이동</color>시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>{1}/8</color>포인트씩 증가한다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_433181 = "신규 액티브 스킬 획득: <link=\"30076\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 <color=#00F6FF>홍염을 1칸 이동</color>시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>{1}/8</color>포인트씩 증가한다. 종서가 <color=#00F6FF>불 속성 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_passive_desc_436181 = "신규 액티브 스킬 획득: <link=\"30077\"><#FFAE07><u>통찰력</u></color></link>을 <color=#00F6FF>{1}</color>포인트 소모해 <color=#00F6FF>보스를 제외한 적</color> 1명을 강제로 1칸 이동시키거나, 8포인트를 소모해 <color=#00F6FF>홍염을 1칸 이동</color>시킨다. 한 턴에 여러 번 시전 시 <color=#00F6FF>적/홍염</color> 이동에 소모하는 통찰력이 <color=#00F6FF>{1}/8</color>포인트씩 증가한다. 종서가 <color=#00F6FF>임의의 속성의 칸</color>을 1개 지날 때마다 통찰력을 1포인트 획득한다.",
  str_skill_desc_15011312 = "필드 내 보스를 제외한 모든 단일 칸의 적을 오른쪽으로 1칸 넉백시키며, 필드 내의 적 전체에 피해를 입힌다.",
  str_skill_desc_15011313 = "필드 내 보스를 제외한 모든 단일 칸의 적을 위로 1칸 넉백시키며, 필드 내의 적 전체에 피해를 입힌다.",
  str_skill_desc_15011314 = "필드 내 보스를 제외한 모든 단일 칸의 적을 왼쪽으로 1칸 넉백시키며, 필드 내의 적 전체에 피해를 입힌다.",
  str_skill_desc_15011315 = "필드 내 보스를 제외한 모든 단일 칸의 적을 아래로 1칸 넉백시키며, 필드 내의 적 전체에 피해를 입힌다.",
  str_skill_desc_14008112 = "적 전체에 피해를 입히고 자신의 주변으로 끌어당긴다.",
  str_skill_desc_15001812 = "솔라스톰 폭발을 일으켜 적 전체에 피해를 입히고 자신을 중심으로 명중한 적을 넉백시킨다.",
  str_skill_name_200230101 = "아포닉의 치유",
  str_skill_desc_200230101 = "아포닉은 2서클 범위 내 다른 암귀의 HP를 회복시키며, 다른 암귀가 아포닉의 스킬 범위 내에서 차지하는 칸이 클수록 아포닉이 대상을 치료하는 효과가 강해진다.",
  str_skill_desc_29048011 = "대상의 위치 아래에서 땅을 뚫고 나와 대상을 넉백시키고 피해를 입힌다.",
  str_skill_upgrade_desc_16018413 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 초기 선택 범위가 주변 2서클로 변경된다.",
  str_skill_upgrade_desc_16018416 = "<color=#FFFF00>신규 액티브 스킬</color> 개방: 오로라 타임에 사용 가능하며, 주변 1서클 내 지정 위치로 순간이동한다.",
  str_skill_name_2001841 = "날카로운 깃털",
  str_skill_name_2001842 = "날카로운 깃털",
  str_skill_name_2001843 = "날카로운 깃털",
  str_skill_desc_2001841 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001842 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001843 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_2201841 = "날카로운 깃털",
  str_skill_name_2201842 = "날카로운 깃털",
  str_skill_name_2201843 = "날카로운 깃털",
  str_skill_desc_2201841 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201842 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 랜덤 <color=#00F6FF>1</color>칸에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다.",
  str_skill_desc_2201843 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 랜덤 <color=#00F6FF>2</color>칸에 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 생성한다.",
  str_skill_name_300184 = "환영의 모래",
  str_skill_name_303184 = "환영의 모래",
  str_skill_desc_300184 = "<color=#00F6FF>마름모 12칸</color> 내 지정 위치로 순간이동한다. 착지 지점이 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>일 시 <color=#00F6FF>마름모 12칸</color> 내에서 착지 지점을 다시 선택할 수 있다. 지나는 모든 강화 칸을 흡수하며, 흡수할 때마다 주변 마름모 12칸에 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_desc_303184 = "<color=#00F6FF>주변 2서클</color> 내 지정 위치로 순간이동한다. 착지 지점이 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>일 시 <color=#00F6FF>마름모 12칸</color> 내에서 착지 지점을 다시 선택할 수 있다. 지나는 모든 강화 칸을 흡수하며, 흡수할 때마다 주변 마름모 12칸에 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_name_306184 = "질풍의 모래",
  str_skill_desc_306184 = "오로라 타임에 사용 가능하며, <color=#00F6FF>주변 1서클</color> 내 지정 위치로 순간이동한다.",
  str_skill_passive_name_410184 = "언령 소통",
  str_skill_passive_name_430184 = "언령 소통",
  str_skill_passive_desc_410184 = "파티가 액티브 스킬을 통해 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}</color>의 피해를 입힌다. 강화 칸을 1개 흡수할 때마다 다음 공격의 최종 피해가 <color=#00F6FF>{2}</color> 증가한다.",
  str_skill_passive_desc_430184 = "파티가 액티브 스킬을 통해 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}</color>의 피해를 입히고, 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 1개 생성한다. 강화 칸을 1개 흡수할 때마다 다음 공격의 최종 피해가 <color=#00F6FF>{2}</color> 증가한다.",
  str_skill_name_280061101 = "블락-포탑",
  str_skill_desc_280061101 = "공중 보급을 발사, 이동 가능한 칸 하나를 선택해 <color=#00F6FF>포탑 장치</color>를 소환한다.",
  str_skill_name_280061102 = "블락-크레인",
  str_skill_desc_280061102 = "공중 보급을 발사, 이동 가능한 칸 하나를 선택해 <color=#00F6FF>트랙터</color>를 소환한다.",
  str_skill_name_280061103 = "블락-화염",
  str_skill_desc_280061103 = "공중 보급을 발사, 이동 가능한 칸 하나를 선택해 <color=#00F6FF>플레임 트랩</color>을 소환한다.",
  str_skill_name_280061104 = "블락-파괴",
  str_skill_desc_280061104 = "블락 8가 소환한 장치를 선택해 파괴한다.",
  str_skill_name_280061105 = "블락-긴급 수리",
  str_skill_desc_280061105 = "긴급 수리! 블락 8의 HP를 3칸 회복시킨다.",
  str_skill_desc_140127101 = "최대 4개의 칸을 선택(심연 칸 선택 가능), 종이학을 배치하며, 해당 칸을 만색 칸으로 전환한다. 파티가 종이학을 지날 경우 종이학은 사라진다.",
  str_skill_name_2001851 = "스노우 딜리버리",
  str_skill_name_2001852 = "스노우 딜리버리",
  str_skill_name_2001853 = "스노우 딜리버리",
  str_skill_name_3001851 = "청람의 속달",
  str_skill_name_3001852 = "청람의 신속",
  str_skill_name_3361852 = "청람의 신속",
  str_skill_passive_name_410185 = "지점 공습",
  str_skill_passive_name_416185 = "지점 공습",
  str_skill_passive_name_420185 = "지점 공습",
  str_skill_passive_name_426185 = "지점 공습",
  str_skill_passive_name_430185 = "지점 공습",
  str_skill_passive_name_432185 = "지점 공습",
  str_skill_passive_name_436185 = "지점 공습",
  str_skill_desc_2001851 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001852 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001853 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3001851 = "<color=#00F6FF>십자형 12칸</color> 내 선택한 위치로 순간이동한다.",
  str_skill_desc_3001852 = "카이아나이트 포스 <color=#00F6FF>8</color>단계 누적 시 개방: 적 1명을 선택해 대상의 <color=#00F6FF>주변 1서클</color> 중 거리가 가장 가까운 위치로 순간이동한다.",
  str_skill_desc_3361852 = "카이아나이트 포스 <color=#00F6FF>5</color>단계 누적 시 개방: 적 1명을 선택해 대상의 <color=#00F6FF>주변 1서클</color> 중 거리가 가장 가까운 위치로 순간이동한다.",
  str_skill_passive_desc_410185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_416185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고, 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득한다. 카이아나이트 포스 단계마다 피해율이 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_passive_desc_420185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입힌다. 키아의 액티브 스킬로 본 효과 활성화 시 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_passive_desc_426185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고, 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득한다. 카이아나이트 포스 단계마다 피해율이 <color=#00F6FF>5%</color> 증가하며, 키아의 액티브 스킬로 본 효과 활성화 시 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_passive_desc_430185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고, 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득한다, 키아의 액티브 스킬로 본 효과 활성화 시 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_passive_desc_432185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고, 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득한다, 키아의 액티브 스킬로 본 효과 활성화 시 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_passive_desc_436185 = "액티브 스킬을 통해 이동할 때마다 <color=#00F6FF>주변 1서클</color> 범위 내 HP가 가장 낮은 적에게 <color=#00F6FF>{1}</color>의 피해를 입히고, 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득한다. 카이아나이트 포스 단계마다 피해율이 <color=#00F6FF>5%</color> 증가하며, 키아의 액티브 스킬로 본 효과 활성화 시 최종 피해가 <color=#00F6FF>60%</color> 증가한다.",
  str_skill_upgrade_desc_15018512 = "액티브 스킬 강화: 청람의 신속 개방에 필요한 카이아나이트 포스가 <color=#00F6FF>5</color>단계로 감소한다(각성 3단계 달성 시 적용).",
  str_skill_upgrade_desc_15018515 = "장비 스킬 강화: 장비 스킬이 발동할 때마다 카이아나이트 포스를 <color=#00F6FF>1</color>단계 획득하며, 단계마다 키아의 장비 스킬 피해율이 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_name_28005016 = "트랙터",
  str_skill_desc_28005016 = "트랙터가 전방 좁은 범위 내의 암귀를 트랙터의 위치로 1칸 끌어당기며, 각 암귀는 턴마다 트랙터의 끌어당김 효과를 1회만 받는다.",
  str_skill_name_400054101 = "힘의 발산",
  str_skill_desc_400054101 = "범위 내 대상에게 피해를 입히며, 동시에 범위 내 모든 칸을 부수고, 범위 내 모든 블락 8가 소환한 장치를 파괴한다.",
  str_skill_desc_5410100 = "장창으로 공격 범위 내 암귀를 공격한다.",
  str_skill_desc_888426101 = "플레이어가 연속으로 액티브 스킬 3회 시전 시 백야성 장창병 1명을 전장에 소환한다.",
  str_skill_desc_4100002 = "턴마다 불 속성 드레드블레이드를 전장에 소환한다. 전장 내 불 속성 드레드블레이드가 4마리가 되면 더는 소환하지 않는다.",
  str_skill_desc_4100004 = "턴마다 번개 속성 드레드블레이드를 전장에 소환한다. 전장 내 번개 속성 드레드블레이드가 4마리가 되면 더는 소환하지 않는다.",
  str_skill_desc_4100005 = "턴마다 블레이저를 전장에 소환한다. 전장 내 블레이저가 2마리가 되면 더는 소환하지 않는다.",
  str_skill_desc_4100006 = "턴마다 블레이저를 전장에 소환한다. 전장 내 블레이저가 있을 시 더는 소환하지 않는다.",
  str_skill_desc_5401005 = "블레이저가 포티파이어 근처 랜덤 위치에 불의 비를 소환해 속성 피해를 입히며, 대상을 작열 상태에 빠트린다.",
  str_skill_name_290470111 = "기계 사냥꾼-강타",
  str_skill_desc_290470111 = "거대한 망치로 다크매터를 조종해 전체화면 범위 내 대상에게 대량의 피해를 입힌다. 오로리안이 가드 에어리어 범위 내에 있을 시 이번 공격이 오로리안의 HP를 강제로 1까지 떨어트린다.",
  str_skill_name_290470121 = "기계 사냥꾼-추격",
  str_skill_desc_290470121 = "대상이 가드 에어리어 내에 있을 시 대상의 곁으로 이동해 근접 피해를 입힌다. 대상이 가드 에어리어 밖에 있을 시 동일 행과 열 내의 대상을 자신의 주변으로 끌어당긴다.",
  str_skill_desc_290470122 = "대상이 가드 에어리어 내에 있을 시 대상의 곁으로 이동해 근접 피해를 입힌다. 대상이 가드 에어리어 밖에 있을 시 동일 행과 열 내의 대상을 자신의 주변으로 끌어당긴다.",
  str_skill_name_290470131 = "기계 사냥꾼-전율",
  str_skill_desc_290470131 = "거대한 망치를 휘둘러 에너지를 방출, 전체화면 범위에 피해를 입힌다. 플레이어가 가드 에어리어 내에 있을 시 에너지 방출에 의해 필드 가장자리까지 넉백된다.",
  str_skill_name_290490101 = "4기사-차륜전",
  str_skill_desc_290490101 = "네 기사 중 대상과 가장 가까운 기사가 있는 칸의 대각선 위치로 이동하며(자신이 대상과 가장 가까울 경우 제자리 유지), 이후 주변 1서클 범위의 대상을 공격한다.",
  str_skill_desc_290490103 = "네 기사 중 대상과 가장 가까운 기사가 있는 칸의 대각선 위치로 이동하며(자신이 대상과 가장 가까울 경우 제자리 유지), 이후 주변 1서클 범위의 대상을 공격, 오로리안에게 부상 상태를 추가한다(단계마다 오로리안의 방어력 2% 감소).",
  str_skill_desc_290490107 = "주변 1서클 범위 내 대상을 공격한다.",
  str_skill_name_290490102 = "4기사-전격",
  str_skill_desc_290490102 = "다른 네 기사와 함께 지도의 가장자리 위치로 분산하여 이동한 후 대상을 공격한다.",
  str_skill_desc_290490108 = "제자리에서 대상을 공격한다.",
  str_skill_name_290550101 = "푸른 화염",
  str_skill_desc_290550101 = "마견 하티가 현재 HP의 15%를 잃고, 마름모 12칸 내 적 대상과 가장 가까운 위치로 순간이동한 후, 주변 1서클 내의 적 대상에게 피해를 입히며, 대상 명중 시 감소했던 HP 15%를 회복한다.",
  str_skill_name_290550111 = "푸른 화염+",
  str_skill_desc_290550111 = "마견 하티가 현재 HP의 15%를 잃고, 주변 2서클 내 적 대상과 가장 가까운 위치로 순간이동한 후, 주변 1서클 내의 적 대상에게 피해를 입히며, 대상 명중 시 감소했던 HP 15%를 회복한다.",
  str_skill_name_290550121 = "푸른 화염++",
  str_skill_desc_290550121 = "마견 하티가 현재 HP의 15%를 잃고, 주변 2서클 내 적 대상과 가장 가까운 위치로 순간이동한 후, 주변 2서클 내의 적 대상에게 피해를 입히며, 대상 명중 시 감소했던 HP 15%를 회복한다.",
  str_skill_name_290550102 = "혼의 불꽃",
  str_skill_desc_290550102 = "마견 하티가 오로리안 근처로 순간이동하고, 현재 HP의 15%를 소모해 오로리안에게 대량의 피해를 입히며, 오로리안 명중 시 감소했던 HP 15%를 회복한다.",
  str_skill_name_2001891 = "필연적 심판",
  str_skill_name_2001892 = "필연적 심판",
  str_skill_name_2001893 = "필연적 심판",
  str_skill_desc_2001891 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001892 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001893 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_3001890 = "나선 가르기",
  str_skill_name_3001891 = "나선 가르기",
  str_skill_name_3001892 = "나선 가르기",
  str_skill_name_3061891 = "나선 가르기",
  str_skill_name_3061892 = "나선 가르기",
  str_skill_name_3301892 = "오버히트 테크닉",
  str_skill_name_3331892 = "오버히트 테크닉",
  str_skill_desc_3001890 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 <color=#00F6FF>부채꼴 2줄</color> 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_desc_3001891 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 <color=#00F6FF>부채꼴 2줄</color> 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 열에너지에 따라 피해 범위와 피해율이 증가하며, 최대 <color=#00F6FF>부채꼴 7줄</color> 범위에 <color=#00F6FF>400%</color>의 피해를 입힌다. 스킬 시전 후 열에너지는 초기화된다.",
  str_skill_desc_3001892 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 <color=#00F6FF>부채꼴 2줄</color> 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 열에너지에 따라 피해 범위와 피해율이 증가하며, 최대 <color=#00F6FF>부채꼴 7줄</color> 범위에 <color=#00F6FF>400%</color>의 피해를 입힌다. 스킬 시전 후 열에너지는 초기화된다.",
  str_skill_desc_3061891 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 <color=#00F6FF>부채꼴 2줄</color> 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 열에너지에 따라 피해 범위와 피해율이 증가하며, 최대 <color=#00F6FF>부채꼴 7줄</color> 범위에 <color=#00F6FF>400%</color>의 피해를 입힌다. 스킬 시전 후 열에너지는 초기화된다. 자신이 위치한 칸을 선택하면 피해를 입히지 않고, 열에너지가 <color=#00F6FF>35</color>포인트 증가한다.",
  str_skill_desc_3061892 = "자신의 주변 <color=#00F6FF>십자형 4칸</color> 중 1곳을 선택, 해당 방향 <color=#00F6FF>부채꼴 2줄</color> 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 열에너지에 따라 피해 범위와 피해율이 증가하며, 최대 <color=#00F6FF>부채꼴 7줄</color> 범위에 <color=#00F6FF>400%</color>의 피해를 입힌다. 스킬 시전 후 열에너지는 초기화된다. 자신이 위치한 칸을 선택하면 피해를 입히지 않고, 열에너지가 <color=#00F6FF>35</color>포인트 증가한다.",
  str_skill_desc_3301892 = "이번 턴 과열 상태에서도 정상적으로 일반공격을 할 수 있으며, 턴 종료 후 열에너지는 초기화된다.",
  str_skill_desc_3331892 = "열에너지를 <color=#00F6FF>100</color>포인트까지 증가시키고, 이번 턴 과열 상태에서도 정상적으로 일반공격을 할 수 있으며, 턴 종료 후 열에너지는 초기화된다.",
  str_skill_name_2001901 = "네 죄를 알라",
  str_skill_name_2001902 = "네 죄를 알라",
  str_skill_name_2001903 = "네 죄를 알라",
  str_skill_name_2001933 = "네 죄를 알라",
  str_skill_name_3001901 = "채찍 정화",
  str_skill_name_3001902 = "채찍 정화",
  str_skill_name_3001903 = "채찍 정화",
  str_skill_name_3021901 = "채찍 정화",
  str_skill_name_3051901 = "채찍 정화",
  str_skill_desc_2001901 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_desc_2001902 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>155%</color>의 피해를 입힌다.",
  str_skill_desc_2001903 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2001933 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 2명에게 <color=#00F6FF>160%</color>의 피해를 입힌다. 불 속성 오로리안이 액티브 스킬을 시전할 때마다 발동 조건이 <color=#00F6FF>1</color> 증가하며, 명중 대상이 1 증가하거나 범위가 <color=#00F6FF>1</color>서클 확대된다.",
  str_skill_desc_3001901 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환한다.",
  str_skill_desc_3001902 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3001903 = "가장 가까운 숲 속성 <color=#00F6FF>5</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3021901 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3051901 = "가장 가까운 숲 속성 <color=#00F6FF>5</color>칸을 불 속성으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
