  str_skill_passive_desc_410189 = "레인의 일반공격은 <link=\"30078\"><#FFAE07><u>열에너지</u></color></link>에 따라 최대 <color=#00F6FF>{1}</color>의 피해 보너스를 획득하며, 열에너지가 높을수록 보너스 효율이 증가한다. 열에너지가 <color=#00F6FF>100</color>포인트가 되면 과열 상태에 진입해 일반공격을 할 수 없게 된다.",
  str_skill_passive_desc_420189 = "레인의 일반공격은 <link=\"30078\"><#FFAE07><u>열에너지</u></color></link>에 따라 최대 <color=#00F6FF>{1}</color>의 피해 보너스를 획득하며, 열에너지가 높을수록 보너스 효율이 증가한다. 열에너지가 <color=#00F6FF>100</color>포인트가 되면 과열 상태에 진입해 일반공격을 할 수 없게 되나, 연쇄 스킬의 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_430189 = "레인의 일반공격은 <link=\"30078\"><#FFAE07><u>열에너지</u></color></link>에 따라 최대 <color=#00F6FF>{1}</color>의 피해 보너스를 획득하며, 열에너지가 높을수록 보너스 효율이 증가한다. 열에너지가 <color=#00F6FF>100</color>포인트가 되면 과열 상태에 진입해 일반공격을 할 수 없게 되나, 연쇄 스킬의 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_433189 = "레인의 일반공격은 <link=\"30078\"><#FFAE07><u>열에너지</u></color></link>에 따라 최대 <color=#00F6FF>{1}</color>의 피해 보너스를 획득하며, 열에너지가 높을수록 보너스 효율이 증가한다. 열에너지가 <color=#00F6FF>100</color>포인트가 되면 과열 상태에 진입해 일반공격을 할 수 없게 되나, 연쇄 스킬의 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_desc_410190 = "연쇄 스킬로 입힌 피해의 <color=#00F6FF>50%</color>가 실드로 전환되며, 해당 수치는 마티외의 공격력의 <color=#00F6FF>{1}</color>를 초과할 수 없다.",
  str_skill_passive_desc_420190 = "연쇄 스킬로 입힌 피해의 <color=#00F6FF>50%</color>가 실드로 전환되며, 해당 수치는 마티외의 공격력의 <color=#00F6FF>{1}</color>를 초과할 수 없다. 불 속성 오로리안이 액티브 스킬을 시전할 때마다 마티외의 공격력의 <color=#00F6FF>10%</color>에 해당하는 실드를 획득한다.",
  str_skill_passive_desc_430190 = "연쇄 스킬로 입힌 피해의 <color=#00F6FF>50%</color>가 실드로 전환되며, 해당 수치는 마티외의 공격력의 <color=#00F6FF>{1}</color>를 초과할 수 없다. 불 속성 오로리안이 액티브 스킬을 시전할 때마다 마티외의 공격력의 <color=#00F6FF>10%</color>에 해당하는 실드를 획득한다.",
  str_skill_upgrade_desc_16018613 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16018616 = "액티브 스킬 강화: 연결 가능한 칸 수가 <color=#00F6FF>1</color>칸 증가한다.",
  str_skill_name_2001861 = "광휘의 통찰",
  str_skill_name_2001862 = "광휘의 통찰",
  str_skill_name_2001863 = "광휘의 통찰",
  str_skill_desc_2001861 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001862 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001863 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_name_410186 = "눈부신 광채",
  str_skill_passive_name_430186 = "눈부신 광채",
  str_skill_passive_desc_410186 = "티나가 턴마다 처음 입히는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_430186 = "티나가 턴마다 처음 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 지난 턴에 티나가 출전하지 않으면 이번 턴에서 효과가 2배로 증가한다.",
  str_skill_name_3001861 = "빛의 안식",
  str_skill_name_3061861 = "빛의 안식",
  str_skill_name_3201861 = "빛의 안식",
  str_skill_name_3261861 = "빛의 안식",
  str_skill_desc_3001861 = "티나가 꿈속으로 들어가 색상을 무시하고 최대 <color=#00F6FF>3</color>칸을 이동해 <color=#00F6FF>지나는 칸</color>을 물 속성으로 전환하고 출발점으로 돌아온다.",
  str_skill_desc_3061861 = "티나가 꿈속으로 들어가 색상을 무시하고 최대 <color=#00F6FF>4</color>칸을 이동해 <color=#00F6FF>지나는 칸</color>을 물 속성으로 전환하고 출발점으로 돌아온다.",
  str_skill_desc_3201861 = "티나가 꿈속으로 들어가 색상을 무시하고 최대 <color=#00F6FF>3</color>칸을 이동해 <color=#00F6FF>출발점과 지나는 칸</color>을 물 속성으로 전환하고 출발점으로 돌아온다. 또한 연결 가능 수를 무시하고 적의 위치를 연결의 도착지로 삼을 수 있으며, 대상에게 <color=#00F6FF>200%</color>의 피해를 입히고, 출발점으로 돌아가지 않는다.",
  str_skill_desc_3261861 = "티나가 꿈속으로 들어가 색상을 무시하고 최대 <color=#00F6FF>4</color>칸을 이동해 <color=#00F6FF>출발점과 지나는 칸</color>을 물 속성으로 전환하고 출발점으로 돌아온다. 또한 연결 가능 수를 무시하고 적의 위치를 연결의 도착지로 삼을 수 있으며, 대상에게 <color=#00F6FF>200%</color>의 피해를 입히고, 출발점으로 돌아가지 않는다.",
  str_skill_upgrade_desc_16018913 = "액티브 스킬 강화: 액티브 스킬2 오버히트 테크닉이 <color=#FFFF00>선제공격</color>으로 변경되며, 발동 후 열에너지가 <color=#00F6FF>100</color>포인트까지 증가한다(각성 3단계 달성 시 적용).",
  str_skill_upgrade_desc_16018916 = "액티브 스킬 강화: 자신이 위치한 칸을 선택할 수 있게 되며, 피해를 입히지 않는 대신 열에너지가 <color=#00F6FF>35</color>포인트 증가한다(각성 1단계 달성 시 적용).",
  str_skill_upgrade_desc_15019012 = "액티브 스킬 강화: 이전 턴에 스킬이 준비되면 이번 턴의 색 변경 수량이 <color=#FFFF00>1</color> 증가한다.",
  str_skill_upgrade_desc_15019015 = "액티브 스킬 강화: 색 변경 수량이 <color=#FFFF00>1</color> 증가한다.",
  str_skill_upgrade_refine_desc_16001111 = "장비 스킬 강화: 적에게 용아의 인장을 최대 <color=#00F6FF>7</color>개까지 추가한다.",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>주변 3서클</color> 내 지정 위치로 순간이동하며, <color=#FFFF00>주변 1서클</color>에 <color=#FFFF00>200%</color>의 피해를 입히고 용아의 인장 2개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. <color=#FFFF00>지정</color> 위치로 순간이동하며, <color=#FFFF00>주변 3서클</color>에 <color=#FFFF00>360%</color>의 피해를 입히고 용아의 인장 2개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_desc_3300111 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>주변 3서클</color> 내 지정 위치로 순간이동하며, <color=#FFFF00>주변 1서클</color>에 <color=#FFFF00>200%</color>의 피해를 입히고 용아의 인장 2개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_desc_3300112 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. <color=#FFFF00>지정</color> 위치로 순간이동하며, <color=#FFFF00>주변 3서클</color>에 <color=#FFFF00>360%</color>의 피해를 입히고 용아의 인장 2개를 추가한다(적 처치 시 범위 내 다른 적의 인장이 최대 개수까지 증가함).",
  str_skill_upgrade_desc_16019113 = "신규 액티브 스킬 획득: 파티의 현재 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>주변 1서클</color>에 250%의 피해를 입힌다.",
  str_skill_upgrade_desc_16019116 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 1 감소한다.",
  str_skill_name_2001911 = "창염의 폭발",
  str_skill_name_2001912 = "창염의 폭발",
  str_skill_name_2001913 = "창염의 폭발",
  str_skill_name_2301911 = "창염의 폭발",
  str_skill_name_2301912 = "창염의 폭발",
  str_skill_name_2301913 = "창염의 폭발",
  str_skill_desc_2001911 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2001912 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2001913 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_2301911 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다. HP가 40% 미만일 시 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대된다.",
  str_skill_desc_2301912 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>160%</color>의 피해를 입힌다. HP가 40% 미만일 시 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대된다.",
  str_skill_desc_2301913 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>170%</color>의 피해를 입힌다. HP가 40% 미만일 시 도약 범위가 <color=#00F6FF>주변 2서클</color>로 확대된다.",
  str_skill_name_3001911 = "구축의 화염",
  str_skill_name_3201911 = "구축의 화염",
  str_skill_name_32019111 = "구축의 화염",
  str_skill_desc_3001911 = "주변 <color=#00F6FF>마름모 24칸</color> 내에서 적 1명을 선택, 해당 적과 가장 가까운 칸으로 순간이동해 적에게 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_3201911 = "주변 <color=#00F6FF>마름모 24칸</color> 내에서 적 1명을 선택, 해당 적과 가장 가까운 칸으로 순간이동해 적에게 <color=#00F6FF>150%</color>의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 4서클</color>로 변경된다.",
  str_skill_desc_32019112 = "주변 <color=#00F6FF>마름모 24칸</color> 내에서 적 1명을 선택, 해당 적과 가장 가까운 칸으로 순간이동해 적에게 <color=#00F6FF>150%</color>의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 4서클</color>로 변경되고, 피해가 <color=#00F6FF>200%</color>로 증가한다.",
  str_skill_desc_32019113 = "주변 <color=#00F6FF>마름모 24칸</color> 내에서 적 1명을 선택, 해당 적과 가장 가까운 칸으로 순간이동해 십자형 5칸에 <color=#00F6FF>150%</color>의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 4서클</color>로 변경되고, 피해가 <color=#00F6FF>200%</color>로 증가한다.",
  str_skill_name_3001912 = "화염의 공진",
  str_skill_name_3061912 = "화염의 공진",
  str_skill_desc_3001912 = "파티의 현재 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>주변 1서클</color>에 {1}%의 피해를 입힌다.",
  str_skill_passive_name_410191 = "혼의 발톱",
  str_skill_passive_desc_410191 = "파티의 HP가 낮을수록 하티가 입히는 피해가 증가하며, 파티의 HP가 <color=#00F6FF>30%</color> 이하일 시 최대 보너스인 <color=#00F6FF>{1}</color>까지 증가한다.",
  str_skill_passive_desc_4101911 = "파티의 HP가 낮을수록 하티가 입히는 피해가 증가하며, 파티의 HP가 <color=#00F6FF>30%</color> 이하일 시 최대 보너스인 <color=#00F6FF>60%</color>까지 증가한다.",
  str_skill_upgrade_refine_desc_16019111 = "장비 스킬 강화: 파티의 HP가 30% 이하일 시 <color=#00F6FF>60%</color>의 최대 보너스를 획득한다.",
  str_skill_upgrade_refine_desc_16019112 = "액티브 스킬 강화: 액티브 스킬이 이전 턴에 준비되면 이번 턴의 순간이동 범위가 주변 4서클로 변경되고, <color=#00F6FF>피해가 200%로 증가한다</color>.",
  str_skill_upgrade_refine_desc_16019113 = "액티브 스킬 강화: 단일 대상에게 입히는 피해가 <color=#00F6FF>목표 칸 기준 십자형 5칸</color> 피해로 변경된다.",
