  str_skill_name_3401932 = "천상의 지저귐-진화Ⅱ",
  str_skill_desc_2001931 = "<color=#00F6FF>십자형 8칸</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001932 = "<color=#00F6FF>마름모 12칸</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20019333 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2201931 = "<color=#00F6FF>십자형 8칸</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 십자 방향의 적에게 입히는 피해가 30% 증가한다.",
  str_skill_desc_2201932 = "<color=#00F6FF>마름모 12칸</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 십자 방향의 적에게 입히는 피해가 30% 증가한다.",
  str_skill_desc_2201933 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 십자 방향의 적에게 입히는 피해가 30% 증가한다.",
  str_skill_desc_3001931 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_3051931 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>200%</color>의 피해를 입힌다.",
  str_skill_desc_3301931 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>160%</color>의 피해를 입힌다. 대상이 멀수록 피해가 증가하며, 서클당 <color=#00F6FF>10%</color>의 최종 피해가 증가한다.",
  str_skill_desc_3351931 = "1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 <color=#00F6FF>200%</color>의 피해를 입힌다. 대상이 멀수록 피해가 증가하며, 서클당 <color=#00F6FF>10%</color>의 최종 피해가 증가한다.",
  str_skill_desc_3401931 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 160%의 피해를 입히고 파티 내 <color=#FFFF00>바로 위</color>의 오로리안과 위치를 변경한다. 대상이 멀수록 피해가 증가하며, 서클당 10%의 최종 피해가 증가한다. <color=#FFFF00>외곽 칸 선택 시 크리스틴이 앞으로 1칸 이동한 후 스킬을 시전한다</color>.",
  str_skill_desc_3451931 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 1개 방향을 선택해 공격, 해당 방향의 모든 적에게 공격력의 200%의 피해를 입히고 파티 내 <color=#FFFF00>바로 위</color>의 오로리안과 위치를 변경한다. 대상이 멀수록 피해가 증가하며, 서클당 10%의 최종 피해가 증가한다. <color=#FFFF00>외곽 칸 선택 시 크리스틴이 앞으로 1칸 이동한 후 스킬을 시전한다</color>.",
  str_skill_desc_3401932 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>공격하지 않고</color> 파티 내 <color=#FFFF00>바로 아래</color>의 오로리안과 위치를 변경하며, <color=#FFFF00>다음 액티브 스킬이 입히는 피해가 50% 증가한다</color>. 중복 시전 시 피해 보너스가 누적되지 않는다.",
  str_skill_passive_name_410193 = "관통의 격류",
  str_skill_passive_name_430193 = "관통의 격류",
  str_skill_passive_desc_410193 = "일반공격 시 적을 관통하며, 적의 후방 1칸에 있는 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430193 = "일반공격 시 적을 관통하며, 적의 후방 1칸에 있는 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_4401933 = "일반공격 시 적을 관통하며, 적의 후방 1칸에 있는 대상에게 <color=#00F6FF>60%</color>의 피해를 입힌다. 크리스틴의 파티 내 위치가 바뀔 시 이번 전투의 리더 변경 횟수가 <color=#00F6FF>1</color>회 증가하며, 리더 변경 횟수는 턴마다 1번만 증가한다.",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 1개 방향을 선택해 공격, 해당 방향의 모든 적에게 피해를 입히고 파티 내 <color=#FFFF00>바로 위</color>의 오로리안과 위치를 변경한다. 대상이 멀수록 피해가 증가하며, 서클당 10%의 최종 피해가 증가한다. <color=#FFFF00>외곽 칸 선택 시 크리스틴이 앞으로 1칸 이동한 후 스킬을 시전한다</color>.",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>공격하지 않고</color> 파티 내 <color=#FFFF00>바로 아래</color>의 오로리안과 위치를 변경하며, <color=#FFFF00>다음 액티브 스킬이 입히는 피해가 50% 증가한다</color>. 중복 시전 시 피해 보너스가 누적되지 않는다.",
  str_skill_upgrade_refine_desc_15019313 = "장비 스킬 강화: 크리스틴의 파티 내 위치가 바뀔 시 이번 전투의 리더 변경 횟수가 1회 증가하며, 리더 변경 횟수는 턴마다 1번만 증가한다.",
  str_skill_upgrade_desc_15019312 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15019315 = "액티브 스킬 강화: 액티브 스킬 피해가 <color=#FFFF00>40%</color> 증가한다.",
  str_skill_upgrade_refine_desc_14004811 = "장비 스킬 강화: 적의 발밑에 번개 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_upgrade_refine_desc_14004812 = "액티브 스킬 강화: 범위 중앙 칸에 2배의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_14004813 = "액티브 스킬 강화: 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_passive_desc_4400481 = "디나가 번개 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>10%</color> 증가하며, 적의 발밑에 번개 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다. 파티 내 다른 번개 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_name_3400482 = "기행의 새",
  str_skill_name_3420482 = "기행의 새",
  str_skill_name_3400483 = "기행의 새",
  str_skill_name_3420483 = "기행의 새",
  str_skill_desc_3400482 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입힌다.",
  str_skill_desc_3420482 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입히며, 적의 위치 중 최대 1칸을 번개 속성으로 전환한다.",
  str_skill_desc_3400483 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_3420483 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입히며, 적의 위치 중 최대 1칸을 번개 속성으로 전환한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_upgrade_refine_desc_15009811 = "연쇄 스킬 강화: 연쇄 스킬 피해 계수가 <color=#00F6FF>15%/20%/20%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15009812 = "장비 스킬 강화: 분리의 인장을 최대 <color=#00F6FF>10</color>개까지 추가할 수 있으며, 개당 피해가 6% 증가한다.",
  str_skill_upgrade_refine_desc_15009813 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>500%</color>로 증가한다. 액티브 스킬로 선택한 적을 이동시킬 수 없는 경우, <color=#00F6FF>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>.",
  str_skill_desc_2009811 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2009821 = "<color=#00F6FF>주변 3서클</color> 내의 적 4명에게 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2009831 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적에게 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_3300981 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적 1명을 선택해 대상에게 <color=#00F6FF>500%</color>의 피해를 입히고, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다. 넉백 불가능한 적일 시 <color=#00F6FF>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 인장을 지닌 적 처치 시 대상 <color=#00F6FF>주변 1서클</color> 내의 적에게 쿠스쿠타의 공격력의 <color=#00F6FF>40%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_desc_3350981 = "적 1명을 선택해 대상에게 <color=#00F6FF>500%</color>의 피해를 입히고, 단일 칸 크기의 넉백 가능한 적일 시 대상을 공격 범위 내의 선택한 위치로 이동시킨다. 넉백 불가능한 적일 시 <color=#00F6FF>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 인장을 지닌 적 처치 시 대상 <color=#00F6FF>주변 1서클</color> 내의 적에게 쿠스쿠타의 공격력의 <color=#00F6FF>40%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_desc_3200331 = "랜덤으로 필드의 적에게 <color=#00F6FF>95%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다. 각 대상에게 처음으로 입히는 피해는 <color=#00F6FF>2배</color>가 된다.",
  str_skill_desc_3250331 = "랜덤으로 필드의 적에게 <color=#00F6FF>95%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 물 속성 칸이 1개 있을 때마다 추가로 1회 공격한다. 각 대상에게 처음으로 입히는 피해는 <color=#00F6FF>2배</color>가 된다.",
  str_skill_passive_desc_4300331 = "바이스가 피해를 입힐 때마다 주시의 인장을 1개 획득하며, 인장 개수마다 피해가 <color=#00F6FF>2.5%</color> 증가한다(연쇄 스킬은 <color=#00F6FF>5%</color> 증가). 턴 종료 후 인장은 초기화된다.",
  str_skill_passive_desc_4300332 = "바이스가 피해를 입힐 때마다 주시의 인장을 1개 획득하며, 인장 개수마다 피해가 <color=#00F6FF>2.5%</color> 증가하며(연쇄 스킬은 <color=#00F6FF>5%</color> 증가), 바이스의 기본 공격력을 0.5% 증가시킨다. 턴 종료 후 인장은 초기화된다.",
  str_skill_upgrade_refine_desc_15003311 = "장비 스킬 강화: 인장 개수마다 피해가 <color=#00F6FF>2.5%</color> 증가한다(연쇄 스킬은 <color=#00F6FF>5%</color> 증가).",
  str_skill_upgrade_refine_desc_15003312 = "액티브 스킬 강화: 각 대상에게 처음으로 입히는 피해는 <color=#00F6FF>2배</color>가 된다.",
  str_skill_upgrade_refine_desc_15003313 = "장비 스킬 강화: 인장 개수마다 기본 공격력을 <color=#00F6FF>0.5%</color> 증가시킨다.",
  str_skill_desc_340093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>250%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다. 적 5명을 처치할 때마다 선택 가능한 순간이동 범위가 1서클 증가한다.",
  str_skill_desc_346093 = "<color=#00F6FF>주변 3서클</color> 내 선택한 위치로 순간이동해 <color=#00F6FF>주변 1서클</color> 내의 적에게 <color=#00F6FF>250%</color>의 피해를 입힌다. 범위 내에 적이 1명만 있을 경우 피해가 2배로 증가한다. 적 1명을 처치할 때마다 최종 피해가 <color=#00F6FF>15%</color> 증가하며, 10회까지 누적될 수 있다. 액티브 스킬로 적 처치 시 재사용할 수 있다(턴마다 1회 한정). 적 5명을 처치할 때마다 선택 가능한 순간이동 범위가 1서클 증가한다.",
  str_skill_passive_desc_4300931 = "연쇄 스킬 또는 액티브 스킬 시전 후 대상의 HP가 <color=#00F6FF>30%</color> 미만일 시 대상에게 공격력의 <color=#00F6FF>120%</color>에 해당하는 방어무시 피해를 추가로 1회 입힌다. 추가 공격 후 대상의 HP가 미자드의 공격력보다 낮을 경우 대상을 즉시 처치한다.",
  str_skill_passive_desc_4300932 = "연쇄 스킬 또는 액티브 스킬 시전 후 대상의 HP가 <color=#00F6FF>30%</color> 미만일 시 대상에게 공격력의 <color=#00F6FF>120%</color>에 해당하는 방어무시 피해를 추가로 1회 입힌다. 추가 공격 후 대상의 HP가 미자드의 공격력의 250%보다 낮을 경우 대상을 즉시 처치한다.",
  str_skill_upgrade_refine_desc_16009311 = "장비 스킬 강화: 추가 공격 피해가 <color=#00F6FF>120%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16009312 = "액티브 스킬 강화: 액티브 스킬이 피해 보너스를 <color=#00F6FF>5회</color> 획득할 때마다 선택 범위가 <color=#00F6FF>1서클</color> 증가한다.",
  str_skill_upgrade_refine_desc_16009313 = "장비 스킬 강화: 추가 공격 후 대상의 HP가 미자드의 공격력의 <color=#00F6FF>250%</color>보다 낮을 경우 대상을 즉시 처치한다.",
  str_skill_upgrade_refine_desc_15001811 = "장비 스킬 강화: 적과의 거리가 가까울수록 액티브 스킬과 연쇄 스킬 피해가 증가하며, 최대 <color=#00F6FF>110%</color>까지 증가한다.",
  str_skill_upgrade_refine_desc_15001812 = "연쇄 스킬 강화: 연쇄 스킬 피해 계수가 <color=#00F6FF>10%/15%/20%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15001813 = "장비 스킬 강화: 장비 스킬의 유효 범위가 <color=#00F6FF>5서클</color>까지 확대된다.",
  str_skill_passive_desc_440018 = "<color=#00F6FF>주변 8칸</color> 범위에 적이 1명 있을 때마다 공격력이 <color=#00F6FF>5%</color> 증가한다. 적과의 거리가 가까울수록 액티브 스킬과 연쇄 스킬 피해가 증가하며, 최대 <color=#00F6FF>110%</color>까지 증가한다. 적과의 거리가 3서클 초과 시 증가하지 않는다.",
  str_skill_passive_desc_450018 = "<color=#00F6FF>주변 8칸</color> 범위에 적이 1명 있을 때마다 공격력이 <color=#00F6FF>5%</color> 증가한다. 적과의 거리가 가까울수록 액티브 스킬과 연쇄 스킬 피해가 증가하며, 최대 <color=#00F6FF>110%</color>까지 증가한다. 적과의 거리가 5서클 초과 시 증가하지 않는다.",
  str_skill_desc_2400181 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>115%</color>의 피해를 입힌다.",
  str_skill_desc_2400182 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>125%</color>의 피해를 입힌다.",
  str_skill_desc_2400183 = "<color=#00F6FF>세로 5열</color>에 <color=#00F6FF>130%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16006411 = "액티브 스킬 강화: 전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다.",
  str_skill_upgrade_refine_desc_16006412 = "장비 스킬 강화: 자신이 액티브 스킬 시전 시 탄약을 <color=#00F6FF>5</color>개 비축할 수 있고, 다른 오로리안이 액티브 스킬 시전 시 <color=#00F6FF>1</color>개 비축할 수 있다.",
  str_skill_upgrade_refine_desc_16006413 = "장비 스킬 강화: 연쇄 스킬의 탄약 소모 여부를 수동으로 전환해 선택할 수 있다.",
  str_skill_passive_desc_440064 = "<link=\"30079\"><#FFAE07><u>탄약을 비축</u></color></link>할 수 있다. 연쇄 스킬이 피해를 1회 입힐 때마다 탄약 1발을 소모해 <color=#00F6FF>30%</color>의 최종 피해를 증가시킨다(오버로드 모드에서는 매회 최대 <color=#00F6FF>3</color>발의 탄약 소모 가능).",
  str_skill_desc_341064 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. 오버로드 모드에 진입. 레이스의 연쇄 스킬 피해가 <color=#00F6FF>50%</color> 증가하며, 가장 가까운 적 1명에게 2턴간 2회의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16001911 = "빅토리아가 전투 진입 시 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다.\n<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 범위 내의 적 3명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 일정 비율만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_upgrade_refine_desc_16001912 = "액티브 스킬 강화: 액티브 스킬이 적 1명을 추가로 공격할 수 있다.",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 범위 내의 적 4명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 일정 비율만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_3200192 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 주변 3서클 내의 적 3명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 25%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_3200191 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 주변 3서클 내의 적 3명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 25%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_3230192 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 주변 3서클 내의 적 3명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_3230191 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 주변 3서클 내의 적 3명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_3260192 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 가장 가까운 적 3명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_3260191 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 가장 가까운 적 3명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_32001922 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 주변 3서클 내의 적 4명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 25%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_32001912 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 주변 3서클 내의 적 4명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 25%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_32301922 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 주변 3서클 내의 적 4명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_32301912 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 주변 3서클 내의 적 4명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_32601922 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 가장 가까운 적 4명에게 <color=#FFFF00>300%</color>의 피해를 입히고, 적이 1명일 시 <color=#FFFF00>300%</color>의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 잃는다</color>.",
  str_skill_desc_32601912 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 가장 가까운 적 4명에게 250%의 피해를 입히고, 적이 1명일 시 250%의 방어무시 피해를 입히며, 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다. 이번 피해의 35%만큼 HP를 회복하며, <color=#FFFF00>이번 HP 회복 비율과 동일한 이성 수치를 회복한다</color>.",
  str_skill_desc_340019 = "<color=#00F6FF>주변 3서클</color> 내의 적 4명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 25%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_desc_343019 = "<color=#00F6FF>주변 3서클</color> 내의 적 4명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_desc_346019 = "가장 가까운 적 4명에게 <color=#00F6FF>250%</color>의 피해를 입히고, 적이 1명일 시 <color=#00F6FF>250%</color>의 방어무시 피해를 입히며, 이번 피해의 35%에 해당하는 HP를 회복한다. 대상에게 출혈 상태가 1개 있을 때마다 최종 피해가 10% 증가한다.",
  str_skill_name_290510101 = "드릴 에어리어 시전",
  str_skill_desc_290510101 = "드릴러가 랜덤으로 비교적 넓은 구역을 선택해 이동하며, 인접 4칸에 전기 피해를 입힌다. 이동이 종료되면 주변 2칸 범위에 일정 수량의 체인 존과 어시스트 존을 생성한다.",
  str_skill_desc_290511102 = "드릴러가 랜덤으로 비교적 넓은 구역을 선택해 이동하며, 인접 4칸에 전기 피해를 입힌다. 이동이 종료되면 일정 수량의 체인 존과 어시스트 존을 생성한다.",
  str_skill_desc_290511103 = "행동을 시작할 때 주변에 일정 수량의 체인 존과 어시스트 존을 생성한다.",
  str_skill_name_290510102 = "드릴러 에어리어 체인 링크",
  str_skill_desc_290510102 = "드릴러가 필드 내 체인 존을 흡수해 제자리에 드릴러 플랫폼을 조립하고 전체 피해를 입힌다.",
  str_skill_name_290510203 = "드릴러 에어리어 어시스트 어택",
  str_skill_desc_290510203 = "드릴러가 드릴러 플랫폼을 이용해 오로리안의 위치를 고정하며, 플레이어와 가장 가까운 5개의 어시스트 존을 끌어당겨 플레이어에게 피해를 입힌다. 에너지 축적은 2턴의 쿨다운 시간을 가진다.",
  str_skill_desc_290510213 = "드릴러가 드릴러 플랫폼을 이용해 오로리안의 위치를 고정하며, 플레이어와 가장 가까운 3개의 어시스트 존을 끌어당겨 플레이어에게 피해를 입힌다. 에너지 축적은 1턴의 쿨다운 시간을 가진다.",
  str_skill_name_290510204 = "드릴러 플랫폼 자폭",
  str_skill_desc_290510204 = "에너지 축적이 완료되어 드릴러 플랫폼이 자폭을 발동해 전체 범위에 대량의 피해를 입힌다.",
  str_skill_name_290510123 = "조작 중",
  str_skill_desc_290510123 = "드릴러가 플랫폼 후방에서 조작을 진행할 때, 드릴러와 드릴러 플랫폼의 HP는 별도로 구분된다.",
  str_skill_desc_290511101 = "드릴러가 플레이어의 위치를 향해 이동하며, 인접 4칸에 전기 피해를 입힌다. 이동이 종료되면 주변 4칸 범위에 어시스트 존을 생성한다.",
  str_skill_desc_290511203 = "드릴러가 드릴러 플랫폼을 이용해 오로리안의 위치를 고정하며, 모든 어시스트 존을 끌어당겨 플레이어에게 피해를 입힌다. 어시스트 존 수량이 많을수록 플레이어가 받는 피해가 증가한다.",
  str_skill_desc_290512101 = "드릴러가 발굴에 집중하며, 턴 시작 시 근처 범위에 소량의 체인 존과 어시스트 존을 생성한다.",
  str_skill_upgrade_desc_16019913 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16019916 = "장비 스킬 강화: 잉겔이 갈라진 상처가 있는 대상에게 피해를 입힐 시 1개마다 대상의 방어력을 <color=#00F6FF>5%</color> 무시한다(각성 3단계 달성 시 적용).",
  str_skill_name_2001991 = "정밀 초점",
  str_skill_name_2001992 = "정밀 초점",
  str_skill_name_2001993 = "정밀 초점",
  str_skill_desc_2001991 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001992 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001993 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_2201991 = "정밀 초점",
  str_skill_name_2201992 = "정밀 초점",
  str_skill_name_2201993 = "정밀 초점",
  str_skill_desc_2201991 = "갈라진 상처가 가장 많고 HP가 가장 높은 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 해당하는 조건이 없을 시 가장 가까운 적을 공격한다.",
  str_skill_desc_2201992 = "갈라진 상처가 가장 많고 HP가 가장 높은 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 해당하는 조건이 없을 시 가장 가까운 적을 공격한다.",
  str_skill_desc_2201993 = "갈라진 상처가 가장 많고 HP가 가장 높은 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 해당하는 조건이 없을 시 가장 가까운 적을 공격한다.",
  str_skill_name_3001991 = "정점 공명",
  str_skill_desc_3001991 = "1칸을 선택해 번개 속성의 <link=\"30080\"><#FFAE07><u>십자 프리즘 칸</u></color></link>으로 전환한다.",
  str_skill_passive_name_410199 = "특수중형탄 장전",
  str_skill_passive_name_420199 = "특수중형탄 장전",
  str_skill_passive_name_430199 = "특수중형탄 장전",
  str_skill_passive_name_436199 = "특수중형탄 장전",
  str_skill_passive_desc_410199 = "잉겔의 일반공격이 <color=#00F6FF>1회 간격</color>을 두고 피해를 입히며, 일반공격 배율이 <color=#00F6FF>{1}</color>로 증가한다.",
  str_skill_passive_desc_420199 = "잉겔의 일반공격이 <color=#00F6FF>1회 간격</color>을 두고 피해를 입히며, 일반공격 배율이 <color=#00F6FF>{1}</color>로 증가한다. 또한 갈라진 상처를 1개 추가하고(최대 20개), 잉겔이 갈라진 상처가 있는 대상에게 입히는 연쇄 스킬 최종 피해가 개당 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_430199 = "잉겔의 일반공격이 <color=#00F6FF>1회 간격</color>을 두고 피해를 입히며, 일반공격 배율이 <color=#00F6FF>{1}</color>로 증가한다. 또한 갈라진 상처를 1개 추가하고(최대 20개), 잉겔이 갈라진 상처가 있는 대상의 방어력을 개당 <color=#00F6FF>3%</color> 무시하며, 입히는 연쇄 스킬 최종 피해가 개당 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_436199 = "잉겔의 일반공격이 <color=#00F6FF>1회 간격</color>을 두고 피해를 입히며, 일반공격 배율이 <color=#00F6FF>{1}</color>로 증가한다. 또한 갈라진 상처를 1개 추가하고(최대 20개), 잉겔이 갈라진 상처가 있는 대상의 방어력을 개당 <color=#00F6FF>5%</color> 무시하며, 입히는 연쇄 스킬 최종 피해가 개당 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_desc_1601751002 = "십자 프리즘 칸",
  str_skill_desc_160175102 = "큐빅 에너지를 <color=#00F6FF>3</color>포인트 소모, 칸 1개를 선택해 십자 프리즘 칸으로 전환한다.",
  str_skill_name_3400231 = "어비스 카코포니-진화Ⅰ",
  str_skill_name_3430231 = "어비스 카코포니-진화Ⅰ",
  str_skill_name_3400232 = "어비스 카코포니-진화Ⅱ",
  str_skill_name_3430232 = "어비스 카코포니-진화Ⅱ",
  str_skill_desc_3400231 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 감소한다</color>. 모든 적에게 <color=#FFFF00>250%</color>의 피해를 입히며, 본 진화 스킬은 장비 스킬의 공포 효과를 발동시키지 않는다.",
  str_skill_desc_3430231 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 감소한다</color>. 모든 적에게 <color=#FFFF00>250%</color>의 피해를 입히며, 본 진화 스킬은 장비 스킬의 공포 효과를 발동시키지 않는다.",
  str_skill_desc_3400232 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 증가한다</color>. 모든 적에게 <color=#FFFF00>1턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 추가</color>하고 <color=#FFFF00>550%</color>의 피해를 입힌다.",
  str_skill_desc_3430232 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 증가한다</color>. 모든 적에게 <color=#FFFF00>1턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 추가</color>하고 <color=#FFFF00>550%</color>의 피해를 입힌다.",
  str_skill_passive_desc_440023 = "연쇄 스킬 시전 시 전율의 인장을 1개 획득한다(최대 <color=#00F6FF>5</color>개). 인장 개수마다 액티브 스킬 피해가 <color=#00F6FF>20%</color> 증가하며, 액티브 스킬 사용 시 인장 개수와 동일한 수의 적을 <color=#00F6FF>1</color>턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태에 빠트리며, <color=#00F6FF>인장은 초기화되지 않는다</color>. 연쇄 스킬을 시전하기 전 이미 5개의 인장을 지니고 있을 경우, 이번 연쇄 스킬이 추가로 가장 가까운 적 1명에게 피해를 입히며, 코놀리가 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태의 적에게 입히는 최종 피해가 15% 증가한다.",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 감소한다</color>. 모든 적에게 <color=#FFFF00>250%</color>의 피해를 입히며, 본 진화 스킬은 장비 스킬의 공포 효과를 발동시키지 않는다.",
  str_skill_upgrade_refine_desc_16002312 = "장비 스킬 강화: 코놀리가 공포에 빠진 적에게 입히는 <color=#00F6FF>최종 피해가 15% 증가</color>한다.",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 2 증가한다</color>. 모든 적에게 <color=#FFFF00>1턴간 <link=\"10003\"><#FFAE07><u>공포</u></color></link> 상태를 추가</color>하고 <color=#FFFF00>550%</color>의 피해를 입힌다.",
  str_skill_name_290520101 = "흉폭한 습격",
  str_skill_desc_290520101 = "오로리안을 향해 이동해 대량의 피해를 입힌 후 대상과 멀리 떨어진 위치로 이동한다.",
  str_skill_name_290520102 = "흉폭한 습격",
  str_skill_desc_290520102 = "이동 후 범위 내의 오로리안에게 피해를 입힌다.",
  str_skill_name_200250101 = "행진-사격",
  str_skill_desc_200250101 = "범위 내 대상에게 원거리 공격을 1회 가한다.",
  str_skill_name_200250102 = "돌진-단검",
  str_skill_desc_200250102 = "범위 내 대상에게 근접 공격을 1회 가한다.",
  str_skill_name_290500122 = "거미알",
  str_skill_desc_290500122 = "거미 여왕이 낳은 거미알은 단시간에 새끼로 부화할 수 있다.",
  str_skill_name_3400901 = "달콤한 키스-진화Ⅰ",
  str_skill_name_3420901 = "달콤한 키스-진화Ⅰ",
  str_skill_name_3400902 = "달콤한 키스-진화Ⅱ",
  str_skill_name_3420902 = "달콤한 키스-진화Ⅱ",
  str_skill_desc_3400901 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 적에게 <color=#FFFF00>{1}%</color>의 피해를 입히고 <color=#FFFF00>스턴시킨다</color>.",
  str_skill_desc_3420901 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 적에게 <color=#FFFF00>{1}%</color>의 피해를 입히고 <color=#FFFF00>스턴시킨다</color>.",
  str_skill_desc_3400902 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 모든 적에게 <color=#FFFF00>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3420902 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 모든 적에게 <color=#FFFF00>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_440090 = "바바라가 불 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>10%</color> 증가하며, 적의 발밑에 불 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다. 파티 내 다른 불 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_upgrade_refine_desc_15009011 = "장비 스킬 강화: 적의 발밑에 불 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 적에게 <color=#FFFF00>600%</color>의 피해를 입히고 <color=#FFFF00>스턴시킨다</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 모든 적에게 <color=#FFFF00>450%</color>의 피해를 입힌다.",
  str_skill_name_5000961 = "연결",
  str_skill_desc_5000961 = "오로리안이 스파이크의 2서클 범위 내 진입 시 자동으로 연결하며, 오로리안이 스파이크의 4서클 범위를 벗어나면 연결이 끊어진다. 연결 중 스파이크는 플레이어가 받는 피해의 50%를 분담한다.",
  str_skill_desc_4001531 = "스킬 시전 시 3서클 내의 적을 1칸 넉백시키고, 대상의 발밑을 번개 속성 칸으로 전환한다.",
  str_skill_desc_4001751 = "스킬 시전 후 플레이어가 이번 턴에 피해를 1회 입을 때마다 리더와 동일한 속성의 칸 1개를 갱신하며, 파티의 HP를 소량 회복시킨다.",
  str_skill_name_2001921 = "전방위 돌진",
  str_skill_name_2001922 = "전방위 돌진",
  str_skill_name_2001923 = "전방위 돌진",
  str_skill_name_3001920 = "도약 진격",
  str_skill_name_3301920 = "도약 진격",
  str_skill_name_3301921 = "도약 진격",
  str_skill_name_3301922 = "도약 진격",
  str_skill_name_3301923 = "도약 진격",
  str_skill_name_3401921 = "가시 인장의 창",
  str_skill_desc_2001921 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001922 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001923 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3001920 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입힌다.",
  str_skill_desc_34019200 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입히고, 피해 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>2</color>개를 생성한다.\n현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_34019201 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입히고, 피해 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>2</color>개를 생성한다.\n현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_34019202 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입히고, 피해 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>2</color>개를 생성한다.\n현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_34019203 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입히고, 피해 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>2</color>개를 생성한다.\n현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_3301920 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입힌다.현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_3301921 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입힌다.현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_3301922 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입힌다.현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_3301923 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 공격력의 <color=#00F6FF>270%</color>에 해당하는 피해를 입힌다.현재 <color=#00F6FF>가시 인장</color> 수량에 따라 스킬 효과 강화:\n<color=#00F6FF>10</color>개 이상: 피해 범위가 정방형 25칸으로 확장됨\n<color=#00F6FF>20</color>개 이상: 스킬 쿨다운 턴 수 1 감소\n<color=#00F6FF>30</color>개 이상: 해당 스킬 발동 시 모든 적에게 270%의 피해를 입힘",
  str_skill_desc_3401921 = "가시 인장을 <color=#00F6FF>5</color>개 소모해 이번 턴에 일반공격이 사선 방향의 적을 공격하며, 일반공격 피해가 <color=#00F6FF>20%</color> 증가한다(중복 시전 시 중첩 가능). 본 스킬 시전 시 액티브 스킬 시전으로 간주되지 않는다.",
  str_skill_passive_name_410192 = "가시의 인장",
  str_skill_passive_name_416192 = "가시의 인장",
  str_skill_passive_name_430192 = "가시의 인장",
  str_skill_passive_name_436192 = "가시의 인장",
  str_skill_passive_desc_410192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_416192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가한다. 웨이브가 시작될 때마다 가시 인장을 <color=#00F6FF>5</color>개 획득한다.",
  str_skill_passive_desc_430192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_436192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가한다. 웨이브가 시작될 때마다 가시 인장을 <color=#00F6FF>5</color>개 획득한다.",
  str_skill_passive_desc_440192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_446192 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>3%</color> 증가한다. 웨이브가 시작될 때마다 가시 인장을 <color=#00F6FF>5</color>개 획득한다.",
  str_skill_upgrade_refine_desc_16019211 = "장비 스킬 강화: 가시 인장 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16019212 = "장비 스킬 강화: 전투 시작 시 가시 인장 <color=#00F6FF>5</color>개를 획득한다.",
  str_skill_upgrade_refine_desc_16019213 = "액티브 스킬 강화: 피해 범위 내에 랜덤으로 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> <color=#00F6FF>2</color>개를 생성한다.",
  str_skill_passive_desc_440193 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>3%</color> 증가한다. 전투 시작 시 가시 인장을 <color=#00F6FF>5</color>개 획득한다.",
  str_skill_passive_desc_446193 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link> 1개를 획득할 때마다(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함) <color=#00F6FF>가시 인장</color> 1개를 획득하며, 1개마다 연쇄 스킬 피해율이 <color=#00F6FF>3%</color> 증가한다. 전투 시작 시 및 웨이브가 시작될 때마다 가시 인장을 <color=#00F6FF>5</color>개 획득한다.",
  str_skill_upgrade_desc_16019213 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16019216 = "장비 스킬 강화: 웨이브가 시작될 때마다 추가로 가시 인장 <color=#00F6FF>5</color>개를 획득한다.",
  str_skill_name_5010152 = "격려",
  str_skill_desc_5010152 = "다크 워커가 아군 대상이 가장 많은 구역으로 이동해 전체 범위의 아군 대상에게 강세의 인장을 부여한다. 인장을 지닌 대상은 공격력이 증가한다.",
  str_skill_name_888450061 = "섀도 블리츠",
  str_skill_desc_888450061 = "그레이홀트 1마리를 소환하며, 2턴이 지날 때마다 그레이홀트가 오로리안을 공격한다.",
  str_skill_desc_888450081 = "실러가 자신 및 주변 1서클 내 동일 속성 칸 에너지를 흡수한 후, 모든 적에게 에너지볼 공격을 시전한다. 흡수한 칸수가 많을수록 피해가 증가한다. 오로리안 명중 시 다시 2턴이 지난 후 오로리안이 있는 위치에 위험 구역이 생성된다.",
  str_skill_upgrade_refine_desc_13004611 = "장비 스킬 강화: 조소의 인장 1개마다 키팅의 일반공격 피해에 주는 보너스가 <color=#00F6FF>2배</color> 증가한다.",
  str_skill_upgrade_refine_desc_13004613 = "장비 스킬 강화: 키팅이 일반공격을 할 때마다 <color=#00F6FF>35%</color> 확률로 적에게 조소의 인장을 1개 추가한다.",
  str_skill_passive_desc_4400461 = "조소의 인장을 지닌 적 처치 시 모든 적의 인장 개수가 <color=#00F6FF>1</color> 증가한다. 인장 개수마다 번개 속성 오로리안의 일반공격 피해가 <color=#00F6FF>1.8%</color> 증가하며, 키팅 자신은 <color=#00F6FF>2배</color>의 보너스를 받는다.",
  str_skill_desc_340046 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. 1칸을 선택해 분신을 배치, 분신은 <color=#00F6FF>주변 3서클</color> 내의 적을 끌어당기며, 인장 5개를 지닌 적에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다. 2턴간 지속.",
  str_skill_desc_342046 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. 1칸을 선택해 분신을 배치, 분신은 <color=#00F6FF>주변 3서클</color> 내의 적을 끌어당기고 인장 4개를 지닌 적에게 2턴간 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여하며, 6개를 지닌 적에게 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다.",
  str_skill_desc_345046 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. 1칸을 선택해 분신을 배치, 적 <color=#00F6FF>전체</color>를 끌어당기고 인장 4개를 지닌 적에게 2턴간 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여하며, 6개를 지닌 적에게 <color=#00F6FF>1</color>턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다.",
  str_skill_passive_desc_4400463 = "조소의 인장을 지닌 적 처치 시 모든 적의 인장 개수가 <color=#00F6FF>1</color> 증가한다. 인장 개수마다 번개 속성 오로리안의 일반공격 피해가 <color=#00F6FF>2%</color> 증가하며, 키팅 자신은 <color=#00F6FF>2배</color>의 보너스를 받는다. 키팅이 일반공격을 할 때마다 <color=#00F6FF>35%</color> 확률로 적에게 조소의 인장을 1개 추가한다.",
  str_skill_upgrade_refine_desc_16006011 = "장비 스킬 강화: 정오 상태에서 일반공격의 스플래시 피해가 <color=#00F6FF>60%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16006012 = "장비 스킬 강화: 정오 상태에서 일반공격 피해가 추가로 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16006013 = "연쇄 스킬 강화: 정오 상태에서 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_passive_desc_4400601 = "정오 상태에서 일반공격 피해가 <color=#00F6FF>20%</color> 증가하며, 동시에 일반공격이 적 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>60%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_passive_desc_4400602 = "정오 상태에서 일반공격 피해가 <color=#00F6FF>25%</color> 증가하며, 동시에 일반공격이 적 주변 <color=#00F6FF>십자형 4칸</color> 범위 내의 대상에게 <color=#00F6FF>60%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_243601 = "<color=#00F6FF>주변 2서클</color> 내의 적 4명에게 <color=#00F6FF>155%</color>의 피해를 입히고, 정오 상태에서는 범위가 1서클 확대된다.",
  str_skill_desc_243602 = "<color=#00F6FF>주변 3서클</color> 내의 적 4명에게 <color=#00F6FF>160%</color>의 피해를 입히고, 정오 상태에서는 범위가 1서클 확대된다.",
  str_skill_desc_243603 = "<color=#00F6FF>주변 4서클</color> 내의 적 4명에게 <color=#00F6FF>175%</color>의 피해를 입히고, 정오 상태에서는 범위가 1서클 확대된다.",
  str_skill_name_2002001 = "엄호 사격",
