  str_skill_desc_2102002 = "<color=#00F6FF>주변 4서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2102003 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300200 = "최대 2명의 적을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸 및 경로상의 모든 칸에 있는 적을 해당 구역의 중심 위치로 <link=\"30081\"><#FFAE07><u>끌어당긴다</u></color></link>. 적을 1명만 선택한 경우 해당 적은 피해만 입으며, 위치는 바뀌지 않는다.",
  str_skill_desc_305200 = "최대 2명의 적을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸 및 경로상의 모든 칸에 있는 적을 해당 구역의 중심 위치에 <link=\"30081\"><#FFAE07><u>끌어당긴다</u></color></link>. 적이 <color=#00F6FF>1</color>칸 끌어당겨질 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다. 적을 1명만 선택한 경우 해당 적은 피해만 입으며, 위치는 바뀌지 않는다.",
  str_skill_desc_320200 = "최대 2명의 적을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸 및 경로상의 모든 칸에 있는 적을 해당 구역의 중심 위치로 <link=\"30081\"><#FFAE07><u>끌어당긴다</u></color></link>. 적을 1명만 선택한 경우 아나톨리 자신을 나머지 1개 대상으로 판정해 중심 위치로 끌어당긴다.",
  str_skill_desc_325200 = "최대 2명의 적을 선택해 <color=#00F6FF>{1}%</color>의 피해를 입히고, 선택한 칸 및 경로상의 모든 칸에 있는 적을 해당 구역의 중심 위치에 <link=\"30081\"><#FFAE07><u>끌어당긴다</u></color></link>. 적이 <color=#00F6FF>1</color>칸 끌어당겨질 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다. 적을 1명만 선택한 경우 아나톨리 자신을 나머지 1개 대상으로 판정해 중심 위치로 끌어당긴다.",
  str_skill_passive_desc_410200 = "아나톨리의 연쇄 스킬이 랜덤으로 대상과 인접한 적에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430200 = "아나톨리의 연쇄 스킬이 랜덤으로 대상과 인접한 적에게 추가로 <color=#00F6FF>{1}</color>의 피해를 입히며, 파티의 모든 <color=#00F6FF>타깃형</color> 연쇄 스킬이 <link=\"30082\"><#FFAE07><u>밀집</u></color></link>한 적에게 입히는 최종 피해가 <color=#00F6FF>7%</color> 증가한다.",
  str_skill_upgrade_desc_15020012 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15020015 = "액티브 스킬 강화: 적이 <color=#00F6FF>1</color>칸 끌어당겨질 때마다 최종 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_name_290530101 = "공포의 인장",
  str_skill_desc_290530101 = "대상에게 직접 피해를 입히고, 대상이 위치한 칸에 인장을 생성한다.",
  str_skill_name_290530102 = "공포의 돌진",
  str_skill_desc_290530102 = "대상의 방향으로 최대 2칸 돌진해 경로 및 도착 위치 주변 십자형 4칸 범위 내의 대상에게 피해를 입힌다. 공포의 돌진이 대상에게 명중하지 않을 경우 헬리오스가 추가로 공포의 인장을 시전한다.",
  str_skill_desc_290530312 = "대상의 방향으로 최대 2칸 돌진해 경로 및 도착 위치 주변 십자형 4칸 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_290530103 = "공포의 도약",
  str_skill_desc_290530103 = "대상이 스킬 범위 내에 있을 시 헬리오스가 대상의 근처로 도약해 대상에게 대량의 피해를 입히고 넉백시킨다. 공포의 도약이 대상에게 명중하지 않거나 대상이 공포의 도약의 스킬 범위 내에 있지 않을 경우 헬리오스가 추가로 공포의 인장을 시전한다.",
  str_skill_name_290530104 = "공포의 습격",
  str_skill_desc_290530104 = "헬리오스가 공포의 인장 생성 순서에 따라 인장 위치로 돌진하며, 대상 주변으로 돌진해 경로 및 도착 위치 일정 범위 내의 대상에게 대량의 피해를 입힌다. 그와 동시에 헬리오스가 적혈 수치의 일부를 HP로 전환한다.",
  str_skill_name_215009011 = "일반공격",
  str_skill_desc_215009011 = "이동 후 범위 내 대상을 1회 공격한다.",
  str_skill_name_11150713 = "위험한 샘물",
  str_skill_desc_11150713 = "위험 구역으로 돌아와 일부 HP를 회복하며, 자신을 영구적으로 강화한다.",
  str_skill_name_290530302 = "공포의 돌진",
  str_skill_desc_290530302 = "대상의 방향으로 최대 2칸 돌진해 경로 및 도착 위치 주변 십자형 4칸 범위 내의 대상에게 피해를 입힌다.",
  str_skill_desc_11150313 = "신비한 빛의 수정. 해당 칸을 지나갈 때 효과를 발동시킬 수 있다. 발동 시 번개를 소환해 오로리안을 포함한 모든 대상을 공격한다.",
  str_skill_name_290500102 = "포식",
  str_skill_name_290500112 = "포식-산란",
  str_skill_name_290500103 = "수렵",
  str_skill_name_290500113 = "수렵+",
  str_skill_name_290500104 = "군체 소집",
  str_skill_name_290500114 = "군체 소집+",
  str_skill_desc_290500102 = "거미 여왕이 사냥감을 향해 달려들어 거미줄로 칸을 잠그고 오로리안에게 피해를 입힌다.",
  str_skill_desc_290500112 = "거미 여왕이 사냥감을 향해 달려들어 거미줄로 칸을 잠그고 오로리안에게 피해를 입히며, 필드에 거미 알을 소환한다.",
  str_skill_desc_290500103 = "거미 여왕이 거미줄로 오로리안 주변의 칸을 잠그고 새끼 거미를 소집해 오로리안에게 달려들어 피해를 입힌다.",
  str_skill_desc_290500113 = "거미 여왕이 거미줄로 오로리안 주변의 칸을 잠그고 새끼 거미를 소집해 오로리안에게 달려들어 피해를 입힌다. 잠긴 칸은 1턴 후 기존 상태를 회복한다.",
  str_skill_desc_290500104 = "거미 여왕이 새끼 거미를 소집해 공격하며, 새끼 거미가 거미줄로 대량의 칸을 잠근다.",
  str_skill_desc_290500114 = "거미 여왕이 새끼 거미를 소집해 공격하며, 새끼 거미가 거미줄로 대량의 칸을 잠근다. 잠긴 칸은 1턴 후 기존 상태를 회복한다.",
  str_skill_name_200240102 = "순찰",
  str_skill_name_200240103 = "포식",
  str_skill_name_200240104 = "군체 소집",
  str_skill_desc_200240102 = "새끼 거미는 거미줄 영역 내를 순찰하며, 적을 발견하면 즉시 공격한다.",
  str_skill_desc_200240103 = "새끼 거미가 사냥감을 향해 몸을 날려 공격한다.",
  str_skill_desc_200240104 = "새끼 거미가 거미 여왕의 소집에 응해 무리를 지어 공격한다.",
  str_skill_name_290530204 = "공포의 습격",
  str_skill_desc_290530204 = "헬리오스가 공포의 인장 생성 순서에 따라 인장 위치로 돌진하며, 대상 주변으로 돌진해 경로 및 도착 위치 일정 범위 내의 대상에게 대량의 피해를 입힌다. 그와 동시에 헬리오스가 필드 내 공포의 인장을 제거하고, 제거된 공포의 인장의 수량에 따라 적혈 수치의 일부를 HP로 전환한다.",
  str_skill_name_290530404 = "공포의 습격",
  str_skill_desc_290530404 = "헬리오스가 공포의 인장 생성 순서에 따라 인장 위치로 돌진하며, 대상 주변으로 돌진해 경로 및 도착 위치 일정 범위 내의 대상에게 대량의 피해를 입힌다. 그와 동시에 헬리오스가 적혈 수치의 일부를 HP로 전환한다.",
  str_skill_upgrade_desc_16020113 = "액티브 스킬 강화: <color=#FFFF00>「지난날의 부름」</color> 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16020116 = "액티브 스킬 강화: <color=#FFFF00>「바바 야가 탄생」</color> 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_upgrade_refine_desc_16020111 = "장비 스킬 강화: 실드 보유 시 피해 기본 보너스가 <color=#FFFF00>15%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16020112 = "액티브 스킬 강화: <color=#FFFF00>「지난날의 부름」</color>으로 획득하는 실드 수치가 자신의 HP의 <color=#FFFF00>90%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16020113 = "장비 스킬 강화: HP가 최저 수치까지 도달했을 때 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득한다.",
  str_skill_name_2002011 = "무정의 불길",
  str_skill_name_2002012 = "무정의 불길",
  str_skill_name_2002013 = "무정의 불길",
  str_skill_desc_2002011 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002012 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002013 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_name_410201 = "베로니카의 손길",
  str_skill_passive_desc_410201 = "실드 보유 시 미아 더 러스트러스 소울이 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가하며, 실드 수치에 따라 추가 피해 보너스를 획득한다. 실드 수치가 파티 최대 HP의 50%에 도달 시 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득한다.",
  str_skill_passive_name_420201 = "베로니카의 손길",
  str_skill_passive_desc_420201 = "실드 보유 시 미아 더 러스트러스 소울이 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가하며, 실드 수치 및 현재 HP 퍼센트에 따라 추가 피해 보너스를 획득한다. 실드 수치가 파티 최대 HP의 50%에 도달 시 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득하며, 현재 HP가 최저 수치까지 도달했을 때 최대인 <color=#00F6FF>5%</color>의 피해 보너스를 획득한다.",
  str_skill_passive_desc_4202011 = "실드 보유 시 미아 더 러스트러스 소울이 입히는 모든 피해가 <color=#00F6FF>15%</color> 증가하며, 실드 수치 및 현재 HP 퍼센트에 따라 추가 피해 보너스를 획득한다. 실드 수치가 파티 최대 HP의 50%에 도달 시 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득하며, 현재 HP가 최저 수치까지 도달했을 때 최대인 <color=#00F6FF>5%</color>의 피해 보너스를 획득한다.",
  str_skill_passive_desc_4432011 = "실드 보유 시 미아 더 러스트러스 소울이 입히는 모든 피해가 <color=#00F6FF>15%</color> 증가하며, 실드 수치 및 현재 HP 퍼센트에 따라 추가 피해 보너스를 획득한다. 실드 수치가 파티 최대 HP의 50%에 도달 시 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득하며, 현재 HP가 최저 수치까지 도달했을 때 최대인 <color=#00F6FF>10%</color>의 피해 보너스를 획득한다.",
  str_skill_name_300201 = "지난날의 부름",
  str_skill_name_330201 = "바바 야가 탄생",
  str_skill_name_336201 = "바바 야가 탄생",
  str_skill_name_340201 = "바바 야가 탄생",
  str_skill_name_346201 = "바바 야가 탄생",
  str_skill_desc_300201 = "정화 상태에 진입해 기본 공격력이 <color=#00F6FF>15%</color> 증가하고, 일반공격이 사선 방향을 공격할 수 있게 되며, 효과는 1턴간 지속된다. 또한 미아 더 러스트러스 소울의 HP의 <color=#00F6FF>75%</color>에 해당하는 실드를 즉시 획득한다.",
  str_skill_desc_342201 = "정화 상태에 진입해 기본 공격력이 <color=#00F6FF>15%</color> 증가하고, 일반공격이 사선 방향을 공격할 수 있게 되며, 효과는 1턴간 지속된다. 또한 미아 더 러스트러스 소울의 HP의 <color=#00F6FF>90%</color>에 해당하는 실드를 즉시 획득한다.",
  str_skill_desc_330201 = "<color=#00F6FF>파티의 현재 HP의 7%</color>를 소모해 자신의 공격력의 <color=#00F6FF>150%</color>에 해당하는 실드로 전환한다.",
  str_skill_desc_336201 = "<color=#00F6FF>파티의 현재 HP의 7%</color>를 소모해 자신의 공격력의 <color=#00F6FF>150%</color>에 해당하는 실드로 전환한다.",
  str_skill_desc_340201 = "<color=#00F6FF>파티의 현재 HP의 7%</color>를 소모해 자신의 공격력의 <color=#00F6FF>150%</color>에 해당하는 실드로 전환한다.",
