  str_skill_desc_3022031 = "파티의 최대 HP의 <color=#00F6FF>15%</color>를 소모해 이번 연결의 첫 번째 칸을 <color=#00F6FF>불 속성 칸</color>으로 간주하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3052031 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 이번 연결의 첫 번째 칸을 <color=#00F6FF>불 속성 칸</color>으로 간주하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3202031 = "파티의 최대 HP의 <color=#00F6FF>15%</color>를 소모해 이번 연결의 첫 번째 칸을 <color=#00F6FF>만색 칸</color>으로 간주하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3222031 = "파티의 최대 HP의 <color=#00F6FF>15%</color>를 소모해 이번 연결의 첫 번째 칸을 <color=#00F6FF>만색 칸</color>으로 간주하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3252031 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 이번 연결의 첫 번째 칸을 <color=#00F6FF>만색 칸</color>으로 간주하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_passive_name_410203 = "날 가려줘!",
  str_skill_passive_name_430203 = "날 가려줘!",
  str_skill_passive_desc_410203 = "파티가 <color=#00F6FF>오로리안 액티브 스킬의 영향으로 HP를 잃을 때마다</color> 쟈키니의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 획득한다.",
  str_skill_passive_desc_430203 = "파티가 <color=#00F6FF>오로리안 액티브 스킬의 영향으로 HP를 잃을 때마다</color> 쟈키니의 기본 공격력의 <color=#00F6FF>{1}</color>에 해당하는 실드를 획득한다. 쟈키니가 본 효과를 발동시킬 경우 실드 수치가 <color=#00F6FF>2배</color>로 증가한다.",
  str_skill_name_2002021 = "지배의 광휘",
  str_skill_name_2002022 = "지배의 광휘",
  str_skill_name_2002023 = "지배의 광휘",
