  str_skill_name_3402021 = "영원한 태양",
  str_skill_name_3432021 = "영원한 태양",
  str_skill_name_3402023 = "영원한 태양",
  str_skill_name_3432023 = "영원한 태양",
  str_skill_name_3302022 = "어둠을 깨는 일격",
  str_skill_name_3362022 = "어둠을 깨는 일격",
  str_skill_desc_2002021 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002022 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002023 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 가장 먼 범위 내 이동 가능한 랜덤 1칸에 멸각의 칼날 1개를 소환한다. 해당 효과는 턴마다 최대 1회만 발동한다.",
  str_skill_desc_3002021 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>3</color> 감소한다. 자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color>의 피해를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3032021 = "자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color>의 피해를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3202021 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>3</color> 감소한다. 자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3232021 = "자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3402021 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>3</color> 감소한다. 자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3432021 = "자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>500%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3402022 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>3</color> 감소한다. 자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>650%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3432022 = "자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>650%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3402023 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>3</color> 감소한다. 자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>650%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 적 처치 시 해당 위치에 다시 멸각의 칼날을 1개 소환하며, 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3432023 = "자신의 <color=#00F6FF>주변 3서클</color> 내 적 1명이 밟고 있는 칸을 선택해 <color=#00F6FF>650%</color> 및 대상의 <color=#00F6FF>최대 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 추가 피해(추가 피해는 속성 상성의 영향을 받음)를 입히고, 선택한 위치 주변 2서클 내 이동 가능한 랜덤 <color=#00F6FF>3</color>칸에 멸각의 칼날 1개를 소환한다. 적 처치 시 해당 위치에 다시 멸각의 칼날을 1개 소환하며, 멸각의 칼날 1개를 획득/회수할 때마다 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_3302022 = "멸각의 칼날 <color=#00F6FF>1</color>개를 선택해 회수한다.",
  str_skill_desc_3362022 = "멸각의 칼날 <color=#00F6FF>1</color>개를 선택해 회수한다.",
  str_skill_passive_name_410202 = "빛의 길",
  str_skill_passive_name_420202 = "빛의 길",
  str_skill_passive_name_430202 = "빛의 길",
  str_skill_passive_desc_410202 = "멸각의 칼날 1개를 획득할 때마다 서광의 힘을 1단계 획득하며, 다음 일반공격이 서광의 힘을 1단계 소모해 대상에게 추가로 <color=#00F6FF>현재 HP</color>의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다(기본 공격력의 <color=#00F6FF>{2}</color> 이상, <color=#00F6FF>{3}</color> 이하).",
  str_skill_passive_desc_420202 = "멸각의 칼날 1개를 획득할 때마다 서광의 힘을 1단계 획득하며, 다음 일반공격이 서광의 힘을 1단계 소모해 대상에게 추가로 <color=#00F6FF>현재 HP</color>의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다(기본 공격력의 <color=#00F6FF>{2}</color> 이상, <color=#00F6FF>{3}</color> 이하).",
  str_skill_passive_desc_430202 = "멸각의 칼날 1개를 획득/회수할 때마다 서광의 힘을 1단계 획득하며, 다음 일반공격이 서광의 힘을 1단계 소모해 대상에게 추가로 <color=#00F6FF>현재 HP</color>의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다(기본 공격력의 <color=#00F6FF>{2}</color> 이상, <color=#00F6FF>{3}</color> 이하).",
  str_skill_passive_desc_440202 = "멸각의 칼날 1개를 획득/회수할 때마다 서광의 힘을 1단계 획득하며, 다음 일반공격이 서광의 힘을 1단계 소모해 대상에게 추가로 <color=#00F6FF>현재 HP</color>의 <color=#00F6FF>4%</color>에 해당하는 피해를 입힌다(기본 공격력의 <color=#00F6FF>150%</color> 이상, <color=#00F6FF>600%</color> 이하).",
  str_skill_upgrade_desc_16020213 = "액티브 스킬 강화: <color=#FFFF00>「영원한 태양」</color> 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16020216 = "액티브 스킬 강화: <color=#FFFF00>「어둠을 깨는 일격」</color> 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다(각성 3단계 달성 시 적용).",
  str_skill_upgrade_refine_desc_16020211 = "장비 스킬 강화: 추가 피해 한도가 자신의 기본 공격력의 <color=#00F6FF>600%</color> 이하로 증가한다.",
  str_skill_upgrade_refine_desc_16020212 = "액티브 스킬 강화: 피해가 <color=#00F6FF>650%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16020213 = "액티브 스킬 강화: 적 처치 시 해당 위치에 추가로 멸각의 칼날을 1개 소환한다.",
  str_skill_upgrade_refine_desc_15007811 = "장비 스킬 강화: 적의 발밑에 숲 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15007812 = "액티브 스킬 강화: 범위 중앙 칸에 2배의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_15007813 = "액티브 스킬 강화: 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_passive_desc_4400781 = "로빈이 숲 속성 칸에 위치한 적에게 입히는 피해가 <color=#00F6FF>10%</color> 증가하며, 적의 발밑에 숲 속성 칸이 1개 있을 때마다 피해 보너스가 <color=#00F6FF>1%</color> 증가한다. 파티 내 다른 숲 속성 오로리안이 <color=#00F6FF>절반</color>의 효과를 획득한다.",
  str_skill_name_3400782 = "브레스",
  str_skill_name_3420782 = "브레스",
  str_skill_name_3400783 = "브레스",
  str_skill_name_3420783 = "브레스",
  str_skill_desc_3400782 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입힌다.",
  str_skill_desc_3420782 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입히며, 적의 위치 중 최대 1칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다.",
  str_skill_desc_3400783 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_desc_3420783 = "1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>250%</color>의 피해를 입히고, 중앙 칸에 2배의 피해를 입히며, 적의 위치 중 최대 1칸을 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환한다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 선택 범위가 <color=#00F6FF>주변 2서클</color>로 변경된다.",
  str_skill_upgrade_refine_desc_15007511 = "장비 스킬 강화: 일반공격이 중독 상태를 추가할 확률이 <color=#00F6FF>80%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15007512 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>500%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15007513 = "액티브 스킬 강화: 전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다.",
  str_skill_name_340075 = "오토 인탱글 파워",
  str_skill_name_342075 = "오토 인탱글 파워",
  str_skill_name_345075 = "오토 인탱글 파워",
  str_skill_desc_340075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_342075 = "<color=#00F6FF>주변 3서클</color> 내의 적에게 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_345075 = "적 <color=#00F6FF>전체</color>에 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_350075 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. <color=#00F6FF>주변 3서클</color> 내의 적에게 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_352075 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. <color=#00F6FF>주변 3서클</color> 내의 적에게 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_desc_355075 = "전투 시작 시 스킬 쿨다운 턴 수가 <color=#00F6FF>2</color> 감소한다. 적 <color=#00F6FF>전체</color>에 500%의 피해를 입히고 대상에게 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여, 2턴간 지속되며, 추가로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 2회 부여한다. 2턴간 지속.",
  str_skill_passive_desc_440075 = "일반공격이 <color=#00F6FF>사선 방향의 적을 공격</color>할 수 있으며, <color=#00F6FF>80%</color> 확률로 <link=\"10001\"><#FFAE07><u>중독</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_5220014 = "이동 가능한 칸 <color=#00F6FF>2</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_desc_5220015 = "이동 가능한 칸 <color=#00F6FF>3</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_desc_5220016 = "이동 가능한 칸 <color=#00F6FF>4</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_desc_5220017 = "이동 가능한 칸 <color=#00F6FF>5</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_desc_5220018 = "이동 가능한 칸 <color=#00F6FF>6</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_desc_5220019 = "이동 가능한 칸 <color=#00F6FF>7</color>개를 선택해 <color=#00F6FF>만색 칸</color>으로 전환한다.",
  str_skill_name_290540101 = "파괴의 손길",
  str_skill_desc_290540101 = "오로리안을 향해 이동 후 전방 2칸 범위 내의 대상에게 대량의 피해를 입힌다.",
  str_skill_name_290540102 = "소멸의 창",
  str_skill_desc_290540102 = "오로리안을 향해 이동한 후 창을 휘둘러 전방 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_290540103 = "붕괴",
  str_skill_desc_290540103 = "환영의 수정의 속성에 따라 해당 속성 칸의 에너지를 흡수하고 칸 속성을 초기화하며, 이후 전체화면 범위 내의 대상을 공격한다. 흡수한 에너지가 많을수록 피해가 증가한다.",
  str_skill_name_290540202 = "파괴의 손길",
  str_skill_name_290540203 = "저주의 파멸",
  str_skill_name_290540204 = "저주의 외침",
  str_skill_desc_290540202 = "오로리안을 향해 이동 후 전방 2칸 범위 내의 대상에게 대량의 피해를 입힌다.",
  str_skill_desc_290540203 = "오로리안을 향해 이동한 후 창을 휘둘러 전방 범위 내의 대상에게 저주를 시전한다. 저주 수치가 대상의 현재 HP를 초과할 시 대량의 피해를 입힌다.",
  str_skill_desc_290540204 = "강력한 일격을 가해 전체화면 범위의 피해를 입히고 저주 수치를 증가시키며, 백야성 경비병 2명을 소환한다.",
  str_skill_desc_290540206 = "강력한 일격을 가해 전체화면 범위의 피해를 입히고 저주 수치를 증가시키며, 백야성 경비병 3명을 소환한다.",
  str_skill_name_200060601 = "어둠의 포옹",
  str_skill_desc_200060601 = "허거가 주변 1서클 내 백야성 경비병에게 빙의해 스턴 상태를 해제하고 힘을 강화시킨다.",
  str_skill_desc_29002111 = "암석으로도 적을 쓰러트리지 못한다면, 아비시어는 필드의 암석을 하나로 합쳐 적을 박살낼 것이다.",
  str_skill_name_29001811 = "치유의 암귀",
  str_skill_name_29001821 = "혼의 치료",
  str_skill_name_29001411 = "불의 악령",
  str_skill_name_29001421 = "화염의 습격",
  str_skill_desc_29001811 = "치유 능력을 가진 섀도고스트 한 마리를 소환한다.",
  str_skill_desc_29001821 = "스예트 사망 시 더 강한 치유 능력을 각성하고, 치유 능력이 있는 섀도고스트 두 마리를 소환한다.",
  str_skill_desc_29001411 = "원거리 공격 능력을 가진 섀도프리크 한 마리를 소환한다.",
  str_skill_desc_29001421 = "한 사람의 불완전함은 나머지 한 사람을 광기에 빠트리고, 파괴의 힘을 이용해 섀도프리크 두 마리를 소환해 어느 위치에서든지 적을 공격한다.",
  str_skill_name_200320101 = "카르티마의 사슬철퇴",
  str_skill_desc_200320101 = "카르티마가 사슬철퇴를 휘둘러 자신의 우측 전방에 범위 피해를 입힌다.",
  str_skill_name_200320102 = "카르티마의 격퇴",
  str_skill_desc_200320102 = "카르티마가 방패로 자신의 좌측 전방의 대상을 넉백시킨다.",
  str_skill_name_200320201 = "분쇄",
  str_skill_desc_200320201 = "사슬철퇴를 휘둘러 자신의 우측 전방에 범위 피해를 입힌다.",
  str_skill_name_200320202 = "격퇴",
  str_skill_desc_200320202 = "방패로 자신의 좌측 전방의 대상을 넉백시킨다.",
  str_skill_desc_290480122 = "공격 범위 내 대상에게 화염을 뿜어 피해를 입힌다.",
  str_skill_desc_3000331 = "랜덤으로 필드 내의 불 속성 칸 8개를 제거한다.",
  str_skill_desc_3000411 = "1칸을 선택해 해당 위치 기준 십자형 5칸을 물 속성 칸으로 전환한다.",
  str_skill_desc_3000061 = "1칸을 선택해 해당 위치 기준 세로 1열을 물 속성 칸으로 전환한다.",
  str_skill_desc_3000961 = "랜덤으로 필드 내의 불 또는 숲 속성 칸 8개를 물 속성으로 전환한다.",
  str_skill_desc_3000111 = "1칸을 선택해 해당 위치 주변 2서클 내의 불 및 숲 속성 칸을 제거한다.",
  str_skill_desc_3000731 = "1칸을 선택해 해당 위치 마름모 13칸 내의 숲 속성 칸을 제거한다.",
  str_skill_desc_3000251 = "5열 또는 5행을 선택해 범위 내의 불 속성이 아닌 칸을 초기화한다.",
  str_skill_desc_3000261 = "불 속성이 아닌 모든 칸을 초기화한다.",
  str_skill_desc_3001031 = "랜덤으로 필드 내의 숲 또는 번개 속성 칸 8개를 불 속성으로 전환한다.",
  str_skill_desc_3000301 = "1개 방향을 선택해 해당 방향 부채꼴 범위 내의 숲 및 번개 속성 칸을 제거한다.",
  str_skill_desc_3000161 = "1칸을 선택해 해당 선택 방향의 번개 속성이 아닌 모든 칸을 제거한다.",
  str_skill_desc_3000321 = "랜덤으로 필드 내의 물 속성 칸 8개를 선택해 제거하나, 일정 확률로 제거에 실패한다.",
  str_skill_desc_3000381 = "랜덤으로 필드 내의 물 또는 불 속성 칸 8개를 번개 속성으로 전환한다.",
  str_skill_desc_3000051 = "모든 물 속성 칸을 제거한다.",
  str_skill_desc_3000541 = "3턴간 유지되는 등잔 1개를 배치하며, 등잔이 유지되는 동안 해당 칸은 번개 속성으로 고정된다.",
  str_skill_desc_3000931 = "주변 2서클 내의 1칸을 선택해 해당 위치 주변 1서클 내의 번개 속성 칸을 제거한다.",
  str_skill_desc_3000021 = "2칸을 선택해 숲 속성 강화 칸으로 전환한다.",
  str_skill_desc_3000011 = "랜덤으로 필드 내의 번개 또는 물 속성 칸 6개를 숲 속성으로 전환하고, 강화 칸 3개를 생성한다.",
  str_skill_desc_3200821 = "2칸을 선택해 속성을 전환한다. 전환된 칸이 숲 속성일 경우 해당 칸은 강화 칸으로 전환된다.",
  str_skill_desc_3000291 = "물, 불, 번개 속성 칸 중의 1종을 선택해 다른 속성으로 초기화한다(칸의 강화 속성 유지).",
  str_skill_desc_5002331 = "시간의 모래시계가 있는 칸 제거 시 남은 턴 수가 1 증가한다.",
  str_skill_desc_53140511 = "마름모 12칸 범위 내의 적에게 대량의 피해를 입힌다.",
