  str_skill_desc_2202043 = "가장 가까운 두 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 대상이 하나만 있을 경우 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_2302041 = "가장 가까운 두 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_2302042 = "가장 가까운 두 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_2302043 = "가장 가까운 두 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_desc_2502041 = "가장 가까운 두 대상에게 <color=#00F6FF>140%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>65%</color> 증가한다.",
  str_skill_desc_2502042 = "가장 가까운 두 대상에게 <color=#00F6FF>155%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>65%</color> 증가한다.",
  str_skill_desc_2502043 = "가장 가까운 두 대상에게 <color=#00F6FF>170%</color>의 피해를 입히며, 3서클 내의 대상에게 입히는 피해가 <color=#00F6FF>30%</color> 증가한다. 대상이 하나만 있을 경우 피해가 <color=#00F6FF>65%</color> 증가한다.",
  str_skill_desc_3002041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 200%</color>에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>200%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가).",
  str_skill_desc_3032041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 250%</color>에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>250%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가).",
  str_skill_desc_3062041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 250%+대상의 HP 한도의 3%</color>(조슈아의 공격력의 <color=#00F6FF>120%</color> 이상)에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>370%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가).",
  str_skill_passive_desc_4102041 = "조슈아가 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태의 적에게 실드를 무시하는 <color=#00F6FF>{1}</color>의 피해를 입히며, 해당 피해가 전부 심판 수치로 전환된다.",
  str_skill_upgrade_refine_desc_16020411 = "장비 스킬 강화: 심판 상태의 대상에게 입히는 모든 피해가 <color=#00F6FF>124%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16020412 = "연쇄 스킬 강화: 대상이 하나만 있을 경우 피해가 <color=#00F6FF>65%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16020413 = "액티브 스킬 강화: 심판 상태의 대상 사망 시 액티브 스킬 쿨다운을 초기화한다.",
  str_skill_desc_3502041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 200%</color>에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>200%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가). 심판 상태의 대상 사망 시 액티브 스킬 쿨다운을 초기화한다.",
  str_skill_desc_3532041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 250%</color>에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>250%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가). 심판 상태의 대상 사망 시 액티브 스킬 쿨다운을 초기화한다.",
  str_skill_desc_3562041 = "1개 대상을 선택해 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태를 부여하고, <color=#00F6FF>조슈아의 공격력의 250%+대상의 HP 한도의 3%</color>(조슈아의 공격력의 <color=#00F6FF>120%</color> 이상)에 해당하는 심판 수치를 추가한다. HP 한도가 없는 대상에게는 <color=#00F6FF>370%</color>의 방어무시 피해를 입히는 것으로 변경된다. 대상에게 중복 시전 시 심판 수치를 누적하며, 대상의 심판 수치가 현재 HP를 초과할 시 실드를 무시하는 즉사 피해를 입힌다(HP 자물쇠 무시 불가). 심판 상태의 대상 사망 시 액티브 스킬 쿨다운을 초기화한다.",
  str_skill_passive_desc_4502041 = "조슈아가 <link=\"30083\"><#FFAE07><u>심판</u></color></link> 상태의 적에게 실드를 무시하는 <color=#00F6FF>124%</color>의 피해를 입히며, 해당 피해가 전부 심판 수치로 전환된다.",
