  str_skill_name_3002051 = "일소의 무예",
  str_skill_name_3052051 = "일소의 무예",
  str_skill_desc_2002051 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002052 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002053 = "<color=#00F6FF>쌍십자형 24칸</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2202051 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>1</color>턴 감소시킨다.",
  str_skill_desc_2202052 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>2</color>턴 감소시킨다.",
  str_skill_desc_2202053 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>3</color>턴 감소시킨다.",
  str_skill_desc_2262051 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>2</color>턴 감소시킨다.",
  str_skill_desc_2262052 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>3</color>턴 감소시킨다.",
  str_skill_desc_2262053 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>4</color>턴 감소시킨다.",
  str_skill_desc_2302051 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>1</color>턴 감소시킨다.",
  str_skill_desc_2302052 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>2</color>턴 감소시킨다.",
  str_skill_desc_2302053 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>3</color>턴 감소시킨다.",
  str_skill_desc_2362051 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>2</color>턴 감소시킨다.",
  str_skill_desc_2362052 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>3</color>턴 감소시킨다.",
  str_skill_desc_2362053 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 파괴된 칸의 지속 시간을 <color=#00F6FF>4</color>턴 감소시킨다.",
  str_skill_desc_3002051 = "파괴되지 않은 칸 1개를 선택해 해당 위치에 9턴간 존재하는 파괴된 칸을 생성하며, 해당 칸의 <color=#00F6FF>주변 십자형 4칸</color>을 물 속성으로 전환한다.",
  str_skill_desc_3052051 = "파괴되지 않은 칸 1개를 선택해 해당 위치에 9턴간 존재하는 파괴된 칸을 생성하며, 해당 칸의 <color=#00F6FF>주변 십자형 4칸</color>을 물 속성으로 전환한다.",
  str_skill_passive_name_410205 = "안부 인사",
  str_skill_passive_name_430205 = "안부 인사",
  str_skill_passive_desc_410205 = "블랑 더 푸라 코르디스는 물 속성 칸에서 일반공격을 하지 않으며, 물 속성 칸을 지날 때마다 해당 칸의 <color=#00F6FF>주변 십자형 4칸</color>에 적이 있을 시 안부의 인장을 1개 획득한다. 인장 1개당 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가하며, 연쇄 스킬 발동에 필요한 칸 수가 <color=#00F6FF>1</color> 감소한다. 인장은 연쇄 스킬 시전 후 초기화된다.",
  str_skill_passive_desc_430205 = "블랑 더 푸라 코르디스는 물 속성 칸에서 일반공격을 하지 않으며, 물 속성 칸을 지날 때마다 해당 칸의 <color=#00F6FF>주변 십자형 4칸</color>에 적 또는 파괴된 칸이 있을 시 안부의 인장을 1개 획득한다. 인장 1개당 연쇄 스킬 피해율이 <color=#00F6FF>{1}</color> 증가하며, 연쇄 스킬 발동에 필요한 칸 수가 <color=#00F6FF>1</color> 감소한다. 인장은 연쇄 스킬 시전 후 초기화된다.",
  str_skill_upgrade_desc_15020512 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15020515 = "연쇄 스킬 강화: 연쇄 스킬 범위 내 파괴된 칸의 지속 턴 수가 <color=#FFFF00>2/3/4턴</color> 감소한다(각성 2단계 달성 시 적용).",
  str_skill_passive_desc_440097 = "일반공격이 2연타로 변하며, 기본 피해의 <color=#00F6FF>60%</color>만큼 회당 피해를 입힌다. 매회 공격 시 <color=#00F6FF>20%</color> 확률로 피해가 <color=#00F6FF>50%</color> 증가하며, 1회 콤보마다 발동 확률이 추가로 <color=#00F6FF>1%</color> 증가, 최대 50%까지 증가한다.",
  str_skill_name_3400971 = "콜드 슬리트-진화Ⅰ",
  str_skill_name_3400972 = "콜드 슬리트-진화Ⅱ",
  str_skill_name_3420971 = "콜드 슬리트-진화Ⅰ",
  str_skill_name_3420972 = "콜드 슬리트-진화Ⅱ",
  str_skill_desc_3400971 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>600%</color>까지 증가한다.",
  str_skill_desc_3400972 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>주변 3서클</color> 내 선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>360%</color>까지 증가한다.",
  str_skill_desc_3420971 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>.선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>720%</color>까지 증가한다.",
  str_skill_desc_3420972 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>주변 3서클</color> 내 선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 최대 <color=#00F6FF>480%</color>까지 증가한다.",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 액티브 스킬 피해가 <color=#FFFF00>120%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15009712 = "장비 스킬 강화: 1회 콤보마다 피해 증가 발동 확률이 추가로 <color=#00F6FF>1%</color> 증가하며, 최대 50%까지 증가한다.",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#FFFF00>주변 3서클</color> 내 선택한 위치로 순간이동해 시작점과 종점 사이의 사각형 범위 내의 적에게 피해를 입힌다. 사각형 공간이 작을수록 입히는 피해가 증가하며, 액티브 스킬 피해가 <color=#FFFF00>120%</color> 감소한다.",
  str_skill_upgrade_refine_desc_16002711 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>360%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16002712 = "장비 스킬 강화: 액티브 스킬 시전 시 경뢰의 인장 <color=#00F6FF>2</color>개를 획득한다.",
  str_skill_upgrade_refine_desc_16002713 = "장비 스킬 강화: 일반공격 시 경뢰의 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>2.5%</color>에 해당하는 추가 피해를 입힌다(미카엘의 공격력의 <color=#00F6FF>50%</color> 이상).",
  str_skill_desc_3400271 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>360%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입힌다.",
  str_skill_desc_3430271 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>360%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입히며, 이동 거리에 따라 선택 위치에서 연쇄 스킬을 즉시 1회 시전한다.",
  str_skill_desc_3400272 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>360%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입힌다.",
  str_skill_desc_3430272 = "선택한 위치로 돌진해 경로 및 인접 칸의 적에게 <color=#00F6FF>360%</color>의 피해를 입히고, 추가로 적의 현재 HP의 <color=#00F6FF>5%</color>만큼 피해를 입히며, 이동 거리에 따라 선택 위치에서 연쇄 스킬을 즉시 1회 시전한다.",
  str_skill_desc_4400271 = "턴 시작, 연쇄 스킬 시전 시마다 경뢰의 인장을 1개 획득하며, 액티브 스킬 시전 시 2개 획득한다. 일반공격 시 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>2.5%</color>에 해당하는 추가 피해를 입힌다.",
  str_skill_desc_440027 = "턴 시작, 연쇄 스킬 시전 시마다 경뢰의 인장을 1개 획득하며, 액티브 스킬 시전 시 2개 획득한다. 일반공격 시 인장을 1개 소모해 적에게 현재 HP의 <color=#00F6FF>2.5%</color>에 해당하는 추가 피해를 입힌다(미카엘의 공격력의 <color=#00F6FF>50%</color> 이상).",
  str_skill_name_490250101 = "추방-신기루의 세례",
  str_skill_desc_490250101 = "추방-미노스가 주변 2서클 내의 약화 칸과 강화 칸을 흡수하며, 주변 1서클 내의 대상에게 피해를 입힌다. 흡수한 양에 따라 피해가 증가한다.",
  str_skill_name_490250102 = "추방-희생의 종결",
  str_skill_desc_490250102 = "추방-미노스가 필드의 모든 약화 칸과 강화 칸을 흡수하며, 오로리안에게 사격을 가해 피해를 입힌다. 칸을 1개 흡수할 때마다 추가로 1회의 피해를 입힌다.",
  str_skill_name_490250103 = "추방-신기루의 세례+",
  str_skill_desc_490250103 = "추방-미노스가 주변 2서클 내의 약화 칸과 강화 칸을 흡수하며, 주변 1서클 내의 대상에게 피해를 입힌다. 흡수한 양에 따라 피해가 증가한다.",
  str_skill_name_490250104 = "추방-희생의 종결+",
  str_skill_desc_490250104 = "추방-미노스가 필드의 모든 약화 칸과 강화 칸을 흡수하며, 오로리안에게 사격을 가해 피해를 입힌다. 칸을 1개 흡수할 때마다 추가로 1회의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16002811 = "장비 스킬 강화: 회복 계수가 <color=#00F6FF>1.8%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16002812 = "액티브 스킬 강화: 회복 계수가 <color=#00F6FF>250%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16002813 = "액티브 스킬 강화: 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 <color=#00F6FF>100%의 보너스</color>를 제공한다.",
  str_skill_passive_desc_450028 = "지도에 물 속성 칸이 생성될 때마다 칸 1개당 라파엘의 HP 한도의 <color=#00F6FF>1.8%</color>만큼 파티의 HP를 회복시킨다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 <color=#00F6FF>100%의 보너스</color>를 제공한다.",
  str_skill_desc_350028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>250%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화한다.",
  str_skill_desc_356028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>250%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 물 속성 칸을 생성한다.",
  str_skill_desc_360028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>250%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화한다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 <color=#00F6FF>100%의 보너스</color>를 제공한다.",
  str_skill_desc_366028 = "파티의 HP를 라파엘의 공격력의 <color=#00F6FF>250%</color>만큼 회복시키며, <color=#00F6FF>물 속성이 아닌 모든</color> 칸을 초기화해 <color=#00F6FF>낮은 확률</color>로 물 속성 칸을 생성한다. 파티의 HP가 낮을수록 회복 효과가 높으며, 최대 <color=#00F6FF>100%의 보너스</color>를 제공한다.",
  str_skill_upgrade_refine_desc_15007011 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>100%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15007012 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>60%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15007013 = "액티브 스킬 강화: 피해를 입힐 때마다 <color=#00F6FF>25%</color>의 확률로 적에게 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다.",
  str_skill_desc_350070 = "랜덤으로 필드의 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_355070 = "랜덤으로 필드의 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다.",
  str_skill_desc_360070 = "랜덤으로 필드의 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>5</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 1서클</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다. 피해를 입힐 때마다 <color=#00F6FF>25%</color>의 확률로 적에게 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다.",
  str_skill_desc_365070 = "랜덤으로 필드의 적에게 <color=#00F6FF>100%</color>의 피해를 <color=#00F6FF>6</color>회 입히며, 해당 위치의 <color=#00F6FF>주변 12칸</color> 내에 불 속성 칸이 1개 있을 때마다 추가로 1회 공격한다. 피해를 입힐 때마다 <color=#00F6FF>25%</color>의 확률로 적에게 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다.",
  str_skill_passive_desc_450070 = "일반공격 시 <color=#00F6FF>75%</color> 확률로 레드 드래곤의 공격이 1회 발동, 레오나의 일반공격 피해의 <color=#00F6FF>60%</color>만큼 피해를 입히고 <link=\"10002\"><#FFAE07><u>작열</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_400140110 = "오로리안이 이동을 시작하면 텐타클로가 몸을 웅크려 공격을 피하며, 밀렌 고티에의 HP를 회복시킨다.",
  str_skill_upgrade_desc_16020713 = "장비 스킬 강화: 발동에 필요한 잔물결 단계가 5개로 감소하며, 잔물결 단계 소모량도 5의 배수로 감소한다(각성 1단계 달성 시 적용).",
  str_skill_upgrade_desc_16020716 = "액티브 스킬 강화: 선택한 칸을 물 속성으로 전환한다.",
  str_skill_name_2002071 = "환락과 고통",
  str_skill_name_2002072 = "환락과 고통",
  str_skill_name_2002073 = "환락과 고통",
  str_skill_desc_2002071 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002072 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002073 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_3002071 = "꿈 바깥의 군무",
  str_skill_name_3062071 = "꿈 바깥의 군무",
  str_skill_name_3202071 = "꿈 바깥의 군무",
  str_skill_name_3262071 = "꿈 바깥의 군무",
  str_skill_name_3302071 = "꿈 바깥의 군무",
  str_skill_name_3362071 = "꿈 바깥의 군무",
  str_skill_desc_3002071 = "1칸을 선택해 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다.",
  str_skill_desc_3062071 = "1칸을 선택해 해당 칸을 물 속성으로 전환하고, 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다.",
  str_skill_desc_3202071 = "1칸을 선택해 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다. 다시 터치하면 <color=#00F6FF>행/열</color> 범위를 전환할 수 있다.",
  str_skill_desc_3262071 = "1칸을 선택해 해당 칸을 물 속성으로 전환하고, 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다. 다시 터치하면 <color=#00F6FF>행/열</color> 범위를 전환할 수 있다.",
  str_skill_desc_3302071 = "1칸을 선택해 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다. 다시 터치하면 <color=#00F6FF>행/열</color> 범위를 전환할 수 있다. 액티브 스킬 범위 내의 물 속성 칸 1개마다 잔물결 단계를 1 획득한다.",
  str_skill_desc_3362071 = "1칸을 선택해 해당 칸을 물 속성으로 전환하고, 해당 열의 물 속성 칸을 선택한 칸 방향으로 <link=\"30084\"><#FFAE07><u>취합</u></color></link>한다. 다시 터치하면 <color=#00F6FF>행/열</color> 범위를 전환할 수 있다. 액티브 스킬 범위 내의 물 속성 칸 1개마다 잔물결 단계를 1 획득한다.",
  str_skill_passive_name_410207 = "부유의 물결",
  str_skill_passive_desc_410207 = "이번 턴에 파티 내 오로리안이 처음으로 액티브 스킬을 시전할 시 세나가 <link=\"30085\"><#FFAE07><u>잔물결</u></color></link>을 1단계 획득하며, 잔물결을 획득할 때 현재 단계가 7 이상일 시 잔물결을 소모해 세나의 최대 HP의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_passive_name_416207 = "부유의 물결",
  str_skill_passive_desc_416207 = "이번 턴에 파티 내 오로리안이 처음으로 액티브 스킬을 시전할 시 세나가 <link=\"30086\"><#FFAE07><u>잔물결</u></color></link>을 1단계 획득하며, 잔물결을 획득할 때 현재 단계가 5 이상일 시 잔물결을 소모해 세나의 최대 HP의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_desc_350025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>300%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.7배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화한다.",
  str_skill_desc_356025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>300%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.7배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다.",
  str_skill_desc_360025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>340%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.7배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화한다.",
  str_skill_desc_366025 = "<color=#00F6FF>3열</color> 또는 <color=#00F6FF>3행</color>을 선택해 <color=#00F6FF>340%</color>의 피해를 입히고 적을 넉백시키며, 중간 행 또는 열에는 양측의 1.7배의 피해를 입힌다. 범위 내 <color=#00F6FF>불 속성이 아닌 칸을</color> 초기화해 <color=#00F6FF>낮은 확률</color>로 불 속성 칸을 생성한다.",
  str_skill_passive_desc_440025 = "일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있으며, 일반공격에 공격력의 <color=#00F6FF>12%</color>에 해당하는 방어무시 피해를 추가한다.",
  str_skill_upgrade_refine_desc_16002511 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>12%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16002512 = "액티브 스킬 강화: 가운데 열 또는 행의 피해가 <color=#00F6FF>1.7</color>배로 증가한다.",
  str_skill_upgrade_refine_desc_16002513 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>340%</color>로 증가한다.",
  str_skill_name_2002061 = "모네타이즈",
  str_skill_name_2002062 = "모네타이즈",
  str_skill_name_2002063 = "모네타이즈",
  str_skill_desc_2002061 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002062 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>십자 방향으로 이어지는</color> 모든 불 속성 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002063 = "<color=#00F6FF>주변 1서클</color> 및 <color=#00F6FF>8방향으로 이어지는</color> 모든 불 속성 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_3002061 = "투자의 재능",
  str_skill_name_3062061 = "투자의 재능",
  str_skill_desc_3002061 = "1칸을 선택해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 공격 범위의 칸을 불 속성으로 전환한다.",
  str_skill_desc_3062061 = "1칸을 선택해 <color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 적을 넉백시키며, 공격 범위의 칸을 불 속성으로 전환한다.",
  str_skill_passive_name_410206 = "투자 위험 전가",
  str_skill_passive_name_420206 = "투자 위험 전가",
  str_skill_passive_name_430206 = "투자 위험 전가",
  str_skill_passive_desc_410206 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>인접 십자형 범위</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}</color>의 피해를 입히고 칸을 부순다.",
  str_skill_passive_desc_420206 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>인접 십자형 범위</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_passive_desc_430206 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>주변 1서클</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
