  str_skill_desc_32020624 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>인접 십자형 범위</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}%</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_desc_3302062 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>주변 1서클</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}%</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_desc_33020622 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>주변 1서클</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}%</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_desc_33020623 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>주변 1서클</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}%</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_desc_33020624 = "신규 액티브 스킬 획득: 전투 진입 즉시 사용할 수 있으며, <color=#00F6FF>주변 1서클</color> 내의 칸 중 1개를 선택해 불 속성으로 전환한다. 동시에 <color=#00F6FF>{1}%</color>의 피해를 입히고 칸을 부순다. 대상의 현재 HP가 낮을수록 피해가 증가하며, 최대 <color=#00F6FF>250%</color>까지 증가한다.",
  str_skill_upgrade_desc_16020613 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16020616 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_upgrade_refine_desc_15002411 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>65%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15002412 = "액티브 스킬 강화: 두 위치의 연쇄 스킬 최종 피해가 <color=#00F6FF>35%</color> 증가한다.",
  str_skill_upgrade_refine_desc_15002413 = "연쇄 스킬 강화: 액티브 스킬을 시전한 턴은 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_passive_desc_440024 = "일반공격이 불 속성 칸의 적에게 추가로 <color=#00F6FF>65%</color>의 피해를 입힌다.",
  str_skill_desc_340024 = "칸 1개에 표식을 남긴다. 이번 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>1.5</color>배 도달 시 표식 위치에도 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 <color=#00F6FF>35%</color> 증가).",
  str_skill_desc_342024 = "칸 1개에 표식을 남긴다. 이번 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>1.5</color>배 도달 시 표식 위치에도 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 <color=#00F6FF>35%</color> 증가).",
  str_skill_desc_345024 = "칸 1개에 표식을 남긴다. 이번 연결 칸 수량이 연쇄 스킬 발동에 필요한 칸 수량의 <color=#00F6FF>1.5</color>배 도달 시 표식 위치에도 연쇄 스킬이 1회 발동한다(두 연쇄 스킬의 최종 피해가 <color=#00F6FF>35%</color> 증가).",
  str_skill_desc_240241 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>140%</color>의 피해를 입힌다. 액티브 스킬을 시전한 턴은 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_240242 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>145%</color>의 피해를 입힌다. 액티브 스킬을 시전한 턴은 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_desc_240243 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>155%</color>의 피해를 입힌다. 액티브 스킬을 시전한 턴은 연쇄 스킬 발동에 필요한 칸 수량이 <color=#00F6FF>1</color> 감소한다.",
  str_skill_name_290560101 = "여신나비-덩굴 가시",
  str_skill_desc_290560101 = "오로리안을 향해 이동 후 전방 1행 또는 1열 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_290560102 = "여신나비-가루받이",
  str_skill_desc_290560102 = "오로리안을 향해 이동 후 자신의 주변 마름모 12칸 범위 내의 모든 대상에게 피해를 입히고 독소를 추가하며, 범위 내 식물의 성장을 촉진시킨다.",
  str_skill_name_290560103 = "여신나비-성장 폭발",
  str_skill_desc_290560103 = "오로리안을 조준해 오로리안 주변 마름모 12칸 범위 내의 모든 대상에게 피해를 입히고 독소를 추가하며(반드시 명중), 범위 내 식물의 성장을 촉진시킨다.",
  str_skill_name_200260101 = "칩거",
  str_skill_desc_200260101 = "유체 상태가 되어 오로리안의 공격을 받지 않는다.",
  str_skill_name_200260201 = "생장",
  str_skill_desc_200260201 = "변태기에 진입해 오로리안에게 공격을 받으며, 자신은 오로리안을 공격할 수 없다.",
  str_skill_name_200260301 = "기괴한 침",
  str_skill_desc_200260301 = "오로리안을 조준해 피해를 입히고 독소를 추가한다.",
  str_skill_name_53310002 = "여신나비-가루받이",
  str_skill_desc_53310002 = "자신의 주변 마름모 12칸 범위 내 식물의 성장을 촉진시킨다.",
  str_skill_desc_3300051 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가). 영혼이 입히는 충격 피해가 개당 130%로 증가한다.",
  str_skill_desc_3300052 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가). 오로리안 액티브 스킬로 적 처치 시 영혼을 획득하지 않는다.",
  str_skill_desc_3360051 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가). 영혼이 입히는 충격 피해가 개당 130%로 증가한다.",
  str_skill_desc_3360052 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 적의 HP 퍼센트가 낮을수록 피해가 증가한다(최대 100%까지 증가). 오로리안 액티브 스킬로 적 처치 시 영혼을 획득하지 않는다.",
  str_skill_passive_desc_443005 = "<color=#00F6FF>오로리안</color> 액티브 스킬로 적 처치 시 영혼 1개를 획득한다(최대 <color=#00F6FF>8</color>개). 영혼 개수마다 단일 적에게 공격력의 <color=#00F6FF>100%</color>에 해당하는 충격을 1회 시전하며, 미아의 연쇄 피해가 <color=#00F6FF>5%</color>, 일반공격 피해가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 영혼이 입히는 충격 피해가 개당 130%로 증가한다.",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 오로리안 액티브 스킬로 적 처치 시 영혼을 획득하지 않는다.",
  str_skill_upgrade_refine_desc_16000513 = "장비 스킬 강화: 영혼 한도가 <color=#00F6FF>8</color>개로 증가한다.",
  str_skill_desc_8001201 = "즉시 근처에 섀도고스트를 소환한다.",
  str_skill_desc_8001441 = "필드에 대량의 그레이웜을 소환하며, 자신에게 공격력을 제공하는 30단계의 에너지 인장을 추가한다.",
  str_skill_desc_800128107 = "다크 서머너가 대상 근처로 순간이동해 일정 수량의 실드를 획득하며, 대규모 범위 공격을 준비한다. 이번 턴에 다크 서머너의 방어력이 대폭 감소한다.",
  str_skill_desc_8001391 = "굵은 꼬리를 사용해 자신의 공격 범위 내 대상을 공격하며, 2회의 피해 효과를 입힌다.",
  str_skill_desc_800141 = "꼬리에 응축된 에너지 스파이크를 사용해 공격 범위 내 대상에게 원거리 공격을 가하며, 2회의 피해 효과를 입힌다.",
  str_skill_desc_800139 = "굵은 꼬리를 사용해 자신의 공격 범위 내 대상을 공격한다.",
  str_skill_desc_800140 = "꼬리에 응축된 에너지 스파이크를 사용해 공격 범위 내 대상에게 원거리 공격을 가한다.",
  str_skill_name_52200191 = "각성 전이-영역",
  str_skill_desc_52200191 = "1칸을 선택한 후 다시 2*2 또는 1*4 범위를 선택해 범위 내의 칸을 만색 칸으로 전환한다.",
  str_skill_name_5220021 = "각성 전이-충격",
  str_skill_desc_5220021 = "1칸을 선택한 후 정방형 9칸 범위 내에 랜덤으로 5개의 만색 칸을 생성한다.",
  str_skill_name_5220024 = "각성 전이-폭발",
  str_skill_desc_5220024 = "1칸을 선택한 후 만색 칸/번개 속성 칸이 아닌 가장 가까운 6개의 칸을 3개의 번개 속성 칸과 3개의 만색 칸으로 전환한다.",
  str_skill_desc_52200241 = "1칸을 선택한 후 만색 칸이 아닌 가장 가까운 6개의 칸을 6개의 만색 칸으로 전환한다.",
  str_skill_name_5220022 = "각성 전이-벼락",
  str_skill_desc_5220022 = "1칸을 선택해 주변 4칸을 번개 속성 칸으로 전환한다.",
  str_skill_desc_52200221 = "1칸을 선택해 주변 4칸을 만색 칸으로 전환한다.",
  str_skill_name_5220023 = "각성 전이-우뢰",
  str_skill_desc_5220023 = "5칸을 선택해 번개 속성 칸으로 전환한다.",
  str_skill_desc_52200231 = "5칸을 선택해 만색 칸으로 전환한다.",
  str_skill_desc_5010421 = "부하가 자신의 주변 2서클 범위 내 대상에게 파열의 인장을 대량으로 추가한다. 인장 개수마다 대상의 방어력을 일정량 감소시키며, 인장 개수가 많을수록 방어력이 감소한다.",
  str_skill_desc_5010821 = "필드의 랜덤 위치에 이동할 수 없는 거츠더의 부하 여러 명을 소환한다.",
  str_skill_desc_5010831 = "범위 내 대상을 공격하고, 대상에게 파열의 인장을 10회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_desc_5010832 = "범위 내 대상을 공격하고, 대상에게 파열의 인장을 1회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_desc_5010841 = "포효해 범위 내 적 대상에게 파열의 인장을 20회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_desc_5010842 = "포효해 범위 내 적 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_desc_5010851 = "대상이 지닌 파열의 인장을 폭발시켜 대상에게 대량의 피해를 입힌다. 인장 개수가 많을수록 피해가 증가한다.",
  str_skill_desc_5010871 = "필드의 랜덤 위치에 이동할 수 없는 부하 3명을 소환한다.",
  str_skill_desc_5010881 = "미친 듯이 범위 내 대상을 2회 공격하고, 대상에게 파열의 인장을 여러 개 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다.",
  str_skill_desc_5010891 = "최후의 포효로 범위 내 대상에게 파열의 인장을 여러 개 부여하며, 인장 개수가 많을수록 대상의 방어력이 낮아진다.",
  str_skill_desc_533500601 = "범위 내 대상에게 피해를 입히며, 동시에 넓은 범위 내 모든 칸을 부순다.",
  str_skill_desc_990050211 = "추방-솔모프가 전체 범위에 피해를 입힌다.",
  str_skill_desc_990050212 = "추방-솔모프가 대상이 있는 방향을 향해 두 행 넓이의 충격파 1개를 발사해 명중한 대상에게 피해를 입힌다.",
  str_skill_name_990050211 = "확산",
  str_skill_name_1002802 = "급속 도주",
  str_skill_desc_1002802 = "자신과 가장 가까운 텔레포트 웜홀로 이동해 전장 사이를 빠르게 누빈다.",
  str_skill_name_300208 = "유사의 흐름",
  str_skill_name_305208 = "유사의 흐름",
  str_skill_name_310208 = "유사의 흐름",
  str_skill_name_315208 = "유사의 흐름",
  str_skill_name_320208 = "유사의 흐름",
  str_skill_name_325208 = "유사의 흐름",
  str_skill_name_330208 = "유사의 흐름",
  str_skill_name_335208 = "유사의 흐름",
  str_skill_name_2002081 = "모래의 격류",
  str_skill_name_2002082 = "모래의 격류",
  str_skill_name_2002083 = "모래의 격류",
  str_skill_name_2302081 = "모래의 격류",
  str_skill_name_2302082 = "모래의 격류",
  str_skill_name_2302083 = "모래의 격류",
  str_skill_desc_2002081 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002082 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002083 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300208 = "이동 가능한 칸 1개를 선택해 <link=\"30087\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다.",
  str_skill_desc_305208 = "이동 가능한 칸 1개를 선택해 <link=\"30087\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>소환 직후</color> 및 <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다.",
  str_skill_desc_310208 = "이동 가능한 칸 1개를 선택해 <link=\"30087\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다.",
  str_skill_desc_315208 = "이동 가능한 칸 1개를 선택해 <link=\"30087\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>소환 직후</color> 및 <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다.",
  str_skill_desc_320208 = "이동 가능한 칸 1개를 선택해 <link=\"30088\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다. 사족 강철 도마뱀이 <link=\"30089\"><#FFAE07><u>「끌림의 울음소리」</u></color></link> 스킬을 획득한다.",
  str_skill_desc_325208 = "이동 가능한 칸 1개를 선택해 <link=\"30088\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>소환 직후</color> 및 <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다. 사족 강철 도마뱀이 <link=\"30089\"><#FFAE07><u>「끌림의 울음소리」</u></color></link> 스킬을 획득한다.",
  str_skill_desc_330208 = "이동 가능한 칸 1개를 선택해 <link=\"30088\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다. 사족 강철 도마뱀이 <link=\"30089\"><#FFAE07><u>「끌림의 울음소리」</u></color></link>와 <link=\"30090\"><#FFAE07><u>「거대한 힘」</u></color></link> 스킬을 획득한다.",
  str_skill_desc_335208 = "이동 가능한 칸 1개를 선택해 <link=\"30088\"><#FFAE07><u>사족 강철 도마뱀</u></color></link>을 소환하며, <color=#00F6FF>소환 직후</color> 및 <color=#00F6FF>몬스터 턴 시작 전</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다. 사족 강철 도마뱀이 <link=\"30089\"><#FFAE07><u>「끌림의 울음소리」</u></color></link>와 <link=\"30090\"><#FFAE07><u>「거대한 힘」</u></color></link> 스킬을 획득한다.",
  str_skill_passive_name_410208 = "폭렬 도마뱀",
  str_skill_passive_desc_410208 = "사족 강철 도마뱀이 사라질 때 주변 2서클에 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_upgrade_desc_15020812 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15020815 = "액티브 스킬 강화: 사족 강철 도마뱀 <color=#FFFF00>소환 직후</color> 사족 강철 도마뱀이 <color=#00F6FF>주변 2서클</color> 내의 적을 자신의 방향으로 1칸 끌어당긴다.",
  str_skill_name_1522081 = "끌림의 울음소리",
  str_skill_desc_1522081 = "시전 시 주변 2서클 내의 적을 1칸 끌어당긴 후 사라진다.",
  str_skill_name_1532081 = "거대한 힘",
  str_skill_desc_1532081 = "시전 시 보프의 이번 턴 연쇄 스킬 범위가 사족 강철 도마뱀 자신을 향하도록 바꾸며, 범위가 필드 가장자리까지 확장된다.",
  str_skill_name_99039011 = "추방-원샷 원킬",
  str_skill_name_99039012 = "오로리안의 위치를 향해 이동하고, 오로리안의 인접 4칸에 있을 시 공격을 발동한다.",
  str_skill_desc_99039011 = "추방-건 카타",
  str_skill_desc_99039012 = "오로리안의 위치를 향해 이동하고, 오로리안의 주변 1서클에 있을 시 공격을 발동한다.",
  str_skill_name_52200232 = "각성의 전환",
  str_skill_desc_52200232 = "1칸을 선택해 만색 칸으로 전환한다.",
  str_skill_name_290600103 = "순간이동 공격",
  str_skill_name_290600104 = "슬픔의 폭풍",
  str_skill_name_290600105 = "원망의 결속",
  str_skill_name_290600106 = "무의 존재",
  str_skill_desc_290600103 = "슬픔의 사념체 「이브」가 대상 기준 십자형 최대 범위 내 가장 먼 칸으로 순간이동한 후 대상을 공격한다.",
  str_skill_desc_290600104 = "슬픔의 사념체 「이브」가 전장 중앙 넓은 범위의 구역에 피해를 입힌다.",
  str_skill_desc_290600105 = "슬픔의 사념체 「이브」가 대량의 다크매터 단계를 획득하며, 단계 수에 따라 피해감소 효과를 획득한다. 공격을 받을 때마다 다크매터 단계가 감소한다.",
  str_skill_desc_290600106 = "슬픔의 사념체 「이브」가 대상을 조준해 피해를 입히고, 남은 다크매터 단계에 따라 대량의 HP를 회복한다.",
  str_skill_name_291600103 = "슬픔의 사념체 「이브」가 대상과 가장 가까운 칸으로 순간이동한 후 대상을 공격한다.",
  str_skill_name_291600104 = "슬픔의 사념체 「이브」가 전장 중앙 넓은 범위의 구역에 피해를 입힌다.",
  str_skill_name_291600105 = "슬픔의 사념체 「이브」가 일정량의 다크매터 단계를 획득하며, 단계 수에 따라 피해감소 효과를 획득한다. 공격을 받을 때마다 다크매터 단계가 감소한다.",
  str_skill_name_291600106 = "슬픔의 사념체 「이브」가 대상을 조준해 피해를 입히고, 남은 다크매터 단계에 따라 대량의 HP를 회복한다.",
  str_skill_name_20060011 = "새벽꽃",
  str_skill_desc_20060011 = "슬픔의 사념체 「이브」에게 HP 회복 보너스를 제공한다.",
  str_skill_name_200310102 = "솔선수범",
  str_skill_desc_200310102 = "적을 베어 피해를 준 다음 발로 차서 추가로 소량의 피해를 입히고 넉백시킨다.",
  str_skill_name_200310103 = "전우 격려",
  str_skill_desc_200310103 = "주변 2서클 내 일루미나 병사의 행동력을 높이고, 자신과 범위 내 일루미나 병사에게 누적된 적혈 수치 일부를 HP로 전환한다.",
  str_skill_name_200290103 = "L5형 기관총 제압",
  str_skill_desc_200290103 = "적이 주변 20칸 내에 있을 시 연발포를 사용해 적에게 피해를 입힌다.",
  str_skill_name_200290104 = "L5형 돌진 충격",
  str_skill_desc_200290104 = "적이 20칸 범위를 벗어나면 십자 방향 중 적과 가장 가까운 위치로 돌진하며, 종점 전방의 적에게 피해를 입히고 2칸 넉백시킨다.",
  str_skill_name_200300101 = "부채꼴 화염 분사",
  str_skill_desc_200300101 = "전방 부채꼴 범위 내의 모든 대상에게 피해를 입히고, 1단계의 작열 효과를 추가하며, 범위 내 이동 가능한 칸에 화염을 생성한다.",
  str_skill_name_200340103 = "휩쓸기",
  str_skill_desc_200340103 = "무기를 휘둘러 전방의 적에게 피해를 입힌다.",
  str_skill_name_200340104 = "습격",
  str_skill_desc_200340104 = "무기를 찔러 전방의 적에게 피해를 입힌다.",
  str_skill_name_200270101 = "일루미나 전장 구조법",
  str_skill_desc_200270101 = "자신의 주변 십자형 4칸 내 HP가 가장 낮은 일루미나 병사의 HP를 회복하고, 자신에게 누적된 적혈 수치 일부를 HP로 전환한다.",
  str_skill_name_200280101 = "지원 요청",
  str_skill_desc_200280101 = "일루미나 병사 1명을 전장에 소환한다.",
  str_skill_upgrade_desc_16020913 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16020916 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_name_2002091 = "진열 충격",
  str_skill_name_2002092 = "진열 충격",
  str_skill_name_2002093 = "진열 충격",
  str_skill_name_2002094 = "진열 충격",
  str_skill_desc_2002091 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 9칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2002092 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2002093 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>쌍십자형 17칸</color>에 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_2002094 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가깝고 HP가 가장 높은 적을 향해 도약, <color=#00F6FF>정방형 25칸</color>에 <color=#00F6FF>200%</color>의 피해를 입힌다. 단일 연결 이동 중 피해를 1회 입힐 때마다 발동 조건이 1 감소한다.",
  str_skill_name_3002091 = "뇌명의 순항",
  str_skill_name_3002092 = "뇌명의 순항-진화Ⅱ",
  str_skill_name_3002093 = "뇌명의 순항-진화Ⅰ",
  str_skill_name_3062091 = "뇌명의 순항",
  str_skill_name_3062092 = "뇌명의 순항-진화Ⅱ",
  str_skill_name_3062093 = "뇌명의 순항-진화Ⅰ",
  str_skill_desc_3002091 = "1칸을 선택해 정방형 25칸에 <color=#00F6FF>200%</color>의 피해를 입힌다. 자신이 선택한 범위 내에 있을 시 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_desc_3002092 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 정방형 9칸에 <color=#00F6FF>100%</color>의 피해를 입힌다. 자신이 선택한 범위 내에 있을 시 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_desc_3002093 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 칸에 300%의 피해를 입히고, 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_desc_3062091 = "1칸을 선택해 정방형 25칸에 <color=#00F6FF>200%</color>의 피해를 입힌다. 자신이 선택한 범위 내에 있을 시 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_desc_3062092 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 정방형 9칸에 <color=#00F6FF>100%</color>의 피해를 입힌다. 자신이 선택한 범위 내에 있을 시 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_desc_3062093 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 칸에 <color=#00F6FF>300%</color>의 피해를 입히고, 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_passive_name_410209 = "뇌명의 기세",
  str_skill_passive_name_420209 = "뇌명의 기세",
  str_skill_passive_name_430209 = "뇌명의 기세",
  str_skill_passive_desc_410209 = "액티브 스킬에 공격받은 적은 <color=#00F6FF>2턴간</color> 뇌명 상태에 진입하며, 아군이 칸을 연결해 1칸을 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color> 범위 내 뇌명 상태의 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420209 = "액티브 스킬에 공격받은 적은 <color=#00F6FF>2턴간</color> 뇌명 상태에 진입하며, 아군이 칸을 연결해 1칸을 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color> 범위 내 뇌명 상태의 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_430209 = "일반공격이 <color=#00F6FF>십자 8칸</color>의 적을 공격할 수 있다. 액티브 스킬에 공격받은 적은 <color=#00F6FF>2턴간</color> 뇌명 상태에 진입하며, 아군이 칸을 연결해 1칸을 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color> 범위 내 뇌명 상태의 대상에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_440209 = "일반공격이 <color=#00F6FF>십자 8칸</color>의 적을 공격할 수 있다. 액티브 스킬에 공격받은 적은 <color=#00F6FF>2턴간</color> 뇌명 상태에 진입하며, 아군이 칸을 연결해 1칸을 이동할 때마다 주변 <color=#00F6FF>마름모 12칸</color> 범위 내 뇌명 상태의 대상에게 <color=#00F6FF>50%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16020911 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>50%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 모든 칸에 <color=#00F6FF>300%</color>의 피해를 입히고, 최종 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 정방형 9칸에 <color=#00F6FF>100%</color>의 피해를 입힌다. 자신이 선택한 범위 내에 있을 시 최종 피해가 30% 증가한다.",
  str_skill_desc_320116 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 해당 대상에게 표식을 추가한다. 플뢰르가 이번 턴에 연쇄 스킬 시전 시 표식 대상에게 추가로 피해를 1회 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>35%</color> 증가한다.",
  str_skill_desc_323116 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 해당 대상에게 표식을 추가한다. 플뢰르가 이번 턴에 연쇄 스킬 시전 시 표식 대상에게 추가로 피해를 1회 입힌다. 액티브 스킬이 이전 턴에 준비되면 이번 턴의 최종 피해가 <color=#00F6FF>35%</color> 증가한다.",
  str_skill_upgrade_desc_16011113 = "장비 스킬 강화: 수정 생성 범위가 주변 1/2/3서클까지 확대된다.",
  str_skill_upgrade_desc_16011116 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_desc_300111 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 필드 내 적의 수가 적을수록 입히는 피해가 최대 2배까지 증가한다.",
  str_skill_desc_303111 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 필드 내 적의 수가 적을수록 입히는 피해가 최대 2배까지 증가한다.",
  str_skill_desc_320111 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 필드 내 적의 수가 적을수록 입히는 피해가 최대 2배까지 증가한다. <color=#00F6FF>액티브 스킬 시전 후</color> 및 <color=#00F6FF>오로라 타임 진입 시</color> 현재 위치에 표식을 추가하며, 이번 턴에 장비 스킬을 발동해 수정을 생성할 경우, 표식 위치에도 장비 스킬이 1회 발동한다.",
  str_skill_desc_323111 = "적 <color=#00F6FF>전체</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 필드 내 적의 수가 적을수록 입히는 피해가 최대 2배까지 증가한다. <color=#00F6FF>액티브 스킬 시전 후</color> 및 <color=#00F6FF>오로라 타임 진입 시</color> 현재 위치에 표식을 추가하며, 이번 턴에 장비 스킬을 발동해 수정을 생성할 경우, 표식 위치에도 장비 스킬이 1회 발동한다.",
  str_skill_passive_name_416111 = "스톤 마인드",
  str_skill_passive_name_436111 = "스톤 마인드",
  str_skill_passive_desc_410111 = "적이 행동을 개시하기 전, 이번 턴에 베릴이 연쇄 스킬을 시전한 경우 해당 <color=#00F6FF>연쇄 스킬 범위</color>에 수정을 생성한다. 1턴간 지속. 적이 수정에 <link=\"30091\"><#FFAE07><u>닿으면</u></color></link> 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다(해당 피해는 속성 상성의 보정이 적용됨).",
  str_skill_passive_desc_430111 = "적이 행동을 개시하기 전, 이번 턴에 베릴이 연쇄 스킬을 시전한 경우 해당 <color=#00F6FF>연쇄 스킬 범위</color>에 수정을 생성한다. 1턴간 지속. 적이 수정에 <link=\"30091\"><#FFAE07><u>닿으면</u></color></link> 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다(해당 피해는 속성 상성의 보정이 적용됨). 연결이 1칸 추가될 때마다 수정의 피해가 <color=#00F6FF>10%</color> 증가하며, 20칸 도달 시 더는 증가하지 않는다.",
  str_skill_passive_desc_416111 = "적이 행동을 개시하기 전, 이번 턴에 베릴이 연쇄 스킬을 시전한 경우 자신의 <color=#00F6FF>주변 1/2/3서클 범위</color>에 수정을 생성한다. 1턴간 지속. 적이 수정에 <link=\"30091\"><#FFAE07><u>닿으면</u></color></link> 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다(해당 피해는 속성 상성의 보정이 적용됨).",
  str_skill_passive_desc_436111 = "적이 행동을 개시하기 전, 이번 턴에 베릴이 연쇄 스킬을 시전한 경우 자신의 <color=#00F6FF>주변 1/2/3서클 범위</color>에 수정을 생성한다. 1턴간 지속. 적이 수정에 <link=\"30091\"><#FFAE07><u>닿으면</u></color></link> 대상에게 공격력의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다(해당 피해는 속성 상성의 보정이 적용됨). 연결이 1칸 추가될 때마다 수정의 피해가 <color=#00F6FF>10%</color> 증가하며, 20칸 도달 시 더는 증가하지 않는다.",
  str_skill_desc_2001161 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_2001162 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_2001163 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다.",
  str_skill_desc_2061161 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 모든 방어력을 무시한다.",
  str_skill_desc_2061162 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 모든 방어력을 무시한다.",
  str_skill_desc_2061163 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 모든 방어력을 무시한다.",
  str_skill_desc_2201161 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 방어력을 40% 무시한다.",
  str_skill_desc_2201162 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 방어력을 40% 무시한다.",
  str_skill_desc_2201163 = "가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 표식을 지닌 대상의 방어력을 40% 무시한다.",
  str_skill_name_2201161 = "알렌의 펀치",
  str_skill_name_2201162 = "알렌의 펀치",
  str_skill_name_2201163 = "알렌의 펀치",
  str_skill_desc_300116 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 해당 대상에게 표식을 추가한다. 플뢰르의 연쇄 스킬이 이번 턴에 표식 대상에게 추가로 피해를 1회 입힌다.",
  str_skill_desc_303116 = "적 1명을 선택해 대상에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 해당 대상에게 표식을 추가한다. 플뢰르의 연쇄 스킬이 이번 턴에 표식 대상에게 추가로 피해를 1회 입힌다. <color=#00F6FF>오로라 타임 진입</color> 또는 <color=#00F6FF>표식을 지닌 대상 처치</color> 시 액티브 스킬을 1회 더 시전할 수 있다.",
  str_skill_passive_name_400116 = "시스템 마스터",
  str_skill_passive_name_410116 = "시스템 마스터",
  str_skill_passive_name_430116 = "시스템 마스터",
  str_skill_passive_desc_410116 = "HP가 50% 미만인 적에게 플뢰르가 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가한다(대상이 HP 한도가 없을 시 해당 효과를 즉시 적용함).",
  str_skill_passive_desc_430116 = "HP가 50% 미만인 적에게 플뢰르가 입히는 모든 피해가 <color=#00F6FF>{1}</color> 증가하며(대상이 HP 한도가 없을 시 해당 효과를 즉시 적용함), 표식을 지닌 대상 공격 시 추가로 <color=#00F6FF>{2}</color>의 보너스를 획득한다.",
  str_skill_upgrade_desc_16011613 = "연쇄 스킬 강화: 연쇄 스킬이 표식을 지닌 대상의 모든 방어력을 무시한다(각성 2단계 달성 시 적용).",
  str_skill_upgrade_desc_16011616 = "액티브 스킬 강화: 오로라 타임 진입 시 또는 표식을 지닌 대상 처치 시 1회 더 시전할 수 있다.",
  str_skill_name_20021011 = "무결의 참격",
  str_skill_name_2002102 = "무결의 참격",
  str_skill_name_2002103 = "무결의 참격",
