  str_skill_name_3122101 = "기도의 칼끝",
  str_skill_name_3222101 = "기도의 칼끝",
  str_skill_name_3322101 = "기도의 칼끝",
  str_skill_name_3152101 = "기도의 칼끝",
  str_skill_name_3252101 = "기도의 칼끝",
  str_skill_name_3352101 = "기도의 칼끝",
  str_skill_passive_name_410210 = "잔념베기",
  str_skill_passive_name_415210 = "잔념베기",
  str_skill_desc_20021011 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002102 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>135%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002103 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>140%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_3002101 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3102101 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3202101 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_3302101 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_3022101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3122101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3222101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_3322101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_3152101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3252101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_3352101 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>마름모 12칸</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_passive_desc_410210 = "조셀린의 일반공격 및 연쇄 스킬이 적에게 명중할 때마다 잔념 상태를 1회 추가하며, 최대 <color=#00F6FF>6</color>개까지 추가할 수 있다. 액티브 스킬이 <color=#00F6FF>전방 1칸</color>의 적에게 대상이 지닌 잔념 수와 동일한 횟수로 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입히며, 이후 잔념 상태는 초기화된다.",
  str_skill_passive_desc_415210 = "조셀린의 일반공격 및 연쇄 스킬이 적에게 명중할 때마다 잔념 상태를 1회 추가하며, 최대 <color=#00F6FF>8</color>개까지 추가할 수 있다. 액티브 스킬이 <color=#00F6FF>전방 1칸</color>의 적에게 대상이 지닌 잔념 수와 동일한 횟수로 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입히며, 이후 잔념 상태는 초기화된다.",
  str_skill_upgrade_desc_15021012 = "액티브 스킬 강화: 주변 <color=#FFFF00>8</color>방향 중 하나를 선택해 돌격한다.",
  str_skill_upgrade_desc_15021015 = "장비 스킬 강화: 잔념 한도가 <color=#FFFF00>8</color>개로 증가한다.",
  str_skill_name_200330110 = "영감 제어",
  str_skill_desc_200330110 = "드레드위버가 플레이어로부터 멀리 떨어진다. 파티의 이동이 끝나면 즉시 파티의 위치를 변화시켜, 파티의 연쇄 스킬 시전 위치에 영향을 준다.",
  str_skill_name_200330121 = "잔혹한 봉헌",
  str_skill_desc_200330121 = "드레드위버가 자신의 남은 HP를 1포인트만 남기고 연소시켜, 플레이어에게 방어무시 고정피해를 입힌다. 연소된 HP에 따라 피해의 최종 수치가 결정되며, 해당 스킬은 1회만 시전할 수 있다.",
  str_skill_upgrade_refine_desc_15021011 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>36%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15021012 = "액티브 스킬 강화: 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 120%의 피해를 1회 입힌다.",
  str_skill_upgrade_refine_desc_15021013 = "액티브 스킬 강화: 액티브 스킬 및 장비 스킬로 발생하는 피해가 관통한 칸에 동일한 피해를 입힌다.",
  str_skill_passive_desc_440210 = "조셀린의 일반공격 및 연쇄 스킬이 적에게 명중할 때마다 잔념 상태를 1회 추가하며, 최대 <color=#00F6FF>8</color>개까지 추가할 수 있다. 액티브 스킬이 <color=#00F6FF>전방 1칸</color>의 적에게 대상이 지닌 잔념 수와 동일한 횟수로 공격력의 <color=#00F6FF>36%</color>에 해당하는 피해를 입히며, 이후 잔념 상태는 초기화된다.",
  str_skill_passive_desc_445210 = "조셀린의 일반공격 및 연쇄 스킬이 적에게 명중할 때마다 잔념 상태를 1회 추가하며, 최대 <color=#00F6FF>8</color>개까지 추가할 수 있다. 액티브 스킬이 <color=#00F6FF>전방 1칸</color>의 적에게 대상이 지닌 잔념 수와 동일한 횟수로 공격력의 <color=#00F6FF>36%</color>에 해당하는 피해를 입히며, 이후 잔념 상태는 초기화된다.",
  str_skill_desc_34021011 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_34221011 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_34521011 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>절반</color>의 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_34021012 = "주변 <color=#00F6FF>4</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>동일</color>한 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_34221012 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>동일</color>한 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_desc_34521012 = "주변 <color=#00F6FF>8</color>방향 중 하나를 선택해 돌격하며, 가로막히면 정지해 <color=#00F6FF>전방 1칸</color>의 적에게 <color=#00F6FF>80%</color>의 피해를 입힌다. 해당 피해 및 장비 스킬로 발생하는 피해는 1칸을 관통할 수 있으며, 관통한 칸에 <color=#00F6FF>동일</color>한 피해를 입힌다. 대상이 지닌 잔념 4개마다 자신을 중심으로 <color=#00F6FF>주변 2서클</color> 내의 모든 적에게 추가로 <color=#00F6FF>120%</color>의 피해를 1회 입힌다.",
  str_skill_name_70010981 = "추방-콜로서스의 칼날",
  str_skill_name_70010982 = "추방-번개의 힘",
  str_skill_name_70010983 = "추방-콜로서스의 소리",
  str_skill_desc_70010981 = "추방-디바우러호 슈모르가 자신의 십자형 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_70010982 = "추방-디바우러호 슈모르가 번개의 힘을 소환해 필드의 여러 랜덤 구역에 피해를 입히고 마비 효과를 부여한다.",
  str_skill_desc_70010983 = "추방-디바우러호 슈모르가 콜로서스를 제어해 음파 공격으로 필드의 모든 대상을 공격하고, 오로리안을 주변으로 끌어당긴다.",
  str_skill_name_290610101 = "전진 돌파",
  str_skill_desc_290610101 = "전방 범위 내 적이 있을 경우 천천히 전진하여 전방의 적을 공격한다.",
  str_skill_name_290610102 = "엔진 가속",
  str_skill_desc_290610102 = "전방이 비어있을 경우 가속하여 전진한다.",
  str_skill_name_290610103 = "360도 폭격",
  str_skill_desc_290610103 = "주변의 오로리안 유닛에게 피해를 입히고 넉백시키며, 성벽에 피해를 입힌다.",
  str_skill_name_290610104 = "고온 분사",
  str_skill_desc_290610104 = "강력한 공성 스킬로, 전방의 오로리안 유닛과 성벽에 막대한 피해를 입힌다.",
  str_skill_name_290610105 = "오염된 파일럿",
  str_skill_desc_290610105 = "마비 상태일 시 자신의 부품을 수리하며, 수리 완료 후 공성 작전을 다시 개시한다.",
  str_skill_name_280240101 = "구축 충격",
  str_skill_desc_280240101 = "요새 관문 앞의 적 유닛을 공격해 마비 상태로 만든다.",
  str_skill_name_290570101 = "늪 튀기기",
  str_skill_name_290570102 = "늪 분사",
  str_skill_name_290570103 = "소용돌이 늪",
  str_skill_desc_290570101 = "머드번들이 늪으로 잠수한 후 오로리안과 가장 가까운 위치에 출몰, 주변 2서클에 피해를 입히고 필드에 다수의 늪을 생성한다.",
  str_skill_desc_290570102 = "머드번들이 늪으로 잠수한 후 오로리안과 가장 가까운 위치에 출몰, 전방 2열에 피해를 입히고 다수의 늪을 남긴다.",
  str_skill_desc_290570103 = "모든 칸을 빨아들여 오로리안에게 피해를 입히고, 칸을 초기화하여 랜덤으로 오로리안을 늪 위로 옮긴다.",
  str_skill_desc_290570104 = "마레이셀이 드레드위버 2마리를 전장에 소환한다.",
  str_skill_upgrade_desc_16021213 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.\n액티브 스킬로 확정한 사각형 구역 내 랜덤 2개의 숲 속성이 아닌 칸을 숲 속성 칸으로 전환한다.",
  str_skill_upgrade_desc_16021216 = "액티브 스킬 강화: 두 번째 선택 가능 범위가 <color=#00F6FF>주변 4서클</color>로 확대된다.",
  str_skill_desc_3002121 = "1칸을 선택하고, <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성으로 전환하고, 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_3032121 = "1칸을 선택하고, <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성으로 전환하고, 사각형 구역 내 랜덤 2개의 숲 속성이 아닌 칸을 숲 속성 칸으로 전환한다. 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_3062121 = "1칸을 선택하고, <color=#00F6FF>주변 4서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성으로 전환하고, 사각형 구역 내 랜덤 2개의 숲 속성이 아닌 칸을 숲 속성 칸으로 전환한다. 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_3202121 = "1칸을 선택하고, <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하고, 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_3232121 = "1칸을 선택하고, <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하고, 사각형 구역 내 랜덤 2개의 숲 속성이 아닌 칸을 숲 속성 칸으로 전환한다. 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_3262121 = "1칸을 선택하고, <color=#00F6FF>주변 4서클</color> 내 1칸을 다시 선택해 사각형 구역을 만든다. 선택한 두 칸을 숲 속성 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>으로 전환하고, 사각형 구역 내 랜덤 2개의 숲 속성이 아닌 칸을 숲 속성 칸으로 전환한다. 파티가 사각형 구역 내에 있을 시 안토니의 공격력의 <color=#00F6FF>250%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_desc_2002121 = "<color=#00F6FF>세로 1열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002122 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002123 = "<color=#00F6FF>세로 3열</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_passive_desc_410212 = "파티가 숲 속성 칸에서 1칸을 연결해 이동하거나, 다른 방식으로 1칸 <link=\"30092\"><#FFAE07><u>위치이동</u></color></link>을 할 때마다 안토니의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_430212 = "파티가 숲 속성 칸에서 1칸을 연결해 이동하거나, 다른 방식으로 1칸 <link=\"30092\"><#FFAE07><u>위치이동</u></color></link>을 할 때마다 안토니의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다. 파티의 HP가 낮을수록 회복 효과가 증가한다(최대 <color=#00F6FF>100%</color> 증가).",
  str_skill_name_3002121 = "응급 술식",
  str_skill_name_3032121 = "응급 술식",
  str_skill_name_3062121 = "응급 술식",
