  str_skill_name_2002123 = "에너지 유출",
  str_skill_passive_name_410212 = "지식 피드백",
  str_skill_passive_name_430212 = "지식 피드백",
  str_skill_name_8002001 = "꿈의 확장-울림",
  str_skill_name_8002002 = "꿈의 확장-충격",
  str_skill_name_8002003 = "꿈의 확장-벼락",
  str_skill_name_8002004 = "꿈의 확장-번개",
  str_skill_name_8002005 = "꿈의 확장-천둥",
  str_skill_desc_8002001 = "1칸을 선택한 후 다시 2*2 또는 1*4 범위를 선택해 범위 내의 칸을 만색 칸으로 전환하고 강화 칸을 생성한다.",
  str_skill_desc_8002002 = "1칸을 선택한 후 정방형 9칸 범위 내에 랜덤으로 5개의 만색 칸과 5개의 강화 칸을 생성한다.",
  str_skill_desc_8002003 = "1칸을 선택한 후 만색 칸이 아닌 가장 가까운 6개의 칸을 6개의 만색 칸으로 전환하고 강화 칸을 생성한다.",
  str_skill_desc_8002004 = "1칸을 선택해 주변 4칸을 만색 칸으로 전환하고 강화 칸을 생성한다.",
  str_skill_desc_8002005 = "5칸을 선택해 만색 칸으로 전환하고 강화 칸을 생성한다.",
  str_skill_name_8002006 = "적막",
  str_skill_desc_8002006 = "긴 적막에 빠져 더는 응답하지 않는다. 동시에 모든 암귀와 백야성 병사가 받는 피해를 이어받는다.",
  str_skill_name_80020042 = "경악",
  str_skill_desc_80020042 = "오로리안이 자신을 기준으로 쌍십자형 범위 내에 있을 시 오로리안의 근처로 이동, 피해를 입히고 넉백시킨다. 장애물이 있을 시 공격이 차단된다.",
  str_skill_name_80020052 = "망설임",
  str_skill_desc_80020052 = "필드 밖에 있어 플레이어의 타깃형 스킬에만 명중하며, 범위 피해 및 일반공격 피해를 받지 않으나, 필드 내 적이 받는 피해는 이리돈에게도 적용된다.",
  str_skill_name_2002111 = "빙설의 눈기둥",
  str_skill_name_2002112 = "빙설의 눈기둥",
