  str_skill_name_30321101 = "서리의 창궁",
  str_skill_name_30321102 = "조각상의 그림자",
  str_skill_desc_2002111 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002112 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002113 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_30021101 = "가장 가까운 번개 속성 <color=#00F6FF>2</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「조각상의 그림자」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30021102 = "가장 가까운 숲 속성 <color=#00F6FF>2</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「서리의 창궁」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30021103 = "가장 가까운 번개 속성 <color=#00F6FF>3</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「조각상의 그림자」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30021104 = "가장 가까운 숲 속성 <color=#00F6FF>3</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「서리의 창궁」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30021105 = "가장 가까운 번개 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「조각상의 그림자」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30021106 = "가장 가까운 숲 속성 <color=#00F6FF>4</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「서리의 창궁」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30321101 = "가장 가까운 번개 속성 <color=#00F6FF>2</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 다음 액티브 스킬의 전환 칸 수가 <color=#00F6FF>3</color>개로 증가하며, 「조각상의 그림자」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30321102 = "가장 가까운 숲 속성 <color=#00F6FF>2</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 다음 액티브 스킬의 전환 칸 수가 <color=#00F6FF>3</color>개로 증가하며, 「서리의 창궁」의 스킬 쿨다운 턴 수가 1 증가한다.",
  str_skill_desc_30621103 = "가장 가까운 번개 속성 <color=#00F6FF>3</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「조각상의 그림자」의 스킬 쿨다운 턴 수가 1 증가한다. 턴 시작 시 두 액티브 스킬이 모두 쿨다운 상태일 경우 파티와 가장 가까운 물 속성이 아닌 칸 <color=#00F6FF>1</color>개를 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환한다.",
  str_skill_desc_30621104 = "가장 가까운 숲 속성 <color=#00F6FF>3</color>칸을 물 속성으로 전환한다. 해당 스킬 시전 후 「서리의 창궁」의 스킬 쿨다운 턴 수가 1 증가한다. 턴 시작 시 두 액티브 스킬이 모두 쿨다운 상태일 경우 파티와 가장 가까운 물 속성이 아닌 칸 <color=#00F6FF>1</color>개를 <color=#00F6FF>물 속성 </color><link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환한다.",
  str_skill_passive_name_410211 = "눈의 치유",
  str_skill_passive_name_420211 = "눈의 치유",
  str_skill_passive_name_430211 = "눈의 치유",
  str_skill_passive_desc_410211 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>절반</color>만큼 매번 피해를 입힌다. 일반공격 <color=#00F6FF>7</color>회마다 자신의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_420211 = "일반공격이 2연타로 변경되며, 기본 피해의 <color=#00F6FF>절반</color>만큼 매번 피해를 입힌다. 일반공격 <color=#00F6FF>7</color>회마다 자신의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 오로라 타임 진입 시 자신의 공격력의 <color=#00F6FF>100%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_passive_desc_430211 = "일반공격이 사선 방향을 공격할 수 있고, 십자 방향의 적에게는 2연타로 변경되며, 기본 피해의 <color=#00F6FF>절반</color>만큼 매번 피해를 입힌다. 일반공격 <color=#00F6FF>7</color>회마다 자신의 공격력의 <color=#00F6FF>{1}</color>만큼 파티의 HP를 회복시키며, 오로라 타임 진입 시 자신의 공격력의 <color=#00F6FF>100%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_upgrade_desc_16021113 = "액티브 스킬 강화: 색 변경 수량이 <color=#FFFF00>3개</color>로 증가한다.",
  str_skill_upgrade_desc_16021116 = "액티브 스킬 강화: 턴 시작 시 두 액티브 스킬이 모두 쿨다운 상태일 경우 파티와 가장 가까운 물 속성이 아닌 칸 <color=#00F6FF>1</color>개를 물 속성 짙은 칸으로 전환한다.",
  str_skill_name_200350101 = "대지 진동",
  str_skill_name_200350102 = "고통의 타격",
  str_skill_name_200350103 = "두개골 분쇄",
  str_skill_name_200350104 = "피 핥기",
  str_skill_desc_200350101 = "라임비스트가 지면을 내리쳐 십자형 최대 범위에 여러 차례의 피해를 입히고 적을 끝까지 넉백시킨다.",
  str_skill_desc_200350102 = "적이 자신의 주변 1서클 내에 있을 시 라임비스트가 적에게 피해를 입히고 한 칸 뒤로 넉백시킨다.",
  str_skill_desc_200350103 = "라임비스트 주변 특정 범위 내에 적이 있고, 해당하는 십자 방향에 장애물이 없을 경우 라임비스트가 빠르게 적에게 접근, 강타하여 피해를 입히고, 중심 구역의 적에게 더 높은 피해를 입힌 후 스턴시킨다.",
  str_skill_desc_200350104 = "근처에 적이 없을 경우 라임비스트가 HP를 회복한다.",
  str_skill_name_200360102 = "추적",
  str_skill_desc_200360102 = "플레이어 근처로 순간이동해 전방 1칸 내의 대상에게 여러 차례의 피해를 입히고 넉백시킨다. 순간이동 거리가 멀수록 공격 횟수가 감소한다.",
  str_skill_name_290213101 = "영원한 유적",
  str_skill_name_290213102 = "수호의 심판",
  str_skill_name_290213103 = "지정 위협",
  str_skill_desc_290213101 = "순간이동해 피해를 입힌 후 오로리안 주변 1서클 내 랜덤 3칸을 숲 속성 칸으로 전환한다.",
  str_skill_desc_290213102 = "순간이동해 피해를 입힌 후 오로리안 주변 1서클 내 랜덤 3칸을 번개 속성 칸으로 전환한다.",
  str_skill_desc_290213103 = "자신의 주변 2서클 내 물 속성 칸의 에너지를 흡수해 오로리안을 공격한다(흡수한 칸이 많을수록 피해 증가).",
  str_skill_desc_200270201 = "일루미나 무전병의 HP를 회복하고, 자신에게 누적된 적혈 수치 일부를 HP로 전환한다.",
  str_skill_desc_200280201 = "일루미나 전투병 2명을 전장에 소환한다.",
  str_skill_desc_200280202 = "일루미나 전투병 1명과 일루미나 장교 1명을 전장에 소환한다.",
  str_skill_desc_200280301 = "일루미나 화염방사병 2명을 전장에 소환한다.",
  str_skill_desc_200280302 = "일루미나 화염방사병 1명과 일루미나 장교 1명을 전장에 소환한다.",
  str_skill_name_290280111 = "가로베기",
  str_skill_desc_290280111 = "산키가 대상을 향해 이동한 후 에이카쿠를 휘둘러 피해를 입힌다.",
  str_skill_name_290280121 = "난무",
  str_skill_desc_290280121 = "제자리에서 칼날의 난무를 시전해 공격 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_290280131 = "송곳니 돌격",
  str_skill_desc_290280131 = "에이카쿠의 유도에 따라 대상 곁으로 돌진해 2단 피해를 입힌다.",
  str_skill_name_290280141 = "4방향 투척",
  str_skill_desc_290280141 = "산키의 본체가 행동하기 전 4개 방향으로 에이카쿠를 투척하며, 에이카쿠가 경로상의 대상에게 피해를 입힌다.",
  str_skill_name_290280151 = "도검 회수",
  str_skill_desc_290280151 = "산키의 본체가 행동하기 전 필드의 모든 에이카쿠를 회수하며, 에이카쿠가 경로상의 대상에게 피해를 입힌다.",
  str_skill_name_290280112 = "가로베기",
  str_skill_desc_290280112 = "가장 가까운 암귀에게 접근해 에이카쿠를 휘둘러 대량의 피해를 입힌다.",
  str_skill_name_290280122 = "난무",
  str_skill_desc_290280122 = "암귀가 밀집한 위치로 이동, 칼날의 난무를 시전해 일정 범위 내의 모든 암귀에게 피해를 입힌다.",
  str_skill_name_700110233 = "추방-불사자의 맹공",
  str_skill_name_700110234 = "추방-진압권",
  str_skill_name_700110235 = "추방-터빈 흡수",
  str_skill_desc_700110233 = "이동 후 상하좌우 방향의 대상을 공격한다.",
  str_skill_desc_700110234 = "범위 공격을 가해 마름모 12칸에 피해를 입힌다.",
  str_skill_desc_700110235 = "글러브의 증가된 압력이 적을 근처로 끌어당기며, 파괴적인 일격으로 피해를 입힌다.",
  str_skill_name_700110413 = "추방-뇌신",
  str_skill_name_700110414 = "추방-정도의 위엄",
  str_skill_name_700110415 = "추방-임페리얼 썬더",
  str_skill_desc_700110413 = "이동 후 주변 대상을 공격한다.",
  str_skill_desc_700110414 = "이동 후 쌍십자형 16칸에 번개를 소환해 적에게 피해를 입힌다.",
  str_skill_desc_700110415 = "전체화면 범위 내의 적에게 피해를 입히고, 현재 HP의 10%만큼 피해를 입힌다.",
  str_skill_desc_700110416 = "이동 후 쌍십자형 16칸에 번개를 소환해 적에게 피해를 입힌다.",
  str_skill_desc_700110417 = "전체화면 범위 내의 적에게 피해를 입히고, 현재 HP의 15%만큼 피해를 입힌다.",
  str_skill_name_111807112 = "고대 스크롤의 비밀",
  str_skill_desc_111807112 = "획득 시 공격력과 방어력 증가",
  str_skill_name_111807113 = "스크롤 습득자",
  str_skill_desc_111807113 = "필드의 양피지 스크롤을 습득한다.",
  str_skill_name_111807111 = "스크롤 소환자",
  str_skill_desc_111807111 = "사망 시 랜덤 위치에 양피지 스크롤 3개를 소환한다.",
  str_skill_name_111807212 = "스크롤 소환자",
  str_skill_desc_111807212 = "사망 시 랜덤 위치에 양피지 스크롤 5개를 소환한다.",
  str_skill_name_2002131 = "지정 위협",
  str_skill_name_2102131 = "지정 위협",
  str_skill_desc_2002131 = "가장 가까운 적 1명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 연쇄 수에 따라 피해 보너스가 증가한다.",
  str_skill_desc_2102131 = "가장 가까운 적 1명에게 기존의 30%에 해당하는 피해를 3회 입히고, 이번 턴에 자신이 가한 일반공격 횟수 보너스가 적용된다.",
  str_skill_name_300213 = "영역 제어",
  str_skill_desc_300213 = "1칸을 선택해 해당 칸의 속성을 일시적으로 숨기고, 해당 칸을 중심으로 <color=#00F6FF>정방형 25칸</color> 범위의 영역을 형성한다. <color=#00F6FF>15초</color> 카운트다운 동안 지속적으로 터치해 인접 칸의 속성을 전환할 수 있고, 카운트다운이 끝나면 나머지 빈칸은 <color=#00F6FF>번개 속성 칸</color>으로 전환된다. 이번 전투에서 1회만 시전할 수 있다.",
  str_skill_name_302213 = "영역 제어",
  str_skill_desc_302213 = "1칸을 선택해 해당 칸의 속성을 일시적으로 숨기고, 해당 칸을 중심으로 <color=#00F6FF>정방형 25칸</color> 범위의 영역을 형성한다. <color=#00F6FF>15초</color> 카운트다운 동안 지속적으로 터치해 인접 칸의 속성을 전환할 수 있고, 카운트다운이 끝나면 나머지 빈칸은 <color=#00F6FF>번개 속성 칸</color>으로 전환된다. 전투 진입 시/2웨이브 진입 시에 시전 기회가 각 1회씩 주어진다.",
  str_skill_name_305213 = "영역 제어",
  str_skill_desc_305213 = "1칸을 선택해 해당 칸의 속성을 일시적으로 숨기고, 해당 칸을 중심으로 <color=#00F6FF>정방형 25칸</color> 범위의 영역을 형성한다. <color=#00F6FF>15초</color> 카운트다운 동안 지속적으로 터치해 인접 칸의 속성을 전환할 수 있고, 카운트다운이 끝나면 나머지 빈칸은 <color=#00F6FF>번개 속성 칸</color>으로 전환된다. 전투 진입 시/2웨이브 진입 시/7번째 턴에 시전 기회가 각 1회씩 주어진다.",
  str_skill_passive_name_410213 = "분쇄의 시간",
  str_skill_passive_desc_410213 = "콤보 수 <color=#00F6FF>{1}</color> 도달 시 연쇄 스킬이 기존의 30%에 해당하는 피해를 3회 입히는 것으로 변경되며, 이번 턴에 자신이 가한 일반공격 횟수 보너스가 적용된다.",
  str_skill_passive_name_420213 = "분쇄의 시간",
  str_skill_passive_desc_420213 = "콤보 수 <color=#00F6FF>{1}</color> 도달 시 연쇄 스킬이 기존의 30%에 해당하는 피해를 3회 입히는 것으로 변경되며, 이번 턴에 자신이 가한 일반공격 횟수 보너스가 적용된다. <color=#00F6FF>연결 속성을 무시</color>하고 시전할 수 있다.",
  str_skill_passive_name_430213 = "분쇄의 시간",
  str_skill_passive_desc_430213 = "콤보 수 <color=#00F6FF>{1}</color> 도달 시 연쇄 스킬이 기존의 30%에 해당하는 피해를 3회 입히는 것으로 변경된다. 이번 턴에 자신이 가한 일반공격 횟수 보너스가 적용되며, <color=#00F6FF>연결 속성을 무시</color>하고 시전할 수 있다. 연결 후 칸을 보충할 때 이번 연결의 N번째 칸(N=남은 턴 수)을 번개 속성으로 전환한다.",
  str_skill_upgrade_desc_15021312 = "액티브 스킬 강화: 2웨이브 진입 시 시전 기회가 1회 주어진다.",
  str_skill_upgrade_desc_15021315 = "액티브 스킬 강화: 7번째 턴 진입 시 시전 기회가 1회 주어진다.",
  str_skill_name_53520212 = "소환",
  str_skill_desc_53520212 = "자신의 주변에 오로리안이 있을 시 우선적으로 공격하며, 없을 시 더 많은 백야성 장창병을 소환해 전투를 돕도록 한다.",
  str_skill_name_53520213 = "격려",
  str_skill_desc_53520213 = "자신의 주변에 오로리안이 있을 시 우선적으로 공격하며, 없을 시 자신의 주변에 있는 백야성 병사를 격려해 대상의 공격력을 증가시킨다.",
  str_skill_name_53520411 = "지정 위협",
  str_skill_desc_53520411 = "자신의 주변 2서클 내 물 속성 칸의 에너지를 흡수해 적에게 피해를 입히며, 흡수한 칸이 많을수록 피해가 증가한다.",
  str_skill_name_53520412 = "지정 위협",
  str_skill_desc_53520412 = "자신의 주변 2서클 내 불 속성 칸의 에너지를 흡수해 적에게 피해를 입히며, 흡수한 칸이 많을수록 피해가 증가한다.",
  str_skill_name_53520413 = "지정 위협",
  str_skill_desc_53520413 = "자신의 주변 2서클 내 숲 속성 칸의 에너지를 흡수해 적에게 피해를 입히며, 흡수한 칸이 많을수록 피해가 증가한다.",
  str_skill_name_5352031 = "치명적 폭발",
  str_skill_desc_5352031 = "일정 시간마다 폭발해 필드 내 모든 대상에게 피해를 입힙니다.",
  str_skill_name_29089011 = "「대심판관」의 심문",
  str_skill_name_29089012 = "「대심판관」의 판결",
  str_skill_name_29089014 = "「대심판관」의 심문",
  str_skill_desc_29089011 = "대상의 지난 턴 위치에 성스러운 빛을 시전해 경로 및 인접 칸의 대상에게 피해를 입히며, 피해 수치는 대상의 「편견」 상태 수에 따라 증가한다.",
  str_skill_desc_29089012 = "대상의 위치를 조준해 대량의 피해를 입히고, 피해 수치는 대상의 「편견」 상태 수에 따라 증가한다.",
  str_skill_desc_29089014 = "대상의 지난 턴 위치에 성스러운 빛을 시전해 경로 및 인접 칸의 대상에게 피해를 입히며, 피해 수치는 대상의 「편견」 상태 수에 따라 증가한다. 고정 위치에 배심원 조각상을 소환한다.",
  str_skill_name_29089021 = "「대심판관」의 심문",
  str_skill_desc_29089021 = "대상의 지난 턴 위치에 성스러운 빛을 시전해 경로 및 인접 칸의 대상에게 피해를 입히며, 피해 수치는 대상의 「편견」 상태 수에 따라 증가한다.",
  str_skill_name_290580101 = "카오스 블래스트",
  str_skill_name_290580102 = "에너지 핑거",
  str_skill_name_290580103 = "파멸을 향한 전진",
  str_skill_name_290580104 = "운명의 종결",
  str_skill_desc_290580101 = "전방 부채꼴 범위 내 모든 대상에게 피해를 입히고 끝까지 넉백시킨다.",
  str_skill_desc_290580102 = "순간이동 후 플레이어에게 피해를 입히고 2칸 넉백시킨다.",
  str_skill_desc_290580103 = "대상 주변 2서클 범위의 구역에 표식을 남기고, 적 턴 시작 시 표식이 있는 구역에 대량의 피해를 입히고 3칸 넉백시킨다.",
  str_skill_desc_290580104 = "에너지 비축 상태에 진입하며, 적 턴 시작 전 위치이동 또는 넉백되지 않을 시 플레이어에게 대량의 피해를 입힌다.",
  str_skill_desc_2905801011 = "전방 부채꼴 범위 내 모든 대상에게 피해를 입힌다.",
  str_skill_desc_2905801021 = "순간이동 후 플레이어에게 피해를 입힌다.",
  str_skill_desc_2905801031 = "대상 주변 2서클 범위의 구역에 표식을 남기고, 적 턴 시작 시 표식이 있는 구역에 대량의 피해를 입힌다.",
  str_skill_desc_2905801022 = "순간이동 후 플레이어에게 피해를 입히고, 침묵 상태를 추가한다.",
