  str_skill_desc_3001871 = "1칸을 선택해 랜덤으로 <color=#00F6FF>마름모 13칸</color> 범위 내의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>6</color>회 입힌다.",
  str_skill_desc_3051871 = "1칸을 선택해 랜덤으로 <color=#00F6FF>마름모 13칸</color> 범위 내의 적에게 <color=#00F6FF>90%</color>의 피해를 <color=#00F6FF>8</color>회 입힌다.",
  str_skill_passive_desc_410187 = "자신의 <color=#00F6FF>주변 1서클</color> 내에 적이 없을 시 연쇄 스킬의 각 단계 모두 <color=#00F6FF>25%</color>의 확률로 <color=#00F6FF>{1}</color>배의 피해를 입힌다.",
  str_skill_passive_desc_420187 = "자신의 <color=#00F6FF>주변 1서클</color> 내에 적이 없을 시 액티브 스킬과 연쇄 스킬의 각 단계 모두 <color=#00F6FF>25%</color>의 확률로 <color=#00F6FF>{1}</color>배의 피해를 입힌다.",
  str_skill_passive_desc_430187 = "자신의 <color=#00F6FF>주변 1서클</color> 내에 적이 없을 시 액티브 스킬과 연쇄 스킬의 각 단계 모두 <color=#00F6FF>25%</color>의 확률로 <color=#00F6FF>{1}</color>배의 피해를 입힌다. 자신의 <color=#00F6FF>주변 2서클</color> 내에 적이 없을 시 확률이 <color=#00F6FF>50%</color>로 증가한다.",
  str_skill_upgrade_desc_15018712 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15018715 = "액티브 스킬 강화: 액티브 스킬 피해 횟수가 8회로 증가한다.",
