  str_skill_desc_2001882 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2001883 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_300188 = "<color=#00F6FF>2</color>칸을 선택해 불 속성으로 전환하고, 두 칸의 경로 및 인접 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_306188 = "<color=#00F6FF>2</color>칸을 선택해 불 속성으로 전환하고, 두 칸의 경로 및 인접 칸에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 보스를 제외한 HP <color=#00F6FF>15%</color> 미만의 적을 즉시 처치한다.",
  str_skill_passive_desc_410188 = "이번 턴에 각 방향의 첫 번째 일반공격은 치명타가 되어 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420188 = "이번 턴에 각 방향의 첫 번째 일반공격은 치명타가 되어 <color=#00F6FF>{1}</color>의 피해를 입힌다. 오로라 타임 진입 시 모든 일반공격 방향의 치명타 횟수가 초기화된다.",
  str_skill_passive_desc_430188 = "일반공격이 <color=#00F6FF>사선 방향을 공격</color>할 수 있으며, 이번 턴에 각 방향의 첫 번째 일반공격은 치명타가 되어 <color=#00F6FF>{1}</color>의 피해를 입힌다. 오로라 타임 진입 시 모든 일반공격 방향의 치명타 횟수가 초기화된다.",
  str_skill_upgrade_desc_16018813 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16018816 = "액티브 스킬 강화: 피해율이 <color=#FFFF00>360%</color>로 증가하며, 범위 내 보스를 제외한 HP 15% 미만의 적을 즉시 처치한다.",
  str_skill_desc_1501301061 = "이동 후 가장 가까운 적 1명에게 피해를 입힌다.",
  str_skill_desc_1501301062 = "자신의 현재 HP을 소모해 잃은 HP에 따라 적에게 피해를 입히고, 출혈 상태를 추가한다.",
  str_skill_desc_1500921061 = "X형 8칸에 피해를 입힌다.",
  str_skill_desc_1500921062 = "X형 최대 범위에 피해를 입힌다.",
