  str_skill_desc_1601201061 = "이동 후 자신의 주변 마름모 12칸에 피해를 입히고, 주변 1서클에 추가 피해를 입힌다.",
  str_skill_desc_1601201062 = "자신의 주변 2서클에 피해를 입히고, 주변 1서클에 추가 피해를 입힌다.",
