  str_skill_desc_2201341 = "<color=#00F6FF>주변 3서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 칸나가 액티브 스킬 시전 시 이번 턴의 연쇄 스킬 범위가 <color=#00F6FF>1서클</color> 확대된다.",
  str_skill_desc_2201342 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 칸나가 액티브 스킬 시전 시 이번 턴의 연쇄 스킬 범위가 <color=#00F6FF>1서클</color> 확대된다.",
