  str_skill_desc_22013411 = "<color=#00F6FF>주변 3서클</color> 내의 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 칸나가 액티브 스킬 시전 시 이번 턴의 연쇄 스킬 범위가 <color=#00F6FF>1서클</color> 확대된다.",
  str_skill_desc_22013421 = "<color=#00F6FF>주변 3서클</color> 내의 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 칸나가 액티브 스킬 시전 시 이번 턴의 연쇄 스킬 범위가 <color=#00F6FF>1서클</color> 확대된다.",
  str_skill_desc_22013431 = "<color=#00F6FF>주변 3서클</color> 내의 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 칸나가 액티브 스킬 시전 시 이번 턴의 연쇄 스킬 범위가 <color=#00F6FF>1서클</color> 확대된다.",
  str_skill_desc_30013411 = "이동 가능한 칸 1개를 선택해 스킬의 시작점으로 삼고, 1칸을 선택해 해당 방향 <color=#00F6FF>경로</color> 및 <color=#00F6FF>인접</color> 칸의 적에게 공격력의 <color=#00F6FF>{1}%</color>에 해당하는 피해를 입히고 끝까지 넉백시킨다. <color=#00F6FF>경로</color>의 적에게는 <color=#00F6FF>1.3</color>배의 피해를 입힌다.",
