  str_skill_desc_2301331 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 2회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>25%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_2301332 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>140%</color>의 피해를 3회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>25%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_2301333 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>145%</color>의 피해를 4회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>25%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_2361331 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 2회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_2361332 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>140%</color>의 피해를 3회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_2361333 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>145%</color>의 피해를 4회 입히며, 동시에 대상 주변 <color=#00F6FF>십자형 4칸</color>에 <color=#00F6FF>30%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소하며, 토르가 액티브 스킬을 1회 시전할 때마다 연쇄 스킬의 피해 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_desc_16013311 = "스킬을 시전해 5회의 피해를 입히며, 동시에 주변 1서클 내 번개 속성이 아닌 칸을 초기화한다.",
  str_skill_name_16013411 = "파열 전환",
  str_skill_desc_16013411 = "자신의 주변 4칸을 불 속성 부서진 칸으로 바꾸며, 오로리안이 칸나 주변 4칸을 지날 때마다 1칸당 콤보 수가 10 증가한다.",
  str_skill_name_390040311 = "강화",
  str_skill_desc_390040311 = "제자리에서 강화 스킬을 시전하며, 방어력이 대폭 증가한다. 위치이동 효과를 받을 시 강화가 무효화된다.",
  str_skill_name_5362003 = "데스 스피어",
  str_skill_desc_5362003 = "발동 시 위에 있는 대상에게 고정피해를 입힌다.",
  str_skill_desc_5362004 = "스페큘러가 변신한 물체다. 스페큘러는 적과 가장 가까운 빛의 벽에 숨으며(해당 빛의 벽은 공격당할 수 있음), 모든 빛의 벽을 파괴하면 승리할 수 있다.",
  str_skill_desc_5362005 = "스페큘러가 이동 후 범위 내 대상에게 원거리 공격을 가하며, 턴마다 가장자리에서 환영 2개와 센터 1마리를 소환해 전장에 진입시킨다.",
  str_skill_desc_5362006 = "스페큘러가 대상의 근처로 이동해 피해를 입히고, 대상의 주변에 환영 2개와 센터 1마리를 소환해 전장에 진입시킨다.",
  str_skill_name_5362011 = "일반공격",
  str_skill_name_5362012 = "일반공격",
  str_skill_desc_5362011 = "이동 후 주변 1서클 범위 내 대상을 공격한다.",
  str_skill_desc_5362012 = "이동 후 세로 3열 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_5362013 = "이동 후 세로 3열 범위 내 대상에게 피해를 입힌다. 대상이 오로리안일 시 대상에게 중독 상태를 부여한다.",
  str_skill_desc_5362014 = "모든 적에게 피해를 입힌다.",
  str_skill_desc_5362015 = "오로리안을 3칸 넉백시키고 피해를 입힌다.",
  str_skill_name_290900101 = "패왕의 기세",
  str_skill_name_290900102 = "격분의 파도",
  str_skill_name_290900112 = "짧은 휴식",
  str_skill_desc_290900101 = "이동 후 오로리안을 공격하고, 1칸 넉백시킨다.",
  str_skill_desc_290900102 = "오로리안에게 피해를 입히고 끝까지 넉백시킨다.",
  str_skill_desc_290900112 = "잠시 쉬도록 하지. 어디 네가 얼마나 강한지 한번 볼까.",
  str_skill_desc_290900114 = "오로리안과 먼 위치로 이동한다.",
  str_skill_desc_290900124 = "플레이어와 같은 행 또는 열의 가장 먼 위치로 순간이동하며, 급류를 소환해 플레이어를 끝까지 넉백시킨다.",
  str_skill_name_20090011 = "포격 출동",
  str_skill_name_21090011 = "포격 출동",
  str_skill_desc_20090011 = "3서클 범위 내 적을 공격한다. 범위 내에 대상이 없을 경우 자신을 강화하고 공격력을 증가시킨다.",
  str_skill_desc_21090011 = "3서클 범위 내 적을 공격한다. 범위 내에 대상이 없을 경우 자신을 강화하고 공격력을 증가시키며, 어인 국왕의 HP를 회복한다.",
  str_skill_upgrade_desc_15021512 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_15021515 = "장비 스킬 강화: 추가 피해 계수가 <color=#00F6FF>150%</color>로 증가한다(각성 2단계 달성 시 적용).",
  str_skill_passive_name_410215 = "해피 아워",
  str_skill_passive_name_420215 = "해피 아워",
  str_skill_passive_name_430215 = "해피 아워",
  str_skill_passive_name_425215 = "해피 아워",
  str_skill_passive_name_435215 = "해피 아워",
  str_skill_passive_desc_410215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>{1}</color>의 피해를 3회 입힌다.",
  str_skill_passive_desc_420215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>{1}</color>의 피해를 3회 입힌다. 이사의 일반공격이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>100%</color>에 해당하는 추가 피해를 1회 입힌다.",
  str_skill_passive_desc_430215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>{1}</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>100%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다.",
  str_skill_passive_desc_425215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>{1}</color>의 피해를 3회 입힌다. 이사의 일반공격이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>150%</color>에 해당하는 추가 피해를 1회 입힌다.",
  str_skill_passive_desc_435215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>{1}</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>150%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다.",
  str_skill_name_2002151 = "성난 번개의 채찍",
  str_skill_name_2002152 = "성난 번개의 채찍",
  str_skill_name_2002153 = "성난 번개의 채찍",
  str_skill_desc_2002151 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002152 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002153 = "<color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_300215 = "채권 추심 요령",
  str_skill_desc_300215 = "적이 밟고 있는 칸 1개를 선택한 후 주변 4개 방향 중 1개를 선택, 보스를 제외한 적을 선택한 방향으로 1칸 강제 이동시키고 {1}%의 피해를 입힌다. 동시에 선택한 칸에 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 생성한다.",
  str_skill_upgrade_refine_desc_15021511 = "장비 스킬 강화: <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 피해를 3회 입히며, 회당 피해 계수가 <color=#00F6FF>65%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_15021512 = "장비 스킬 신규 효과: 이사와 레베카(각성 1단계 이상)가 함께 출전할 경우 이사의 장비 스킬이 입히는 추가 피해가 대상에게 <color=#00F6FF>신체 침식</color> 효과를 1회 추가한다.",
  str_skill_upgrade_refine_desc_15021513 = "장비 스킬 강화: 추가 피해 발동 조건이 <color=#00F6FF>6회</color>로 감소한다.",
  str_skill_passive_desc_440215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>100%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다.",
  str_skill_passive_desc_445215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>150%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다.",
  str_skill_passive_desc_450215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>100%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다. 이사와 레베카(각성 1단계 이상)가 함께 출전할 경우, 피해를 입힐 시 <color=#00F6FF>신체 침식</color> 효과를 1회 추가한다.",
  str_skill_passive_desc_455215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>7회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>150%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다. 이사와 레베카(각성 1단계 이상)가 함께 출전할 경우, 피해를 입힐 시 <color=#00F6FF>신체 침식</color> 효과를 1회 추가한다.",
  str_skill_passive_desc_460215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>6회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>100%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다. 이사와 레베카(각성 1단계 이상)가 함께 출전할 경우, 피해를 입힐 시 <color=#00F6FF>신체 침식</color> 효과를 1회 추가한다.",
  str_skill_passive_desc_465215 = "이사가 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>에서 일반공격을 가할 시 <color=#00F6FF>65%</color>의 피해를 3회 입힌다. 이사의 일반공격, 연쇄 스킬이 동일한 적에게 누적 <color=#00F6FF>6회</color>의 피해를 입히면 이사의 공격력의 <color=#00F6FF>150%</color>에 해당하는 추가 피해를 1회 입히며, 액티브 스킬이 대상에 명중할 경우 즉시 추가 피해를 1회 발동한다. 이사와 레베카(각성 1단계 이상)가 함께 출전할 경우, 피해를 입힐 시 <color=#00F6FF>신체 침식</color> 효과를 1회 추가한다.",
  str_skill_name_70011101 = "추방-독 흡수",
