  str_skill_desc_2202142 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_desc_2202143 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_desc_2302141 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_desc_2302142 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_desc_2302143 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_desc_2402141 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>145%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>2</color>회 추가한다.",
  str_skill_desc_2402142 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>160%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>2</color>회 추가한다.",
  str_skill_desc_2402143 = "<color=#00F6FF>쌍십자형 최대</color> 범위에 <color=#00F6FF>165%</color>의 피해를 입히고, 범위 내 대상에게 신체 침식 효과를 <color=#00F6FF>2</color>회 추가한다.",
  str_skill_desc_3002141 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 동시에 해당 칸과 가장 가까운 물 속성 칸 <color=#00F6FF>3</color>개를 물 속성 짙은 칸으로 전환한다.",
  str_skill_desc_3062141 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 동시에 해당 칸과 가장 가까운 물 속성 칸 <color=#00F6FF>5</color>개를 물 속성 짙은 칸으로 전환한다.",
  str_skill_passive_name_410214 = "독액 확산",
  str_skill_passive_desc_410214 = "짙은 칸을 지나갈 때마다 <color=#00F6FF>마름모 12칸</color> 범위에 <link=\"30094\"><#FFAE07><u>신체 침식</u></color></link> 효과를 추가하며, 적 턴 시작 시 대상의 신체 침식 단계마다 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_name_430214 = "독액 확산",
  str_skill_passive_desc_430214 = "짙은 칸을 지나갈 때마다 <color=#00F6FF>마름모 12칸</color> 범위에 <link=\"30094\"><#FFAE07><u>신체 침식</u></color></link> 효과를 추가하며, 적 턴 시작 시 대상의 신체 침식 단계마다 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 연쇄 스킬에 공격받은 적에게는 이번 턴의 신체 침식 효과가 방어무시 피해를 입힌다.",
  str_skill_upgrade_desc_16021413 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16021416 = "액티브 스킬 강화: 선택한 칸과 가장 가까운 물 속성 칸 <color=#FFFF00>5</color>개를 물 속성 짙은 칸으로 전환한다.",
  str_skill_upgrade_refine_desc_16021411 = "장비 스킬 강화: 신체 침식 단계마다 대상에게 레베카의 공격력의 <color=#00F6FF>40%</color>에 해당하는 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16021412 = "연쇄 스킬 강화: 연쇄 스킬이 범위 내의 대상에게 신체 침식 효과를 <color=#00F6FF>2</color>회 부여한다.",
  str_skill_upgrade_refine_desc_16021413 = "액티브 스킬 강화: 액티브 스킬 시전 시 신체 침식 효과를 지닌 대상에게 피해를 1회 입히며, 피해가 2배로 증가한다.",
  str_skill_passive_desc_440214 = "짙은 칸을 지나갈 때마다 <color=#00F6FF>마름모 12칸</color> 범위에 <link=\"30094\"><#FFAE07><u>신체 침식</u></color></link> 효과를 추가하며, 적 턴 시작 시 대상의 신체 침식 단계마다 공격력의 <color=#00F6FF>40%</color>에 해당하는 피해를 입힌다. 연쇄 스킬에 공격받은 적에게는 이번 턴의 신체 침식 효과가 방어무시 피해를 입힌다.",
  str_skill_desc_3402141 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 동시에 해당 칸과 가장 가까운 물 속성 칸 <color=#00F6FF>3</color>개를 물 속성 짙은 칸으로 전환한다. 또한 전체화면 범위 내 신체 침식 효과를 지닌 대상에게 피해를 1회 입히고, 피해가 2배로 증가한다.",
  str_skill_desc_3462141 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 동시에 해당 칸과 가장 가까운 물 속성 칸 <color=#00F6FF>5</color>개를 물 속성 짙은 칸으로 전환한다. 또한 전체화면 범위 내 신체 침식 효과를 지닌 대상에게 피해를 1회 입히고, 피해가 2배로 증가한다.",
