  str_skill_name_200380101 = "스피드스터",
  str_skill_desc_200380101 = "대상으로부터 최대한 멀어진 후 대상에게 피해를 2회 입힌다.",
  str_skill_name_200370101 = "원거리 화살",
  str_skill_desc_200370101 = "십자형 최대 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_290910102 = "독의 안개",
  str_skill_name_290910103 = "모여드는 독나비",
  str_skill_name_290910104 = "독나비 소환",
  str_skill_desc_290910102 = "이동 후 십자 방향 2칸 범위 내 대상을 공격하고, 「신체 융해」 효과를 2회 추가하며, 턴이 시작될 때마다 각 「신체 융해」 효과는 독에 잠식된 레베카의 공격력의 일정 퍼센트에 해당하는 피해를 입힌다.",
  str_skill_desc_290910103 = "대상에게서 멀어진 후 피해를 입히고, 「신체 융해」 효과를 1회 추가하며, 턴이 시작될 때마다 각 「신체 융해」 효과는 독에 잠식된 레베카의 공격력의 일정 퍼센트에 해당하는 피해를 입힌다.",
  str_skill_desc_290910104 = "이동 후 일정 범위에 피해를 입히고, 「신체 융해」 효과를 3회 추가하며, 범위 내에 랜덤으로 「독의 흔적」을 일정량 소환한다.",
  str_skill_name_200390101 = "기계 타격",
  str_skill_desc_200390101 = "가장 가까운 적 대상을 공격하며, 자신의 HP가 40% 미만일 시 더 멀리 이동한 후 자신의 HP를 일정 비율 회복한다.",
  str_skill_name_200390102 = "치유 지속 공격",
  str_skill_desc_200390102 = "자신의 HP를 일정 비율 회복한다.",
  str_skill_name_200410101 = "암살 공격",
  str_skill_desc_200410101 = "이동 후 대상을 두 번 공격하고, 최대 2칸 거리를 후퇴한다. 범위 내에 대상이 없을 시 다음 턴의 행동력이 증가한다.",
  str_skill_name_9997042 = "태양 플로터",
  str_skill_name_9997041 = "빙원 플로터",
  str_skill_name_9997043 = "나무 플로터",
  str_skill_name_9997044 = "천둥 플로터",
  str_skill_name_9997045 = "여명의 접시",
  str_skill_name_200140111 = "텐타클로-피해 회피",
  str_skill_desc_200140111 = "피해를 입으면 키티푸스의 본체로 피해를 전달하나, 오로리안이 연쇄 스킬을 시전하기 전 텐타클로가 몸을 숨겨 공격을 피한다.",
  str_skill_name_5000591 = "골도어-퇴치",
  str_skill_desc_5000591 = "모든 대상에게 피해를 1회 입히고 넉백시킨다.",
  str_skill_name_5000592 = "골도어-세례",
  str_skill_desc_5000592 = "전방의 모든 대상에게 피해를 1회 입힌다.",
  str_skill_name_5000593 = "줄행랑",
  str_skill_desc_5000593 = "오로리안이 액티브 스킬 시전 시 이동하며, 랜덤으로 번개 속성 칸을 불 속성 칸으로 전환한다.",
  str_skill_name_5000594 = "단결의 힘",
  str_skill_desc_5000594 = "어디에 있든지 항상 골도어의 근처로 향한다.",
  str_skill_name_29092001 = "고리침 회전참",
  str_skill_desc_29092001 = "비채가 자신의 주변 1서클 내의 대상에게 피해를 2회 입히고, 대상에게 출혈 효과를 추가한다.",
  str_skill_desc_290920011 = "비채가 자신의 주변 1서클 내의 대상에게 피해를 2회 입히고, 대상에게 출혈 및 치료금지 효과를 추가한다.",
  str_skill_name_29092002 = "강철의 돌격",
  str_skill_desc_29092002 = "비채가 십자 방향 내 플레이어가 있는 방향을 선택, 전장 가장자리 또는 가장 가까운 장애물까지 돌격하며, 경로상의 대상을 넉백시키고, 경로 양쪽 1칸의 대상에게 추가 피해와 출혈 효과를 추가한다.",
  str_skill_name_29092003 = "공뢰의 분심",
  str_skill_desc_29092003 = "비채가 꼬리에서 에너지를 방출해 대상에게 대량의 피해를 1회 입힌다.",
  str_skill_name_29092004 = "축력 찌르기",
  str_skill_desc_29092004 = "비채가 1칸 뒤로 도약하고 전방의 대상에게 피해를 입히며, 출혈 및 중독 효과를 추가한다.",
  str_skill_name_29092005 = "종횡 돌진",
  str_skill_desc_29092005 = "비채가 가로 및 세로로 2회 연속 돌진해 전방의 대상에게 피해를 입히며, 출혈 및 중독 효과를 추가한다.",
  str_skill_name_29092006 = "거울나비 반사",
  str_skill_desc_29092006 = "비채가 거울나비를 향해 뇌광을 발사, 거울나비의 반사광이 삼각형 경로를 형성해 경로상에 피해를 입힌다.",
  str_skill_name_2002161 = "기산의 견기",
  str_skill_name_2002162 = "기산의 견기",
  str_skill_name_2002163 = "기산의 견기",
  str_skill_name_2202161 = "기산의 견기",
  str_skill_name_2202162 = "기산의 견기",
  str_skill_name_2202163 = "기산의 견기",
  str_skill_name_300216 = "뇌광의 기철",
  str_skill_name_303216 = "뇌광의 기철",
  str_skill_passive_name_410216 = "잠자리의 번성",
  str_skill_passive_name_430216 = "잠자리의 번성",
  str_skill_desc_2002161 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002162 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002163 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2202161 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 「사방포뢰진」 내 랜덤 1명의 적에게 추가로 피해를 1회 입힌다.",
  str_skill_desc_2202162 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 「사방포뢰진」 내 랜덤 1명의 적에게 추가로 피해를 1회 입힌다.",
  str_skill_desc_2202163 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 「사방포뢰진」 내 랜덤 1명의 적에게 추가로 피해를 1회 입힌다.",
  str_skill_desc_300216 = "<link=\"30095\"><#FFAE07><u>공구</u></color></link> 3개를 소모해 1칸을 선택, <color=#00F6FF>정방형 9칸</color> 범위에 「사방포뢰진」을 생성한다. <color=#00F6FF>2</color>턴간 지속. 「사방포뢰진」 안에서는 선극의 <color=#00F6FF>일반공격이 사선 방향을 공격할 수 있게 된다</color>.",
  str_skill_desc_303216 = "<link=\"30095\"><#FFAE07><u>공구</u></color></link> 3개를 소모해 1칸을 선택, <color=#00F6FF>정방형 25칸</color> 범위에 「사방포뢰진」을 생성한다. <color=#00F6FF>3</color>턴간 지속. 「사방포뢰진」 안에서는 선극의 <color=#00F6FF>일반공격이 사선 방향을 공격할 수 있게 된다</color>.",
  str_skill_passive_desc_410216 = "선극이 「사방포뢰진」 안에서 입히는 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_416216 = "선극이 「사방포뢰진」 안에서 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 필드 내 「사방포뢰진」이 1개 늘어날 때마다 피해가 추가로 <color=#00F6FF>5%</color> 증가한다. 턴 종료 시 선극이 「사방포뢰진」 안에 있으면 공구 1개를 획득한다.",
  str_skill_passive_desc_430216 = "선극이 「사방포뢰진」 안에서 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 선극이 「사방포뢰진」 안에서 연쇄 스킬을 시전할 때마다 기본 공격력이 <color=#00F6FF>4%</color> 증가한다. 해당 효과는 최대 5회 중첩할 수 있다. 턴 종료 시 선극이 「사방포뢰진」 밖에 있으면 효과 단계가 절반으로 감소한다.",
  str_skill_passive_desc_436216 = "선극이 「사방포뢰진」 안에서 입히는 피해가 <color=#00F6FF>{1}</color> 증가하며, 필드 내 「사방포뢰진」이 1개 늘어날 때마다 피해가 추가로 <color=#00F6FF>5%</color> 증가한다. 선극이 「사방포뢰진」 안에서 연쇄 스킬을 시전할 때마다 기본 공격력이 <color=#00F6FF>4%</color> 증가하며, 해당 효과는 최대 5회 중첩할 수 있다. 턴 종료 시 선극이 「사방포뢰진」 밖에 있으면 효과 단계가 절반으로 감소하며, 「사방포뢰진」 안에 있으면 공구 1개를 획득한다.",
  str_skill_upgrade_desc_16021613 = "액티브 스킬 강화: 「사방포뢰진」의 범위가 <color=#00F6FF>정방형 25칸</color>으로 확대되며, <color=#00F6FF>3</color>턴간 지속된다.",
  str_skill_upgrade_desc_16021616 = "장비 스킬 강화: 필드 내 「사방포뢰진」이 1개 늘어날 때마다 피해가 추가로 <color=#00F6FF>5%</color> 증가한다. 턴 종료 시 선극이 「사방포뢰진」 안에 있으면 공구 1개를 획득한다.",
  str_skill_name_53820323 = "오로리안이 접근 시 폭발하며, 아무도 접근하지 않을 시 일정 턴 이후 자폭해 근처에 여러 개의 화염을 생성한다.",
  str_skill_name_200400103 = "화염 돌격",
  str_skill_name_200400104 = "화염 돌격",
  str_skill_desc_200400103 = "가로로 이동하면서 화염을 내뿜어 전방의 대상에게 피해를 입히고, 장애물을 만나면 이동을 멈춘다.",
  str_skill_desc_200400104 = "가로로 이동하면서 화염을 내뿜어 전방의 대상에게 피해를 입히고, 장애물을 만나면 이동을 멈춘다.",
  str_skill_name_290570123 = "머드번들-탐식",
  str_skill_desc_290570123 = "머드번들이 거대한 늪의 중심에서 뛰쳐나와 모든 것을 집어삼키고 오로리안에게 피해를 입힌다.",
  str_skill_name_290620102 = "공간 절단-위",
  str_skill_desc_290620102 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 가로로 베어 3칸 길이의 금제의 벽을 소환한 후 자신은 새로운 위치로 순간이동한다.",
  str_skill_name_290620104 = "공간 절단-경",
  str_skill_desc_290620104 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 세로로 베어 3칸 길이의 금제의 벽을 소환한 후 자신은 새로운 위치로 순간이동한다.",
  str_skill_name_290620106 = "산 자는 물러가라",
  str_skill_desc_290620106 = "사검이 주변 1서클 내의 적에게 피해를 입히고 가장 먼 곳으로 넉백시키며, 자신의 주변 1서클 가장자리에 금제의 벽을 소환한다.",
  str_skill_name_800400011 = "퇴마 기관",
  str_skill_desc_800400011 = "퇴마 기관을 밟으면 필드 내 모든 금제의 벽을 제거할 수 있다.",
  str_skill_desc_2900273 = "오로리안에게 피해를 입히고 골도어를 소환한다.",
  str_skill_desc_2000303 = "커스 골도어의 주변 1서클에 다가갈 시 금화를 바쳐 대상의 HP를 회복시킨다.",
  str_skill_desc_2000304 = "이스타반의 주변 1서클에 다가갈 시 금화를 바쳐 대상의 HP를 회복시킨다.",
  str_skill_desc_200381101 = "이동 범위가 증가하며, 대상 근처로 이동해 피해를 2회 입힌다. 장애물을 넘어 이동할 수 있다.",
  str_skill_desc_200411101 = "이동 후 대상을 두 번 공격하고, 대상을 넉백시킨 후 폭탄을 두며, 최대 3칸 거리를 후퇴한다. 범위 내에 대상이 없을 시 다음 턴의 행동력이 증가한다.",
  str_skill_desc_200371101 = "십자형 12칸 내의 적에게 피해를 주고 넉백시키며, 넉백 전 위치에 폭탄을 둔다.",
  str_skill_upgrade_desc_16021913 = "액티브 스킬 강화: 전투 진입 시 그림자의 선물 <color=#00F6FF>5</color>포인트를 획득한다.\n장비 스킬 강화: [행마] 스킬의 선택 가능 범위가 주변 2서클로 확대된다.",
  str_skill_upgrade_desc_16021916 = "신규 액티브 스킬 획득: 칸 <color=#00F6FF>2</color>개를 선택해 짙은 칸 상태를 전이시킨다. 만약 선택한 칸이 그림자 기물을 포함할 시 그림자 기물을 반대쪽 칸으로 이동시킨다.",
  str_skill_name_2002191 = "분멸의 발톱",
  str_skill_name_2002192 = "분멸의 발톱",
  str_skill_name_2002193 = "분멸의 발톱",
  str_skill_desc_2002191 = "<color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002192 = "<color=#00F6FF>주변 3서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002193 = "<color=#00F6FF>주변 4서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_3002191 = "캐슬링즈 실루엣",
  str_skill_name_3302191 = "캐슬링즈 실루엣",
  str_skill_name_3032191 = "캐슬링즈 실루엣",
  str_skill_name_3332191 = "캐슬링즈 실루엣",
  str_skill_name_3062191 = "팬텀 시프트",
  str_skill_desc_3002191 = "<color=#00F6FF>아군 팀원</color> 1명을 선택하고 <link=\"30096\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘린다</color>(효과 중첩 불가). 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용되며, 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3302191 = "<color=#00F6FF>아군 팀원</color> 1명을 선택하고 <link=\"30096\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘린다</color>(효과 중첩 불가). 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용되며, 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>50%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3032191 = "<color=#00F6FF>아군 팀원</color> 1명을 선택하고 <link=\"30097\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘린다</color>(효과 중첩 불가). 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용되며, 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3332191 = "<color=#00F6FF>아군 팀원</color> 1명을 선택하고 <link=\"30097\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘린다</color>(효과 중첩 불가). 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용되며, 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>50%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3062191 = "칸 <color=#00F6FF>2</color>개를 선택해 짙은 칸 상태를 전이시킨다. 만약 선택한 칸이 그림자 기물을 포함할 시 그림자 기물을 반대쪽 칸으로 이동시킨다.",
  str_skill_passive_name_410219 = "옛그림자의 승급",
  str_skill_passive_name_420219 = "옛그림자의 승급",
  str_skill_passive_name_403219 = "옛그림자의 승급",
  str_skill_passive_name_423219 = "옛그림자의 승급",
  str_skill_passive_desc_410219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다.\n[행마]: 주변 <color=#00F6FF>마름모 12칸</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_420219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다. 턴 종료 시 그림자 기물이 자신의 위치에 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 생성한다.\n[행마]: 주변 <color=#00F6FF>마름모 12칸</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_403219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다.\n[행마]: 주변 <color=#00F6FF>2서클</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_desc_423219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다. 턴 종료 시 그림자 기물이 자신의 위치에 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 생성한다.\n[행마]: 주변 <color=#00F6FF>2서클</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
