  str_skill_desc_160219118 = "주변 <color=#00F6FF>마름모 12칸</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_desc_160219119 = "주변 <color=#00F6FF>2서클</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_desc_160219120 = "주변 <color=#00F6FF>마름모 12칸</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>110%</color>의 피해를 입힌다.",
  str_skill_desc_160219121 = "주변 <color=#00F6FF>2서클</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>110%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16021911 = "장비 스킬 강화: [행마] 스킬의 피해가 <color=#00F6FF>110%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16021912 = "액티브 스킬 강화: 그림자 기물을 선택해 액티브 스킬 시전 시 해당 턴에 그림자 기물이 시전하는 연쇄 스킬의 최종 피해 보너스가 <color=#00F6FF>60%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16021913 = "액티브 스킬 강화: 웨이브가 시작될 때마다 그림자의 선물 <color=#00F6FF>2</color>포인트를 획득한다.",
  str_skill_passive_desc_450219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다. 턴 종료 시 그림자 기물이 자신의 위치에 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 생성한다.\n[행마]: 주변 <color=#00F6FF>마름모 12칸</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>110%</color>의 피해를 입힌다.",
  str_skill_passive_desc_453219 = "전투 진입 시 이스타반 더 스칼드 피스가 파티 주변에 그림자 기물을 1개 소환하고, 그림자 기물을 조종해 스킬을 시전할 수 있다. 턴 종료 시 그림자 기물이 자신의 위치에 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 생성한다.\n[행마]: 주변 <color=#00F6FF>2서클</color> 내 이동 가능한 칸으로 순간이동하며, <color=#00F6FF>주변 2서클</color> 내 가장 가까운 적 4명에게 <color=#00F6FF>110%</color>의 피해를 입힌다.",
  str_skill_desc_3602191 = "<link=\"30096\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모, <color=#00F6FF>아군 팀원</color> 1명을 선택해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘리며</color>(효과 중첩 불가), 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용된다. 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>60%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3632191 = "<link=\"30097\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모, <color=#00F6FF>아군 팀원</color> 1명을 선택해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘리며</color>(효과 중첩 불가), 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용된다. 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>60%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3702191 = "<link=\"30099\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모, <color=#00F6FF>아군 팀원</color> 1명을 선택해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘리며</color>(효과 중첩 불가), 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용된다. 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>60%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_desc_3732191 = "<link=\"30098\"><#FFAE07><u>그림자의 선물</u></color></link> <color=#00F6FF>2</color>포인트를 소모, <color=#00F6FF>아군 팀원</color> 1명을 선택해 이번 턴의 <color=#00F6FF>연쇄 스킬 시전 횟수를 1회 늘리며</color>(효과 중첩 불가), 추가 시전 시 팀원의 공격력은 이스타반 더 스칼드 피스의 공격력의 <color=#00F6FF>100%</color>가 적용된다. 이스타반 더 스칼드 피스는 이번 턴에 연쇄 스킬을 시전하지 않는다. 또는 그림자의 선물 <color=#00F6FF>2</color>포인트를 소모, 필드의 그림자 기물을 선택해 액티브 스킬을 시전하며, 이번 턴에 그림자 기물이 이스타반 더 스칼드 피스 대신 연쇄 스킬을 시전하고, 최종 피해가 <color=#00F6FF>60%</color> 증가한다. 그림자 기물을 선택해 시전할 시 그림자의 선물 소모량은 2포인트로 고정되며, 해당 전투 중 동일한 팀원에게 액티브 스킬을 시전할 때마다 그림자의 선물 소모량이 1 증가한다.",
  str_skill_name_2002201 = "감별의 혜안",
  str_skill_name_2002202 = "감별의 혜안",
  str_skill_name_2002203 = "감별의 혜안",
  str_skill_name_3002201 = "팔방미인",
  str_skill_name_3002202 = "팔방미인",
