  str_skill_name_3052202 = "팔방미인",
  str_skill_name_3022201 = "팔방미인",
  str_skill_desc_20022011 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>125%</color>의 피해를 2회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002202 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002203 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>135%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_3002201 = "가장 가까운 번개 속성 <color=#00F6FF>2</color>칸을 물 속성 짙은 칸으로 전환한다.",
  str_skill_desc_3002202 = "가장 가까운 번개 속성 <color=#00F6FF>2</color>칸을 물 속성 짙은 칸으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3052201 = "가장 가까운 번개 속성 <color=#00F6FF>3</color>칸을 물 속성 짙은 칸으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_desc_3052202 = "가장 가까운 번개 속성 <color=#00F6FF>3</color>칸을 물 속성 짙은 칸으로 전환하며, 액티브 스킬이 이전 턴에 준비되면 이번 턴의 색 변경 수량이 <color=#00F6FF>1</color> 증가한다.",
  str_skill_passive_name_410220 = "어센틱 라이트",
  str_skill_passive_name_420220 = "어센틱 라이트",
  str_skill_passive_name_430220 = "어센틱 라이트",
  str_skill_passive_desc_410220 = "턴이 시작될 때마다 필드 내 가장 먼 적 1명에게 <color=#00F6FF>감정</color> 효과를 추가하며, 1턴간 지속된다. 감정 효과를 지닌 대상이 타깃형 연쇄 스킬 공격을 1회 받을 때마다 추가로 버질의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_420220 = "턴이 시작될 때마다 필드 내 가장 먼 적 1명에게 <color=#00F6FF>감정</color> 효과를 추가하며, 1턴간 지속된다. 오로라 타임 진입 시 해당 효과가 추가로 1회 발동한다. 감정 효과를 지닌 대상이 타깃형 연쇄 스킬 공격을 1회 받을 때마다 추가로 버질의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_430220 = "턴이 시작될 때마다 필드 내 가장 먼 적 1명에게 <color=#00F6FF>감정</color> 효과를 추가하며, 1턴간 지속된다. 오로라 타임 진입 시 해당 효과가 추가로 1회 발동한다. 감정 효과를 지닌 대상이 타깃형 연쇄 스킬 공격을 1회 받을 때마다 추가로 버질의 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입히며, 대상이 버질의 연쇄 스킬 공격을 받을 시 추가 공격의 피해가 2배로 증가한다.",
  str_skill_upgrade_desc_15022012 = "액티브 스킬 강화: 액티브 스킬이 이전 턴에 준비되면 이번 턴의 물 속성 짙은 칸 변경 수량이 1 증가한다.",
  str_skill_upgrade_desc_15022015 = "액티브 스킬 강화: 물 속성 짙은 칸 변경 수량이 1 증가한다.",
  str_skill_desc_290910114 = "이동 후 일정 범위에 피해를 입히고, 「신체 융해」 효과를 3회 추가한다.",
  str_skill_desc_290910124 = "이동 후 일정 범위에 피해를 입히고, 「신체 융해」 효과를 3회 추가하며, 「독의 흔적」을 대량으로 소환한다.",
  str_skill_name_16021911 = "일반공격",
  str_skill_desc_16021911 = "이동 후 일반공격을 진행하며, 대상을 일격에 처치한다.",
  str_skill_desc_16021912 = "이동 후 연쇄 스킬을 시전해 각 대상의 최대 HP의 40%에 해당하는 피해를 입힌다.",
