  str_skill_passive_name_436218 = "자본론",
  str_skill_desc_2002181 = "고정 순서로 <color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>150%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002182 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>155%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002183 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>165%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002184 = "고정 순서로 <color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>150%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다.",
  str_skill_desc_2002185 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>155%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다.",
  str_skill_desc_2002186 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>165%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다.",
  str_skill_desc_2202181 = "고정 순서로 <color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>150%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_2202182 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>155%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_2202183 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>165%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_2202184 = "고정 순서로 <color=#00F6FF>주변 2서클</color> 내의 적에게 <color=#00F6FF>150%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_2202185 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>155%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_2202186 = "고정 순서로 <color=#00F6FF>주변 3서클</color> 내의 적에게 <color=#00F6FF>165%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다. 추가로 가장 먼 대상에게 피해를 1회 입히며, 횟수에 따라 피해가 감소하지 않는다. 이번 연결이 짙은 칸을 1개 지날 때마다 연쇄 스킬 범위가 1서클 확대된다.",
  str_skill_desc_3002181 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_30021811 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3402181 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3412181 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3402182 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 현재 보유 중인 캐피탈 크레딧 5포인트마다 배당으로 캐피탈 크레딧을 1포인트 획득한다.",
  str_skill_desc_3412182 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 현재 보유 중인 캐피탈 크레딧 5포인트마다 배당으로 캐피탈 크레딧을 1포인트 획득한다.",
  str_skill_desc_30021812 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_300218112 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_34021812 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_34121812 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_34021822 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>십자형 5칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다. 현재 보유 중인 캐피탈 크레딧 5포인트마다 배당으로 캐피탈 크레딧을 1포인트 획득한다.",
  str_skill_desc_34121822 = "1칸을 선택해 물 속성 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하며, <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>150%</color>의 피해를 입힌다. 현재 보유 중인 캐피탈 크레딧 5포인트마다 배당으로 캐피탈 크레딧을 1포인트 획득한다.",
  str_skill_passive_desc_410218 = "샤엘이 전투 진입 후 자신에게 <link=\"510218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_passive_desc_413218 = "샤엘이 전투 진입 후 자신에게 <link=\"513218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_passive_desc_416218 = "샤엘이 전투 진입 후 자신에게 <link=\"516218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 5포인트 획득한다. 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_passive_desc_430218 = "샤엘이 전투 진입 후 자신에게 <link=\"530218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_passive_desc_433218 = "샤엘이 전투 진입 후 자신에게 <link=\"533218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_passive_desc_436218 = "샤엘이 전투 진입 후 자신에게 <link=\"536218\"><#FFAE07><u>[투자 전략]</u></color></link>을 적용하며, 캐피탈 크레딧을 5포인트 획득한다. 캐피탈 크레딧을 누적해 투자 전략을 선택하고, 해당하는 전투 능력을 획득할 수 있다. 1회차 투자 후 이어서 2회차 투자를 진행하며, 1회차 때 획득하지 못한 전투 능력을 획득할 수 있다. 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(투자 전략 중 「안개 조종」, 「일확억금」, 「자본 타격」은 장비 레벨 3/6/10 도달 후 개방).",
  str_skill_upgrade_desc_16021813 = "장비 스킬 강화: 2회차 투자 후 캐피탈 크레딧을 1포인트 획득할 때마다 샤엘의 공격력이 1% 증가하며, 최대 40포인트까지 적용된다(각성3 개방).",
  str_skill_upgrade_desc_16021816 = "전투 진입 시 캐피탈 크레딧을 5포인트 보유하며, 액티브 스킬 시전 시 현재 보유 중인 캐피탈 크레딧 5포인트마다 배당으로 캐피탈 크레딧을 1포인트 획득한다.",
  str_skill_name_53920111 = "일반공격",
  str_skill_desc_53920111 = "이동 후 적에게 일반공격을 가하고 대량의 피해를 입힌다.",
  str_skill_desc_53920112 = "이동 후 주변 2서클 범위 내의 적에게 피해를 입힌다.",
  str_skill_desc_53920214 = "파티가 짙은 칸을 지날 시 샤엘이 주변 2서클 범위 내의 적에게 피해를 2회 입힌다.",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>액티브 스킬 진화 획득</color>: <color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소하며</color>, 액티브 스킬이 물 속성 짙은 칸을 생성하지 않고, 피해만 입힌다.",
  str_skill_upgrade_refine_desc_16021812 = "액티브 스킬 강화: 피해가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16021813 = "장비 스킬 강화: 투자 전략 중 2회차 투자의 캐피탈 크레딧 조건이 1포인트 감소한다.",
  str_skill_name_70011191 = "추방-악령의 회오리",
  str_skill_desc_70011191 = "대상이 범위 내에 있을 시 전방 2서클 범위 내 오로리안과 「오니」를 삼켜 오로리안에게 피해를 입히며, 이후 대상을 외곽으로 토해낸다.",
  str_skill_name_70011192 = "추방-악령의 소멸",
  str_skill_desc_70011192 = "대상이 범위 내에 있을 시 대상에게 대량의 피해를 입히고, 대상 주변의 모든 「오니」를 처치한다.",
  str_skill_name_70011193 = "추방-악령의 진",
  str_skill_desc_70011193 = "대상이 범위 내에 있을 시 대량의 「오니」를 소환하며, 필드 내 모든 「오니」를 강화한다.",
  str_skill_name_70011195 = "추방-악령의 회오리",
  str_skill_desc_70011195 = "대상이 범위 내에 있을 시 전방 2서클 범위 내 오로리안과 「오니」를 삼켜 오로리안에게 고정피해를 입히며, 삼킨 「오니」의 수가 많을수록 피해가 증가한다. 이후 대상을 외곽으로 토해낸다.",
  str_skill_name_200440103 = "파괴의 타격",
  str_skill_name_200450103 = "연속 폭파",
  str_skill_name_200460103 = "무장 돌격",
  str_skill_name_200460104 = "섬멸 타격",
  str_skill_desc_200440103 = "무기를 휘둘러 오로리안에게 피해를 입힌다.",
  str_skill_desc_200450103 = "십자형 최대 범위 내 오로리안에게 피해를 입힌다.",
  str_skill_desc_200460103 = "이동 후 오로리안에게 피해를 입힌다.",
  str_skill_desc_200460104 = "이동 후 오로리안의 위치를 향해 관통 공격을 가하며, 피아 구분 없이 피해를 입힌 후 자신의 HP가 일정량 감소한다.",
  str_skill_name_8004003 = "오로리안이 접근 시 폭발하며, 아무도 접근하지 않을 시 일정 턴 이후 자폭해 근처에 1칸 길이의 금제의 벽을 생성한다.",
  str_skill_desc_8004039 = "이번 턴 피해 폭발: 드레드블레이드가 칼날을 휘둘러 공격 범위 내 대상을 2회 공격하며, 매우 큰 피해를 입힌다.",
  str_skill_name_8004039 = "더블 슬래시+",
  str_skill_desc_8004055 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 가로로 베어 5칸 길이의 금제의 벽을 소환한 후 자신은 새로운 위치로 순간이동한다.",
  str_skill_desc_8004057 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 세로로 베어 5칸 길이의 금제의 벽을 소환한 후 자신은 새로운 위치로 순간이동한다.",
  str_skill_desc_8004051 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 가로로 베어 3칸 길이의 금제의 벽을 소환한 후 자신은 제자리로 순간이동한다.",
  str_skill_desc_8004053 = "사검이 아군 근처로 돌진해 피해를 입히고, 아군 주변을 세로로 베어 3칸 길이의 금제의 벽을 소환한 후 자신은 제자리로 순간이동한다.",
  str_skill_name_8004012 = "소환-체이스비 데드아이+",
  str_skill_desc_8004012 = "턴마다 데드아이와 체이스비 각 1마리를 전장에 소환한다.",
  str_skill_desc_8004022 = "퇴마 기관을 밟으면 다음 턴부터 오로리안 주변 금제의 벽이 주변 3서클로 확장된다.",
  str_skill_desc_8004040 = "퇴마 기관을 밟으면 적의 주변에 금제의 벽을 소환할 수 있다.",
  str_skill_desc_8004050 = "퇴마 기관을 밟으면 주변 2서클 내 금제의 벽을 제거할 수 있다.",
  str_skill_name_290640101 = "만물 유린",
  str_skill_name_290640102 = "출력 공격",
  str_skill_name_290640103 = "부품 교체",
  str_skill_desc_290640101 = "이동 후 자신의 HP 일정 퍼센트와 모든 기계 갑주 단계를 소모, 전방 2칸 범위 내의 대상을 공격하며, 대상이 브로거움과 인접한 경우 대상을 뒤로 1칸 넉백시킨다. 공격 후 소모한 기계 갑주 단계 수에 따라 자신의 HP를 회복한다.",
  str_skill_desc_290640102 = "전방 부채꼴 범위 내 모든 대상에게 피해를 입히며, 대상과 거리가 가까울수록 피해가 증가한다.",
  str_skill_desc_290640103 = "브로거움이 힘을 축적해 자신의 공격력, 방어력, 최대 HP를 영구적으로 증가시키며, 동시에 기계 갑주 상태를 일정 횟수 획득한다.",
  str_skill_name_29063011 = "풍속의 압박",
  str_skill_name_29063012 = "오로리안이 있는 위치를 조준해 외곽까지 돌진하며, 경로 범위 내의 적에게 피해를 입힌다.",
  str_skill_name_29063013 = "신체 개조",
  str_skill_desc_29063011 = "오로리안을 향해 이동한 후 전방 2칸 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_29063012 = "데이터 타격",
  str_skill_desc_29063013 = "율리시스가 가디언 프로토타입을 이용해 오로리안이 어떤 위치에 있든지 피해를 입힌다.",
  str_skill_name_2002211 = "이진 트리 분화",
  str_skill_name_2002212 = "이진 트리 분화",
  str_skill_name_2002213 = "이진 트리 분화",
  str_skill_desc_2002211 = "부르가 <color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002212 = "부르가 <color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002213 = "부르가 <color=#00F6FF>쌍십자형 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_name_300221 = "죽음의 대입",
  str_skill_name_306221 = "죽음의 대입",
  str_skill_name_320221 = "죽음의 대입",
  str_skill_name_326221 = "죽음의 대입",
  str_skill_name_340221 = "죽음의 대입",
  str_skill_name_346221 = "죽음의 대입",
  str_skill_desc_300221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 1서클</color> 내 3칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_306221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 마름모 12칸</color> 내 4칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 1서클</color> 내 3칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 피해 1회당 연산값 1포인트를 획득한다.",
  str_skill_desc_326221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 마름모 12칸</color> 내 4칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 피해 1회당 연산값 1포인트를 획득한다.",
  str_skill_desc_340221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 1서클</color> 내 3칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>250%</color>의 피해를 입히며, 피해 1회당 연산값 1포인트를 획득한다.",
  str_skill_desc_346221 = "1칸을 선택한 후 해당 칸 <color=#00F6FF>주변 마름모 12칸</color> 내 4칸을 선택해 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>으로 전환하고, 부르가 해당 범위에 <color=#00F6FF>250%</color>의 피해를 입히며, 피해 1회당 연산값 1포인트를 획득한다.",
  str_skill_passive_name_410221 = "나노미터 매직 넘버",
  str_skill_passive_name_430221 = "나노미터 매직 넘버",
  str_skill_passive_name_440221 = "나노미터 매직 넘버",
  str_skill_passive_name_443221 = "나노미터 매직 넘버",
  str_skill_passive_desc_410221 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 지날 때마다 연산값 1포인트를 획득하며, 연산값 1포인트마다 부르의 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 연산값의 절반이 유지된다.",
  str_skill_passive_desc_430221 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 지날 때마다 연산값 1포인트를 획득하며, 연산값 1포인트마다 부르의 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴 종료 시 연산값의 절반이 유지된다. 행동 종료 후 현재 연산값이 <color=#00F6FF>3</color> 이상일 시 부르에게 가장 많은 횟수의 피해를 입은 적에게 부르가 추가로 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_passive_desc_440221 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 지날 때마다 연산값 1포인트를 획득하며, 연산값 1포인트마다 부르의 피해가 <color=#00F6FF>6%</color> 증가한다. 턴 종료 시 연산값의 절반이 유지된다. 행동 종료 후 현재 연산값이 <color=#00F6FF>3</color> 이상일 시 부르에게 가장 많은 횟수의 피해를 입은 적에게 부르가 추가로 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_passive_desc_443221 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 지날 때마다 연산값 1포인트를 획득하며, 연산값 1포인트마다 부르의 피해가 <color=#00F6FF>6%</color> 증가한다. 턴 종료 시 연산값의 절반이 유지된다. 행동 종료 후 현재 연산값이 <color=#00F6FF>3</color> 이상일 시 부르에게 가장 많은 횟수의 피해를 입은 적에게 부르가 추가로 <color=#00F6FF>120%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16022111 = "장비 스킬 강화: 연산값 1포인트마다 부르의 피해가 <color=#00F6FF>6%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16022112 = "액티브 스킬 강화: 피해 계수가 <color=#00F6FF>30%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16022113 = "장비 스킬 강화: 부르가 입히는 추가 피해가 <color=#00F6FF>120%</color>까지 증가한다.",
  str_skill_upgrade_desc_16022113 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16022116 = "액티브 스킬 강화: 범위가 마름모 13칸으로 확장되며, 칸 선택 가능 수량이 4개로 증가한다.",
  str_skill_name_802401 = "특수기·파공",
  str_skill_name_802402 = "특수기·소거",
  str_skill_name_802403 = "특수기·활성",
  str_skill_name_802404 = "특수기·감진",
  str_skill_name_802405 = "특수기·실혼",
  str_skill_desc_802401 = "공간을 접히게 하는 금속을 임의의 칸으로 전송한다.",
  str_skill_desc_802402 = "성을 파괴한 암석과 진흙의 잔류물이다. 임의의 1칸 내 암석과 금제의 벽을 제거할 수 있다.",
  str_skill_desc_802403 = "별이 움직일 때 남긴 이슬이다. 사용 시 오로리안의 행동력을 7포인트 증가시킨다.",
  str_skill_desc_802404 = "신비한 동방의 화약 무기다. 1서클 범위 내의 적을 끝까지 넉백시키고 피해를 입힌다.",
  str_skill_desc_802405 = "약초는 사람을 구할 수도 있고, 독이 될 수도 있다. 대상을 1턴간 스턴시킨다.",
  str_skill_desc_80240131 = "한 번에 섀도고스트 룬 3개를 소환하며, 3턴 후 치료 능력을 지닌 섀도고스트로 바뀐다.",
  str_skill_desc_8024441 = "레지스터가 범위 내 대상을 공격하며, 대상의 행동력을 2포인트 감소시킨다.",
  str_skill_name_802431111 = "사념의 부름",
  str_skill_desc_802431111 = "소량의 적을 소환해 전투를 지원한다.",
  str_skill_desc_8024150 = "컬렉터가 주변의 적에게 자신의 HP 한도의 30%에 해당하는 피해를 입히며, 행동력 5포인트를 소모한다.",
  str_skill_desc_8024151 = "컬렉터가 자가수복을 진행해 HP 한도의 25%에 해당하는 HP를 회복하며, 행동력 3포인트를 소모한다.",
  str_skill_desc_8024152 = "컬렉터가 에너지 물질을 방출해 피해를 막을 수 있는 실드를 3회 생성하며, 행동력 1포인트를 소모한다.",
  str_skill_name_80242801 = "매복 우리",
  str_skill_desc_80242801 = "파괴하기 어려운 단단한 우리다. 안에 있는 적이 받는 피해의 일부는 핵심 적에게 전달되며, 행동력 3포인트를 소모해 우리 안의 적을 풀어줄 수 있다.",
  str_skill_upgrade_desc_16022313 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16022316 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소하며, 짙은 칸 생성 수가 5개로 증가한다.",
  str_skill_name_2002231 = "가호의 용춤",
  str_skill_name_2002232 = "가호의 용춤",
  str_skill_name_2002233 = "가호의 용춤",
  str_skill_name_3002231 = "여의신뢰",
  str_skill_name_3062231 = "여의신뢰",
  str_skill_passive_name_410223 = "낙린룡",
  str_skill_passive_name_420223 = "낙린룡",
  str_skill_passive_name_430223 = "낙린룡",
  str_skill_desc_2002231 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002232 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002233 = "<color=#00F6FF>마름모 24칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_3002231 = "자신의 주변 8개 방향 중 1개 방향을 선택하고, 해당 방향 전후의 <color=#00F6FF>모든 칸</color>을 번개 속성으로 전환하며, 선택한 방향에 우선적으로 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 <color=#00F6FF>3</color>개 생성한다.",
  str_skill_desc_3062231 = "자신의 주변 8개 방향 중 1개 방향을 선택하고, 해당 방향 전후의 <color=#00F6FF>모든 칸</color>을 번개 속성으로 전환하며, 선택한 방향에 우선적으로 <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 <color=#00F6FF>5</color>개 생성한다.",
  str_skill_passive_desc_410223 = "진예의 일반공격이 팀과 HP 퍼센트 차이가 가장 큰 대상을 공격하는 것으로 변경되며, 팀의 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_420223 = "진예의 일반공격이 팀과 HP 퍼센트 차이가 가장 큰 대상을 공격하는 것으로 변경되며, 팀의 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 통과할 때마다 <color=#00F6FF>1.5</color>배의 추가 피해 효과가 1회 발동된다.",
  str_skill_passive_desc_430223 = "진예의 일반공격이 팀과 HP 퍼센트 차이가 가장 큰 대상을 공격하는 것으로 변경되며, 팀의 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 통과할 때마다 <color=#00F6FF>1.5</color>배의 추가 피해 효과가 1회 발동된다. 이상 2종의 피해를 입는 대상과 팀의 HP 퍼센트 차이가 클수록 해당 피해가 증가한다(최대 <color=#00F6FF>50%</color> 증가).",
  str_skill_name_70011211 = "추방-패왕의 기세",
  str_skill_name_70011212 = "추방-격분의 파도",
  str_skill_upgrade_desc_15022412 = "액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 전투 진입 후 수요의 불꽃을 10포인트 획득한다.",
  str_skill_upgrade_desc_15022415 = "장비 스킬 강화: 임의의 속성 칸을 지나도 수요의 불꽃을 획득할 수 있게 된다.",
  str_skill_name_2002241 = "화염 박치기",
  str_skill_name_2002242 = "화염 박치기",
  str_skill_name_2002243 = "화염 박치기",
  str_skill_name_300224 = "능숙한 돌격",
  str_skill_name_3002241 = "능숙한 돌격-진화Ⅰ",
  str_skill_name_3002242 = "능숙한 돌격-진화Ⅱ",
  str_skill_passive_name_410224 = "긴밀한 협력",
  str_skill_passive_name_412224 = "긴밀한 협력",
  str_skill_passive_name_415224 = "긴밀한 협력",
  str_skill_desc_2002241 = "아정을 던져 가장 가까운 적이 위치한 자신과 가장 가까운 칸에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002242 = "아정을 던져 가장 가까운 적이 위치한 자신과 가장 가까운 칸에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>에 30%의 스플래시 피해를 입힌다.",
  str_skill_desc_2002243 = "아정을 던져 가장 가까운 적이 위치한 자신과 가장 가까운 칸에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 대상 <color=#00F6FF>주변 1서클</color>에 30%의 스플래시 피해를 입힌다.",
  str_skill_desc_300224 = "1칸을 선택해 자신이 이번 턴에 연쇄 스킬을 시전할 중심 위치로 삼으며, 이번 턴 연쇄 스킬 발동에 필요한 칸 수가 3 감소한다.",
  str_skill_desc_3002241 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. 시전 후 이번 턴에는 더는 연쇄 스킬을 시전하지 않으며, 일반공격이 사선 방향을 공격할 수 있게 된다. 매회 일반공격 시 수요의 불꽃을 2포인트 획득한다.",
  str_skill_desc_3002242 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color> 1칸을 선택해 자신이 이번 턴에 연쇄 스킬을 시전할 중심 위치로 삼고 <color=#00F6FF>100%</color>의 피해를 입히며, 수요의 불꽃 1포인트마다 피해가 10% 증가한다. 자신의 이번 턴 연쇄 스킬 발동에 필요한 칸 수가 3 감소하며, 넉백 효과가 추가된다.",
  str_skill_passive_desc_410224 = "불 속성 칸에서 1칸 이동할 때마다 수요의 불꽃을 1포인트 획득하며, 1포인트마다 다음 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다. 수요의 불꽃은 연쇄 스킬 시전 후 초기화된다.",
  str_skill_passive_desc_412224 = "전투 진입 시 수요의 불꽃 10포인트를 획득한다. 불 속성 칸에서 1칸 이동할 때마다 수요의 불꽃을 1포인트 획득하며, 1포인트마다 다음 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다. 수요의 불꽃은 연쇄 스킬 시전 후 초기화된다.",
  str_skill_passive_desc_415224 = "전투 진입 시 수요의 불꽃 10포인트를 획득한다. 1칸 이동할 때마다 수요의 불꽃을 1포인트 획득하며, 1포인트마다 다음 연쇄 스킬 피해가 <color=#00F6FF>{1}</color> 증가한다. 수요의 불꽃은 연쇄 스킬 시전 후 초기화된다.",
  str_skill_desc_9997040 = "2칸을 선택해 만색 칸으로 전환, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 60포인트 누적 시 사용 횟수 1회 획득, 최대 2회 비축 가능",
  str_skill_desc_9997041 = "선택한 3*3 범위 내 물 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 50포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_9997042 = "선택한 3*3 범위 내 불 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 50포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_9997043 = "선택한 3*3 범위 내 숲 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 50포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_9997044 = "선택한 3*3 범위 내 번개 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 50포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_9997045 = "전체 칸 초기화, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 80포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_9997046 = "한 가지 속성을 선택해 모든 해당 속성 칸 초기화, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 80포인트 누적 시 사용 횟수 1회 획득, 최대 2회 비축 가능",
  str_skill_desc_9997047 = "1칸을 선택해 가장 가까운 같은 속성의 칸 4개 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 60포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_name_5066101 = "만색 보석",
  str_skill_desc_5066101 = "필드의 모든 칸을 만색 칸으로 전환한다.",
  str_skill_name_5060801 = "월 브레이커",
  str_skill_desc_5060801 = "2턴을 소모해 Lv.2 진영 지원 스킬을 즉시 시전하며, 턴마다 1회만 사용 가능",
  str_skill_name_20047011 = "장벽 관통",
  str_skill_desc_20047011 = "이동 후 인접한 십자형 4칸의 대상을 공격하고, 대상을 통과해 대상 주변 칸으로 이동하며, 대상 후방의 1칸을 우선적으로 선택한다.",
  str_skill_name_5412015 = "소환-섀도프리크",
  str_skill_desc_5412015 = "턴마다 섀도프리크를 전장에 소환한다.",
  str_skill_name_9997040 = "광휘의 대검",
  str_skill_name_9997046 = "광휘의 방패",
  str_skill_name_9997047 = "광휘의 장창",
  str_skill_desc_5064701 = "선택한 5*5 범위 내 물 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 40포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_5064702 = "선택한 5*5 범위 내 불 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 40포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_5064703 = "선택한 5*5 범위 내 숲 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 40포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_desc_5064704 = "선택한 5*5 범위 내 번개 속성 칸 제거, 칸을 1개 제거할 때마다 에너지 1포인트 충전, 40포인트 누적 시 사용 횟수 1회 획득, 최대 3회 비축 가능",
  str_skill_name_5411002 = "가호의 용춤",
  str_skill_desc_5411002 = "마름모 24칸 범위에 피해를 입힌다.",
  str_skill_name_5411003 = "소환-수요령",
  str_skill_desc_5411003 = "수요령·쥐 2마리를 전장에 소환한다.",
  str_skill_desc_5411012 = "맥거핀·스모가 곧 닥칠 백야의 파도를 위해 힘을 축적하며, 전방에 섀도프리크 몇 마리를 소환한다.",
  str_skill_desc_5411020 = "거츠더가 필드의 랜덤 위치에 이동할 수 없는 거츠더의 부하 4명을 소환한다.",
  str_skill_desc_5411021 = "거츠더가 범위 내 대상을 공격하고, 대상에게 파열의 인장을 1회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다. 동시에 거츠더의 부하 2명을 소환한다.",
  str_skill_desc_5411022 = "거츠더가 포효해 범위 내 적 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다. 동시에 거츠더의 부하 2명을 소환한다.",
  str_skill_desc_5411023 = "거츠더가 대상이 지닌 파열의 인장을 폭발시켜 대상에게 대량의 피해를 입힌다. 인장 개수가 많을수록 피해가 증가한다. 동시에 거츠더의 부하 2명을 소환한다.",
  str_skill_desc_5411025 = "거츠더가 필드의 랜덤 위치에 이동할 수 없는 부하 4명을 소환한다.",
  str_skill_desc_5411026 = "거츠더가 미친 듯이 범위 내 대상을 2회 공격하고, 대상에게 파열의 인장을 2회 부여한다. 인장 개수가 많을수록 대상의 방어력이 감소한다. 동시에 거츠더의 부하 2명을 소환한다",
  str_skill_desc_5411027 = "거츠더가 최후의 포효로 범위 내 대상에게 파열의 인장을 3회 부여하며, 인장 개수가 많을수록 대상의 방어력이 낮아진다. 동시에 거츠더의 부하 2명을 소환한다.",
  str_skill_desc_5411004 = "매복 우리를 소환한다.",
  str_skill_name_5411031 = "곤(困)",
  str_skill_desc_5411031 = "환영 속, 거짓과 진실...",
  str_skill_name_5064701 = "빙원 플로터",
  str_skill_name_5064702 = "태양 플로터",
  str_skill_name_5064703 = "나무 플로터",
  str_skill_name_5064704 = "천둥 플로터",
  str_skill_name_5065501 = "피해 증가 장치",
  str_skill_name_5065601 = "충전 사탕 병",
  str_skill_name_5065801 = "이동식 에너지 장치",
  str_skill_desc_5065501 = "제거 후 이번 턴 동안 연쇄 스킬 피해 35% 증가",
  str_skill_desc_5065601 = "제거 후 랜덤 아이테르 특수 장비 1개의 사용 횟수 1회 획득",
  str_skill_desc_5065801 = "제거 후 턴 수 3포인트 획득",
  str_skill_name_29093013 = "새해의 발걸음",
  str_skill_desc_29093013 = "년수가 전방으로 3칸 도약해 낙하 지점 1서클 범위에 피해를 입히고 양쪽으로 넉백시키며, 입구로 도약하면 대문을 부수고 진입한다.",
  str_skill_name_7001125103 = "추방-분노의 외침",
  str_skill_desc_7001125103 = "추방-래비드후프가 전체 오로리안에게 피해를 입히고, 자신의 행동력을 높이며, 암석을 소환한다.",
  str_skill_name_7001125104 = "추방-지면 충돌",
  str_skill_desc_7001125104 = "추방-래비드후프가 약화 칸을 생성하고, 오로리안에게 부딪혀 넉백시키며, 경로상의 암석을 파괴한다.",
  str_skill_name_7001125105 = "추방-파괴의 일격",
  str_skill_desc_7001125105 = "추방-래비드후프가 이동 후 전방 2칸을 강타해 대량의 피해를 입히고 약화 칸을 생성한다.",
  str_skill_name_7001126103 = "추방-나쁜 정서 방출",
  str_skill_desc_7001126103 = "추방-찬드라가 오로리안에게서 멀어진 후 주변 2서클 범위 내의 오로리안에게 피해를 입힌다.",
  str_skill_name_7001126104 = "추방-부정적인 정서 투사",
  str_skill_desc_7001126104 = "추방-찬드라가 전체 오로리안에게 피해를 입힌다.",
  str_skill_name_80150311 = "암석",
  str_skill_desc_80150311 = "암석이 이곳을 오랫동안 막고 있었습니다. 제거하려면 행동력 2포인트를 소모해야 합니다.",
  str_skill_name_290940103 = "혼의 장창",
  str_skill_desc_290940103 = "아이라가 오로리안에게 피해를 입히고 오로리안 기준 십자형 최대 범위 가장자리에 고스트파이어를 생성한다.",
  str_skill_name_290940104 = "이글거리는 폭발",
  str_skill_desc_290940104 = "아이라가 자신의 주변 2서클 내 오로리안에게 피해를 입힌다.",
  str_skill_name_290940105 = "분노의 운석",
  str_skill_desc_290940105 = "아이라가 오로리안의 지난 턴 위치에 운석을 소환, 즉시 처치 피해를 입히고 범위 중앙 칸을 무너트리며, 십자형 4칸에 파괴된 칸을 생성한다.",
  str_skill_name_200480103 = "혼을 태우는 불길",
  str_skill_desc_200480103 = "고스트파이어가 범위 내 오로리안에게 피해를 입히고 필드 반대편으로 순간이동한다. 플레이어를 공격할 수 없을 시 필드 가장자리에서 시계 방향으로 2칸 순간이동한다.",
  str_skill_name_300226 = "하늘의 손길",
  str_skill_name_200226 = "개굴살법",
  str_skill_passive_name_400226 = "개구리의 음색",
  str_skill_desc_300226 = "꿈의 세계 속 흰개구리 왕자는 폭발하는 화산을 진정시켰고, 하늘의 검은 균열을 메웠다. 그러나 현실 속 녀석은 자신의 상냥함으로 동료를 치유하고자 한다... 그게 무슨 의미가 있냐고? 귀여움이야말로 가장 큰 의미인 것이다!",
  str_skill_desc_200226 = "흰개구리 왕자의 결의가 담긴 울음소리가 온 아스트라에 울려퍼진다! ...그게 무슨 의미가 있냐고? 귀여움이야말로 가장 큰 의미인 것이다!",
  str_skill_passive_desc_400226 = "이 개구리의 소리는 자연의 심장 고동 소리이자 아스트라의 숨결이며, 끝없는 어둠 속 한 줄기 빛이다. 들리는가, 녀석은 지금 동료들을 이 성대한 축제로 초대해 함께 개굴개굴 찬가를 부르길 바라고 있다! ...그게 무슨 의미가 있냐고? 모두가 함께 개굴대는 것이야말로 가장 큰 의미인 것이다!",
  str_skill_name_54350081 = "예포 호위병",
  str_skill_desc_54350081 = "“국왕을 지키는 것이 곧 예포의 의무!” 예포가 오로리안의 연쇄 스킬 시전 후 퇴장한다.",
  str_skill_upgrade_desc_16022513 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 범위 내 적에게 추가로 허점을 1개 생성한다.",
  str_skill_upgrade_desc_16022516 = "장비 스킬 강화: <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 50% 확률로 허점을 추가 1개 생성한다.",
  str_skill_name_2002251 = "프로즌 버스트",
