  str_skill_name_343225 = "천뢰의 붕괴",
  str_skill_passive_name_410225 = "뇌천일색",
  str_skill_passive_name_430225 = "뇌천일색",
  str_skill_passive_name_416225 = "뇌천일색",
  str_skill_passive_name_436225 = "뇌천일색",
  str_skill_passive_name_440225 = "뇌천일색",
  str_skill_passive_name_446225 = "뇌천일색",
  str_skill_passive_name_4402253 = "뇌천일색",
  str_skill_passive_name_4462253 = "뇌천일색",
  str_skill_desc_2002251 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로상의 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002252 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002253 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2102251 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로상의 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점 1개를 격파한다.",
  str_skill_desc_2102252 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점 1개를 격파한다.",
  str_skill_desc_2102253 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점을 최대 2개 격파한다.",
  str_skill_desc_2302251 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로상의 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점 1개를 격파한다.",
  str_skill_desc_2302252 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점 1개를 격파한다.",
  str_skill_desc_2302253 = "자신을 중심으로 가장 가까운 적을 대상으로 삼고, 경로 및 인접 칸이 속한 열에 <color=#00F6FF>{1}%</color>의 피해를 입히며, 동시에 해당 방향의 허점을 최대 2개 격파한다.",
  str_skill_desc_300225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_303225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_320225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 해당 방향으로 범위 내의 적에게 허점을 1개 생성한다.",
  str_skill_desc_323225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 해당 방향으로 범위 내의 적에게 허점을 2개 생성한다.",
  str_skill_desc_340225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>250%</color>의 피해를 입히고, 해당 방향으로 범위 내의 적에게 허점을 1개 생성한다.",
  str_skill_desc_343225 = "1칸을 선택해 해당 방향 원뿔형 범위에 <color=#00F6FF>250%</color>의 피해를 입히고, 해당 방향으로 범위 내의 적에게 허점을 2개 생성한다.",
  str_skill_passive_desc_410225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다. 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>{1}</color>의 피해를 입히며, 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_416225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다(50% 확률로 추가 1개 생성). 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>{1}</color>의 피해를 입히며, 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_430225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다. 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>{2}</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_436225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다(50% 확률로 추가 1개 생성). 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>{1}</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>{2}</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_440225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다. 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>230%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_446225 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다(50% 확률로 추가 1개 생성). 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>230%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_4402253 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 또는 오로라 타임 진입 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다. 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>230%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_passive_desc_4462253 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 또는 오로라 타임 진입 시 티아라가 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향부터 허점을 1개 생성한다(50% 확률로 추가 1개 생성). 일반공격 및 연쇄 스킬로 해당 방향에서 피해를 입힐 때마다 허점을 격파하고 <color=#00F6FF>230%</color>의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입히며, 스플래시 범위에 <color=#00F6FF>100%</color>의 피해를 입힌다. 적 사망 시 가장 가까운 다른 적에게 허점이 전이되며, 적의 모든 방향에 허점이 있을 시 추가로 허점을 생성하면 절반의 격파 피해가 발동한다.",
  str_skill_upgrade_refine_desc_16022511 = "장비 스킬 강화: 허점을 격파해 입히는 피해가 <color=#00F6FF>230%</color>까지 증가한다.",
  str_skill_upgrade_refine_desc_16022512 = "액티브 스킬 강화: 스킬 피해 계수가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16022513 = "장비 스킬 강화: 오로라 타임 진입 시 필드에서 HP가 가장 높은 적에게 자신과 가장 가까운 방향에 허점을 1개 생성한다.",
  str_skill_desc_70011272 = "레체가 에너지를 발산해 가로+세로 4열 범위에 피해를 입힌다.",
  str_skill_desc_70011273 = "레체가 월륜으로 변해 범위 내의 대상에게 피해를 입히며, 동시에 필드의 반대편으로 이동한다. 이동 후 자신의 주변 1서클 내의 칸을 잠그며, 잠긴 칸은 색 변경을 진행할 수 없다.",
  str_skill_name_290501142 = "추방-포식",
  str_skill_name_290501143 = "추방-사냥",
  str_skill_name_290501144 = "추방-군체 소집",
  str_skill_desc_290501142 = "거미 여왕이 사냥감을 향해 달려들어 거미줄로 칸을 잠그고 오로리안에게 피해를 입힌다. 잠긴 칸은 1턴 후 기존 상태를 회복한다.",
  str_skill_desc_290501143 = "거미 여왕이 거미줄로 오로리안 주변의 칸을 잠그고 새끼 거미를 소집해 오로리안에게 달려들어 피해를 입힌다. 잠긴 칸은 1턴 후 기존 상태를 회복한다.",
  str_skill_desc_290501144 = "거미 여왕이 새끼 거미를 소집해 공격하며, 새끼 거미가 거미줄로 대량의 칸을 잠근다. 잠긴 칸은 1턴 후 기존 상태를 회복한다.",
  str_skill_desc_9011062 = "획득 시 현재 쿨다운 턴 수가 가장 많은 오로리안의 스킬 턴 수가 1 감소한다.",
  str_skill_name_290420209 = "낫",
  str_skill_desc_290420209 = "글룸의 환영이 이동 후 전방의 대상에게 피해를 입힌다.",
  str_skill_desc_510233 = "출전한 모든 오로리안의 스킬 쿨다운 턴 수가 2 감소한다.",
  str_skill_desc_520233 = "랜덤 1명 오로리안의 스킬 쿨다운이 종료된다.",
  str_skill_desc_530233 = "출전한 모든 오로리안의 스킬 쿨다운이 종료된다.",
  str_skill_desc_292600105 = "슬픔의 사념체 「이브」가 대량의 다크매터 단계를 획득하며, 단계 수에 따라 강타 효과를 획득한다. 공격을 받을 때마다 다크매터 단계가 감소한다.",
  str_skill_desc_292600106 = "슬픔의 사념체 「이브」가 대상을 조준해 피해를 입힌다.",
  str_skill_desc_20060012 = "슬픔의 사념체 「이브」에게 HP 방어력 보너스를 제공한다.",
  str_skill_name_200490101 = "증오의 안개",
  str_skill_desc_200490101 = "증오의 안개가 오로리안을 향해 이동한다.",
  str_skill_name_290950105 = "덩굴 우박",
  str_skill_name_290950106 = "덩굴 회오리",
  str_skill_name_290950107 = "덩굴 우박",
  str_skill_name_290950108 = "덩굴 회오리",
  str_skill_name_290950109 = "덩굴 돌진",
  str_skill_desc_290950105 = "가시덩굴 당근이 오로리안에게 여러 차례의 피해를 입히며, 오로리안의 HP가 낮을수록 피해가 증가한다.",
  str_skill_desc_290950106 = "가시덩굴 당근이 고속으로 회전해 자신의 주변에 여러 차례의 피해를 입힌다. 피해를 입힐 때마다 일정 확률로 오로리안을 시계 반대 방향 또는 외곽으로 한 칸 넉백시킨다. 오로리안 명중 시 후속 피해가 감소한다.",
  str_skill_desc_290950107 = "가시덩굴 당근이 오로리안에게 여러 차례의 피해를 입히며, 오로리안의 HP가 낮을수록 피해가 증가한다.",
  str_skill_desc_290950108 = "오로리안이 덩굴 돌진의 스킬 범위에 있지 않을 시 가시덩굴 당근이 고속으로 회전해 자신의 주변에 여러 차례의 피해를 입힌다. 피해를 입힐 때마다 일정 확률로 오로리안을 시계 반대 방향 또는 외곽으로 한 칸 넉백시킨다. 오로리안 명중 시 후속 피해가 감소한다.",
  str_skill_desc_290950109 = "오로리안이 덩굴 돌진의 스킬 범위 내에 있을 시 가시덩굴 당근이 거대 당근으로 대상을 내리쳐 오로리안에게 피해를 입히고 2칸 넉백시킨다.",
  str_skill_name_80060401 = "모순의 가시",
  str_skill_desc_80060401 = "턴 종료 시 칸 위에 있는 몬스터에게 피해를 입히며, 추가로 중상 효과를 1회 추가한다. 흔히 보던 가시 같지만, 이번에는 지나가도 피해를 입지 않을 것이다.",
  str_skill_name_80060501 = "소환-다크 하운드",
  str_skill_name_80060502 = "소환-프로버",
  str_skill_name_80060503 = "소환-실러",
  str_skill_desc_80060501 = "다크 하운드를 전장에 소환한다.",
  str_skill_desc_80060502 = "프로버를 전장에 소환한다.",
  str_skill_desc_80060503 = "실러를 전장에 소환한다.",
  str_skill_desc_800637101 = "정확하고 은밀하며, 숙련된 기교의 사격을 진행해 십자형 최대 범위의 대상을 명중시킬 수 있다.",
  str_skill_desc_800638101 = "비범한 움직임으로 대상과 멀어진 후 대상에게 피해를 2회 입힌다.",
  str_skill_desc_80062201 = "파티가 턴마다 회복하는 행동력이 1 증가한다.",
  str_skill_name_2002271 = "호크아이 락온",
  str_skill_name_2002272 = "호크아이 락온",
  str_skill_name_2002273 = "호크아이 락온",
  str_skill_name_20022712 = "호크아이 락온",
  str_skill_name_20022722 = "호크아이 락온",
  str_skill_name_20022732 = "호크아이 락온",
  str_skill_name_2202271 = "호크아이 락온",
  str_skill_name_2202272 = "호크아이 락온",
  str_skill_name_2202273 = "호크아이 락온",
  str_skill_name_3002271 = "죽음의 제도학",
  str_skill_name_3032271 = "죽음의 제도학",
  str_skill_name_3002272 = "죽음의 제도학-가불",
  str_skill_name_3032272 = "죽음의 제도학-가불",
  str_skill_name_3062272 = "죽음의 제도학-가불",
  str_skill_name_3062271 = "죽음의 제도학",
  str_skill_desc_2002271 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002272 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002273 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_20022712 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 1개 추가한다.",
  str_skill_desc_20022722 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 2개 추가한다.",
  str_skill_desc_20022732 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 3개 추가한다.",
  str_skill_desc_2202271 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 1개 추가한다.",
  str_skill_desc_2202272 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 2개 추가한다.",
  str_skill_desc_2202273 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 가불 상태에서는 피해를 입히지 않으며, 대상에게 매의 발톱 인장을 3개 추가한다.",
  str_skill_desc_3002271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환한다.\n쿨다운 상태에서도 재시전이 가능하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3032271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환한다.\n쿨다운 상태에서도 재시전이 가능하며, 전환되는 번개 속성 칸이 <color=#00F6FF>2</color>개, 짙은 칸이 <color=#00F6FF>1</color>개 증가하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3062271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>2</color>개를 짙은 칸으로 전환한다.\n쿨다운 상태에서도 재시전이 가능하며, 전환되는 번개 속성 칸이 <color=#00F6FF>2</color>개, 짙은 칸이 <color=#00F6FF>1</color>개 증가하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3002272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3032272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>5</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>2</color>개를 짙은 칸으로 전환한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3062272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>5</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>3</color>개를 짙은 칸으로 전환한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_passive_name_410227 = "데스 트라이앵글",
  str_skill_passive_name_420227 = "데스 트라이앵글",
  str_skill_passive_name_430227 = "데스 트라이앵글",
  str_skill_passive_desc_410227 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>3</color>개 추가하며, 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 턴 종료 시 인장 수가 절반으로 감소하며, 대상 사망 시 인장의 절반이 가장 가까운 다른 적에게 전이된다.",
  str_skill_passive_desc_420227 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>3</color>개 추가하며, 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 턴 종료 시 인장 수가 절반으로 감소하며, 대상 사망 시 인장의 절반이 가장 가까운 다른 적에게 전이된다.",
  str_skill_passive_desc_430227 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>3</color>개 추가하며, 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 턴 종료 시 인장 수가 절반으로 감소하며, 대상 사망 시 인장의 절반이 가장 가까운 다른 적에게 전이된다. 레이첼이 <color=#00F6FF>가불 상태</color>일 시 연결로 1칸을 이동할 때마다 자신의 공격력이 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_440227 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>3</color>개 추가하며, 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>80%</color>에 해당하는 피해를 입힌다. 턴 종료 시 인장 수가 절반으로 감소하며, 대상 사망 시 인장의 절반이 가장 가까운 다른 적에게 전이된다. 레이첼이 <color=#00F6FF>가불 상태</color>일 시 연결로 1칸을 이동할 때마다 자신의 공격력이 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_passive_desc_460227 = "<link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link> 통과 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>3</color>개 추가하며, 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>80%</color>에 해당하는 피해를 입힌다. 턴 종료 시 인장 수가 절반으로 감소하며, 대상 사망 시 인장의 절반이 가장 가까운 다른 적에게 전이된다. 레이첼이 <color=#00F6FF>가불 상태</color>일 시 연결로 1칸을 이동할 때마다 자신의 공격력이 <color=#00F6FF>4%</color> 증가한다.",
  str_skill_desc_3502271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n쿨다운 상태에서도 재시전이 가능하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3532271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n쿨다운 상태에서도 재시전이 가능하며, 전환되는 번개 속성 칸이 <color=#00F6FF>2</color>개, 짙은 칸이 <color=#00F6FF>1</color>개 증가하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3562271 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>2</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n쿨다운 상태에서도 재시전이 가능하며, 전환되는 번개 속성 칸이 <color=#00F6FF>2</color>개, 짙은 칸이 <color=#00F6FF>1</color>개 증가하나, 시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3502272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>3</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>1</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3532272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>5</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>2</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_desc_3562272 = "번개 속성이 아닌 가장 가까운 칸 <color=#00F6FF>5</color>개를 번개 속성 칸으로 전환하고, 그중 랜덤 <color=#00F6FF>3</color>개를 짙은 칸으로 전환하며, 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.\n시전 시 쿨다운 턴 수가 1 증가하고, 레이첼이 <color=#00F6FF>가불 상태</color>에 진입한다. 해당 상태에서는 일반공격 및 연쇄 스킬을 시전할 수 없으며, 액티브 스킬이 준비되면 가불 상태가 해제된다.",
  str_skill_upgrade_desc_16022713 = "액티브 스킬 강화: 전환되는 번개 속성 칸이 <color=#FFFF00>2</color>개, 짙은 칸이 <color=#FFFF00>1</color>개 증가한다.",
  str_skill_upgrade_desc_16022716 = "액티브 스킬 강화: 짙은 칸 전환 수가 <color=#FFFF00>1</color>개 증가한다.",
  str_skill_upgrade_refine_desc_16022711 = "장비 스킬 강화: 적 턴 시작 시 인장 1개당 레이첼의 현재 공격력의 <color=#00F6FF>80%</color>에 해당하는 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16022712 = "액티브 스킬 강화: 시전 시 가장 가까운 대상에게 매의 발톱 인장을 <color=#00F6FF>2</color>개 추가한다.",
  str_skill_upgrade_refine_desc_16022713 = "장비 스킬 강화: 레이첼이 가불 상태일 시 연결로 1칸을 이동할 때마다 자신의 공격력이 <color=#00F6FF>4%</color> 증가한다.",
  str_skill_upgrade_desc_15022812 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.\n([컬러풀 미스틱] <color=#FFFF00>선제공격</color>은 각성 1단계 달성 시 적용)",
  str_skill_upgrade_desc_15022815 = "액티브 스킬 [혼합 폭격] 강화: 선택 가능한 칸 수가 <color=#FFFF00>1</color>개 증가한다.",
  str_skill_desc_10071120 = "대상의 이전 턴 위치에 광선 타격을 시전하며, 경로 위치 및 목표 위치의 대상에게 피해를 입힌다.",
  str_skill_desc_10071130 = "범위 내 대상을 필드 중간 위치로 넉백시킨다.",
  str_skill_name_54550920 = "텐타클로-피해 회피",
  str_skill_desc_54550920 = "오로리안이 연쇄 스킬을 시전하기 전 텐타클로가 몸을 숨겨 공격을 피하며, 동시에 모든 위치의 강화 칸을 흡수한다.",
  str_skill_name_29097013 = "일반공격",
  str_skill_desc_29097013 = "이동 후 전방의 오로리안에게 피해를 입힌다.",
  str_skill_name_29097014 = "용암 충격",
  str_skill_desc_29097014 = "오로리안 방향으로 부채꼴 넓은 범위에 피해를 입히고 암석을 생성한다.",
  str_skill_name_29097015 = "불타는 포효",
  str_skill_desc_29097015 = "전체화면 범위에 피해를 3회 입히며, 회당 1칸 넉백시킨다. 더는 넉백시킬 수 없을 경우 더 큰 피해를 입힌다.",
  str_skill_name_2002281 = "감미로운 기습",
  str_skill_name_2002282 = "감미로운 기습",
  str_skill_name_2002283 = "감미로운 기습",
  str_skill_desc_2002281 = "제타가 「코난」을 소환한다. 「코난」은 주변 마름모 12칸 범위에서 가장 가까운 적을 향해 이동 후 자폭하며, 십자형 5칸에 <color=#00F6FF>150%</color>의 피해를 입힌다.",
  str_skill_desc_2002282 = "제타가 「코난」을 소환한다. 「코난」은 주변 마름모 24칸 범위에서 가장 가까운 적을 향해 이동 후 자폭하며, 십자형 5칸에 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2002283 = "제타가 「코난」을 소환한다. 「코난」은 주변 마름모 24칸 범위에서 가장 가까운 적을 향해 이동 후 자폭하며, 십자형 5칸에 <color=#00F6FF>160%</color>의 피해를 입힌다.\n제타가 3단계 연쇄 스킬 시전 시 액티브 스킬 [컬러풀 미스틱]으로 소환된 「코난」의 피해 범위가 주변 1서클로 확장된다.",
  str_skill_name_3002281 = "혼합 폭격",
  str_skill_name_3052281 = "혼합 폭격",
  str_skill_name_3102281 = "혼합 폭격",
  str_skill_name_3152281 = "혼합 폭격",
  str_skill_desc_3002281 = "3칸을 선택해 색상을 초기화 및 정화하며, 초기화 시 물 속성 칸은 유지된다.",
  str_skill_desc_3052281 = "4칸을 선택해 색상을 초기화 및 정화하며, 초기화 시 물 속성 칸은 유지된다.",
  str_skill_desc_3102281 = "3칸을 선택해 색상을 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>에 기록한 후 초기화 및 정화하며, 초기화 시 물 속성 칸은 유지된다.",
  str_skill_desc_3152281 = "4칸을 선택해 색상을 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>에 기록한 후 초기화 및 정화하며, 초기화 시 물 속성 칸은 유지된다.",
  str_skill_name_3002282 = "컬러풀 미스틱",
  str_skill_desc_3002282 = "색상을 채운 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>를 소모해 이동 가능한 1칸에 「코난」을 소환한다. 이번 턴에 제타가 첫 연쇄 스킬 시전 시 「코난」이 동시에 적을 찾고 공격한다.",
  str_skill_passive_name_410228 = "화려한 폭파",
  str_skill_passive_name_420228 = "화려한 폭파",
  str_skill_passive_name_430228 = "화려한 폭파",
  str_skill_passive_desc_410228 = "제타가 액티브 스킬 [컬러풀 미스틱]과 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>를 획득한다. [컬러풀 미스틱]을 통해 소환된 「코난」은 제타가 연쇄 스킬 시전 시 <color=#00F6FF>자신을 중심으로 적을 찾고 공격</color>한다. 추적 범위는 제타가 시전하는 연쇄 스킬과 <color=#00F6FF>동일</color>하며, 제타의 연쇄 스킬 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다.",
  str_skill_passive_desc_420228 = "제타가 액티브 스킬 [컬러풀 미스틱]과 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>를 획득한다. [컬러풀 미스틱]을 통해 소환된 「코난」은 제타가 연쇄 스킬 시전 시 <color=#00F6FF>자신을 중심으로 적을 찾고 공격</color>한다. 추적 범위는 제타가 시전하는 연쇄 스킬과 <color=#00F6FF>동일</color>하며, 제타의 연쇄 스킬 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 제타가 3단계 연쇄 스킬 시전 시 액티브 스킬 [컬러풀 미스틱]으로 소환된 「코난」의 피해 범위가 <color=#00F6FF>주변 1서클</color>로 확장된다.",
  str_skill_passive_desc_430228 = "제타가 액티브 스킬 [컬러풀 미스틱]과 <link=\"30100\"><#FFAE07><u>컬러보드</u></color></link>를 획득한다. [컬러풀 미스틱]을 통해 소환된 「코난」은 제타가 연쇄 스킬 시전 시 <color=#00F6FF>자신을 중심으로 적을 찾고 공격</color>한다. 추적 범위는 제타가 시전하는 연쇄 스킬과 <color=#00F6FF>동일</color>하며, 제타의 연쇄 스킬 피해의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 제타가 3단계 연쇄 스킬 시전 시 액티브 스킬 [컬러풀 미스틱]으로 소환된 「코난」의 피해 범위가 <color=#00F6FF>주변 1서클</color>로 확장된다. 컬러보드를 다 채울 때마다 제타의 최대 HP의 <color=#00F6FF>12%</color>만큼 파티의 HP를 회복시킨다.",
  str_skill_name_2002291 = "「출구 발견!」",
  str_skill_name_2002292 = "「출구 발견!」",
  str_skill_name_2002293 = "「출구 발견!」",
  str_skill_name_3002291 = "「퍼펙트 클리어!」",
  str_skill_name_3202291 = "「퍼펙트 클리어!」",
  str_skill_name_3302291 = "「퍼펙트 클리어!」",
  str_skill_name_3232291 = "「퍼펙트 클리어!」",
  str_skill_name_3262291 = "「퍼펙트 클리어!」",
  str_skill_name_3332291 = "「퍼펙트 클리어!」",
  str_skill_name_3362291 = "「퍼펙트 클리어!」",
  str_skill_passive_name_4002291 = "「배터리야 버텨!」",
  str_skill_desc_2002291 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002292 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002293 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2202291 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 작열 상태를 1회 추가한다.",
  str_skill_desc_2202292 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 작열 상태를 1회 추가한다.",
  str_skill_desc_2202293 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고 작열 상태를 1회 추가한다.",
  str_skill_desc_3002291 = "바티아가 전투 진입 후 자신에게 <link=\"30110\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 칸을 불 속성으로 전환한다.",
  str_skill_desc_3202291 = "바티아가 전투 진입 후 자신에게 <link=\"30111\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 형태를 랜덤으로 갱신할 수 있다. 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 <color=#00F6FF>5</color>포인트씩 증가한다.",
  str_skill_desc_3232291 = "바티아가 전투 진입 후 자신에게 <link=\"30112\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 형태를 랜덤으로 갱신할 수 있다. 초기 에너지를 <color=#00F6FF>10</color>포인트 보유하고, 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 <color=#00F6FF>5</color>포인트씩 증가한다.",
  str_skill_desc_3262291 = "바티아가 전투 진입 후 자신에게 <link=\"30113\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 형태를 랜덤으로 갱신할 수 있다. 초기 에너지를 <color=#00F6FF>10</color>포인트 보유하고, 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전한다.",
  str_skill_desc_3302291 = "바티아가 전투 진입 후 자신에게 <link=\"30114\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 블록의 형태를 랜덤으로 갱신할 수 있다. 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 <color=#00F6FF>5</color>포인트씩 증가한다. [넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_desc_3332291 = "바티아가 전투 진입 후 자신에게 <link=\"30115\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 블록의 형태를 랜덤으로 갱신할 수 있다. 초기 에너지를 <color=#00F6FF>10</color>포인트 보유하고, 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전하며, 다음 액티브 스킬을 시전하기 전 갱신마다 소모하는 에너지가 <color=#00F6FF>5</color>포인트씩 증가한다. [넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_desc_3362291 = "바티아가 전투 진입 후 자신에게 <link=\"30116\"><#FFAE07><u>[넥스트 블록]</u></color></link>을 적용한다. 1칸을 선택해 [넥스트 블록]의 형태와 동일한 범위의 칸을 불 속성으로 전환하며, 에너지 <color=#00F6FF>5</color>포인트를 소모해 블록의 형태를 랜덤으로 갱신할 수 있다. 초기 에너지를 <color=#00F6FF>10</color>포인트 보유하며, 불 속성 칸을 지날 시 <color=#00F6FF>1</color>포인트를 충전한다. [넥스트 블록]의 형태를 잠글 수 있으며, 잠금 상태에서는 블록의 형태가 랜덤으로 변경되지 않는다. 잠금 상태에서 갱신 기능 사용 시 현재 블록을 강화하며, 강화할 때마다 액티브 스킬 시전 시 추가로 범위 내 랜덤 1개 위치에 짙은 칸을 생성한다.",
  str_skill_passive_desc_4002291 = "파티 내 오로리안이 대상에게 추가한 작열 상태가 <color=#00F6FF>열축적 상태</color>로 대체되며, 단계마다 파티 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 입힌다. 대상의 HP가 많을수록 피해가 최대 2배까지 증가하며, 최대 5회 중첩 가능, 2턴간 지속된다. <link=\"30093\"><#FFAE07><u>짙은 칸</u></color></link>을 지날 때마다 가장 가까운 대상에게 열축적 상태를 <color=#00F6FF>1</color>회 추가한다.",
  str_skill_upgrade_desc_16022913 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. [넥스트 블록]의 초기 에너지 10포인트를 보유한다(각성 2단계 달성 시 적용).",
  str_skill_upgrade_desc_16022916 = "액티브 스킬 강화: [넥스트 블록]의 형태 갱신 시 에너지 소모량이 더는 증가하지 않는다(각성 2단계 달성 시 적용).",
  str_skill_name_28002414 = "제압",
  str_skill_desc_28002414 = "노라가 강력한 마법을 시전해 오로리안을 넉백시킨다.",
  str_skill_name_28002415 = "소환",
  str_skill_desc_28002415 = "노라가 필드 내 랜덤 위치에 암귀를 소환한다.",
  str_skill_name_1003003 = "고정",
  str_skill_desc_1003003 = "섀도고스트가 턴마다 가장 가까운 랜덤 칸을 잠근다.",
  str_skill_name_29102421 = "연소",
  str_skill_desc_29102421 = "자신의 전방 4열 범위 내 오로리안에게 피해를 입히고 랜덤 위치에 화염을 소환한다.",
  str_skill_name_29102422 = "불타는 대지",
  str_skill_desc_29102422 = "화염을 분사해 전체화면에 피해를 입히고, 추가로 외곽 3개 열 범위 내의 대상에게 높은 피해를 1회 입힌다.",
  str_skill_name_15017611 = "오스트랄리스의 바람",
  str_skill_desc_15017611 = "자신이 지닌 오스트랄리스의 바늘 인장 수에 따라 주변 3서클 내의 오로리안에게 여러 차례의 피해를 입히며, 피해마다 대상에게 오스트랄리스의 바늘을 1개 추가한다. 대상을 공격할 수 없을 경우 자신에게 오스트랄리스의 바늘 인장을 3회 추가한다.",
  str_skill_name_15017612 = "보레알리스의 빛",
  str_skill_desc_15017612 = "주변 2서클 내의 적이 지닌 오스트랄리스의 바늘을 뽑아 대상에게 바늘 1개당 20%의 피해를 입힌다. 대상을 공격할 수 없을 경우 자신에게 오스트랄리스의 바늘 인장을 3회 추가한다.",
  str_skill_name_15020011 = "엄호 사격",
  str_skill_desc_15020011 = "주변 3서클 내의 적 대상에게 피해를 입힌다.",
  str_skill_name_15020012 = "홀로그램 교란법",
  str_skill_desc_15020012 = "오로리안과 일루미나 전투병을 서로의 중간 위치로 끌어당긴다.",
  str_skill_name_547100101 = "라인하르트 일반공격",
  str_skill_desc_547100101 = "라인하르트가 적에게 접근해 공격한다.",
  str_skill_name_547100102 = "여명의 충격",
  str_skill_desc_547100102 = "라인하르트가 적에게 대량의 피해를 입힌다.",
  str_skill_name_290980101 = "사념의 위협",
  str_skill_name_290980102 = "혼의 심판",
  str_skill_name_290980103 = "웨이브 볼트",
  str_skill_name_290980104 = "에너지 브레스",
  str_skill_desc_290980101 = "X자형 범위 내에 적이 존재할 시 대상에게 피해를 입히고 말초 조각을 소환하며, 존재하지 않을 시 자신의 주변에 말초 조각을 소환한다.",
  str_skill_desc_290980102 = "십자형 범위 내에 적이 존재할 시 대상에게 피해를 입히고 말초 조각을 소환하며, 존재하지 않을 시 자신의 주변에 말초 조각을 소환한다.",
  str_skill_desc_290980103 = "자신의 주변에 말초 조각을 소환한다.",
  str_skill_desc_290980104 = "전체화면 범위 내의 적에게 피해를 입히고 적을 넉백시키며, 대상의 주변에 말초 조각을 소환한다.",
  str_skill_name_200510101 = "도발 공격",
  str_skill_desc_200510101 = "말초 조각이 적에게 접근해 공격한다.",
  str_skill_name_290520111 = "추방-흉폭한 습격",
  str_skill_desc_290520111 = "피제로가 오로리안을 향해 이동해 대량의 피해를 입힌 후 대상과 멀리 떨어진 위치로 이동한다.",
  str_skill_name_290520112 = "추방-흉폭한 일격",
  str_skill_desc_290520112 = "피제로가 이동 후 범위 내의 오로리안에게 피해를 입힌다.",
  str_skill_name_290940113 = "추방-혼의 장창",
  str_skill_desc_290940113 = "아이라가 오로리안에게 현재 HP의 40%만큼 피해를 입히고, 해당 피해 수치에 따라 아군의 최대 HP를 증가시키며, 오로리안 기준 십자형 최대 범위 가장자리에 고스트파이어를 생성한다.",
  str_skill_name_290940114 = "추방-이글거리는 폭발",
  str_skill_desc_290940114 = "아이라가 자신의 주변 2서클 내 오로리안에게 피해를 입힌다.",
  str_skill_name_290940115 = "추방-분노의 운석",
  str_skill_desc_290940115 = "아이라가 오로리안의 지난 턴 위치에 운석을 소환, 즉시 처치 피해를 입히고 범위 중앙 칸을 무너트리며, 십자형 4칸에 파괴된 칸을 생성한다.",
  str_skill_upgrade_refine_desc_17010711 = "액티브 스킬 강화: 증폭 상태에서 연쇄 스킬 피해가 <color=#00F6FF>25%</color> 증가한다.",
  str_skill_upgrade_refine_desc_17010712 = "장비 스킬 강화: 턴 시작 시 <color=#00F6FF>주변 1서클</color>에 적 1명이 있을 때마다 ESP 1포인트를 획득한다.",
  str_skill_upgrade_refine_desc_17010713 = "장비 스킬 강화: 턴 종료 시 ESP <color=#00F6FF>5</color>포인트를 획득한다(손실 HP <color=#00F6FF>15%</color>마다 ESP 1포인트 추가 획득).",
  str_skill_desc_346107 = "ESP <color=#00F6FF>10</color>포인트를 소모하여 해당 턴에 증폭 상태가 된다. 증폭 상태: 일반공격이 사선 방향을 공격할 수 있으며, 일반공격/연쇄 피해가 각각 <color=#00F6FF>20%/25%</color> 증가한다(중복 시전 시 중첩 가능). 증폭 상태에서 적 1명을 처치할 때마다 ESP 2포인트를 획득한다.",
  str_skill_passive_desc_456107 = "전투 시작 시 ESP 10포인트를 획득한다. 턴 시작 시 <color=#00F6FF>주변 1서클</color>에 적 1명이 있을 때마다 ESP <color=#00F6FF>1</color>포인트를 획득한다. 비증폭 상태에서 턴이 종료되면 ESP <color=#00F6FF>5</color>포인트를 획득한다(손실 HP 20%마다 ESP 1포인트 추가 획득).",
  str_skill_passive_desc_466107 = "전투 시작 시 ESP 10포인트를 획득한다. 턴 시작 시 <color=#00F6FF>주변 1서클</color>에 적 1명이 있을 때마다 ESP <color=#00F6FF>1</color>포인트를 획득하며, 턴 종료 시 ESP <color=#00F6FF>5</color>포인트를 획득한다(손실 HP 15%마다 ESP 1포인트 추가 획득).",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: ESP <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>480%</color>의 피해를 입힌다. 1회 시전할 때마다 기본 공격력이 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다.",
  str_skill_upgrade_refine_desc_17010812 = "액티브 스킬 강화: 1회 시전할 때마다 액티브 스킬 최종 피해가 <color=#00F6FF>3%</color> 증가한다.",
  str_skill_upgrade_refine_desc_17010813 = "액티브 스킬 강화: HP가 <color=#00F6FF>10%</color> 미만인 대상에게 <color=#00F6FF>3배</color>의 피해를 입힌다.",
  str_skill_name_366108 = "떨어지는 용암",
  str_skill_name_33610801 = "떨어지는 용암-진화Ⅰ",
  str_skill_name_36610801 = "떨어지는 용암-진화Ⅰ",
  str_skill_desc_33610801 = "ESP <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>480%</color>의 피해를 입힌다. 1회 시전할 때마다 기본 공격력이 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_356108 = "ESP <color=#00F6FF>10</color>포인트를 소모해 1칸에 <color=#00F6FF>240%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 절반의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 1회 시전할 때마다 기본 공격력 및 액티브 스킬 최종 피해가 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_35610801 = "ESP <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>480%</color>의 피해를 입힌다. 1회 시전할 때마다 기본 공격력 및 액티브 스킬 최종 피해가 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다.",
  str_skill_desc_366108 = "ESP <color=#00F6FF>10</color>포인트를 소모해 1칸에 <color=#00F6FF>240%</color>의 피해를 입히고, 대상 주변 <color=#00F6FF>십자형 4칸</color>의 적에게 절반의 <link=\"30015\"><#FFAE07><u>스플래시</u></color></link> 피해를 입힌다. 1회 시전할 때마다 기본 공격력 및 액티브 스킬 최종 피해가 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다. HP가 <color=#00F6FF>10%</color> 미만인 대상에게 <color=#00F6FF>3배</color>의 피해를 입힌다.",
  str_skill_desc_36610801 = "ESP <color=#00F6FF>15</color>포인트를 소모, 1칸을 선택해 <color=#00F6FF>480%</color>의 피해를 입힌다. 1회 시전할 때마다 기본 공격력 및 액티브 스킬 최종 피해가 <color=#00F6FF>3%</color> 증가하며, 턴마다 여러 번 시전할 수 있다. HP가 <color=#00F6FF>10%</color> 미만인 대상에게 <color=#00F6FF>3배</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_17010911 = "액티브 스킬 강화: 액티브 스킬이 <color=#00F6FF>원하는 칸</color>을 선택할 수 있게 되고, <color=#00F6FF>자신의 등 뒤 대상</color>도 공격한다.",
  str_skill_upgrade_refine_desc_17010912 = "장비 스킬 강화: 턴마다 <color=#00F6FF>첫 2회</color> 일반공격 시 ESP <color=#00F6FF>1</color>포인트를 획득하며, 해당 일반공격의 피해가 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_upgrade_refine_desc_17010913 = "신규 액티브 스킬 획득: ESP <color=#00F6FF>10</color>포인트를 소모, 이번 턴의 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가한다(중복 시전 시 중첩 가능).",
  str_skill_name_340109 = "월야의 사냥",
  str_skill_desc_340109 = "ESP <color=#00F6FF>10</color>포인트를 소모하고 남은 ESP 포인트를 제거해 선택한 칸 방향 전후 경로 및 인접 칸에 있는 적에게 <color=#00F6FF><color=#00F6FF>150%</color></color>의 피해를 입힌다. 제거된 ESP 1포인트마다 최종 피해가 <color=#00F6FF>8%</color> 증가한다.",
  str_skill_passive_desc_453109 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 턴마다 <color=#00F6FF>첫 2회</color> 일반공격 시 ESP <color=#00F6FF>1</color>포인트를 획득하며, 해당 일반공격의 피해가 <color=#00F6FF>100%</color> 증가한다.",
  str_skill_name_360109 = "숲의 포착",
  str_skill_desc_360109 = "ESP <color=#00F6FF>10</color>포인트를 소모, 이번 턴의 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가한다(중복 시전 시 중첩 가능).",
  str_skill_upgrade_refine_desc_17011011 = "장비 스킬 강화: 일반공격 시 <color=#00F6FF>35%</color> 확률로 자신으로부터 거리가 가장 먼 적에게 뇌격을 1회 시전한다.",
  str_skill_upgrade_refine_desc_17011012 = "장비 스킬 강화: 뇌격 시전 시 ESP가 5포인트 미만일 경우 ESP 1포인트를 획득한다.",
  str_skill_upgrade_refine_desc_17011013 = "액티브 스킬 강화: 뇌격 시전 시 진혼의 인장 1개를 획득한다. 액티브 스킬 시전 시 모든 진혼의 인장을 제거하며, 제거한 진혼의 인장 1개당 액티브 스킬 피해 계수가 10% 증가한다.",
  str_skill_passive_desc_443110 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 액티브 스킬로 적 1명을 처치할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득하며, 일반공격 시 <color=#00F6FF>35%</color> 확률로 자신으로부터 거리가 가장 먼 적에게 뇌격을 1회 시전한다.",
  str_skill_passive_desc_453110 = "턴이 시작될 때마다 ESP <color=#00F6FF>5</color>포인트를 획득한다. 액티브 스킬로 적 1명을 처치할 때마다 ESP <color=#00F6FF>2</color>포인트를 획득하며, 일반공격 시 <color=#00F6FF>35%</color> 확률로 자신으로부터 거리가 가장 먼 적에게 뇌격을 1회 시전한다. 뇌격 시전 시 ESP가 5포인트 미만일 경우 ESP 1포인트를 획득한다.",
  str_skill_desc_366110 = "ESP <color=#00F6FF>10</color>포인트를 소모하고 남은 ESP 포인트와 <link=\"30117\"><#FFAE07><u>진혼의 인장</u></color></link>을 제거해 적 전체에 <color=#00F6FF>150%</color>의 피해를 입힌다. 제거된 ESP 1포인트마다 피해가 <color=#00F6FF>15%</color> 증가하고, 대상의 방어를 <color=#00F6FF>1%</color> 무시하며, 제거된 진혼의 인장 1개마다 액티브 스킬 피해 계수가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_upgrade_desc_16023013 = "장비 스킬 강화: 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_upgrade_desc_16023014 = "액티브 스킬, 장비 스킬 강화: 피해를 입힐 때 파티가 잃은 HP 계산에 <color=#00F6FF>4000</color>포인트를 추가한다.",
  str_skill_upgrade_desc_16023015 = "장비 스킬 강화: 파티의 HP가 감소할수록 자신이 진리의 계약을 지닌 적에게 입히는 모든 피해가 증가한다(HP 50% 도달 시 최대치인 <color=#00F6FF>15%</color> 증가).",
  str_skill_name_2002301 = "진홍의 연옥",
  str_skill_name_2002302 = "진홍의 연옥",
  str_skill_name_2002303 = "진홍의 연옥",
  str_skill_name_3002301 = "핏빛 달의 광연",
  str_skill_name_3042301 = "핏빛 달의 광연",
  str_skill_name_30023011 = "핏빛 달의 광연",
  str_skill_name_30423011 = "핏빛 달의 광연",
  str_skill_name_3002302 = "춤추는 잔물결",
  str_skill_passive_name_4102301 = "관용의 전지",
  str_skill_passive_name_4302301 = "관용의 전지",
  str_skill_passive_name_4132301 = "관용의 전지",
  str_skill_passive_name_4332301 = "관용의 전지",
  str_skill_passive_name_4142301 = "관용의 전지",
  str_skill_passive_name_4342301 = "관용의 전지",
  str_skill_passive_name_4162301 = "관용의 전지",
  str_skill_passive_name_4362301 = "관용의 전지",
  str_skill_desc_2002301 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 <color=#00F6FF>동일 배율</color>의 피해를 입힌다.",
  str_skill_desc_2002302 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 <color=#00F6FF>동일 배율</color>의 피해를 입힌다.",
  str_skill_desc_2002303 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 <color=#00F6FF>동일 배율</color>의 피해를 입힌다.",
  str_skill_desc_3002301 = "빅토리아 디 엘레지가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 10포인트 소모, 대상을 선택해 <link=\"30118\"><#FFAE07><u>진리의 계약</u></color></link>을 부여하고, 파티가 잃은 HP의 <color=#00F6FF>200%</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_desc_3042301 = "빅토리아 디 엘레지가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치를 10포인트 소모, 대상을 선택해 <link=\"30118\"><#FFAE07><u>진리의 계약</u></color></link>을 부여하고, 파티가 잃은 HP + 4000포인트 수치의 <color=#00F6FF>200%</color>에 해당하는 방어무시 피해를 입힌다",
  str_skill_desc_3002302 = "파티의 현재 HP와 이성 수치 퍼센트를 교환한다. 전투 진입 시 1회의 시전 기회를 획득하며, 이성 수치가 0인 경우 시전할 수 없다.",
  str_skill_passive_desc_4102301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다.",
  str_skill_passive_desc_4302301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트).",
  str_skill_passive_desc_4132301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4332301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4142301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP + <color=#00F6FF>4000</color>포인트 수치의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4342301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4162301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP + <color=#00F6FF>4000</color>포인트 수치의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입히며, 파티의 HP가 감소할수록 자신이 진리의 계약을 지닌 적에게 입히는 모든 피해가 증가한다(HP 50% 도달 시 최대치인 <color=#00F6FF>15%</color> 증가). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4362301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>{1}</color>에 해당하는 방어무시 피해를 입힌다. 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복하며(최소 1포인트), 파티의 HP가 감소할수록 자신이 진리의 계약을 지닌 적에게 입히는 모든 피해가 증가한다(HP 50% 도달 시 최대치인 <color=#00F6FF>15%</color> 증가). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_upgrade_refine_desc_16023011 = "장비 스킬 강화: 피해 계수가 <color=#00F6FF>35%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_16023012 = "연쇄 스킬 강화: 진리의 계약을 지닌 적에게 입히는 피해가 <color=#00F6FF>10%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16023013 = "액티브 스킬 강화: 시전 횟수가 <color=#00F6FF>1</color>회 증가한다.",
  str_skill_name_2502301 = "진홍의 연옥",
  str_skill_name_2502302 = "진홍의 연옥",
  str_skill_name_2502303 = "진홍의 연옥",
  str_skill_passive_desc_4402301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>35%</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트).",
  str_skill_passive_desc_4432301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>35%</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4442301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>35%</color>에 해당하는 방어무시 피해를 입히며, 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복한다(최소 1포인트). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_passive_desc_4462301 = "턴 시작 시 또는 짙은 칸을 지날 때마다 진리의 계약을 지닌 적에게 파티가 잃은 HP의 <color=#00F6FF>35%</color>에 해당하는 방어무시 피해를 입힌다. 빅토리아 디 엘레지가 진리의 계약을 지닌 적에게 피해를 입힐 때마다 감소한 이성 수치의 <color=#00F6FF>3%</color>를 회복하며(최소 1포인트), 파티의 HP가 감소할수록 자신이 진리의 계약을 지닌 적에게 입히는 모든 피해가 증가한다(HP 50% 도달 시 최대치인 <color=#00F6FF>15%</color> 증가). 이성 수치가 50 이상에서 50 미만으로, 또는 50 미만에서 50 이상으로 변경될 때마다 가장 가까운 불 속성이 아닌 칸이 <color=#00F6FF>불 속성 짙은 칸</color>으로 전환된다.",
  str_skill_desc_2502301 = "가장 가까운 적 3명에게 <color=#00F6FF>135%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 현재 계수의 <color=#00F6FF>1.1배</color>에 해당하는 피해를 입힌다.",
  str_skill_desc_2502302 = "가장 가까운 적 3명에게 <color=#00F6FF>150%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 현재 계수의 <color=#00F6FF>1.1배</color>에 해당하는 피해를 입힌다.",
  str_skill_desc_2502303 = "가장 가까운 적 3명에게 <color=#00F6FF>165%</color>의 피해를 입히고, 진리의 계약을 지닌 적에게 추가로 현재 계수의 <color=#00F6FF>1.1배</color>에 해당하는 피해를 입힌다.",
  str_skill_desc_3602302 = "파티의 현재 HP와 이성 수치 퍼센트를 교환한다. 전투 진입 시 2회의 시전 기회를 획득하며, 이성 수치가 0인 경우 시전할 수 없다.",
  str_skill_name_2002311 = "피의 일섬",
  str_skill_name_2002312 = "피의 일섬",
  str_skill_name_2002313 = "피의 일섬",
  str_skill_name_3002311 = "심연의 나락",
  str_skill_name_3032311 = "심연의 나락",
  str_skill_name_3202311 = "심연의 나락",
  str_skill_name_3232311 = "심연의 나락",
  str_skill_name_3302312 = "입맞춤의 낙인",
  str_skill_desc_2002311 = "자신의 <color=#00F6FF>주변 2서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>130%</color>의 피해를 3회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002312 = "자신의 <color=#00F6FF>주변 2서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>140%</color>의 피해를 4회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_2002313 = "자신의 <color=#00F6FF>주변 3서클</color> 내의 적에게 랜덤으로 <color=#00F6FF>150%</color>의 피해를 5회 입히며, 동일 대상에게 여러 차례 피해를 입힐 시 2번째부터 회당 절반으로 피해가 감소한다.",
  str_skill_desc_3002311 = "빌헬름이 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 두 칸을 물 속성 짙은 칸으로 전환하며, 선택된 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>2</color>포인트 차감한다.",
  str_skill_desc_3032311 = "빌헬름이 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 두 칸을 물 속성 짙은 칸으로 전환하며, 선택된 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>2</color>포인트 차감한다.",
  str_skill_desc_3202311 = "빌헬름이 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 2서클</color> 내 1칸을 다시 선택해 두 칸을 물 속성 짙은 칸으로 전환하며, 선택된 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>2</color>포인트 차감한다. 동시에 해당 구역의 모든 적에게 피의 혼절 상태를 <color=#00F6FF>1</color>회 부여하며, 시전 후 이성 수치가 <color=#00F6FF>50</color> 미만일 시 추가로 1회 부여한다.",
  str_skill_desc_3232311 = "빌헬름이 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 1칸을 선택하고 <color=#00F6FF>주변 3서클</color> 내 1칸을 다시 선택해 두 칸을 물 속성 짙은 칸으로 전환하며, 선택된 구역 내의 한 칸마다 이성 수치를 <color=#00F6FF>2</color>포인트 차감한다. 동시에 해당 구역의 모든 적에게 피의 혼절 상태를 <color=#00F6FF>1</color>회 부여하며, 시전 후 이성 수치가 <color=#00F6FF>50</color> 미만일 시 추가로 1회 부여한다.",
  str_skill_desc_3302312 = "이성 수치를 20 회복하며, 시전 후 이성 수치 한도가 20 감소한다. 이성 수치 한도가 0이 아닐 경우 연속으로 시전할 수 있다.",
  str_skill_passive_name_4002311 = "밤의 장례",
  str_skill_passive_name_4062311 = "밤의 장례",
  str_skill_passive_desc_4002311 = "파티 내 오로리안이 대상에게 부여한 공포 상태가 <color=#00F6FF>피의 혼절</color> 상태로 대체되며, 단계마다 대상의 방어력을 <color=#00F6FF>{1}</color> 감소시킨다. 최대 3회 중첩 가능, 2턴간 지속된다. 피의 혼절 상태가 1단계 제거되거나(대상 사망 포함) 한도를 초과해서 부여될 때마다 이성 수치 1포인트를 회복하며, 빌헬름의 연쇄 스킬이 피해를 입힐 때마다 대상에게 <color=#00F6FF>피의 혼절</color> 상태를 1회 부여한다.",
  str_skill_passive_desc_4062311 = "파티 내 오로리안이 대상에게 부여한 공포 상태가 <color=#00F6FF>피의 혼절</color> 상태로 대체되며, 단계마다 대상의 방어력을 <color=#00F6FF>{1}</color> 감소시킨다. 최대 3회 중첩 가능, 2턴간 지속된다. 피의 혼절 상태가 1단계 제거되거나(대상 사망 포함) 한도를 초과해서 부여될 때마다 이성 수치 2포인트를 회복하며, 빌헬름의 연쇄 스킬이 피해를 입힐 때마다 대상에게 <color=#00F6FF>피의 혼절</color> 상태를 1회 부여한다.",
  str_skill_upgrade_desc_16023113 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다. 2번째 칸 선택 범위가 3서클로 확대된다.",
  str_skill_upgrade_desc_16023116 = "장비 스킬 강화: 피의 혼절 상태가 제거되거나 한도를 초과해서 부여될 때마다 이성 수치 2포인트를 회복한다.",
