  str_skill_passive_name_4052321 = "사면의 술",
  str_skill_desc_2002321 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_2002322 = "<color=#00F6FF>쌍십자형 16칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_2002323 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고 <link=\"10000\"><#FFAE07><u>출혈</u></color></link> 상태를 1회 부여한다. 2턴간 지속.",
  str_skill_desc_3002321 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>1</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3202322 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 파티의 최대 HP의 <color=#00F6FF>25%</color>를 소모해 <color=#00F6FF>2</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3022321 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>1</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3222322 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 파티의 최대 HP의 <color=#00F6FF>25%</color>를 소모해 <color=#00F6FF>2</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3302321 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>1</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, 시전 후 파티 HP가 <color=#00F6FF>30%</color> 미만일 시 해당 칸을 불 속성으로 전환한다. HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3302322 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 파티의 최대 HP의 <color=#00F6FF>25%</color>를 소모해 <color=#00F6FF>2</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, 시전 후 파티 HP가 <color=#00F6FF>30%</color> 미만일 시 처음 선택한 칸을 불 속성으로 전환한다. HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3322321 = "파티의 최대 HP의 <color=#00F6FF>10%</color>를 소모해 <color=#00F6FF>1</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, 시전 후 파티 HP가 <color=#00F6FF>30%</color> 미만일 시 해당 칸을 불 속성으로 전환한다. HP가 부족할 경우 시전할 수 없다.",
  str_skill_desc_3322322 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 증가한다</color>. 파티의 최대 HP의 <color=#00F6FF>25%</color>를 소모해 <color=#00F6FF>2</color>칸을 선택, 해당 칸을 짙은 칸으로 전환하며, 시전 후 파티 HP가 <color=#00F6FF>30%</color> 미만일 시 처음 선택한 칸을 불 속성으로 전환한다. HP가 부족할 경우 시전할 수 없다.",
  str_skill_passive_desc_4002321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4052321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 짙은 칸 통과로 간주하고, 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>{1}</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4402321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4452321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 짙은 칸 통과로 간주하고, 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4502321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>+<color=#00F6FF>잃은 HP의 5%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4552321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 짙은 칸 통과로 간주하고, 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>+<color=#00F6FF>잃은 HP의 5%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4602321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color>, <color=#00F6FF>30%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>+<color=#00F6FF>잃은 HP의 5%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4652321 = "현재 HP 퍼센트가 <color=#00F6FF>50%</color>, <color=#00F6FF>30%</color> 이하일 시 가장 가까운 이동 가능한 불 속성 칸에 진홍의 축복이 생성되며, 통과 시 짙은 칸 통과로 간주하고, 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>+<color=#00F6FF>잃은 HP의 5%</color>만큼 HP를 회복한다.",
  str_skill_upgrade_desc_15023212 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다.",
  str_skill_upgrade_desc_15023215 = "장비 스킬 강화: 진홍의 축복 통과 시 짙은 칸 통과로 간주한다.",
  str_skill_upgrade_refine_desc_15023211 = "장비 스킬 강화: 진홍의 축복 통과 시 나일즈 더 세이크리드 라이트의 공격력의 <color=#00F6FF>110%</color>만큼 HP를 회복한다.",
  str_skill_upgrade_refine_desc_15023212 = "장비 스킬 강화: 진홍의 축복 통과 시 잃은 HP의 <color=#00F6FF>5%</color>를 추가로 회복한다.",
  str_skill_upgrade_refine_desc_15023213 = "장비 스킬 강화: 현재 HP 퍼센트가 <color=#00F6FF>30%</color> 이하일 시 가장 가까운 불 속성 2칸에 진홍의 축복을 생성한다.",
  str_skill_name_29101011 = "사도 소환",
  str_skill_desc_29101011 = "필드 가장자리에 랜덤으로 사도를 다수 소환한다.",
  str_skill_name_29101012 = "탐욕의 복원",
  str_skill_desc_29101012 = "전방 1칸 범위 내 오로리안에게 피해를 입히고 HP를 회복한다. 명중 실패 시 제자리에서 대량의 HP를 회복한다.",
  str_skill_name_20052011 = "이성 흡수",
  str_skill_desc_20052011 = "전방의 오로리안의 이성 수치를 감소시킨다.",
  str_skill_name_20052012 = "일반공격",
  str_skill_desc_20052012 = "전방의 오로리안을 공격해 피해를 입힌다.",
  str_skill_name_291000101 = "파멸의 가지",
  str_skill_desc_291000101 = "슈르톤이 전방 5열 범위에 불을 뿜어 오로리안에게 피해를 입힌다.",
  str_skill_name_291000102 = "황혼의 끝",
  str_skill_desc_291000102 = "슈르톤의 꼬리가 오로리안 턴 시작 시 위치로 직선 범위 공격을 가해 피해를 입힌다.",
  str_skill_name_291000103 = "두 개의 종소리",
  str_skill_desc_291000103 = "슈르톤이 전체화면 범위 내의 오로리안에게 피해를 입힌다.",
  str_skill_upgrade_desc_16023313 = "액티브 스킬 강화: 전투 진입 시 AP <color=#00F6FF>20</color>포인트를 획득한다.\n연쇄 스킬 강화: <color=#00F6FF>2/3</color>단계 연쇄 스킬이 범위 내에 랜덤으로 짙은 칸을 <color=#00F6FF>1</color>개 생성한다.",
  str_skill_upgrade_desc_16023316 = "액티브 스킬 강화: 액티브 스킬을 시전해도 턴 종료 시 AP를 획득한다.",
  str_skill_name_3002331 = "그랑샤리오",
  str_skill_name_3032331 = "그랑샤리오",
  str_skill_name_3062331 = "그랑샤리오",
  str_skill_name_3302331 = "그랑샤리오",
  str_skill_name_3332331 = "그랑샤리오",
  str_skill_name_3362331 = "그랑샤리오",
  str_skill_desc_3002331 = "<link=\"30119\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입힌다.",
  str_skill_desc_3032331 = "<link=\"30120\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입힌다.",
  str_skill_desc_3062331 = "<link=\"30121\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입힌다.",
  str_skill_desc_3302331 = "<link=\"30119\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입히고, 범위 내 모든 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한 후 불 속성으로 전환한다. 이미 불 속성인 짙은 칸을 흡수할 경우 짙은 칸을 2개 흡수한 것으로 간주한다.",
  str_skill_desc_3332331 = "<link=\"30120\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입히고, 범위 내 모든 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한 후 불 속성으로 전환한다. 이미 불 속성인 짙은 칸을 흡수할 경우 짙은 칸을 2개 흡수한 것으로 간주한다.",
  str_skill_desc_3362331 = "<link=\"30121\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1칸을 선택해 주변 21칸에 <color=#00F6FF>300%</color>의 피해를 입히고, 범위 내 모든 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한 후 불 속성으로 전환한다. 이미 불 속성인 짙은 칸을 흡수할 경우 짙은 칸을 2개 흡수한 것으로 간주한다.",
  str_skill_name_2002331 = "샤이닝 블라스트",
  str_skill_name_2002332 = "샤이닝 블라스트",
  str_skill_name_2002333 = "샤이닝 블라스트",
  str_skill_desc_2002331 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002332 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002333 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2032332 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 랜덤 <color=#00F6FF>1</color>칸에 짙은 칸을 생성한다.",
  str_skill_desc_2032333 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 범위 내 랜덤 <color=#00F6FF>1</color>칸에 짙은 칸을 생성한다.",
  str_skill_passive_name_4102331 = "연금술 선생님",
  str_skill_passive_name_4202331 = "연금술 선생님",
  str_skill_passive_desc_4102331 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>{1}</color> 획득한다.",
  str_skill_passive_desc_4202331 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>{1}</color> 획득하며, 짙은 칸을 지날 때마다 택틱스 포인트를 <color=#00F6FF>3</color> 획득한다.",
  str_skill_passive_desc_4402331 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득하며, 짙은 칸을 지날 때마다 택틱스 포인트를 <color=#00F6FF>3</color> 획득한다.",
  str_skill_passive_desc_4502331 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득하며, 짙은 칸을 지날 때마다 택틱스 포인트를 <color=#00F6FF>5</color> 획득한다.",
  str_skill_passive_desc_4602331 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30123\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득하며, 짙은 칸을 지날 때마다 택틱스 포인트를 <color=#00F6FF>5</color> 획득한다.",
  str_skill_upgrade_refine_desc_16023311 = "장비 스킬 강화: 라이자가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득한다.",
  str_skill_upgrade_refine_desc_16023312 = "장비 스킬 강화: 짙은 칸을 지날 때마다 택틱스 포인트를 <color=#00F6FF>5</color> 획득한다.",
  str_skill_upgrade_refine_desc_16023313 = "장비 스킬 강화: [택틱스 시스템] 신규 효과 추가, 라이자가 전투 진입 후 택틱스 시스템 레벨 한도가 1 증가한다.",
