  str_skill_desc_3302351 = "<link=\"30119\"><#FFAE07><u>AP</u></color></link> 20포인트를 소모, 1개 방향을 선택해 해당 방향에 <color=#00F6FF>200%</color>의 피해를 입히며, 가장 먼 대상에게 추가로 1회의 피해를 입히고, 대상 주변 1서클 범위 내 랜덤 <color=#00F6FF>1</color>칸을 짙은 칸으로 전환한다.",
