  str_skill_passive_desc_460235 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30123\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 파트리샤가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득한다.",
