  str_skill_name_3562341 = "화이트 레퀴엠",
  str_skill_desc_2002341 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002342 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002343 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2202341 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2202342 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2202343 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2302341 = "가장 가까운 적 2명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 이번 턴에 짙은 칸을 지날 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2302342 = "가장 가까운 적 3명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 이번 턴에 짙은 칸을 지날 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2302343 = "가장 가까운 적 4명에게 <color=#00F6FF>{1}%</color>의 피해를 입히며, 이번 턴에 짙은 칸을 지날 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2602341 = "가장 가까운 적 2명에게 <color=#00F6FF>165%</color>의 피해를 입힌다. 이번 턴에 짙은 칸을 통과할 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가하며, 피해 계수가 <color=#00F6FF>5%</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 명중한 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2602342 = "가장 가까운 적 3명에게 <color=#00F6FF>170%</color>의 피해를 입힌다. 이번 턴에 짙은 칸을 통과할 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가하며, 피해 계수가 <color=#00F6FF>5%</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 명중한 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
  str_skill_desc_2602343 = "가장 가까운 적 4명에게 <color=#00F6FF>175%</color>의 피해를 입힌다. 이번 턴에 짙은 칸을 통과할 때마다 연쇄 스킬 대상이 <color=#00F6FF>1</color> 증가하며, 피해 계수가 <color=#00F6FF>5%</color> 증가한다. 실제 명중 대상이 스킬 대상 수보다 적을 경우, 명중한 가장 가까운 대상 주변에 짙은 칸을 1개 생성한다.",
