  str_skill_name_2302343 = "인피니티 애로",
  str_skill_passive_name_410234 = "페이스메이커",
  str_skill_passive_desc_410234 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 클라우디아가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>{1}</color> 획득한다.",
  str_skill_passive_desc_440234 = "《라이자의 아틀리에2》 콜라보 오로리안은 전투 진입 시 <link=\"30122\"><#FFAE07><u>[택틱스 시스템]</u></color></link>을 적용한다. 클라우디아가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득한다.",
  str_skill_upgrade_refine_desc_16023411 = "장비 스킬 강화: 클라우디아가 액티브 스킬을 시전할 때마다 택틱스 포인트를 <color=#00F6FF>20</color> 획득한다.",
  str_skill_upgrade_refine_desc_16023412 = "액티브 스킬 강화: 여러 칸 크기의 적에게 입히는 피해가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16023413 = "연쇄 스킬 강화: 이번 턴에 짙은 칸을 지날 때마다 연쇄 스킬 피해 계수가 <color=#00F6FF>5%</color> 증가한다.",
  str_skill_desc_240461 = "<color=#00F6FF>주변 4서클</color> 내의 적 <color=#00F6FF>3</color>명에게 <color=#00F6FF>120%</color>의 피해를 입히고 조소의 인장을 1개 추가하며, 최대 8개까지 중첩된다. 인장 개수마다 연쇄 피해가 <color=#00F6FF>7%</color> 증가한다.",
  str_skill_desc_240462 = "<color=#00F6FF>주변 4서클</color> 내의 적 <color=#00F6FF>3</color>명에게 <color=#00F6FF>140%</color>의 피해를 입히고 조소의 인장을 2개 추가하며, 최대 8개까지 중첩된다. 인장 개수마다 연쇄 피해가 <color=#00F6FF>7%</color> 증가한다.",
  str_skill_desc_240463 = "<color=#00F6FF>주변 4서클</color> 내의 적 <color=#00F6FF>3</color>명에게 <color=#00F6FF>155%</color>의 피해를 입히고 조소의 인장을 3개 추가하며, 최대 8개까지 중첩된다. 인장 개수마다 연쇄 피해가 <color=#00F6FF>7%</color> 증가한다.",
  str_skill_upgrade_refine_desc_13004612 = "연쇄 스킬 강화: 조소의 인장 1개당 연쇄 피해가 <color=#00F6FF>7%</color> 증가한다.",
  str_skill_desc_300046 = "1칸을 선택해 「꼬꼬」를 배치, 「꼬꼬」를 중심으로 <color=#00F6FF>모든 적</color>을 끌어당기며, 인장 5개를 지닌 적에게 2턴간 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여한다.",
  str_skill_desc_302046 = "1칸을 선택해 「꼬꼬」를 배치, 「꼬꼬」를 중심으로 <color=#00F6FF>모든 적</color>을 끌어당기고, 인장 4개를 지닌 적에게 2턴간 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여하며, 6개를 지닌 적에게 1턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다.",
  str_skill_desc_305046 = "1칸을 선택해 「꼬꼬」를 배치, 「꼬꼬」를 중심으로 <color=#00F6FF>모든 적</color>을 끌어당기고, 인장 4개를 지닌 적에게 2턴간 <link=\"10006\"><#FFAE07><u>둔화</u></color></link> 상태를 부여하며, 6개를 지닌 적에게 <color=#00F6FF>1</color>턴간 <link=\"10004\"><#FFAE07><u>마비</u></color></link> 상태를 부여한다.",
  str_skill_name_29099011 = "일반공격",
  str_skill_desc_29099011 = "이동 후 전방 4칸 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_29099012 = "일반공격",
  str_skill_desc_29099012 = "이동 후 전방 2칸 범위 내의 대상에게 피해를 입힌다.",
  str_skill_name_29099013 = "낙하 충격",
  str_skill_desc_29099013 = "뛰어오른 후 오로리안 근처로 착지해 피해를 입히고, 자신의 주변에 일정량의 연금술 소재를 드롭한다.",
  str_skill_name_29099023 = "추방-낙하 충격",
  str_skill_desc_29099023 = "뛰어오른 후 오로리안 근처로 착지해 피해를 입힌다.",
  str_skill_name_700201701 = "백안의 저격",
  str_skill_name_700201702 = "파괴된 위작",
  str_skill_name_700201901 = "멜로딕 메탈 솔로",
  str_skill_name_700201902 = "종언의 천인",
  str_skill_desc_700201701 = "이동 후 전체화면 범위 내 대상에게 피해를 입힌다.",
  str_skill_desc_700201702 = "이동 후 오로리안의 턴 시작 시 위치를 중심으로 쌍십자형 17칸에 피해를 입힌다.",
  str_skill_desc_700201901 = "세로 5열 범위 내의 대상에게 피해를 입힌다.",
  str_skill_desc_700201902 = "전체화면 범위 내 대상에게 피해를 입히고, 자신을 중심으로 대상을 4방으로 3칸 넉백시킨다.",
  str_skill_name_590028203 = "추방-크로스 다크매터",
  str_skill_desc_590028203 = "다크 서머너가 십자형 최대 범위 내 대상에게 피해를 입힌다.",
  str_skill_name_590028204 = "추방-비컨 소환",
  str_skill_desc_590028204 = "다크 서머너가 고정 위치에 비컨을 소환한다.",
  str_skill_name_590028205 = "추방-비컨 소환",
  str_skill_desc_590028205 = "다크 서머너가 필드에 비컨 4개를 소환한다.",
  str_skill_name_590028206 = "추방-에너지 축적Ⅰ",
  str_skill_desc_590028206 = "다크 서머너가 제자리에서 에너지를 축적해 대규모 범위 공격을 준비한다. 비컨의 수가 많을수록 공격 범위가 커진다.",
  str_skill_name_590028207 = "추방-에너지 축적Ⅱ",
  str_skill_desc_590028207 = "다크 서머너가 목표 근처로 순간이동해 에너지를 축적하여 대규모 범위 공격을 준비한다. 비컨의 수가 많을수록 공격 범위가 커진다.",
  str_skill_name_590028208 = "추방-침묵",
  str_skill_desc_590028208 = "다크 서머너가 축적한 에너지 서클을 터트려 좁은 범위에 피해를 입힌다.",
  str_skill_name_590028209 = "추방-적막",
  str_skill_desc_590028209 = "다크 서머너가 축적한 에너지 서클을 터트려 넓은 범위에 피해를 입힌다.",
  str_skill_name_590028210 = "추방-공허",
  str_skill_desc_590028210 = "다크 서머너가 축적한 에너지 서클을 터트려 전체 범위에 피해를 입힌다.",
  str_skill_name_54910020 = "호밍 애로우",
  str_skill_desc_54910020 = "가장 가까운 적 2명에게 피해를 입힌다.",
  str_skill_name_2002371 = "요람의 꿈",
  str_skill_name_2002372 = "요람의 꿈",
  str_skill_name_2002373 = "요람의 꿈",
  str_skill_name_2302371 = "요람의 꿈",
  str_skill_name_2302372 = "요람의 꿈",
  str_skill_name_2302373 = "요람의 꿈",
  str_skill_name_3002371 = "꿈물결의 부름",
  str_skill_name_3032371 = "꿈물결의 부름",
  str_skill_name_3202371 = "꿈물결의 부름",
  str_skill_name_3232371 = "꿈물결의 부름",
  str_skill_desc_2002371 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2002372 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가까운 적을 중심으로 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>170%</color>의 피해를 입힌다.",
  str_skill_desc_2002373 = "<color=#00F6FF>주변 2서클</color> 범위 내 가장 가까운 적을 중심으로 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>180%</color>의 피해를 입힌다.",
  str_skill_desc_2302371 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>160%</color>의 피해를 입힌다.",
  str_skill_desc_2302372 = "<color=#00F6FF>마름모 12칸</color> 범위 내 가장 가까운 적을 중심으로 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>170%</color>의 피해를 입히며, 해당 적의 위치에 찬란한 물거품을 1개 소환한다.",
  str_skill_desc_2302373 = "<color=#00F6FF>주변 2서클</color> 범위 내 가장 가까운 적을 중심으로 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>180%</color>의 피해를 입히며, 해당 적의 위치에 찬란한 물거품을 1개 소환한다.",
  str_skill_desc_3002371 = "<color=#00F6FF>마름모 12칸</color> 범위 내 이동 가능한 칸을 선택해 시작점으로 삼고, 장애물을 무시하고 원하는 수량의 <color=#00F6FF>물 속성 칸</color>을 연결하며, 종점이 적의 위치일 경우 대상에게 <color=#00F6FF>200%</color>의 피해를 입히고, 대상의 주변 위치로 순간이동한다.",
  str_skill_desc_3032371 = "<color=#00F6FF>마름모 12칸</color> 범위 내 이동 가능한 칸을 선택해 시작점으로 삼고, 장애물을 무시하고 원하는 수량의 <color=#00F6FF>물 속성 칸</color>을 연결하며, 종점이 적의 위치일 경우 대상에게 <color=#00F6FF>300%</color>의 피해를 입히고, 대상의 주변 위치로 순간이동한다.",
  str_skill_desc_3202371 = "<color=#00F6FF>마름모 12칸</color> 범위 내 이동 가능한 칸을 선택해 시작점으로 삼고, 장애물을 무시하고 원하는 수량의 <color=#00F6FF>물 속성 칸, 짙은 칸, 찬란한 물거품</color>을 연결하며, 종점이 적의 위치일 경우 대상에게 <color=#00F6FF>200%</color>의 피해를 입히고, 대상의 주변 위치로 순간이동한다.",
  str_skill_desc_3232371 = "<color=#00F6FF>마름모 12칸</color> 범위 내 이동 가능한 칸을 선택해 시작점으로 삼고, 장애물을 무시하고 원하는 수량의 <color=#00F6FF>물 속성 칸, 짙은 칸, 찬란한 물거품</color>을 연결하며, 종점이 적의 위치일 경우 대상에게 <color=#00F6FF>300%</color>의 피해를 입히고, 대상의 주변 위치로 순간이동한다.",
  str_skill_passive_name_4102371 = "경화수월",
  str_skill_passive_desc_4102371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>2</color>곳에 찬란한 물거품을 생성하며, 3턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 3명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_name_4402371 = "경화수월",
  str_skill_passive_desc_4402371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>2</color>곳에 찬란한 물거품을 생성하며, 3턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 3명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_passive_name_4502371 = "경화수월",
  str_skill_passive_desc_4502371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>2</color>곳에 찬란한 물거품을 생성하며, 3턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 4명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_passive_name_4602371 = "경화수월",
  str_skill_passive_desc_4602371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>2</color>곳에 찬란한 물거품을 생성하며, 3턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 4명에게 <color=#00F6FF>140%</color>의 피해를 입힌다. 짙은 칸 또는 찬란한 물거품을 지나 발동 시 환상의 근원 1포인트 누적되며, 환상의 근원 1포인트당 연쇄 스킬 피해가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_passive_name_4162371 = "경화수월",
  str_skill_passive_desc_4162371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>3</color>곳에 찬란한 물거품을 생성하며, 5턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 3명에게 <color=#00F6FF>{1}</color>의 피해를 입힌다.",
  str_skill_passive_name_4462371 = "경화수월",
  str_skill_passive_desc_4462371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>3</color>곳에 찬란한 물거품을 생성하며, 5턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 3명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_passive_name_4562371 = "경화수월",
  str_skill_passive_desc_4562371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>3</color>곳에 찬란한 물거품을 생성하며, 5턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 4명에게 <color=#00F6FF>140%</color>의 피해를 입힌다.",
  str_skill_passive_name_4662371 = "경화수월",
  str_skill_passive_desc_4662371 = "턴이 시작될 때마다 랜덤으로 필드 내 이동 가능한 칸 <color=#00F6FF>3</color>곳에 찬란한 물거품을 생성하며, 5턴간 지속된다. 연결 이동 또는 액티브 스킬 연결로 찬란한 물거품을 지날 시 <color=#00F6FF>주변 3서클</color> 범위 내 적 4명에게 <color=#00F6FF>140%</color>의 피해를 입힌다. 짙은 칸 또는 찬란한 물거품을 지나 발동 시 환상의 근원 1포인트 누적되며, 환상의 근원 1포인트당 연쇄 스킬 피해가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_upgrade_refine_desc_16023711 = "장비 스킬 강화: 찬란한 물거품 발동 시 입히는 피해가 <color=#00F6FF>140%</color>까지 증가한다.",
  str_skill_upgrade_refine_desc_16023712 = "장비 스킬 강화: 찬란한 물거품 발동 시 범위 내 적 <color=#00F6FF>4</color>명에게 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16023713 = "장비 스킬 강화: 짙은 칸 또는 찬란한 물거품을 지나 발동 시 환상의 근원 1포인트 누적되며, 환상의 근원 1포인트당 연쇄 스킬 피해가 <color=#00F6FF>1%</color> 증가한다.",
  str_skill_upgrade_desc_16023713 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#FFFF00>1</color> 감소한다. 종점이 적의 위치일 경우 대상에게 <color=#FFFF00>300%</color>의 피해를 입힌다.",
  str_skill_upgrade_desc_16023716 = "장비 스킬 강화: 찬란한 물거품의 지속 시간이 5턴으로 증가하며, 턴이 시작될 때마다 필드에 찬란한 물거품이 추가로 1개 생성된다.",
  str_skill_name_291020103 = "좌초된 추격",
  str_skill_name_291020104 = "갈구한 사랑",
  str_skill_name_291020105 = "세이렌의 울음",
  str_skill_desc_291020103 = "오로리안에게 피해를 입히고, 오로리안 주변에 예포를 소환한다. 자신의 HP가 70%/40% 미만일 시 소환 수량이 1 증가한다.",
  str_skill_desc_291020104 = "자신의 주변 1서클 범위 내 오로리안과 가장 가까운 칸에 시커를 소환한다. 자신의 HP가 50% 미만일 시 소환 수량이 1 증가한다.",
  str_skill_desc_291020105 = "오로리안에게 점차 증가하는 3회의 피해를 입히고 끝까지 넉백시킨다.",
  str_skill_desc_291020113 = "오로리안에게 피해를 입히고, 오로리안 주변에 예포를 소환한다.",
  str_skill_passive_desc_443173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>25%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬이 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_passive_desc_453173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>25%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬 발동 조건이 단계별로 <color=#00F6FF>1/2/3</color>칸 감소하고, 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_passive_desc_463173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>25%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬 발동 조건이 단계별로 <color=#00F6FF>1/2/3</color>칸 감소하고, 동일 대상에게 명중해도 피해가 감소하지 않음, 액티브 스킬 피해 계수가 <color=#00F6FF>200%</color>로 증가).",
  str_skill_passive_desc_440173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>20%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬이 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_passive_desc_450173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>20%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬 발동 조건이 단계별로 <color=#00F6FF>1/2/3</color>칸 감소하고, 동일 대상에게 명중해도 피해가 감소하지 않음).",
  str_skill_passive_desc_460173 = "파티가 <link=\"20001\"><#FFAE07><u>강화 칸</u></color></link>을 획득(<link=\"30065\"><#FFAE07><u>흡수</u></color></link> 포함)할 때마다 즉시 필드 내 랜덤 <color=#00F6FF>1</color>개 대상에게 <color=#00F6FF>85%</color>의 피해를 입힌다. 전투 진입 시 객중의 인장을 <color=#00F6FF>33</color>단계 획득하며, 강화 칸을 획득할 때마다 <color=#00F6FF>1</color>단계씩 감소한다. 인장이 제거되면 이번 전투에서 뿔그림자 상태에 진입한다(기본 공격력 <color=#00F6FF>20%</color> 증가, 일반공격이 사선 방향 공격 가능, 장비 스킬 피해가 <color=#00F6FF>2.5</color>배로 증가, 연쇄 스킬 발동에 필요한 칸 수가 각각 <color=#00F6FF>1/2/3</color> 감소하고, 동일 대상에게 명중해도 피해가 감소하지 않음, 액티브 스킬 피해 계수가 <color=#00F6FF>200%</color>로 증가).",
  str_skill_upgrade_refine_desc_16017311 = "장비 스킬 강화: 피해 계수가 85%로 증가한다.",
  str_skill_upgrade_refine_desc_16017312 = "장비 스킬 강화: 뿔그림자 상태 진입 시 연쇄 스킬 발동에 필요한 칸 수가 각각 1/2/3 감소한다.",
  str_skill_upgrade_refine_desc_16017313 = "장비 스킬 강화: 뿔그림자 상태 진입 시 액티브 스킬 피해 계수가 200%로 증가한다.",
  str_skill_upgrade_refine_desc_14016911 = "장비 스킬 강화: 새디의 기본 공격력이 <color=#00F6FF>33%</color> 증가하며, 스맥다운 포인트 1포인트당 액티브 스킬 피해 계수가 <color=#00F6FF>22%</color> 증가한다.",
  str_skill_upgrade_refine_desc_14016912 = "장비 스킬 강화: 짙은 칸 통과 시 스맥다운 포인트를 <color=#00F6FF>1</color> 획득한다.",
  str_skill_upgrade_refine_desc_14016913 = "액티브 스킬 강화: 선택 가능 범위가 <color=#00F6FF>주변 1서클</color>로 확대된다.",
  str_skill_passive_desc_440169 = "새디의 기본 공격력이 <color=#00F6FF>33%</color> 증가한다. 매회 연결 이동 시 새디가 최대 <color=#00F6FF>3</color>회까지 일반공격을 진행하고, 3번째 일반공격은 2배의 피해를 입히며, 3회 이후의 일반공격은 <color=#00F6FF>스맥다운 포인트</color>를 1점 획득하는 것으로 변경된다. 스맥다운 포인트 1점마다 액티브 스킬 피해 계수가 <color=#00F6FF>22%</color> 증가하며, 액티브 스킬 시전 후 초기화된다.",
  str_skill_passive_desc_450169 = "새디의 기본 공격력이 <color=#00F6FF>33%</color> 증가한다. 매회 연결 이동 시 새디가 최대 <color=#00F6FF>3</color>회까지 일반공격을 진행하고, 3번째 일반공격은 2배의 피해를 입히며, 3회 이후의 일반공격은 <color=#00F6FF>스맥다운 포인트</color>를 1점 획득하는 것으로 변경된다. 스맥다운 포인트 1점마다 액티브 스킬 피해 계수가 <color=#00F6FF>22%</color> 증가하며, 액티브 스킬 시전 후 초기화된다. 짙은 칸 통과 시 스맥다운 포인트를 <color=#00F6FF>1</color> 획득한다.",
  str_skill_name_360169 = "붕붕 플라이",
  str_skill_name_365169 = "붕붕 플라이",
  str_skill_desc_360169 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 2칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다. 장애물이 다른 적일 시 해당 적도 피해 및 스턴 효과를 받는다.",
  str_skill_desc_365169 = "<color=#00F6FF>주변 1서클</color> 내의 적 1명에게 <color=#00F6FF>300%</color>의 피해를 입히고 3칸 넉백시킨다. 만약 넉백 중 <color=#00F6FF>장애물</color>에 닿으면 추가로 <color=#00F6FF>200%</color>의 피해를 입히고 1턴간 <color=#00F6FF>스턴</color>시킨다. 장애물이 다른 적일 시 해당 적도 피해 및 스턴 효과를 받는다.",
  str_skill_name_20053011 = "깊은 바다의 속삭임",
  str_skill_desc_20053011 = "자신의 주변 1서클 범위 내의 적에게 피해를 입힙니다.",
  str_skill_name_20054011 = "접촉",
  str_skill_desc_20054011 = "오로리안이 자신의 2서클 범위 내에 있으면 오로리안 근처에 암귀를 소환해 자신을 돕게 합니다.",
  str_skill_upgrade_desc_17023613 = "액티브 스킬 강화: 턴이 시작될 때마다 ESP 5포인트를 획득한다.",
  str_skill_upgrade_desc_17023616 = "신규 액티브 스킬 획득: 그라디우스가 이탈 상태일 때 시전할 수 있다. 즉시 파티로 돌아와 경로상의 칸에 <color=#00F6FF>550%</color>의 피해를 입힌다.",
  str_skill_passive_name_4102361 = "운명을 향한 분노",
  str_skill_name_2002361 = "체르니의 기적",
  str_skill_name_2002362 = "체르니의 기적",
  str_skill_name_2002363 = "체르니의 기적",
  str_skill_name_2002364 = "체르니의 기적",
  str_skill_name_3302361 = "개척의 결의",
  str_skill_name_3302362 = "귀환하는 유성",
  str_skill_desc_3302361 = "전투 중 <link=\"30125\"><#FFAE07><u>ESP</u></color></link>를 획득할 수 있다. 스킬 시전 시 그라디우스가 특수한 출전 모드로 진입하며, 본 모드에서는 그라디우스 단독으로 <link=\"30127\"><#FFAE07><u>연결 조종</u></color></link>을 진행할 수 있다. 연결 종료 시 그라디우스가 <link=\"30128\"><#FFAE07><u>이탈 상태</u></color></link>에 진입하며, 연결 종료 위치에 <link=\"30129\"><#FFAE07><u>잔영</u></color></link>을 남겨 다음 액티브 스킬 시전 시 연결 시작점으로 삼는다.",
  str_skill_desc_3332361 = "전투 중 <link=\"30126\"><#FFAE07><u>ESP</u></color></link>를 획득할 수 있다.스킬 시전 시 그라디우스가 특수한 출전 모드로 진입하며, 본 모드에서는 그라디우스 단독으로 <link=\"30127\"><#FFAE07><u>연결 조종</u></color></link>을 진행할 수 있다. 연결 종료 시 그라디우스가 <link=\"30128\"><#FFAE07><u>이탈 상태</u></color></link>에 진입하며, 연결 종료 위치에 <link=\"30129\"><#FFAE07><u>잔영</u></color></link>을 남겨 다음 액티브 스킬 시전 시 연결 시작점으로 삼는다.",
  str_skill_desc_3302362 = "그라디우스가 이탈 상태일 때 시전할 수 있다. 즉시 파티로 돌아와 경로상의 칸에 <color=#00F6FF>550%</color>의 피해를 입힌다.",
  str_skill_desc_2002361 = "<color=#00F6FF>주변 4칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002362 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이탈 상태가 아닐 시 ESP 3포인트를 획득한다.",
  str_skill_desc_2002363 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다. 이탈 상태가 아닐 시 ESP 4포인트를 획득한다.",
  str_skill_desc_2002364 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>175%</color>의 피해를 입힌다. 이탈 상태가 아닐 시 ESP 5포인트를 획득한다.",
  str_skill_passive_desc_4102361 = "그라디우스는 <color=#00F6FF>무속성</color> 오로리안으로, 공격 및 피격 시의 속성 상성 계수는 모두 <color=#00F6FF>100%</color>이다. <color=#00F6FF>그라디우스가 리더일 시에는 모든 칸에서 출전하며, 팀원일 시 연결된 모든 칸이 만색 칸일 때에만 출전한다</color>. 액티브 스킬로 ESP 1포인트를 소모할 때마다 그라디우스가 별의 힘을 1단계 획득하며, 단계당 그라디우스의 피해가 <color=#00F6FF>{1}</color> 증가한다(최대 99단계).",
  str_skill_passive_desc_4402361 = "그라디우스는 <color=#00F6FF>무속성</color> 오로리안으로, 공격 및 피격 시의 속성 상성 계수는 모두 <color=#00F6FF>100%</color>이다. <color=#00F6FF>그라디우스가 리더일 시에는 모든 칸에서 출전하며, 팀원일 시 연결된 모든 칸이 만색 칸일 때에만 출전한다</color>. 액티브 스킬로 ESP 1포인트를 소모할 때마다 그라디우스가 별의 힘을 1단계 획득하며, 단계당 그라디우스의 피해가 <color=#00F6FF>1.1%</color> 증가한다(최대 99단계).",
  str_skill_passive_desc_4602361 = "그라디우스는 <color=#00F6FF>무속성</color> 오로리안으로, 공격 및 피격 시의 속성 상성 계수는 모두 <color=#00F6FF>100%</color>이다. <color=#00F6FF>그라디우스가 리더일 시에는 모든 칸에서 출전하며, 팀원일 시 연결된 모든 칸이 만색 칸일 때에만 출전한다</color>. 액티브 스킬로 ESP 1포인트를 소모할 때마다 그라디우스가 별의 힘을 2단계 획득하며, 단계당 그라디우스의 피해가 <color=#00F6FF>1.1%</color> 증가한다(최대 99단계).",
  str_skill_upgrade_refine_desc_17023611 = "장비 스킬 강화: 단계당 계수가 <color=#00F6FF>1.1%</color>로 증가한다.",
  str_skill_upgrade_refine_desc_17023612 = "신규 <color=#00F6FF>4</color>단계 연쇄 스킬 획득: 12칸 연결 시 시전하며, 주변 2서클 범위에 175%의 피해를 입힌다. 이탈 상태가 아닐 시 ESP 5포인트를 획득한다.",
  str_skill_upgrade_refine_desc_17023613 = "장비 스킬 강화: 획득하는 별의 힘 단계가 <color=#00F6FF>2배</color>로 증가한다.",
  str_skill_upgrade_desc_16023813 = "액티브 스킬 강화: 액티브 스킬이 <color=#FFFF00>선제공격</color>으로 변경되어, 전투 진입 즉시 사용할 수 있게 된다.",
  str_skill_upgrade_desc_16023816 = "액티브 스킬 강화: 선택 가능한 칸 수가 <color=#00F6FF>1</color>개 증가한다.",
  str_skill_name_2002381 = "깃털 속의 칼날",
  str_skill_desc_2002381 = "<color=#00F6FF>가장 가까운 적 1명</color>에게 깃털 칼날을 던져 170%의 피해를 입히고, <color=#00F6FF>대상과 가장 가까운</color> 다른 적에게 도탄시킨다. 대상과 1서클 멀어질 때마다 최종 피해가 10% 증가하며, 최대 50%까지 증가한다. 연쇄 수에 따라 피해 보너스가 증가한다.",
  str_skill_name_3002381 = "계시의 전언",
  str_skill_name_3062381 = "계시의 전언",
  str_skill_name_3302381 = "계시의 전언-진화Ⅰ",
  str_skill_name_3362381 = "계시의 전언-진화Ⅰ",
  str_skill_desc_3002381 = "<color=#00F6FF>5칸</color>을 선택해 강화 칸을 생성한다.",
  str_skill_desc_3062381 = "<color=#00F6FF>6칸</color>을 선택해 강화 칸을 생성한다.",
  str_skill_desc_3302381 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#00F6FF>3칸</color>을 선택해 강화 칸을 생성한다.",
  str_skill_desc_3362381 = "<color=#FFFF00>시전 후 스킬 쿨다운 턴 수가 1 감소한다</color>. <color=#00F6FF>4칸</color>을 선택해 강화 칸을 생성한다.",
  str_skill_passive_name_4102381 = "계승된 별빛",
  str_skill_passive_name_4162381 = "계승된 별빛",
  str_skill_passive_desc_4102381 = "<color=#00F6FF>강화 칸</color> 1개를 획득할 때마다 <color=#00F6FF>별빛 인장 1개</color>를 획득하며, 연쇄 스킬로 피해를 입힐 때마다 별빛 인장을 <color=#00F6FF>1/3</color> 소모, 개당 파티 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 추가한다.",
  str_skill_passive_desc_4162381 = "<color=#00F6FF>강화 칸 1개</color>를 획득할 때마다 <color=#00F6FF>별빛 인장 1개</color>를 획득하며, 연쇄 스킬로 피해를 입힐 때마다 별빛 인장을 <color=#00F6FF>1/3</color> 소모, 개당 파티 평균 공격력의 <color=#00F6FF>{1}</color>에 해당하는 피해를 추가하며, 단일 턴에 강화 칸 1개를 획득할 때마다 연쇄 스킬 발동에 필요한 칸 수가 1 감소한다.",
  str_skill_upgrade_refine_desc_15017611 = "장비 스킬 강화: 베르타의 <color=#00F6FF>4</color>번째 일반공격마다 현재 대상에게 오스트랄리스의 바늘을 1개 추가한다.",
  str_skill_upgrade_refine_desc_15017612 = "액티브 스킬 강화: 오스트랄리스의 바늘이 대상에게 <color=#00F6FF>100%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_15017613 = "액티브 스킬 강화: 오스트랄리스의 바늘이 대상에게 피해를 입힐 시 개당 이번 피해의 <color=#00F6FF>15%~22.5%</color>만큼 HP를 회복한다.",
  str_skill_passive_desc_4401761 = "베르타의 <color=#00F6FF>4</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_passive_desc_4451761 = "베르타의 <color=#00F6FF>4</color>번째 일반공격마다 현재 대상에게 <color=#00F6FF>오스트랄리스의 바늘</color>을 <color=#00F6FF>1</color>개 추가한다.",
  str_skill_desc_3501761 = "<color=#00F6FF>주변 2서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3521761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3551761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%~120%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>10%~15%</color>만큼 HP를 회복한다. 대상의 현재 HP가 낮을수록 피해 계수가 증가하며, 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3601761 = "<color=#00F6FF>주변 2서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>15%~22.5%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3621761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>15%~22.5%</color>만큼 HP를 회복한다. 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_desc_3651761 = "<color=#00F6FF>주변 3서클</color> 내의 모든 적이 지닌 <color=#00F6FF>오스트랄리스의 바늘</color>을 뽑아 대상에게 바늘 1개당 <color=#00F6FF>100%~120%</color>의 피해를 입히고, 이번 피해의 <color=#00F6FF>15%~22.5%</color>만큼 HP를 회복한다. 대상의 현재 HP가 낮을수록 피해 계수가 증가하며, 팀의 HP가 낮을수록 회복 계수가 증가한다.",
  str_skill_name_3501821 = "이룡의 선풍-진화Ⅰ",
  str_skill_name_3601821 = "이룡의 선풍-진화Ⅱ",
  str_skill_desc_3501821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link>가 <color=#00F6FF>2</color>개 점등되면 액티브 스킬이 준비되며, <color=#FFFF00>시전 시 2개의 「정룡의 광휘」가 꺼진다</color>. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>400%</color>의 피해를 입히나, 장비 스킬 「혈유의 비기」가 발동하지 않는다.",
  str_skill_desc_3601821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link>가 <color=#00F6FF>2</color>개 점등되면 액티브 스킬이 준비되며, <color=#FFFF00>시전 시 2개의 「정룡의 광휘」가 꺼진다</color>. 장비 스킬 「혈유의 비기」가 발동하며, 적 <color=#00F6FF>전체</color>에 <color=#00F6FF>300%</color>의 피해를 입힌다.",
  str_skill_upgrade_refine_desc_16018211 = "액티브 스킬 강화: 피해 계수가 400%로 증가한다.",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: 「정룡의 광휘」가 2개 점등되면 액티브 스킬이 준비되며, 시전 시 2개의 「정룡의 광휘」가 꺼진다. 1칸을 선택해 마름모 13칸에 400%의 피해를 입히나, 장비 스킬 「혈유의 비기」가 발동하지 않는다.",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>액티브 스킬 진화Ⅱ 획득</color>: 「정룡의 광휘」가 2개 점등되면 액티브 스킬이 준비되며, 시전 시 2개의 「정룡의 광휘」가 꺼진다. 장비 스킬 「혈유의 비기」가 발동하며, 적 전체에 300%의 피해를 입힌다.",
  str_skill_desc_3401821 = "<link=\"30074\"><#FFAE07><u>「정룡의 광휘」</u></color></link></color>가 <color=#00F6FF>3개 점등되면 액티브 스킬이 준비된다. 1칸을 선택해 <color=#00F6FF>마름모 13칸</color>에 <color=#00F6FF>400%</color>의 피해를 입히며, 액티브 스킬 시전 후 모든 「정룡의 광휘」가 꺼진다.",
  str_skill_upgrade_desc_16024113 = "액티브 스킬 강화: 액티브 스킬 쿨다운 턴 수가 <color=#00F6FF>1</color> 감소하며, 피해 계수가 <color=#00F6FF>50%</color> 증가한다.",
  str_skill_upgrade_desc_16024116 = "<color=#00F6FF>액티브 스킬 진화Ⅰ 획득</color>: 이성 수치 소모량과 피해가 <color=#00F6FF>2배로 증가</color>하고, 짙은 칸을 최대 <color=#00F6FF>3</color>개 생성한다.",
  str_skill_name_2002411 = "탈출의 폭렬",
  str_skill_name_2002412 = "탈출의 폭렬",
  str_skill_name_2002413 = "탈출의 폭렬",
  str_skill_name_2302411 = "탈출의 폭렬",
  str_skill_name_2302412 = "탈출의 폭렬",
  str_skill_name_2302413 = "탈출의 폭렬",
  str_skill_name_3002411 = "만발의 춤사위",
  str_skill_name_3032411 = "만발의 춤사위",
  str_skill_name_3062411 = "만발의 춤사위-진화Ⅰ",
  str_skill_desc_2002411 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002412 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2002413 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입힌다.",
  str_skill_desc_2302411 = "<color=#00F6FF>주변 1서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 주변 4칸 범위 내의 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한다.",
  str_skill_desc_2302412 = "<color=#00F6FF>마름모 12칸</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 주변 1서클 범위 내의 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한다.",
  str_skill_desc_2302413 = "<color=#00F6FF>주변 2서클</color>에 <color=#00F6FF>{1}%</color>의 피해를 입히고, 주변 마름모 12칸 범위 내의 짙은 칸을 <link=\"30124\"><#FFAE07><u>흡수</u></color></link>한다.",
  str_skill_desc_3002411 = "페피타가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>15</color>포인트를 소모, 적 1명을 선택해 대상에게 150%의 피해를 입히며, 대상의 발아래에 랜덤으로 짙은 칸을 1개 생성한다.",
  str_skill_desc_3032411 = "페피타가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>15</color>포인트를 소모, 적 1명을 선택해 대상에게 200%의 피해를 입히며, 대상의 발아래에 랜덤으로 짙은 칸을 1개 생성한다.",
  str_skill_desc_3062411 = "페피타가 전투 진입 후 자신에게 <link=\"30039\"><#FFAE07><u>[이성 시스템]</u></color></link>을 적용한다. 이성 수치 <color=#00F6FF>30</color>포인트를 소모, 적 1명을 선택해 대상에게 400%의 피해를 입히며, 대상의 발아래에 랜덤으로 짙은 칸을 1개 생성한다.",
  str_skill_passive_name_4102411 = "타오르는 심장",
  str_skill_passive_name_4202411 = "타오르는 심장",
  str_skill_passive_desc_4102411 = "짙은 칸을 획득할 때마다 페피타가 심장의 화염을 <color=#00F6FF>1</color>단계 획득한다(최대 <color=#00F6FF>7</color>단계). 현재 리더가 일반공격을 할 때마다 심장의 화염 1단계를 소모하며, 해당 일반공격의 최종 피해가 <color=#00F6FF>{1}</color> 증가한다.",
  str_skill_passive_desc_4202411 = "짙은 칸을 획득할 때마다 페피타가 심장의 화염을 <color=#00F6FF>1</color>단계 획득한다(최대 <color=#00F6FF>7</color>단계). 현재 리더가 일반공격을 할 때마다 심장의 화염 1단계를 소모하며, 해당 일반공격의 최종 피해가 <color=#00F6FF>{1}</color> 증가한다. 턴이 시작될 때마다 모든 적의 발아래에 랜덤으로 짙은 칸을 <color=#00F6FF>2</color>개 생성한다.",
